window.MT_DATA = window.MT_DATA || {};
window.MT_DATA['ru'] = [{"id":1,"name":"Niveau 1","freeLessonsPerModule":{"1":10,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"La vie de tous les jours en Russie, en route et à la maison.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Bonjour, Moscou !","phrases":[{"fr":"Bonjour, Anna Petrovna !","tgt":"Здравствуйте, Анна Петровна!","ro":"Zdrávstvuyte, Ánna Petróvna!","lit":"bonjour · Anna · Petrovna"},{"fr":"Salut, Micha !","tgt":"Привет, Миша!","ro":"Privét, Mísha!","lit":"salut · Micha"},{"fr":"Bonjour, je suis votre nouveau voisin.","tgt":"Здравствуйте, я ваш новый сосед.","ro":"Zdrávstvuyte, ya vash nóvyy saséd.","lit":"bonjour · je · votre · nouveau · voisin"},{"fr":"Salut, comment ça va ?","tgt":"Привет, как дела?","ro":"Privét, kak delá?","lit":"salut · comment · affaires ?"},{"fr":"Ça va super, et toi ?","tgt":"Отлично, а у тебя?","ro":"Atlíchna, a u tebyá?","lit":"excellent · et · [à toi] ?"},{"fr":"Salut tout le monde !","tgt":"Всем привет!","ro":"Vsem privét!","lit":"à tous · salut"},{"fr":"Bonjour, entrez, je vous en prie.","tgt":"Здравствуйте, проходите, пожалуйста.","ro":"Zdrávstvuyte, prakhadíte, pazhálsta.","lit":"bonjour · passez · s'il vous plaît"},{"fr":"Bonne journée à vous !","tgt":"Хорошего дня!","ro":"Kharóshevo dnya!","lit":"bonne · journée"},{"fr":"Au revoir, à demain !","tgt":"До свидания, до завтра!","ro":"Da svidániya, da závtra!","lit":"jusqu'à · revoir · jusqu'à · demain"},{"fr":"Allez, salut, à bientôt !","tgt":"Ну, пока, до встречи!","ro":"Nu, paká, da vstréchi!","lit":"bon · salut · jusqu'à · rencontre"}],"tip":{"title":"Saluer : « zdrávstvuyte » et « privét »","example":"Salut, Micha ! — <b>Привет</b>, Миша!","body":"En russe, on choisit sa salutation selon la personne en face. Avec un inconnu, un voisin âgé ou au travail, on dit « zdrávstvuyte », bonjour poli, qui veut dire littéralement « portez-vous bien ». Avec un ami ou un enfant, on dit simplement « privét », salut. Le mot « zdrávstvuyte » fait peur, mais dans la vie courante les Russes avalent une partie des sons et disent presque « zdrástvuyte ». Découpez-le en trois morceaux : « zdrást », puis « vuy », puis « te », avec la force sur le « a » du début. Pour partir, c'est la même logique : « da svidániya », au revoir, pour être poli, et « paká », salut, entre amis. Une astuce pour retenir : « privét » est court comme une tape amicale sur l'épaule, « zdrávstvuyte » est long comme une poignée de main sérieuse.","exampleRo":"Privét, Mísha!","lit":"salut · Micha"}},{"title":"Mon appartement à Moscou","phrases":[{"fr":"Voilà mon appartement.","tgt":"Вот моя квартира.","ro":"Vot mayá kvartíra.","lit":"voilà · mon · appartement"},{"fr":"La cuisine est toute petite.","tgt":"Кухня совсем маленькая.","ro":"Kúkhnya savsém málen'kaya.","lit":"cuisine · tout à fait · petite"},{"fr":"La pièce est lumineuse.","tgt":"Комната светлая.","ro":"Kómnata svétlaya.","lit":"pièce · lumineuse"},{"fr":"Le salon est grand.","tgt":"Гостиная большая.","ro":"Gastínaya bal'sháya.","lit":"salon · grand"},{"fr":"La fenêtre donne sur la cour.","tgt":"Окно выходит во двор.","ro":"Aknó vykhódit va dvor.","lit":"fenêtre · sort · dans · cour"},{"fr":"J'habite au cinquième étage.","tgt":"Я живу на пятом этаже.","ro":"Ya zhivú na pyátam etazhé.","lit":"je · vis · sur · cinquième · étage"},{"fr":"L'appartement est douillet.","tgt":"Квартира уютная.","ro":"Kvartíra uyútnaya.","lit":"appartement · douillet"},{"fr":"Le métro est tout près.","tgt":"Метро совсем рядом.","ro":"Metró savsém ryádam.","lit":"métro · tout à fait · à côté"},{"fr":"La serrure est neuve.","tgt":"Замок новый.","ro":"Zamók nóvyy.","lit":"serrure · neuve"},{"fr":"Cet appartement me plaît beaucoup.","tgt":"Мне очень нравится эта квартира.","ro":"Mne óchen' nrávitsa éta kvartíra.","lit":"à moi · très · plaît · cet · appartement"}],"tip":{"title":"L'accent tonique : la syllabe forte qui change tout","example":"La serrure est neuve. — <b>Замок</b> новый.","body":"En français, on pose toutes les syllabes à peu près à égalité. En russe, chaque mot a une syllabe forte, plus longue et plus appuyée, et c'est elle qui donne son relief au mot. Dans la transcription, cette syllabe porte un accent aigu : « kvartíra », l'appartement, se dit avec la force sur « tí ». Bonne nouvelle pour l'oral : les « o » qui ne sont pas sous l'accent se prononcent presque « a », c'est pourquoi « okno », la fenêtre, se dit « aknó ». L'accent peut même changer le sens : « zamók » veut dire la serrure, alors que « zámok » veut dire le château. Mot à mot, « Zamók nóvyy » donne serrure, neuve. Exercez-vous avec « kúkhnya », la cuisine, et « metró », le métro. Une astuce : tapez légèrement du pied sur la syllabe forte en répétant, votre bouche suivra le rythme.","exampleRo":"Zamók nóvyy.","lit":"serrure · neuve"}},{"title":"Les voisins de palier","phrases":[{"fr":"Lui, il est très gentil.","tgt":"Он очень добрый.","ro":"On óchen' dóbryy.","lit":"il · très · gentil"},{"fr":"Elle travaille à la boulangerie.","tgt":"Она работает в пекарне.","ro":"Aná rabótayet v pekárne.","lit":"elle · travaille · dans · boulangerie"},{"fr":"Toi, tu es d'ici ?","tgt":"Ты отсюда?","ro":"Ty atsyúda?","lit":"toi · d'ici ?"},{"fr":"Vous êtes notre nouvelle voisine ?","tgt":"Вы наша новая соседка?","ro":"Vy násha nóvaya sasédka?","lit":"vous · notre · nouvelle · voisine ?"},{"fr":"Oui, et lui, c'est mon mari.","tgt":"Да, а это мой муж.","ro":"Da, a éta moy muzh.","lit":"oui · et · ce · mon · mari"},{"fr":"Nous habitons au troisième étage.","tgt":"Мы живём на третьем этаже.","ro":"My zhivyóm na trét'yem etazhé.","lit":"nous · vivons · sur · troisième · étage"},{"fr":"Ils sont très sympathiques.","tgt":"Они очень приятные.","ro":"Aní óchen' priyátnyye.","lit":"ils · très · agréables"},{"fr":"Elle a un chat roux.","tgt":"У неё рыжий кот.","ro":"U neyó rýzhiy kot.","lit":"[à elle] · roux · chat"},{"fr":"Lui, il est étudiant.","tgt":"Он студент.","ro":"On studént.","lit":"il · étudiant"},{"fr":"Et vous, vous habitez où ?","tgt":"А вы где живёте?","ro":"A vy gde zhivyóte?","lit":"et · vous · où · vivez ?"}],"tip":{"title":"Les pronoms : « ya », « ty », « vy », « on », « aná »","example":"Elle travaille à la boulangerie. — <b>Она</b> работает в пекарне.","body":"Les pronoms russes sont courts et faciles à dire. « Ya » veut dire je, « ty » tu, « vy » vous, « on » il, « aná » elle, « my » nous et « aní » ils ou elles. Comme en français, « ty » est pour les amis, la famille et les enfants, et « vy » pour les inconnus, les voisins et les collègues : dans le doute, dites « vy ». Le pronom se place au début de la phrase, exactement comme chez nous. Par exemple « Aná rabótayet v pekárne » se décompose en elle, travaille, dans, boulangerie. Attention à « aná » : la force est sur le « á » final, c'est ce qui le distingue à l'oreille. Pour retenir, pensez que « on » est le même mot qu'en français, mais qu'il veut dire il, un seul homme bien précis.","exampleRo":"Aná rabótayet v pekárne.","lit":"elle · travaille · dans · boulangerie"}},{"title":"Qui suis-je ?","phrases":[{"fr":"Je suis français, et vous ?","tgt":"Я француз, а вы?","ro":"Ya frantsúz, a vy?","lit":"je · Français · et · vous ?"},{"fr":"Moi, je suis ingénieur.","tgt":"Я инженер.","ro":"Ya inzhenér.","lit":"je · ingénieur"},{"fr":"Ma femme est française.","tgt":"Моя жена француженка.","ro":"Mayá zhená frantsúzhenka.","lit":"ma · femme · Française"},{"fr":"Notre immeuble est neuf.","tgt":"Наш дом новый.","ro":"Nash dom nóvyy.","lit":"notre · maison · neuve"},{"fr":"Je suis de Lyon.","tgt":"Я из Лиона.","ro":"Ya iz Lióna.","lit":"je · de · Lyon [cas]"},{"fr":"Notre quartier est calme.","tgt":"Наш район тихий.","ro":"Nash rayón tíkhiy.","lit":"notre · quartier · calme"},{"fr":"La rue est très longue.","tgt":"Улица очень длинная.","ro":"Úlitsa óchen' dlínnaya.","lit":"rue · très · longue"},{"fr":"Il est médecin, et elle est institutrice.","tgt":"Он врач, а она учительница.","ro":"On vrach, a aná uchítel'nitsa.","lit":"il · médecin · et · elle · institutrice"},{"fr":"Je suis ici pour le travail.","tgt":"Я здесь по работе.","ro":"Ya zdes' pa rabóte.","lit":"je · ici · pour · travail"},{"fr":"Moscou est une très grande ville.","tgt":"Москва очень большой город.","ro":"Maskvá óchen' bal'shóy górad.","lit":"Moscou · très · grande · ville"}],"tip":{"title":"Ni verbe être au présent, ni article : « Ya frantsúz »","example":"Je suis français, et vous ? — Я <b>француз</b>, а вы?","body":"Voici une excellente nouvelle pour parler vite : au présent, le russe n'utilise pas le verbe être. On colle simplement les mots les uns aux autres. « Ya frantsúz » se décompose en je, Français, et cela suffit pour dire je suis français. Il n'y a pas non plus d'article, ni le, ni un : « dom » veut dire à la fois la maison et une maison. Ainsi « Ya inzhenér » signifie je suis ingénieur, et « Rayón tíkhiy » signifie le quartier est calme. À l'oral, on marque parfois une toute petite pause là où le français mettrait est. Une astuce : imaginez que vous parlez en style télégramme, moi, ingénieur, quartier, calme. C'est exactement comme ça que le russe construit ses phrases au présent.","exampleRo":"Ya frantsúz, a vy?","lit":"je · Français · et · vous ?"}},{"title":"Faire connaissance","phrases":[{"fr":"Je m'appelle Pierre.","tgt":"Меня зовут Пьер.","ro":"Menyá zavút P'yer.","lit":"moi · on appelle · Pierre"},{"fr":"Et vous, comment vous appelez-vous ?","tgt":"А как вас зовут?","ro":"A kak vas zavút?","lit":"et · comment · vous · on appelle ?"},{"fr":"Je m'appelle Svetlana, et vous ?","tgt":"Меня зовут Светлана, а вас?","ro":"Menyá zavút Svetlána, a vas?","lit":"moi · on appelle · Svetlana · et · vous ?"},{"fr":"Très heureux de faire votre connaissance.","tgt":"Очень рад познакомиться.","ro":"Óchen' rad paznakómitsa.","lit":"très · content · faire connaissance"},{"fr":"Comment s'appelle votre chat ?","tgt":"Как зовут вашего кота?","ro":"Kak zavút váshevo katá?","lit":"comment · on appelle · votre · chat ?"},{"fr":"Mon chat s'appelle Barsik.","tgt":"Моего кота зовут Барсик.","ro":"Mayevó katá zavút Bársik.","lit":"mon · chat · on appelle · Barsik"},{"fr":"Ma voisine s'appelle Olga.","tgt":"Мою соседку зовут Ольга.","ro":"Mayú sasédku zavút Ól'ga.","lit":"ma · voisine · on appelle · Olga"},{"fr":"Et lui, comment s'appelle-t-il ?","tgt":"А его как зовут?","ro":"A yevó kak zavút?","lit":"et · lui · comment · on appelle ?"},{"fr":"Il s'appelle Dmitri, mais tout le monde dit Dima.","tgt":"Его зовут Дмитрий, но все говорят Дима.","ro":"Yevó zavút Dmítriy, no vse gavaryát Díma.","lit":"lui · on appelle · Dmitri · mais · tous · disent · Dima"},{"fr":"Appelez-moi Pierre, tout simplement.","tgt":"Зовите меня просто Пьер.","ro":"Zavíte menyá prósta P'yer.","lit":"appelez · moi · simplement · Pierre"}],"tip":{"title":"« Menyá zavút » : se présenter, on m'appelle","example":"Je m'appelle Pierre. — <b>Меня зовут</b> Пьер.","body":"Pour dire son prénom, le russe ne dit pas je m'appelle, mais on m'appelle. « Menyá zavút Pierre » se décompose en moi, on appelle, Pierre. Le verbe « zavút » ne change jamais, c'est seulement le petit mot du début qui change selon la personne. On dit « Kak vas zavút ? » pour comment vous appelez-vous, mot à mot comment vous on appelle. Pour un homme, on dit « yevó zavút », et pour une femme « yeyó zavút ». La force tombe toujours sur la fin : « me-nyá za-vút », deux fois sur la dernière syllabe. Pour répondre poliment, ajoutez « Óchen' priyátna », très agréable, l'équivalent de enchanté. Astuce : pensez à un professeur qui fait l'appel en classe, on vous appelle, vous répondez.","exampleRo":"Menyá zavút P'yer.","lit":"moi · on appelle · Pierre"}},{"title":"La visite de l'appartement","phrases":[{"fr":"C'est la cuisine.","tgt":"Это кухня.","ro":"Éta kúkhnya.","lit":"ce · cuisine"},{"fr":"Et ça, c'est la salle de bains.","tgt":"А это ванная.","ro":"A éta vánnaya.","lit":"et · ce · salle de bains"},{"fr":"Et voilà ma chambre.","tgt":"А вот это моя спальня.","ro":"A vot éta mayá spál'nya.","lit":"et · voilà · ce · ma · chambre"},{"fr":"Et ça, qu'est-ce que c'est ?","tgt":"А это что?","ro":"A éta shto?","lit":"et · ce · quoi ?"},{"fr":"C'est un vieux samovar.","tgt":"Это старый самовар.","ro":"Éta stáryy samavár.","lit":"ce · vieux · samovar"},{"fr":"C'est le balcon ?","tgt":"Это балкон?","ro":"Éta balkón?","lit":"ce · balcon ?"},{"fr":"Non, c'est une armoire.","tgt":"Нет, это шкаф.","ro":"Net, éta shkaf.","lit":"non · ce · armoire"},{"fr":"C'est la clé de l'appartement.","tgt":"Это ключ от квартиры.","ro":"Éta klyuch at kvartíry.","lit":"ce · clé · de · appartement [cas]"},{"fr":"C'est notre voisin Igor.","tgt":"Это наш сосед Игорь.","ro":"Éta nash saséd Ígar'.","lit":"ce · notre · voisin · Igor"},{"fr":"C'est vraiment pratique.","tgt":"Это очень удобно.","ro":"Éta óchen' udóbna.","lit":"ce · très · pratique"}],"tip":{"title":"« Éta » : c'est, voici","example":"C'est la cuisine. — <b>Это</b> кухня.","body":"Le petit mot « éta » est votre meilleur ami pour faire visiter ou découvrir un lieu. Il veut dire c'est, voici, ou ça, et il ne change jamais, que l'objet soit masculin, féminin ou au pluriel. Comme il n'y a ni verbe être ni article, la phrase est très courte : « Éta kúkhnya » se décompose en ce, cuisine, et veut dire c'est la cuisine. Pour poser la question, on dit « Shto éta ? », quoi ce, c'est-à-dire qu'est-ce que c'est. Pour une personne, on dit tout aussi simplement « Éta Ígar' », c'est Igor. La force est sur le premier son, « É », et le « o » final s'entend « a ». Astuce : pointez du doigt chaque objet de votre cuisine en disant « éta », puis le nom, et vous aurez vite le réflexe.","exampleRo":"Éta kúkhnya.","lit":"ce · cuisine"}},{"title":"Dans le métro de Moscou","phrases":[{"fr":"C'est bien la station Pouchkinskaïa ?","tgt":"Это станция «Пушкинская»?","ro":"Éta stántsiya «Púshkinskaya»?","lit":"ce · station · Pouchkinskaïa ?"},{"fr":"Le métro est loin ?","tgt":"Метро далеко?","ro":"Metró dalekó?","lit":"métro · loin ?"},{"fr":"Vous descendez maintenant ?","tgt":"Вы сейчас выходите?","ro":"Vy seychás vykhódite?","lit":"vous · maintenant · sortez ?"},{"fr":"Oui, je descends.","tgt":"Да, выхожу.","ro":"Da, vykhazhú.","lit":"oui · sors"},{"fr":"Ce train va dans le centre ?","tgt":"Этот поезд идёт в центр?","ro":"État póyezd idyót v tsentr?","lit":"ce · train · va · dans · centre ?"},{"fr":"Le ticket coûte cher ?","tgt":"Билет дорогой?","ro":"Bilét daragóy?","lit":"ticket · cher ?"},{"fr":"C'est votre station ?","tgt":"Это ваша станция?","ro":"Éta vásha stántsiya?","lit":"ce · votre · station ?"},{"fr":"Le métro est déjà ouvert ?","tgt":"Метро уже открыто?","ro":"Metró uzhé atkrýta?","lit":"métro · déjà · ouvert ?"},{"fr":"Oui, le métro est déjà ouvert.","tgt":"Да, метро уже открыто.","ro":"Da, metró uzhé atkrýta.","lit":"oui · métro · déjà · ouvert"},{"fr":"C'est la prochaine station ?","tgt":"Это следующая станция?","ro":"Éta sléduyushchaya stántsiya?","lit":"ce · suivante · station ?"}],"tip":{"title":"La question par l'intonation, sans changer les mots","example":"Le métro est loin ? — <b>Метро далеко?</b>","body":"Pour poser une question simple en russe, on ne change rien à la phrase : seule la voix change. « Metró uzhé atkrýta » veut dire le métro est déjà ouvert, et « Metró uzhé atkrýta ? » veut dire le métro est-il déjà ouvert. C'est comme en français parlé, quand on dit tu viens, avec une voix qui monte. Mais le russe a une petite particularité : la voix monte nettement sur le mot qui porte la vraie question, puis retombe aussitôt. Dans « Metró dalekó ? », qui se décompose en métro, loin, c'est sur « dalekó » que la voix grimpe. Essayez aussi « Éta vásha stántsiya ? », est-ce votre station, en montant sur « vásha ». Astuce : imaginez une petite bosse dans votre voix, posée sur le mot important, et non une montée tout au bout de la phrase.","exampleRo":"Metró dalekó?","lit":"métro · loin ?"}},{"title":"Un matin sans se presser","phrases":[{"fr":"Je ne bois pas de café le matin.","tgt":"Я не пью кофе утром.","ro":"Ya ne p'yu kófe útram.","lit":"je · [ne… pas] · bois · café · le matin"},{"fr":"Je ne travaille pas ce dimanche.","tgt":"В это воскресенье я не работаю.","ro":"V éta vaskresén'ye ya ne rabótayu.","lit":"dans · ce · dimanche · je · [ne… pas] · travaille"},{"fr":"Excusez-moi, je ne comprends pas très bien.","tgt":"Извините, я не очень понимаю.","ro":"Izviníte, ya ne óchen' panimáyu.","lit":"pardon · je · [ne… pas] · très · comprends"},{"fr":"Ma femme ne mange pas de viande.","tgt":"Моя жена не ест мясо.","ro":"Mayá zhená ne yest myása.","lit":"ma · femme · [ne… pas] · mange · viande"},{"fr":"Nous ne sommes pas pressés.","tgt":"Мы не спешим.","ro":"My ne speshím.","lit":"nous · [ne… pas] · nous pressons"},{"fr":"Ce n'est pas mon thé.","tgt":"Это не мой чай.","ro":"Éta ne moy chay.","lit":"ce · [ne… pas] · mon · thé"},{"fr":"Je ne sais pas où sont les clés.","tgt":"Я не знаю, где ключи.","ro":"Ya ne znáyu, gde klyuchí.","lit":"je · [ne… pas] · sais · où · clés"},{"fr":"Ce matin, il ne fait pas froid.","tgt":"Сегодня утром не холодно.","ro":"Sevódnya útram ne khóladna.","lit":"aujourd'hui · le matin · [ne… pas] · froid"},{"fr":"Les voisins ne font pas de bruit.","tgt":"Соседи не шумят.","ro":"Sasédi ne shumyát.","lit":"voisins · [ne… pas] · font du bruit"},{"fr":"Le matin, je ne regarde pas la télévision.","tgt":"Утром я не смотрю телевизор.","ro":"Útram ya ne smatryú televízar.","lit":"le matin · je · [ne… pas] · regarde · télévision"}],"tip":{"title":"« Ne » : la négation, juste devant le verbe","example":"Je ne bois pas de café le matin. — Я <b>не</b> пью кофе утром.","body":"En français, la négation entoure le verbe avec ne et pas. En russe, c'est plus simple : un seul petit mot, « ne », placé juste devant le verbe, et c'est tout. « Ya ne p'yu kófe » se décompose en je, ne pas, bois, café. On n'ajoute rien après le verbe. Le mot « ne » se prononce rapidement, sans force, et il se colle au verbe comme s'il n'en faisait qu'un : « nep'yu ». On peut aussi le placer devant autre chose qu'un verbe, par exemple « Éta ne moy chay », ce n'est pas mon thé. Retenez aussi l'indispensable « Ya ne panimáyu », je ne comprends pas, et « Ya ne znáyu », je ne sais pas. Astuce : imaginez que « ne » est un petit panneau stop planté juste devant le mot que vous voulez nier.","exampleRo":"Ya ne p'yu kófe útram.","lit":"je · [ne… pas] · bois · café · le matin"}},{"title":"La boulangerie du quartier","phrases":[{"fr":"Le pain est encore chaud.","tgt":"Хлеб ещё тёплый.","ro":"Khleb yeshchyó tyóplyy.","lit":"pain · encore · chaud"},{"fr":"La brioche est bien fraîche.","tgt":"Булка свежая.","ro":"Búlka svézhaya.","lit":"brioche · fraîche"},{"fr":"Le gâteau est très bon.","tgt":"Торт очень вкусный.","ro":"Tort óchen' vkúsnyy.","lit":"gâteau · très · bon"},{"fr":"La boulangerie est déjà ouverte.","tgt":"Пекарня уже открыта.","ro":"Pekárnya uzhé atkrýta.","lit":"boulangerie · déjà · ouverte"},{"fr":"Le lait est frais.","tgt":"Молоко свежее.","ro":"Malakó svézheye.","lit":"lait · frais"},{"fr":"Ce petit pâté est au chou.","tgt":"Этот пирожок с капустой.","ro":"État pirazhók s kapústay.","lit":"ce · petit pâté · avec · chou [cas]"},{"fr":"Cette petite brioche est à la cannelle.","tgt":"Эта булочка с корицей.","ro":"Éta búlachka s karítsey.","lit":"cette · petite brioche · avec · cannelle [cas]"},{"fr":"La vendeuse est très accueillante.","tgt":"Продавщица очень приветливая.","ro":"Pradavshchítsa óchen' privétlivaya.","lit":"vendeuse · très · accueillante"},{"fr":"J'adore le pain noir.","tgt":"Я люблю чёрный хлеб.","ro":"Ya lyublyú chyórnyy khleb.","lit":"je · aime · noir · pain"},{"fr":"Cette pâtisserie est très sucrée.","tgt":"Это пирожное очень сладкое.","ro":"Éta pirózhnaye óchen' sládkaye.","lit":"cette · pâtisserie · très · sucrée"}],"tip":{"title":"Masculin, féminin, neutre : le genre s'entend à la fin du mot","example":"La boulangerie est déjà ouverte. — <b>Пекарня</b> уже <b>открыта</b>.","body":"Le russe a trois genres : masculin, féminin et neutre. La bonne nouvelle, c'est qu'on les reconnaît à l'oreille, grâce à la fin du mot. Un mot qui se termine par une consonne est en général masculin, comme « khleb », le pain, ou « tort », le gâteau. Un mot qui finit par le son « a » ou « ya » est souvent féminin, comme « búlka », la brioche, ou « pekárnya », la boulangerie. Enfin, un mot terminé par « o » ou « e » est neutre, comme « malakó », le lait. L'adjectif suit le même genre : « Pekárnya atkrýta » se décompose en boulangerie, ouverte, avec un « a » final des deux côtés. Comparez « khleb tyóplyy », le pain est chaud, et « búlka svézhaya », la brioche est fraîche. Astuce : écoutez la dernière syllabe, elle vous dit tout.","exampleRo":"Pekárnya uzhé atkrýta.","lit":"boulangerie · déjà · ouverte"}},{"title":"Mes affaires dans l'appartement","phrases":[{"fr":"C'est mon fauteuil préféré.","tgt":"Это моё любимое кресло.","ro":"Éta mayó lyubímaye krésla.","lit":"ce · mon · préféré · fauteuil"},{"fr":"Où est ma tasse ?","tgt":"Где моя чашка?","ro":"Gde mayá cháshka?","lit":"où · ma · tasse ?"},{"fr":"Mon frère habite à Saint-Pétersbourg.","tgt":"Мой брат живёт в Петербурге.","ro":"Moy brat zhivyót v Peterbúrge.","lit":"mon · frère · vit · à · Pétersbourg"},{"fr":"Ma sœur passe ce soir.","tgt":"Моя сестра приходит сегодня вечером.","ro":"Mayá sestrá prikhódit sevódnya vécheram.","lit":"ma · sœur · vient · aujourd'hui · le soir"},{"fr":"Mon téléphone est sur la table.","tgt":"Мой телефон на столе.","ro":"Moy telefón na stalé.","lit":"mon · téléphone · sur · table"},{"fr":"Votre manteau est ici.","tgt":"Ваше пальто здесь.","ro":"Váshe pal'tó zdes'.","lit":"votre · manteau · ici"},{"fr":"Ma fenêtre donne sur le parc.","tgt":"Моё окно выходит на парк.","ro":"Mayó aknó vykhódit na park.","lit":"ma · fenêtre · sort · sur · parc"},{"fr":"Mes parents habitent à Lyon.","tgt":"Мои родители живут в Лионе.","ro":"Maí radíteli zhivút v Lióne.","lit":"mes · parents · vivent · à · Lyon"},{"fr":"Ton livre est sur le canapé.","tgt":"Твоя книга на диване.","ro":"Tvayá kníga na diváne.","lit":"ton · livre · sur · canapé"},{"fr":"Mon appartement n'est pas grand, mais il est douillet.","tgt":"Моя квартира небольшая, но уютная.","ro":"Mayá kvartíra nebal'sháya, no uyútnaya.","lit":"mon · appartement · pas grand · mais · douillet"}],"tip":{"title":"« Moy », « mayá », « mayó » : mon et ma qui s'accordent","example":"Où est ma tasse ? — Где <b>моя</b> чашка?","body":"En français, on dit mon ou ma. En russe, il y a trois formes, une par genre, et elles riment avec la fin du nom. Devant un mot masculin, on dit « moy », comme dans « moy telefón », mon téléphone. Devant un mot féminin, on dit « mayá », comme dans « mayá cháshka », ma tasse. Devant un mot neutre, on dit « mayó », comme dans « mayó aknó », ma fenêtre. Attention, le genre russe ne suit pas toujours le français : la fenêtre est neutre, et l'appartement, « kvartíra », est féminin. « Gde mayá cháshka ? » se décompose en où, ma, tasse. Au pluriel, c'est « maí », mes, pour tout le monde. Même logique pour votre : « vash », « vásha », « váshe ». Astuce : écoutez la rime, « mayá kvartíra » finit en « a » des deux côtés.","exampleRo":"Gde mayá cháshka?","lit":"où · ma · tasse ?"}},{"title":"Le petit-déjeuner : blinis et thé","phrases":[{"fr":"J'ai du thé noir.","tgt":"У меня есть чёрный чай.","ro":"U menyá yest' chyórnyy chay.","lit":"[à moi] · il y a · noir · thé"},{"fr":"Vous avez du lait ?","tgt":"У вас есть молоко?","ro":"U vas yest' malakó?","lit":"[à vous] · il y a · lait ?"},{"fr":"Oui, nous avons du lait et de la crème fraîche.","tgt":"Да, у нас есть молоко и сметана.","ro":"Da, u nas yest' malakó i smetána.","lit":"oui · [à nous] · il y a · lait · et · crème fraîche"},{"fr":"J'ai des blinis tout chauds.","tgt":"У меня есть горячие блины.","ro":"U menyá yest' garyáchiye bliný.","lit":"[à moi] · il y a · chauds · blinis"},{"fr":"Tu as de la confiture ?","tgt":"У тебя есть варенье?","ro":"U tebyá yest' varén'ye?","lit":"[à toi] · il y a · confiture ?"},{"fr":"Nous avons du miel de la datcha.","tgt":"У нас есть мёд с дачи.","ro":"U nas yest' myod s dáchi.","lit":"[à nous] · il y a · miel · de · datcha [cas]"},{"fr":"Il a un grand samovar.","tgt":"У него есть большой самовар.","ro":"U nevó yest' bal'shóy samavár.","lit":"[à lui] · il y a · grand · samovar"},{"fr":"Vous avez du sucre ?","tgt":"У вас есть сахар?","ro":"U vas yest' sákhar?","lit":"[à vous] · il y a · sucre ?"},{"fr":"J'ai une heure pour le petit-déjeuner.","tgt":"У меня есть час на завтрак.","ro":"U menyá yest' chas na závtrak.","lit":"[à moi] · il y a · heure · pour · petit-déjeuner"},{"fr":"Il reste encore du thé ?","tgt":"Ещё есть чай?","ro":"Yeshchyó yest' chay?","lit":"encore · il y a · thé ?"}],"tip":{"title":"« U menyá yest' » : avoir, littéralement chez moi il y a","example":"J'ai du thé noir. — <b>У меня есть</b> чёрный чай.","body":"Pour dire j'ai, le russe utilise une tournure étonnante mais très logique : il dit chez moi, il y a. « U menyá yest' chay » se décompose en chez moi, il y a, thé, et veut dire j'ai du thé. Le petit mot « u » veut dire chez, ou auprès de, et « yest' » veut dire il y a. Pour changer de personne, on change seulement le pronom : « u vas yest' », vous avez, « u nas yest' », nous avons, « u tebyá yest' », tu as, et « u nevó yest' », il a. Pour poser la question, on garde exactement les mêmes mots et on monte la voix : « U vas yest' malakó ? », vous avez du lait ? C'est la phrase idéale à la boulangerie ou au marché. Astuce : pensez au français chez moi, il y a du thé, et vous retrouverez l'ordre russe.","exampleRo":"U menyá yest' chyórnyy chay.","lit":"[à moi] · il y a · noir · thé"}},{"title":"Au marché du quartier","phrases":[{"fr":"Désolé, je n'ai pas de petite monnaie.","tgt":"Извините, у меня нет мелочи.","ro":"Izviníte, u menyá net mélachi.","lit":"pardon · [à moi] · il n'y a pas · monnaie [cas]"},{"fr":"Vous n'avez pas de pommes de terre ?","tgt":"У вас нет картошки?","ro":"U vas net kartóshki?","lit":"[à vous] · il n'y a pas · pommes de terre [cas] ?"},{"fr":"Désolé, nous n'avons plus de tomates.","tgt":"Извините, у нас уже нет помидоров.","ro":"Izviníte, u nas uzhé net pamidórav.","lit":"pardon · [à nous] · déjà · il n'y a pas · tomates [cas]"},{"fr":"Je n'ai pas de sac plastique.","tgt":"У меня нет пакета.","ro":"U menyá net pakéta.","lit":"[à moi] · il n'y a pas · sac [cas]"},{"fr":"Il n'a pas le temps aujourd'hui.","tgt":"У него сегодня нет времени.","ro":"U nevó sevódnya net vrémeni.","lit":"[à lui] · aujourd'hui · il n'y a pas · temps [cas]"},{"fr":"Nous n'avons pas de voiture.","tgt":"У нас нет машины.","ro":"U nas net mashíny.","lit":"[à nous] · il n'y a pas · voiture [cas]"},{"fr":"Vous avez des framboises ?","tgt":"У вас есть малина?","ro":"U vas yest' malína?","lit":"[à vous] · il y a · framboises ?"},{"fr":"Non, il n'y a pas de framboises.","tgt":"Нет, малины нет.","ro":"Net, malíny net.","lit":"non · framboises [cas] · il n'y a pas"},{"fr":"Je n'ai pas de liste.","tgt":"У меня нет списка.","ro":"U menyá net spíska.","lit":"[à moi] · il n'y a pas · liste [cas]"},{"fr":"Pas de problème !","tgt":"Нет проблем!","ro":"Net prablém!","lit":"il n'y a pas · problèmes [cas]"}],"tip":{"title":"« U menyá net » : ne pas avoir","example":"Désolé, je n'ai pas de petite monnaie. — Извините, у меня <b>нет</b> мелочи.","body":"Pour dire je n'ai pas, on reprend la tournure chez moi, et on remplace « yest' », il y a, par « net », il n'y a pas. « U menyá net mélachi » se décompose en chez moi, il n'y a pas, monnaie, et veut dire je n'ai pas de monnaie. Le mot « net » est le même que pour dire non, ce qui le rend facile à retenir. Petit détail à l'oreille : après « net », la fin du nom change un peu. On dit « mashína », la voiture, mais « net mashíny », pas de voiture, et « pakét », le sac, mais « net pakéta ». Ne vous inquiétez pas si vous vous trompez, on vous comprendra parfaitement. Et gardez en réserve la formule « Net prablém ! », pas de problème. Astuce : « yest' » ouvre la porte, « net » la ferme.","exampleRo":"Izviníte, u menyá net mélachi.","lit":"pardon · [à moi] · il n'y a pas · monnaie [cas]"}},{"title":"Une journée au bureau","phrases":[{"fr":"Je travaille dans un bureau.","tgt":"Я работаю в офисе.","ro":"Ya rabótayu v ófise.","lit":"je · travaille · dans · bureau"},{"fr":"Où travaillez-vous ?","tgt":"Где вы работаете?","ro":"Gde vy rabótayete?","lit":"où · vous · travaillez ?"},{"fr":"Le matin, je lis le courrier.","tgt":"Утром я читаю почту.","ro":"Útram ya chitáyu póchtu.","lit":"le matin · je · lis · courrier"},{"fr":"Mon collègue parle français.","tgt":"Мой коллега говорит по-французски.","ro":"Moy kaléga gavarít pa-frantsúski.","lit":"mon · collègue · parle · à la française"},{"fr":"Vous connaissez Ivan ?","tgt":"Вы знаете Ивана?","ro":"Vy znáyete Ivána?","lit":"vous · connaissez · Ivan [cas] ?"},{"fr":"Nous déjeunons à la cantine.","tgt":"Мы обедаем в столовой.","ro":"My abédayem v stalóvay.","lit":"nous · déjeunons · dans · cantine"},{"fr":"Qu'est-ce que vous faites ?","tgt":"Что вы делаете?","ro":"Shto vy délayete?","lit":"quoi · vous · faites ?"},{"fr":"Je réponds aux appels.","tgt":"Я отвечаю на звонки.","ro":"Ya atvecháyu na zvankí.","lit":"je · réponds · à · appels"},{"fr":"Ils travaillent jusqu'à six heures.","tgt":"Они работают до шести.","ro":"Aní rabótayut da shestí.","lit":"ils · travaillent · jusqu'à · six"},{"fr":"Tu travailles aussi le samedi ?","tgt":"Ты тоже работаешь в субботу?","ro":"Ty tózhe rabótayesh' v subbótu?","lit":"toi · aussi · travailles · le · samedi ?"}],"tip":{"title":"Le verbe au présent : « ya rabótayu », « vy rabótayete »","example":"Où travaillez-vous ? — Где вы <b>работаете</b>?","body":"Au présent, le verbe russe change de fin selon la personne, un peu comme en français je travaille, vous travaillez. Prenons « rabótat' », travailler. On dit « ya rabótayu », je travaille, avec un son « you » à la fin. On dit « vy rabótayete », vous travaillez, avec « yete ». On dit « on rabótayet », il travaille, « my rabótayem », nous travaillons, et « aní rabótayut », ils travaillent. La force reste toujours au même endroit, sur « bó », seule la queue du mot bouge. « Gde vy rabótayete ? » se décompose en où, vous, travaillez. Bonne nouvelle : beaucoup de verbes suivent ce modèle, comme « chitát' », lire, « ya chitáyu », ou « délat' », faire, « vy délayete ». Astuce : retenez la petite musique « you, yesh, yet, yem, yete, yut ».","exampleRo":"Gde vy rabótayete?","lit":"où · vous · travaillez ?"}},{"title":"Se repérer dans le quartier","phrases":[{"fr":"Où est la station de métro la plus proche ?","tgt":"Где ближайшая станция метро?","ro":"Gde blizháyshaya stántsiya metró?","lit":"où · la plus proche · station · métro ?"},{"fr":"Où se trouve la boulangerie ?","tgt":"Где находится пекарня?","ro":"Gde nakhóditsa pekárnya?","lit":"où · se trouve · boulangerie ?"},{"fr":"Et la pharmacie, elle est où ?","tgt":"А где аптека?","ro":"A gde aptéka?","lit":"et · où · pharmacie ?"},{"fr":"Elle est à côté de la poste.","tgt":"Она рядом с почтой.","ro":"Aná ryádam s póchtay.","lit":"elle · à côté · avec · poste [cas]"},{"fr":"Où est l'arrêt de bus ?","tgt":"Где автобусная остановка?","ro":"Gde avtóbusnaya astanóvka?","lit":"où · de bus · arrêt ?"},{"fr":"C'est tout droit, et ensuite à gauche.","tgt":"Прямо, а потом налево.","ro":"Pryáma, a patóm naléva.","lit":"tout droit · et · puis · à gauche"},{"fr":"Où est le marché couvert ?","tgt":"Где крытый рынок?","ro":"Gde krýtyy rýnak?","lit":"où · couvert · marché ?"},{"fr":"Excusez-moi, où sont les toilettes ici ?","tgt":"Извините, где здесь туалет?","ro":"Izviníte, gde zdes' tualét?","lit":"pardon · où · ici · toilettes ?"},{"fr":"Le parc est derrière l'immeuble.","tgt":"Парк за домом.","ro":"Park za dómam.","lit":"parc · derrière · immeuble [cas]"},{"fr":"Où est la rue Arbat ?","tgt":"Где улица Арбат?","ro":"Gde úlitsa Arbát?","lit":"où · rue · Arbat ?"}],"tip":{"title":"« Gde » : où est, où se trouve","example":"Où se trouve la boulangerie ? — <b>Где</b> находится пекарня?","body":"Pour demander son chemin, un seul mot suffit presque : « gde », qui veut dire où. Comme il n'y a pas de verbe être au présent, on dit simplement « gde », puis le lieu : « Gde aptéka ? », où, pharmacie, c'est-à-dire où est la pharmacie. Pour être un peu plus précis, on peut ajouter « nakhóditsa », se trouve : « Gde nakhóditsa pekárnya ? » se décompose en où, se trouve, boulangerie. Le mot « gde » se prononce d'un seul coup, le « g » et le « d » collés, sans voyelle entre les deux. Commencez toujours par « Izviníte », excusez-moi, pour être poli avec un passant. Pour comprendre la réponse, guettez « pryáma », tout droit, « naléva », à gauche, et « napráva », à droite. Astuce : « gde » ressemble à un petit claquement de langue, court et direct.","exampleRo":"Gde nakhóditsa pekárnya?","lit":"où · se trouve · boulangerie ?"}},{"title":"Compter au marché","phrases":[{"fr":"Un kilo de pommes, s'il vous plaît.","tgt":"Один килограмм яблок, пожалуйста.","ro":"Adín kilográmm yáblak, pazhálsta.","lit":"un · kilogramme · pommes [cas] · s'il vous plaît"},{"fr":"Deux concombres, s'il vous plaît.","tgt":"Два огурца, пожалуйста.","ro":"Dva agurtsá, pazhálsta.","lit":"deux · concombres [cas] · s'il vous plaît"},{"fr":"Et trois tomates.","tgt":"И три помидора.","ro":"I tri pamidóra.","lit":"et · trois · tomates [cas]"},{"fr":"Ça vous fait cinq cents roubles.","tgt":"С вас пятьсот рублей.","ro":"S vas pyat'sót rubléy.","lit":"de · vous · cinq cents · roubles [cas]"},{"fr":"Donnez-moi dix œufs.","tgt":"Дайте десять яиц.","ro":"Dáyte désyat' yaíts.","lit":"donnez · dix · œufs [cas]"},{"fr":"Notre immeuble a neuf étages.","tgt":"В нашем доме девять этажей.","ro":"V náshem dóme dévyat' etazhéy.","lit":"dans · notre · immeuble · neuf · étages [cas]"},{"fr":"Mon appartement a trois pièces.","tgt":"В моей квартире три комнаты.","ro":"V mayéy kvartíre tri kómnaty.","lit":"dans · mon · appartement · trois · pièces [cas]"},{"fr":"Une baguette et deux petites brioches.","tgt":"Один батон и две булочки.","ro":"Adín batón i dve búlachki.","lit":"un · baguette · et · deux · petites brioches [cas]"},{"fr":"Il y a cinq stations jusqu'au bureau.","tgt":"До офиса пять станций.","ro":"Da ófisa pyat' stántsiy.","lit":"jusqu'à · bureau [cas] · cinq · stations [cas]"},{"fr":"Huit, neuf, dix, et c'est tout !","tgt":"Восемь, девять, десять, и всё!","ro":"Vósem', dévyat', désyat', i vsyo!","lit":"huit · neuf · dix · et · tout"}],"tip":{"title":"Compter de un à dix : « adín », « dva », « tri »","example":"Une baguette et deux petites brioches. — <b>Один</b> батон и <b>две</b> булочки.","body":"Voici les chiffres de un à dix, à dire à voix haute : « adín, dva, tri, chetýre, pyat', shest', sem', vósem', dévyat', désyat' ». Plusieurs ressemblent au français : « dva » rappelle deux, « tri » trois, et « sem' » sept. Petite subtilité : un et deux s'accordent avec le genre. On dit « adín batón », une baguette, car le mot est masculin, mais « dve búlachki », deux brioches, car le mot est féminin. Après deux, trois et quatre, le nom change légèrement sa fin, et après cinq, il change encore : « dva agurtsá », deux concombres, mais « pyat' stántsiy », cinq stations. Au marché, ce n'est pas grave si la fin n'est pas parfaite, le chiffre suffit. Astuce : comptez les marches de votre escalier en russe, une marche, un chiffre.","exampleRo":"Adín batón i dve búlachki.","lit":"un · baguette · et · deux · petites brioches [cas]"}},{"title":"Les horaires de la journée","phrases":[{"fr":"Pardon, quelle heure est-il ?","tgt":"Извините, который час?","ro":"Izviníte, katóryy chas?","lit":"pardon · quelle · heure ?"},{"fr":"Il est une heure pile.","tgt":"Сейчас ровно час.","ro":"Seychás róvna chas.","lit":"maintenant · pile · heure"},{"fr":"Il est deux heures maintenant.","tgt":"Сейчас два часа.","ro":"Seychás dva chasá.","lit":"maintenant · deux · heures [cas]"},{"fr":"Il est déjà cinq heures !","tgt":"Уже пять часов!","ro":"Uzhé pyat' chasóv!","lit":"déjà · cinq · heures [cas]"},{"fr":"Le matin, je me lève à sept heures.","tgt":"Утром я встаю в семь часов.","ro":"Útram ya vstayú v sem' chasóv.","lit":"le matin · je · me lève · à · sept · heures [cas]"},{"fr":"La boulangerie ouvre à huit heures.","tgt":"Пекарня открывается в восемь.","ro":"Pekárnya atkryváyetsa v vósem'.","lit":"boulangerie · s'ouvre · à · huit"},{"fr":"Au bureau, je commence à neuf heures.","tgt":"В офисе я начинаю в девять.","ro":"V ófise ya nachináyu v dévyat'.","lit":"dans · bureau · je · commence · à · neuf"},{"fr":"À quelle heure fermez-vous ?","tgt":"Во сколько вы закрываетесь?","ro":"Va skól'ka vy zakryváyetes'?","lit":"à · combien · vous · fermez ?"},{"fr":"Nous fermons à dix heures du soir.","tgt":"Мы закрываемся в десять вечера.","ro":"My zakryváyemsya v désyat' véchera.","lit":"nous · fermons · à · dix · du soir"},{"fr":"Il est presque quatre heures.","tgt":"Уже почти четыре часа.","ro":"Uzhé pachtí chetýre chasá.","lit":"déjà · presque · quatre · heures [cas]"}],"tip":{"title":"L'heure : « Katóryy chas ? », « chas », « dva chasá »","example":"Il est deux heures maintenant. — Сейчас <b>два часа</b>.","body":"Pour demander l'heure, on dit « Katóryy chas ? », mot à mot quelle heure, sans verbe. Pour répondre, on commence souvent par « seychás », maintenant. À une heure, les Russes ne disent même pas un, ils disent simplement « Seychás chas », maintenant, heure. Ensuite, le mot heure change selon le chiffre, et c'est ce qu'il faut entendre : « dva chasá », deux heures, « tri chasá », trois heures, « chetýre chasá », quatre heures, puis à partir de cinq, « pyat' chasóv », « sem' chasóv ». Dans la vie courante, on supprime souvent le mot heure : « v vósem' », à huit heures, suffit très bien. Pour un horaire d'ouverture, retenez la question « Va skól'ka ? », à quelle heure. Astuce : chasá jusqu'à quatre, chasóv à partir de cinq, comme une marche qu'on franchit.","exampleRo":"Seychás dva chasá.","lit":"maintenant · deux · heures [cas]"}},{"title":"Une pause au bureau","phrases":[{"fr":"Qu'est-ce que vous buvez ?","tgt":"Что вы пьёте?","ro":"Shto vy p'yóte?","lit":"quoi · vous · buvez ?"},{"fr":"Qui est ce monsieur, là-bas ?","tgt":"Кто вон тот мужчина?","ro":"Kto von tot muzhchína?","lit":"qui · là-bas · ce · homme ?"},{"fr":"C'est notre nouveau directeur.","tgt":"Это наш новый директор.","ro":"Éta nash nóvyy diréktar.","lit":"ce · notre · nouveau · directeur"},{"fr":"Comment on dit ça en russe ?","tgt":"Как это по-русски?","ro":"Kak éta pa-rússki?","lit":"comment · ce · à la russe ?"},{"fr":"Quand a lieu la réunion ?","tgt":"Когда собрание?","ro":"Kagdá sabrániye?","lit":"quand · réunion ?"},{"fr":"La réunion est à onze heures.","tgt":"Собрание в одиннадцать.","ro":"Sabrániye v adínnatsat'.","lit":"réunion · à · onze"},{"fr":"Qui veut du thé ?","tgt":"Кто хочет чаю?","ro":"Kto khóchet cháyu?","lit":"qui · veut · thé [cas] ?"},{"fr":"Comment va votre famille ?","tgt":"Как ваша семья?","ro":"Kak vásha sem'yá?","lit":"comment · votre · famille ?"},{"fr":"Qu'est-ce que vous faites ce soir ?","tgt":"Что вы делаете сегодня вечером?","ro":"Shto vy délayete sevódnya vécheram?","lit":"quoi · vous · faites · aujourd'hui · le soir ?"},{"fr":"Quand rentrez-vous à la maison ?","tgt":"Когда вы идёте домой?","ro":"Kagdá vy idyóte damóy?","lit":"quand · vous · allez · à la maison ?"}],"tip":{"title":"Les mots interrogatifs : « shto », « kto », « kak », « kagdá »","example":"Quand a lieu la réunion ? — <b>Когда</b> собрание?","body":"Avec quatre petits mots, vous pouvez poser presque toutes les questions du quotidien. « Shto » veut dire quoi, « kto » qui, « kak » comment, et « kagdá » quand. Ils se placent au tout début de la phrase, et le reste ne bouge pas : pas d'inversion comme dans le français fermez-vous. « Kagdá sabrániye ? » se décompose en quand, réunion, et veut dire quand a lieu la réunion. De même, « Shto vy p'yóte ? » donne quoi, vous, buvez. Attention à la prononciation de « shto » : il s'écrit avec un autre son au début, mais tout le monde dit bien « shto ». Ici, la voix ne monte pas à la fin, elle descend, car le mot interrogatif suffit à marquer la question. Astuce : retenez la phrase magique « Kak éta pa-rússki ? », comment dit-on ça en russe, elle vous servira tous les jours.","exampleRo":"Kagdá sabrániye?","lit":"quand · réunion ?"}},{"title":"Ce soir, on reste à la maison","phrases":[{"fr":"Je veux de l'eau froide.","tgt":"Я хочу холодную воду.","ro":"Ya khachú khalódnuyu vódu.","lit":"je · veux · froide · eau [cas]"},{"fr":"Tu veux du bortsch ?","tgt":"Хочешь борщ?","ro":"Khóchesh' borshch?","lit":"veux · bortsch ?"},{"fr":"Ma femme veut une salade.","tgt":"Моя жена хочет салат.","ro":"Mayá zhená khóchet salát.","lit":"ma · femme · veut · salade"},{"fr":"Nous voulons regarder un film.","tgt":"Мы хотим посмотреть фильм.","ro":"My khatím pasmatrét' fil'm.","lit":"nous · voulons · regarder · film"},{"fr":"Je veux acheter une nouvelle lampe.","tgt":"Я хочу купить новую лампу.","ro":"Ya khachú kupít' nóvuyu lámpu.","lit":"je · veux · acheter · nouvelle · lampe [cas]"},{"fr":"Vous voulez du thé ou du café ?","tgt":"Вы хотите чай или кофе?","ro":"Vy khatíte chay íli kófe?","lit":"vous · voulez · thé · ou · café ?"},{"fr":"Je veux finir ce livre.","tgt":"Я хочу прочитать эту книгу.","ro":"Ya khachú prachitát' étu knígu.","lit":"je · veux · lire jusqu'au bout · ce · livre [cas]"},{"fr":"Les enfants veulent une glace.","tgt":"Дети хотят мороженое.","ro":"Déti khatyát marózhenaye.","lit":"enfants · veulent · glace"},{"fr":"Je veux du pain noir et du fromage.","tgt":"Я хочу чёрный хлеб и сыр.","ro":"Ya khachú chyórnyy khleb i syr.","lit":"je · veux · noir · pain · et · fromage"},{"fr":"Tu veux venir dîner chez nous ?","tgt":"Хочешь прийти к нам на ужин?","ro":"Khóchesh' priytí k nam na úzhin?","lit":"veux · venir · chez · nous · pour · dîner ?"}],"tip":{"title":"« Khachú » : je veux, et le complément d'objet","example":"Je veux de l'eau froide. — Я <b>хочу</b> холодную <b>воду</b>.","body":"Pour dire ce qu'on veut, on utilise « khachú », je veux. Les autres formes sont « khóchesh' », tu veux, « khóchet », il veut, « khatím », nous voulons, et « khatíte », vous voulez. Après ce verbe, on peut mettre un verbe à l'infinitif, comme « Ya khachú kupít' », je veux acheter, ou directement une chose. Et là, une petite surprise pour l'oreille : les mots féminins changent leur « a » final en « ou ». « Vadá », l'eau, devient « vódu » : « Ya khachú vódu ». La lampe, « lámpa », devient « lámpu ». Les mots masculins comme « chay » ou « khleb » ne bougent pas, ce qui simplifie beaucoup la vie. « Ya khachú khalódnuyu vódu » se décompose en je, veux, froide, eau. Astuce : quand vous voulez une chose féminine, terminez par « ou », comme si vous l'attrapiez.","exampleRo":"Ya khachú khalódnuyu vódu.","lit":"je · veux · froide · eau [cas]"}},{"title":"Une soirée tranquille à la maison","phrases":[{"fr":"La soirée est très calme.","tgt":"Вечер очень тихий.","ro":"Vécher óchen' tíkhiy.","lit":"soirée · très · calme"},{"fr":"Moi aussi, j'aime le silence.","tgt":"Я тоже люблю тишину.","ro":"Ya tózhe lyublyú tishinú.","lit":"je · aussi · aime · silence [cas]"},{"fr":"Le thé est très chaud.","tgt":"Чай очень горячий.","ro":"Chay óchen' garyáchiy.","lit":"thé · très · chaud"},{"fr":"Ma femme lit, et moi aussi.","tgt":"Жена читает, и я тоже.","ro":"Zhená chitáyet, i ya tózhe.","lit":"femme · lit · et · je · aussi"},{"fr":"Ce film est très drôle.","tgt":"Этот фильм очень смешной.","ro":"État fil'm óchen' smeshnóy.","lit":"ce · film · très · drôle"},{"fr":"Le chat dort, lui aussi.","tgt":"Кот тоже спит.","ro":"Kot tózhe spit.","lit":"chat · aussi · dort"},{"fr":"J'aime beaucoup les soirées tranquilles à la maison.","tgt":"Я очень люблю тихие вечера дома.","ro":"Ya óchen' lyublyú tíkhiye vecherá dóma.","lit":"je · très · aime · calmes · soirées · à la maison"},{"fr":"On est vraiment bien ici.","tgt":"Нам здесь очень хорошо.","ro":"Nam zdes' óchen' kharashó.","lit":"à nous · ici · très · bien"},{"fr":"Les voisins aussi sont calmes ce soir.","tgt":"Соседи сегодня тоже тихие.","ro":"Sasédi sevódnya tózhe tíkhiye.","lit":"voisins · aujourd'hui · aussi · calmes"},{"fr":"Cette musique est très belle.","tgt":"Эта музыка очень красивая.","ro":"Éta múzyka óchen' krasívaya.","lit":"cette · musique · très · belle"}],"tip":{"title":"« Tózhe » et « óchen' » : aussi et très","example":"Moi aussi, j'aime le silence. — Я <b>тоже</b> люблю тишину.","body":"Deux petits mots vont rendre vos phrases beaucoup plus vivantes. « Óchen' » veut dire très, ou beaucoup, et se place juste devant le mot qu'il renforce : « óchen' tíkhiy », très calme, ou « Ya óchen' lyublyú », j'aime beaucoup. « Tózhe » veut dire aussi, et il se place en général juste après la personne dont on parle. « Ya tózhe lyublyú tishinú » se décompose en je, aussi, aime, silence : moi aussi, j'aime le silence. Pour répondre très vite à quelqu'un, il suffit de dire « Ya tózhe », moi aussi. Dans les deux mots, la force est sur la première syllabe : « Ó-chen' », « TÓ-zhe ». Le petit adoucissement à la fin de « óchen' » ressemble au son de « gn » dans peigne, à peine esquissé. Astuce : « óchen' » monte le volume, « tózhe » vous met dans le même bateau.","exampleRo":"Ya tózhe lyublyú tishinú.","lit":"je · aussi · aime · silence [cas]"}},{"title":"Fin du module : un bilan","phrases":[{"fr":"Merci beaucoup pour votre aide !","tgt":"Большое спасибо за помощь!","ro":"Bal'shóye spasíba za pómashch'!","lit":"grand · merci · pour · aide"},{"fr":"Je vous en prie, avec plaisir.","tgt":"Пожалуйста, с удовольствием.","ro":"Pazhálsta, s udavól'stviyem.","lit":"je vous en prie · avec · plaisir [cas]"},{"fr":"Excusez-moi, je suis en retard.","tgt":"Извините, я опаздываю.","ro":"Izviníte, ya apázdyvayu.","lit":"excusez · je · suis en retard"},{"fr":"Ce n'est rien, ne vous inquiétez pas.","tgt":"Ничего, не волнуйтесь.","ro":"Nichevó, ne valnúytes'.","lit":"rien · [ne… pas] · inquiétez-vous"},{"fr":"J'apprends le russe depuis un mois.","tgt":"Я учу русский язык уже месяц.","ro":"Ya uchú rússkiy yazýk uzhé mésyats.","lit":"je · apprends · russe · langue · déjà · mois"},{"fr":"Je parle déjà un peu russe.","tgt":"Я уже немного говорю по-русски.","ro":"Ya uzhé nemnóga gavaryú pa-rússki.","lit":"je · déjà · un peu · parle · à la russe"},{"fr":"Le russe n'est pas si difficile.","tgt":"Русский язык не такой уж трудный.","ro":"Rússkiy yazýk ne takóy uzh trúdnyy.","lit":"russe · langue · [ne… pas] · si · vraiment · difficile"},{"fr":"Je connais les salutations et les chiffres.","tgt":"Я знаю приветствия и цифры.","ro":"Ya znáyu privétstviya i tsífry.","lit":"je · connais · salutations · et · chiffres"},{"fr":"Encore une fois, s'il vous plaît, plus lentement.","tgt":"Ещё раз, пожалуйста, помедленнее.","ro":"Yeshchyó raz, pazhálsta, pamédlenneye.","lit":"encore · fois · s'il vous plaît · plus lentement"},{"fr":"Merci, et à très bientôt à Moscou !","tgt":"Спасибо, и до скорой встречи в Москве!","ro":"Spasíba, i da skóray vstréchi v Maskvé!","lit":"merci · et · jusqu'à · proche · rencontre · à · Moscou"}],"tip":{"title":"Les formules magiques : « spasíba », « pazhálsta », « izviníte », « nichevó »","example":"Merci beaucoup pour votre aide ! — Большое <b>спасибо</b> за помощь!","body":"Quatre petits mots vous ouvriront toutes les portes. « Spasíba » veut dire merci, avec la force sur « sí », et « Bal'shóye spasíba » veut dire un grand merci, mot à mot grand merci. « Pazhálsta » est un mot à double usage : il veut dire s'il vous plaît quand on demande, et je vous en prie quand on répond à un merci. À l'oral, il se raccourcit presque toujours en « pazhálsta », en trois syllabes. « Izviníte » veut dire excusez-moi, pour aborder quelqu'un ou s'excuser. Et « nichevó », mot à mot rien, veut dire ce n'est rien, ce n'est pas grave. Remarquez que dans « nichevó », on prononce un « v » au milieu du mot. Bravo pour ce premier module ! Astuce : dites « spasíba » à chaque personne que vous croisez aujourd'hui, même en pensée.","exampleRo":"Bal'shóye spasíba za pómashch'!","lit":"grand · merci · pour · aide"}}]},{"id":2,"name":"En voyage","desc":"Se déplacer, découvrir et gérer les imprévus en Russie.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à Saint-Pétersbourg","phrases":[{"fr":"Enfin, voici Saint-Pétersbourg !","tgt":"Наконец, вот и Петербург!","ro":"Nakanéts, vot i Peterbúrk!","lit":"enfin · voici · [et] · Pétersbourg"},{"fr":"Le train arrive à la gare Moskovski.","tgt":"Поезд прибывает на Московский вокзал.","ro":"Póyezt pribyváyet na Maskófskiy vagzál.","lit":"train · arrive · sur · de-Moscou · gare"},{"fr":"Pardon, la sortie de la gare, c'est où ?","tgt":"Где выход, пожалуйста?","ro":"Gde výkhat, pazhálsta?","lit":"où · sortie · s'il-vous-plaît"},{"fr":"La sortie est là-bas, à droite.","tgt":"Выход там, справа.","ro":"Výkhat tam, správa.","lit":"sortie · là-bas · à-droite"},{"fr":"J'ai une grosse valise.","tgt":"У меня большой чемодан.","ro":"U menyá bal'shóy chemadán.","lit":"[chez moi] (u menya) · grosse · valise"},{"fr":"Mon hôtel est-il près de la gare ?","tgt":"Моя гостиница рядом с вокзалом?","ro":"Mayá gastínitsa ryádam s vagzálam?","lit":"mon · hôtel · à-côté · avec · gare [cas]"},{"fr":"Oui, à cinq petites minutes à pied.","tgt":"Да, пять минут пешком.","ro":"Da, pyat' minút peshkóm.","lit":"oui · cinq · minutes · à-pied"},{"fr":"Le matin, il fait frais à Pétersbourg.","tgt":"Утром в Петербурге прохладно.","ro":"Útram v Peterbúrge prakhládna.","lit":"le-matin · à · Pétersbourg · frais"},{"fr":"Je cherche la station de taxis.","tgt":"Я ищу стоянку такси.","ro":"Ya ishchú stayánku taksí.","lit":"je · cherche · station · taxi"},{"fr":"Bienvenue à Saint-Pétersbourg !","tgt":"Добро пожаловать в Санкт-Петербург!","ro":"Dabró pazhálavat' v Sankt-Peterbúrk!","lit":"bien · venir · à · Saint-Pétersbourg"}]},{"title":"Un programme pour trois jours","phrases":[{"fr":"Aujourd'hui, je suis à Saint-Pétersbourg.","tgt":"Сегодня я в Петербурге.","ro":"Sevódnya ya v Peterbúrge.","lit":"aujourd'hui · je · à · Pétersbourg"},{"fr":"Demain, je vais au musée.","tgt":"Завтра я иду в музей.","ro":"Záftra ya idú v muzéy.","lit":"demain · je · vais [à pied] · dans · musée"},{"fr":"Hier, j'étais à Moscou.","tgt":"Вчера я был в Москве.","ro":"Vcherá ya byl v Maskvé.","lit":"hier · je · étais · à · Moscou"},{"fr":"Aujourd'hui, il fait doux sur la Neva.","tgt":"Сегодня на Неве тепло.","ro":"Sevódnya na Nevé tepló.","lit":"aujourd'hui · sur · Neva · doux"},{"fr":"Et demain, quel est le programme ?","tgt":"А завтра какая программа?","ro":"A záftra kakáya pragrámma?","lit":"et · demain · quel · programme"},{"fr":"Demain, nous partons pour Peterhof.","tgt":"Завтра мы едем в Петергоф.","ro":"Záftra my yédem v Petergóf.","lit":"demain · nous · allons [en véhicule] · à · Peterhof"},{"fr":"Hier, nous étions sur la perspective Nevski.","tgt":"Вчера мы были на Невском проспекте.","ro":"Vcherá my býli na Névskam praspékte.","lit":"hier · nous · étions · sur · Nevski · perspective"},{"fr":"Le musée est fermé aujourd'hui ?","tgt":"Музей сегодня закрыт?","ro":"Muzéy sevódnya zakrýt?","lit":"musée · aujourd'hui · fermé"},{"fr":"Non, il est fermé seulement demain.","tgt":"Нет, он закрыт только завтра.","ro":"Net, on zakrýt tól'ka záftra.","lit":"non · il · fermé · seulement · demain"},{"fr":"Alors aujourd'hui, on va au musée !","tgt":"Тогда сегодня идём в музей!","ro":"Tagdá sevódnya idyóm v muzéy!","lit":"alors · aujourd'hui · allons [à pied] · dans · musée"}],"tip":{"title":"« Sevódnya », « záftra », « vcherá » : aujourd'hui, demain, hier","example":"Hier, j'étais à Moscou. — <b>Вчера</b> я был в Москве.","body":"Pour situer une action dans le temps, le russe utilise trois petits mots très fréquents : « sevódnya » pour aujourd'hui, « záftra » pour demain et « vcherá » pour hier. Attention à « sevódnya » : on prononce bien un v au milieu, se-VOD-nya, avec la force sur la deuxième syllabe. « Záftra » se dit avec un f et la force au début, alors que « vcherá » porte la force tout à la fin. Comme en français, ces mots se placent volontiers en tête de phrase : « Vcherá ya byl v Maskvé », mot à mot hier, je, étais, à Moscou. Au présent, pas besoin de verbe être : « Sevódnya ya v Peterbúrge », littéralement aujourd'hui moi à Pétersbourg, veut dire aujourd'hui je suis à Pétersbourg. Retenez aussi la petite question « A záftra ? », et demain ?, parfaite pour parler du programme. Astuce : « vcherá » finit sur un a bien fort, comme un souvenir qui claque, tandis que « záftra » démarre fort, comme un projet plein d'élan.","exampleRo":"Vcherá ya byl v Maskvé.","lit":"hier · je · étais · à · Moscou"}},{"title":"À la réception de l'hôtel","phrases":[{"fr":"Bonsoir, j'ai une chambre réservée au nom de Martin.","tgt":"Добрый вечер, у меня бронь на имя Мартен.","ro":"Dóbryy vécher, u menyá bron' na ímya Martén.","lit":"bon · soir · [chez moi] (u menya) · réservation · sur · nom · Martin"},{"fr":"Votre passeport, je vous prie.","tgt":"Ваш паспорт, пожалуйста.","ro":"Vash páspart, pazhálsta.","lit":"votre · passeport · s'il-vous-plaît"},{"fr":"Voici mon passeport français.","tgt":"Вот мой французский паспорт.","ro":"Vot moy frantsúskiy páspart.","lit":"voici · mon · français · passeport"},{"fr":"Votre chambre se trouve au troisième étage.","tgt":"Ваш номер на третьем этаже.","ro":"Vash nómer na trét'yem etazhé.","lit":"votre · chambre · sur · troisième · étage"},{"fr":"Voici la clé de votre chambre.","tgt":"Вот ключ от номера.","ro":"Vot klyuch at nómera.","lit":"voici · clé · de · chambre"},{"fr":"Et le petit-déjeuner, c'est à quelle heure ?","tgt":"А во сколько завтрак?","ro":"A va skól'ka záftrak?","lit":"et · à · combien · petit-déjeuner"},{"fr":"De sept heures à dix heures.","tgt":"С семи до десяти.","ro":"S semí da desyatí.","lit":"de · sept · jusqu'à · dix"},{"fr":"Il y a le wifi dans la chambre ?","tgt":"В номере есть вайфай?","ro":"V nómere yest' vayfáy?","lit":"dans · chambre · [il y a] (yest') · wifi"},{"fr":"Oui, le mot de passe est sur la petite carte.","tgt":"Да, пароль на карточке.","ro":"Da, paról' na kártachke.","lit":"oui · mot-de-passe · sur · petite-carte"},{"fr":"Les fenêtres donnent sur le canal.","tgt":"Окна выходят на канал.","ro":"Ókna vykhódyat na kanál.","lit":"fenêtres · donnent · sur · canal"}]},{"title":"Au petit-déjeuner de l'hôtel","phrases":[{"fr":"Je peux m'asseoir à cette table ?","tgt":"За этот столик можно сесть?","ro":"Za état stólik mózhna sest'?","lit":"à · cette · petite-table · [on peut] (mozhna) · s'asseoir"},{"fr":"Bien sûr, je vous en prie, asseyez-vous.","tgt":"Конечно, садитесь, пожалуйста.","ro":"Kanéshna, sadítes', pazhálsta.","lit":"bien-sûr · asseyez-vous · s'il-vous-plaît"},{"fr":"Je peux avoir du thé, s'il vous plaît ?","tgt":"Можно чай, пожалуйста?","ro":"Mózhna chay, pazhálsta?","lit":"[on peut] (mozhna) · thé · s'il-vous-plaît"},{"fr":"Avec du citron ?","tgt":"С лимоном?","ro":"S limónam?","lit":"avec · citron [cas]"},{"fr":"Oui, et je peux avoir des blinis aussi ?","tgt":"Да, и можно ещё блины?","ro":"Da, i mózhna yeshchyó bliný?","lit":"oui · et · [on peut] · encore · blinis"},{"fr":"Je peux régler par carte ?","tgt":"Можно картой?","ro":"Mózhna kártay?","lit":"[on peut] · carte [cas]"},{"fr":"Est-ce que je peux laisser la valise ici ?","tgt":"Можно оставить здесь чемодан?","ro":"Mózhna astávit' zdes' chemadán?","lit":"[on peut] · laisser · ici · valise"},{"fr":"Non, ici, ce n'est pas permis.","tgt":"Нет, здесь нельзя.","ro":"Net, zdes' nel'zyá.","lit":"non · ici · [on ne peut pas] (nel'zya)"},{"fr":"On peut prendre des photos dans le hall ?","tgt":"В холле можно фотографировать?","ro":"V khólle mózhna fatagrafíravat'?","lit":"dans · hall · [on peut] · photographier"},{"fr":"Oui, bien sûr, vous pouvez.","tgt":"Да, конечно, можно.","ro":"Da, kanéshna, mózhna.","lit":"oui · bien-sûr · [on peut]"}],"tip":{"title":"« Mózhna » : est-ce que je peux, poliment","example":"Je peux avoir du thé, s'il vous plaît ? — <b>Можно</b> чай, пожалуйста?","body":"Voici sans doute le mot le plus utile du voyageur : « mózhna ». Il veut dire à peu près c'est possible, on peut, et il sert à demander poliment presque tout. On le prononce MOZH-na, avec la force sur la première syllabe et un a léger à la fin. Le plus beau, c'est qu'il n'a pas besoin de « je » : on dit simplement « mózhna » suivi de ce qu'on veut. « Mózhna chay ? », mot à mot possible, thé, signifie est-ce que je peux avoir du thé. Avec un verbe, c'est pareil : « Mózhna sest' ? », je peux m'asseoir ?, ou « Mózhna kártay ? », je peux payer par carte ? Ajoutez « pazhálsta », s'il vous plaît, et vous êtes parfaitement poli. Pour répondre oui, on reprend simplement « mózhna », et pour refuser, on dit « nel'zyá », ce n'est pas permis. Astuce : pensez à « mózhna » comme à une porte qu'on entrouvre gentiment avant d'entrer.","exampleRo":"Mózhna chay, pazhálsta?","lit":"[on peut] (mozhna) · thé · s'il-vous-plaît"}},{"title":"Des roubles en poche","phrases":[{"fr":"Où peut-on changer de l'argent près d'ici ?","tgt":"Где здесь можно поменять деньги?","ro":"Gde zdes' mózhna pamenyát' dén'gi?","lit":"où · ici · [on peut] · changer · argent"},{"fr":"Il y a une banque sur la place.","tgt":"На площади есть банк.","ro":"Na plóshchadi yest' bank.","lit":"sur · place · [il y a] (yest') · banque"},{"fr":"Je voudrais changer de l'argent en roubles.","tgt":"Я хочу поменять деньги на рубли.","ro":"Ya khachú pamenyát' dén'gi na rublí.","lit":"je · veux · changer · argent · en · roubles"},{"fr":"Il faut un passeport pour ça ?","tgt":"Нужен паспорт?","ro":"Núzhen páspart?","lit":"[il faut] (nuzhen) · passeport"},{"fr":"Le distributeur est à côté de l'entrée.","tgt":"Банкомат рядом со входом.","ro":"Bankamát ryádam sa fkhódam.","lit":"distributeur · à-côté · avec · entrée [cas]"},{"fr":"Oh, ma carte ne fonctionne pas.","tgt":"Ой, моя карта не работает.","ro":"Oy, mayá kárta ne rabótayet.","lit":"oh · ma · carte · [ne… pas] (ne) · fonctionne"},{"fr":"Essayez encore une fois.","tgt":"Попробуйте ещё раз.","ro":"Papróbuyte yeshchyó ras.","lit":"essayez · encore · fois"},{"fr":"Ça marche, voilà les roubles !","tgt":"Работает, вот рубли!","ro":"Rabótayet, vot rublí!","lit":"fonctionne · voici · roubles"},{"fr":"J'ai deux mille roubles.","tgt":"У меня две тысячи рублей.","ro":"U menyá dve týsyachi rubléy.","lit":"[chez moi] (u menya) · deux · mille · roubles"},{"fr":"Pour aujourd'hui, ça suffit.","tgt":"На сегодня хватит.","ro":"Na sevódnya khvátit.","lit":"pour · aujourd'hui · suffit"}]},{"title":"Acheter des souvenirs","phrases":[{"fr":"Combien coûte cette matriochka ?","tgt":"Сколько стоит эта матрёшка?","ro":"Skól'ka stóit éta matryóshka?","lit":"combien · coûte · cette · matriochka"},{"fr":"Elle coûte mille roubles.","tgt":"Она стоит тысячу рублей.","ro":"Aná stóit týsyachu rubléy.","lit":"elle · coûte · mille · roubles"},{"fr":"Oh, c'est un peu cher pour moi.","tgt":"Ой, для меня это дороговато.","ro":"Oy, dlya menyá éta daragaváta.","lit":"oh · pour · moi · c'est · un-peu-cher"},{"fr":"Et celle-ci, combien elle coûte ?","tgt":"А эта сколько стоит?","ro":"A éta skól'ka stóit?","lit":"et · celle-ci · combien · coûte"},{"fr":"Celle-ci coûte trois cents roubles.","tgt":"Эта стоит триста рублей.","ro":"Éta stóit trísta rubléy.","lit":"celle-ci · coûte · trois-cents · roubles"},{"fr":"Combien coûtent ces cartes postales ?","tgt":"Сколько стоят эти открытки?","ro":"Skól'ka stóyat éti atkrýtki?","lit":"combien · coûtent · ces · cartes-postales"},{"fr":"Cent roubles pièce.","tgt":"Сто рублей за штуку.","ro":"Sto rubléy za shtúku.","lit":"cent · roubles · pour · pièce"},{"fr":"Je prends deux cartes et la petite matriochka.","tgt":"Я беру две открытки и маленькую матрёшку.","ro":"Ya berú dve atkrýtki i málen'kuyu matryóshku.","lit":"je · prends · deux · cartes · et · petite · matriochka"},{"fr":"Et ça fait combien, au total ?","tgt":"А сколько всего?","ro":"A skól'ka fsevó?","lit":"et · combien · en-tout"},{"fr":"Cinq cents roubles, s'il vous plaît.","tgt":"Пятьсот рублей, пожалуйста.","ro":"Pyat'sót rubléy, pazhálsta.","lit":"cinq-cents · roubles · s'il-vous-plaît"}],"tip":{"title":"« Skól'ka stóit ? » : demander un prix en roubles","example":"Combien coûte cette matriochka ? — <b>Сколько стоит</b> эта матрёшка?","body":"Pour demander un prix, une seule formule suffit : « Skól'ka stóit ? », combien ça coûte ? « Skól'ka » veut dire combien, et « stóit » veut dire coûte. Notez la prononciation : on écrit un o à la fin de « skól'ka », mais on dit un a, car en russe un o sans force se prononce a. Il suffit d'ajouter l'objet derrière : « Skól'ka stóit éta matryóshka ? », mot à mot combien, coûte, cette, matriochka. Quand il y a plusieurs objets, le verbe change un peu : « Skól'ka stóyat éti atkrýtki ? », combien coûtent ces cartes postales ? Pour le total, demandez simplement « Skól'ka fsevó ? », combien en tout ? Côté réponse, écoutez le mot rouble, qui change de forme selon le nombre : « adín rubl' », un rouble, mais « sto rubléy », cent roubles, et « dve týsyachi rubléy », deux mille roubles. Astuce : « stóit » ressemble à « c'est toi » dit vite, comme si vous demandiez à l'objet combien il vaut.","exampleRo":"Skól'ka stóit éta matryóshka?","lit":"combien · coûte · cette · matriochka"}},{"title":"Sur la perspective Nevski","phrases":[{"fr":"La perspective Nevski est très longue.","tgt":"Невский проспект очень длинный.","ro":"Névskiy praspékt óchen' dlínnyy.","lit":"Nevski · perspective · très · longue"},{"fr":"Le soir, il y a beaucoup de monde ici.","tgt":"Вечером здесь много людей.","ro":"Vécheram zdes' mnóga lyudéy.","lit":"le-soir · ici · beaucoup · gens"},{"fr":"Regardez, quelle belle maison !","tgt":"Посмотрите, какой красивый дом!","ro":"Pasmatríte, kakóy krasívyy dom!","lit":"regardez · quelle · belle · maison"},{"fr":"C'est une grande librairie.","tgt":"Это большой книжный магазин.","ro":"Éta bal'shóy knízhnyy magazín.","lit":"c'est · grand · de-livres · magasin"},{"fr":"Je voudrais acheter un livre en russe.","tgt":"Я хочу купить книгу на русском.","ro":"Ya khachú kupít' knígu na rússkam.","lit":"je · veux · acheter · livre · en · russe"},{"fr":"Il y a un café à côté ?","tgt":"Рядом есть кафе?","ro":"Ryádam yest' kafé?","lit":"à-côté · [il y a] (yest') · café"},{"fr":"Oui, juste en face.","tgt":"Да, прямо напротив.","ro":"Da, pryáma naprótif.","lit":"oui · juste · en-face"},{"fr":"Pour moi, un café et une part de gâteau.","tgt":"Мне кофе и кусок торта.","ro":"Mne kófe i kusók tórta.","lit":"à-moi · café · et · morceau · gâteau"},{"fr":"Le soir, la perspective est toute illuminée.","tgt":"Вечером проспект весь в огнях.","ro":"Vécheram praspékt ves' v agnyákh.","lit":"le-soir · perspective · toute · dans · lumières"},{"fr":"Pétersbourg est vraiment très beau.","tgt":"Петербург очень красивый.","ro":"Peterbúrk óchen' krasívyy.","lit":"Pétersbourg · très · beau"}]},{"title":"Où êtes-vous ?","phrases":[{"fr":"Allô, vous êtes où ?","tgt":"Алло, вы где?","ro":"Alló, vy gde?","lit":"allô · vous · où"},{"fr":"Je suis sur la perspective Nevski.","tgt":"Я на Невском проспекте.","ro":"Ya na Névskam praspékte.","lit":"je · sur · Nevski · perspective"},{"fr":"Et vous, vous êtes à l'hôtel ?","tgt":"А вы в гостинице?","ro":"A vy v gastínitse?","lit":"et · vous · dans · hôtel"},{"fr":"Non, je suis au musée.","tgt":"Нет, я в музее.","ro":"Net, ya v muzéye.","lit":"non · je · dans · musée"},{"fr":"Ma femme est à la gare.","tgt":"Моя жена на вокзале.","ro":"Mayá zhená na vagzále.","lit":"ma · femme · sur · gare"},{"fr":"Nos amis sont au restaurant.","tgt":"Наши друзья в ресторане.","ro":"Náshi druz'yá v restaráne.","lit":"nos · amis · dans · restaurant"},{"fr":"Ce soir, nous sommes au concert.","tgt":"Вечером мы на концерте.","ro":"Vécheram my na kantsérte.","lit":"le-soir · nous · sur · concert"},{"fr":"Demain, je serai à Moscou.","tgt":"Завтра я в Москве.","ro":"Záftra ya v Maskvé.","lit":"demain · je · à · Moscou"},{"fr":"Moscou ? C'est loin d'ici !","tgt":"Москва? Это далеко отсюда!","ro":"Maskvá? Éta dalekó atsyúda!","lit":"Moscou · c'est · loin · d'ici"},{"fr":"Oui, mais mon frère habite à Moscou.","tgt":"Да, но мой брат живёт в Москве.","ro":"Da, no moy brat zhivyót v Maskvé.","lit":"oui · mais · mon · frère · habite · à · Moscou"}],"tip":{"title":"« V » et « na » : être quelque part, « v Maskvé »","example":"Oui, mais mon frère habite à Moscou. — Да, но мой брат живёт <b>в Москве</b>.","body":"Pour dire où l'on est, le russe utilise deux petits mots : « v », qui veut dire dans, et « na », qui veut dire sur. On met « v » pour les lieux fermés et pour les villes : « v muzéye », au musée, « v gastínitse », à l'hôtel, « v Maskvé », à Moscou. On met « na » pour les rues, les places, les gares et les événements : « na Névskam praspékte », sur la perspective Nevski, « na vagzále », à la gare, « na kantsérte », au concert. Écoutez bien la fin du mot : après « v » et « na », elle se transforme le plus souvent en un e. « Maskvá » devient « v Maskvé », « muzéy » devient « v muzéye ». Et rappelez-vous qu'au présent, pas de verbe être : « Ya v muzéye », mot à mot moi, dans, musée, veut dire je suis au musée. Le petit « v » se prononce collé au mot suivant, comme une seule syllabe. Astuce : imaginez que vous êtes dedans avec « v », et posé dessus avec « na ».","exampleRo":"Da, no moy brat zhivyót v Maskvé.","lit":"oui · mais · mon · frère · habite · à · Moscou"}},{"title":"Les canaux et les ponts","phrases":[{"fr":"Pétersbourg a beaucoup de canaux.","tgt":"В Петербурге много каналов.","ro":"V Peterbúrge mnóga kanálaf.","lit":"à · Pétersbourg · beaucoup · canaux"},{"fr":"Et aussi des centaines de ponts.","tgt":"И ещё сотни мостов.","ro":"I yeshchyó sótni mastóf.","lit":"et · encore · centaines · ponts"},{"fr":"On fait une promenade en bateau ?","tgt":"Покатаемся на катере?","ro":"Pakatáyemsya na kátere?","lit":"[nous] promenons-nous · sur · bateau"},{"fr":"Bonne idée, le bateau part à midi.","tgt":"Хорошая идея, катер отходит в двенадцать.","ro":"Kharóshaya idéya, káter atkhódit v dvenátsat'.","lit":"bonne · idée · bateau · part · à · douze"},{"fr":"Et le billet, c'est combien ?","tgt":"А билет сколько стоит?","ro":"A bilét skól'ka stóit?","lit":"et · billet · combien · coûte"},{"fr":"L'eau est calme aujourd'hui.","tgt":"Вода сегодня спокойная.","ro":"Vadá sevódnya spakóynaya.","lit":"eau · aujourd'hui · calme"},{"fr":"Regardez comme ce pont est bas !","tgt":"Смотрите, какой низкий мост!","ro":"Smatríte, kakóy nískiy most!","lit":"regardez · quel · bas · pont"},{"fr":"La nuit, on ouvre les ponts.","tgt":"Ночью мосты разводят.","ro":"Nóch'yu mastý razvódyat.","lit":"la-nuit · ponts · [on] ouvre"},{"fr":"C'est très beau, surtout en été.","tgt":"Это очень красиво, особенно летом.","ro":"Éta óchen' krasíva, asóbenna létam.","lit":"c'est · très · beau · surtout · en-été"},{"fr":"On reste sur le quai jusqu'à une heure du matin ?","tgt":"Останемся на набережной до часа ночи?","ro":"Astánemsya na náberezhnay da chása nóchi?","lit":"[nous] restons · sur · quai · jusqu'à · heure · nuit"}]},{"title":"À pied ou en taxi ?","phrases":[{"fr":"Je vais au musée à pied.","tgt":"Я иду в музей пешком.","ro":"Ya idú v muzéy peshkóm.","lit":"je · vais [à pied] · dans · musée · à-pied"},{"fr":"Et vous, vous y allez en taxi ?","tgt":"А вы едете на такси?","ro":"A vy yédete na taksí?","lit":"et · vous · allez [en véhicule] · sur · taxi"},{"fr":"Non, moi aussi, je marche.","tgt":"Нет, я тоже иду пешком.","ro":"Net, ya tózhe idú peshkóm.","lit":"non · je · aussi · vais [à pied] · à-pied"},{"fr":"Et ce soir, vous allez où ?","tgt":"А куда вы идёте вечером?","ro":"A kudá vy idyóte vécheram?","lit":"et · où · vous · allez [à pied] · le-soir"},{"fr":"Ce soir, je vais au théâtre.","tgt":"Вечером я иду в театр.","ro":"Vécheram ya idú v teátr.","lit":"le-soir · je · vais [à pied] · dans · théâtre"},{"fr":"Demain, je vais à Peterhof en bus.","tgt":"Завтра я еду в Петергоф на автобусе.","ro":"Záftra ya yédu v Petergóf na aftóbuse.","lit":"demain · je · vais [en véhicule] · à · Peterhof · sur · bus"},{"fr":"Nous allons à la gare en métro.","tgt":"Мы едем на вокзал на метро.","ro":"My yédem na vagzál na metró.","lit":"nous · allons [en véhicule] · sur · gare · sur · métro"},{"fr":"J'arrive à pied, dans dix minutes.","tgt":"Я иду, буду через десять минут.","ro":"Ya idú, búdu chéres désyat' minút.","lit":"je · vais [à pied] · [je] serai · dans · dix · minutes"},{"fr":"Mon ami y va en voiture.","tgt":"Мой друг едет на машине.","ro":"Moy druk yédet na mashíne.","lit":"mon · ami · va [en véhicule] · sur · voiture"},{"fr":"On marche ou on prend un taxi ?","tgt":"Идём пешком или едем на такси?","ro":"Idyóm peshkóm íli yédem na taksí?","lit":"allons [à pied] · à-pied · ou · allons [en véhicule] · sur · taxi"}],"tip":{"title":"« Ya idú » et « ya yédu » : aller à pied ou en véhicule","example":"On marche ou on prend un taxi ? — <b>Идём</b> пешком или <b>едем</b> на такси?","body":"En français, on dit je vais au musée, que l'on marche ou que l'on prenne le bus. Le russe, lui, fait toujours la différence. Si vous y allez à pied, vous dites « ya idú », je vais en marchant. Si vous utilisez un véhicule, bus, taxi, train ou voiture, vous dites « ya yédu », je vais en roulant. Les deux verbes ont la force sur la dernière syllabe pour « idú » et sur la première pour « yédu ». Avec vous, cela donne « vy idyóte » et « vy yédete », et avec nous, « my idyóm » et « my yédem ». Décomposons « Ya yédu v Petergóf na aftóbuse » : je, vais en véhicule, à, Peterhof, sur, bus. Très pratique aussi : « Idyóm ! » tout seul veut dire allons-y ! Astuce : « idú » est court et léger comme un pas, alors que « yédu » commence par un y qui glisse, comme des roues sur la route.","exampleRo":"Idyóm peshkóm íli yédem na taksí?","lit":"allons [à pied] · à-pied · ou · allons [en véhicule] · sur · taxi"}},{"title":"Au musée de l'Ermitage","phrases":[{"fr":"L'Ermitage est vraiment très grand.","tgt":"Эрмитаж очень большой.","ro":"Ermitásh óchen' bal'shóy.","lit":"Ermitage · très · grand"},{"fr":"Un billet adulte pour l'Ermitage, s'il vous plaît.","tgt":"Один взрослый билет в Эрмитаж, пожалуйста.","ro":"Adín vzróslyy bilét v Ermitásh, pazhálsta.","lit":"un · adulte · billet · dans · Ermitage · s'il-vous-plaît"},{"fr":"Il y a une réduction pour les étudiants ?","tgt":"Для студентов есть скидка?","ro":"Dlya studéntaf yest' skítka?","lit":"pour · étudiants · [il y a] (yest') · réduction"},{"fr":"Où est le vestiaire ?","tgt":"Где гардероб?","ro":"Gde garderóp?","lit":"où · vestiaire"},{"fr":"Il faut laisser son manteau au vestiaire.","tgt":"Пальто нужно сдать в гардероб.","ro":"Pal'tó núzhna zdat' v garderóp.","lit":"manteau · [il faut] · remettre · dans · vestiaire"},{"fr":"Les tableaux sont au deuxième étage.","tgt":"Картины на втором этаже.","ro":"Kartíny na ftaróm etazhé.","lit":"tableaux · sur · deuxième · étage"},{"fr":"Ce tableau est magnifique.","tgt":"Эта картина прекрасна.","ro":"Éta kartína prekrásna.","lit":"ce · tableau · magnifique"},{"fr":"Il y a un café dans le musée ?","tgt":"В музее есть кафе?","ro":"V muzéye yest' kafé?","lit":"dans · musée · [il y a] (yest') · café"},{"fr":"Des chats vivent à l'Ermitage, c'est vrai ?","tgt":"В Эрмитаже живут коты, это правда?","ro":"V Ermitázhe zhivút katý, éta právda?","lit":"dans · Ermitage · vivent · chats · c'est · vrai"},{"fr":"Oui, ce sont eux qui gardent le musée !","tgt":"Да, они охраняют музей!","ro":"Da, aní akhranyáyut muzéy!","lit":"oui · ils · gardent · musée"}]},{"title":"Demander son chemin","phrases":[{"fr":"Excusez-moi, où est le Musée russe ?","tgt":"Извините, где Русский музей?","ro":"Izviníte, gde Rússkiy muzéy?","lit":"excusez · où · russe · musée"},{"fr":"Allez tout droit, puis à gauche.","tgt":"Идите прямо, потом налево.","ro":"Idíte pryáma, patóm naléva.","lit":"allez · tout-droit · puis · à-gauche"},{"fr":"C'est à droite, après le pont.","tgt":"Это направо, после моста.","ro":"Éta napráva, pósle mastá.","lit":"c'est · à-droite · après · pont"},{"fr":"La gare, c'est à gauche ou à droite ?","tgt":"Вокзал налево или направо?","ro":"Vagzál naléva íli napráva?","lit":"gare · à-gauche · ou · à-droite"},{"fr":"Tout droit, puis la deuxième rue à droite.","tgt":"Прямо, потом вторая улица направо.","ro":"Pryáma, patóm ftaráya úlitsa napráva.","lit":"tout-droit · puis · deuxième · rue · à-droite"},{"fr":"Au feu, tournez à gauche.","tgt":"На светофоре налево.","ro":"Na svetafóre naléva.","lit":"sur · feu · à-gauche"},{"fr":"La pharmacie est tout droit, à cent mètres.","tgt":"Аптека прямо, через сто метров.","ro":"Aptéka pryáma, chéres sto métraf.","lit":"pharmacie · tout-droit · dans · cent · mètres"},{"fr":"Je ne comprends pas, à gauche ?","tgt":"Не понимаю, налево?","ro":"Ne panimáyu, naléva?","lit":"[ne… pas] (ne) · comprends · à-gauche"},{"fr":"Non, pas à gauche, à droite !","tgt":"Нет, не налево, а направо!","ro":"Net, ne naléva, a napráva!","lit":"non · [ne… pas] · à-gauche · mais · à-droite"},{"fr":"Ah, merci, maintenant c'est clair.","tgt":"Ага, спасибо, теперь понятно.","ro":"Agá, spasíba, tepér' panyátna.","lit":"ah · merci · maintenant · compréhensible"}],"tip":{"title":"« Naléva », « napráva », « pryáma » : demander son chemin","example":"Allez tout droit, puis à gauche. — Идите <b>прямо</b>, потом <b>налево</b>.","body":"Pour vous orienter en ville, trois mots suffisent : « naléva », à gauche, « napráva », à droite, et « pryáma », tout droit. Ils ne changent jamais de forme, quel que soit le reste de la phrase. Écoutez bien la prononciation : les o de la fin se disent a, et la force tombe au milieu, na-LE-va, na-PRA-va, et au début pour PRYA-ma. Pour poser la question, commencez par « Izviníte », excusez-moi, puis « gde », où, et le lieu : « Izviníte, gde vagzál ? », excusez-moi, où est la gare ? La réponse ressemblera souvent à « Idíte pryáma, patóm naléva », mot à mot allez, tout droit, puis, à gauche. Notez aussi le petit « patóm », puis, très utile pour enchaîner les indications. Si vous êtes perdu, dites simplement « Naléva ? » ou « Napráva ? » avec une intonation qui monte, et on vous répondra d'un geste. Astuce : « napráva » contient « práva », qui fait penser au mot français droit.","exampleRo":"Idíte pryáma, patóm naléva.","lit":"allez · tout-droit · puis · à-gauche"}},{"title":"Prendre un taxi","phrases":[{"fr":"Bonjour, à cette adresse, s'il vous plaît.","tgt":"Здравствуйте, вот по этому адресу, пожалуйста.","ro":"Zdrávstvuyte, vot pa étamu ádresu, pazhálsta.","lit":"bonjour · voici · selon · cette · adresse · s'il-vous-plaît"},{"fr":"On met combien de temps pour y aller ?","tgt":"Сколько ехать?","ro":"Skól'ka yékhat'?","lit":"combien · rouler"},{"fr":"Environ vingt minutes.","tgt":"Минут двадцать.","ro":"Minút dvátsat'.","lit":"minutes · vingt [ordre inversé = environ]"},{"fr":"Ce soir, il y a de gros bouchons.","tgt":"Сегодня вечером большие пробки.","ro":"Sevódnya vécheram bal'shíye própki.","lit":"aujourd'hui · le-soir · gros · bouchons"},{"fr":"Je peux mettre la valise dans le coffre ?","tgt":"Можно чемодан в багажник?","ro":"Mózhna chemadán v bagázhnik?","lit":"[on peut] · valise · dans · coffre"},{"fr":"Vous pouvez rouler un peu moins vite ?","tgt":"Можно помедленнее?","ro":"Mózhna pamédlenneye?","lit":"[on peut] · plus-lentement"},{"fr":"Arrêtez-vous ici, s'il vous plaît.","tgt":"Остановите здесь, пожалуйста.","ro":"Astanavíte zdes', pazhálsta.","lit":"arrêtez · ici · s'il-vous-plaît"},{"fr":"Combien je vous dois pour la course ?","tgt":"Сколько с меня за поездку?","ro":"Skól'ka s menyá za payéstku?","lit":"combien · de · moi · pour · trajet"},{"fr":"Quatre cents roubles.","tgt":"Четыреста рублей.","ro":"Chetýresta rubléy.","lit":"quatre-cents · roubles"},{"fr":"Tenez, gardez la monnaie.","tgt":"Вот, сдачи не надо.","ro":"Vot, zdáchi ne náda.","lit":"voici · monnaie · [ne… pas] · [il faut]"}]},{"title":"Une leçon de cuisine : les pelmeni","phrases":[{"fr":"Vous savez faire des pelmeni ?","tgt":"Вы умеете делать пельмени?","ro":"Vy uméyete délat' pel'méni?","lit":"vous · savez · faire · pelmeni"},{"fr":"Non, je ne sais pas cuisiner.","tgt":"Нет, я не умею готовить.","ro":"Net, ya ne uméyu gatóvit'.","lit":"non · je · [ne… pas] (ne) · sais · cuisiner"},{"fr":"Ce n'est rien, je peux vous montrer.","tgt":"Ничего, я могу показать.","ro":"Nichevó, ya magú pakazát'.","lit":"rien · je · peux · montrer"},{"fr":"Est-ce que je peux couper la viande ?","tgt":"Я могу порезать мясо?","ro":"Ya magú parézat' myása?","lit":"je · peux · couper · viande"},{"fr":"Oui, et votre femme peut préparer la pâte.","tgt":"Да, а ваша жена может сделать тесто.","ro":"Da, a vásha zhená mózhet zdélat' tésta.","lit":"oui · et · votre · femme · peut · faire · pâte"},{"fr":"Ma femme sait très bien cuisiner.","tgt":"Моя жена умеет вкусно готовить.","ro":"Mayá zhená uméyet fkúsna gatóvit'.","lit":"ma · femme · sait · délicieusement · cuisiner"},{"fr":"Mon fils sait compter en russe.","tgt":"Мой сын умеет считать по-русски.","ro":"Moy syn uméyet shchitát' pa-rússki.","lit":"mon · fils · sait · compter · en-russe"},{"fr":"Je ne peux pas, j'ai les mains sales !","tgt":"Я не могу, у меня грязные руки!","ro":"Ya ne magú, u menyá gryáznyye rúki!","lit":"je · [ne… pas] · peux · [chez moi] (u menya) · sales · mains"},{"fr":"Quand est-ce qu'on peut les manger ?","tgt":"Когда их можно есть?","ro":"Kagdá ikh mózhna yest'?","lit":"quand · les · [on peut] · manger"},{"fr":"Dans dix minutes, avec de la crème aigre.","tgt":"Через десять минут, со сметаной.","ro":"Chéres désyat' minút, sa smetánay.","lit":"dans · dix · minutes · avec · crème-aigre"}],"tip":{"title":"« Mogú » et « uméyu » : pouvoir et savoir faire","example":"Non, je ne sais pas cuisiner. — Нет, я не <b>умею</b> готовить.","body":"Le russe distingue clairement deux idées que le français mélange parfois. « Ya magú », je peux, parle de la possibilité du moment : j'ai le temps, j'ai les mains libres, rien ne m'en empêche. « Ya uméyu », je sais, parle d'un savoir-faire appris : nager, cuisiner, compter. Comparez « Ya ne magú, u menyá gryáznyye rúki », je ne peux pas, j'ai les mains sales, avec « Ya ne uméyu gatóvit' », je ne sais pas cuisiner. Dans le premier cas, c'est passager ; dans le second, c'est une compétence qui manque. Les deux verbes sont suivis directement d'un infinitif, comme en français : « magú pakazát' », je peux montrer, mot à mot peux, montrer. Avec vous, on dit « vy mózhete » et « vy uméyete ». Pour la prononciation, « magú » a la force à la fin et « uméyu » au milieu, u-MÉ-yu. Astuce : « uméyu » commence comme « humer » : on hume ce qu'on sait cuisiner.","exampleRo":"Net, ya ne uméyu gatóvit'.","lit":"non · je · [ne… pas] (ne) · sais · cuisiner"}},{"title":"Au restaurant : bortsch et pelmeni","phrases":[{"fr":"Bonsoir, une table pour deux près de la fenêtre ?","tgt":"Добрый вечер, столик на двоих у окна?","ro":"Dóbryy vécher, stólik na dvaíkh u akná?","lit":"bon · soir · petite-table · pour · deux · près · fenêtre"},{"fr":"Voici la carte, en russe et en français.","tgt":"Вот меню на русском и французском.","ro":"Vot menyú na rússkam i frantsúskam.","lit":"voici · menu · en · russe · et · français"},{"fr":"Pour moi, un bortsch, s'il vous plaît.","tgt":"Мне борщ, пожалуйста.","ro":"Mne borshch, pazhálsta.","lit":"à-moi · bortsch · s'il-vous-plaît"},{"fr":"Le bortsch est servi avec du pain noir.","tgt":"Борщ подают с чёрным хлебом.","ro":"Borshch padayút s chórnym khlébam.","lit":"bortsch · [on] sert · avec · noir · pain"},{"fr":"Et pour moi, des pelmeni.","tgt":"А мне пельмени.","ro":"A mne pel'méni.","lit":"et · à-moi · pelmeni"},{"fr":"Et comme boisson, qu'est-ce que vous prenez ?","tgt":"А что будете пить?","ro":"A shto búdete pit'?","lit":"et · quoi · [vous] serez · boire"},{"fr":"Un kvas bien frais, s'il vous plaît.","tgt":"Холодный квас, пожалуйста.","ro":"Khalódnyy kvas, pazhálsta.","lit":"froid · kvas · s'il-vous-plaît"},{"fr":"Le bortsch est vraiment délicieux !","tgt":"Борщ очень вкусный!","ro":"Borshch óchen' fkúsnyy!","lit":"bortsch · très · délicieux"},{"fr":"On peut avoir l'addition et un dernier thé ?","tgt":"Можно счёт и ещё чай?","ro":"Mózhna shchot i yeshchyó chay?","lit":"[on peut] · addition · et · encore · thé"},{"fr":"Merci, tout était très bon.","tgt":"Спасибо, всё было очень вкусно.","ro":"Spasíba, fsyo býla óchen' fkúsna.","lit":"merci · tout · était · très · bon"}]},{"title":"Dans le métro de Pétersbourg","phrases":[{"fr":"Je vais au musée en métro.","tgt":"Я еду в музей на метро.","ro":"Ya yédu v muzéy na metró.","lit":"je · vais [en véhicule] · dans · musée · sur · métro"},{"fr":"Le métro de Pétersbourg est très profond.","tgt":"Метро в Петербурге очень глубокое.","ro":"Metró v Peterbúrge óchen' glubókaye.","lit":"métro · à · Pétersbourg · très · profond"},{"fr":"L'escalator est si long !","tgt":"Эскалатор такой длинный!","ro":"Eskalátar takóy dlínnyy!","lit":"escalator · si · long"},{"fr":"Où peut-on acheter une carte de transport ?","tgt":"Где можно купить проездной?","ro":"Gde mózhna kupít' prayezdnóy?","lit":"où · [on peut] · acheter · carte-de-transport"},{"fr":"Ensuite, je continue en bus.","tgt":"Потом я еду на автобусе.","ro":"Patóm ya yédu na aftóbuse.","lit":"puis · je · vais [en véhicule] · sur · bus"},{"fr":"Vous allez à l'hôtel en tram ?","tgt":"Вы едете в гостиницу на трамвае?","ro":"Vy yédete v gastínitsu na tramváye?","lit":"vous · allez [en véhicule] · dans · hôtel · sur · tram"},{"fr":"Non, en taxi, c'est plus simple.","tgt":"Нет, на такси, так проще.","ro":"Net, na taksí, tak próshche.","lit":"non · sur · taxi · ainsi · plus-simple"},{"fr":"Demain, nous allons à Moscou en train.","tgt":"Завтра мы едем в Москву на поезде.","ro":"Záftra my yédem v Maskvú na póyezde.","lit":"demain · nous · allons [en véhicule] · à · Moscou · sur · train"},{"fr":"Voyager en train de nuit, c'est très pratique.","tgt":"Ехать на ночном поезде очень удобно.","ro":"Yékhat' na nachnóm póyezde óchen' udóbna.","lit":"rouler · sur · de-nuit · train · très · pratique"},{"fr":"Et à Moscou, on peut circuler à vélo ?","tgt":"А в Москве можно ездить на велосипеде?","ro":"A v Maskvé mózhna yézdit' na velasipéde?","lit":"et · à · Moscou · [on peut] · circuler · sur · vélo"}],"tip":{"title":"« Na » + transport : « na metró », « na póyezde »","example":"Demain, nous allons à Moscou en train. — Завтра мы едем в Москву <b>на поезде</b>.","body":"En français, on dit en métro, en bus, en train. En russe, on dit littéralement sur le métro, sur le bus, sur le train, avec le petit mot « na ». On se voit donc assis sur le véhicule plutôt que dedans. Comme après tout « na » qui indique un lieu, la fin du mot change souvent en e : « póyezd », le train, devient « na póyezde », et « aftóbus », le bus, devient « na aftóbuse ». Bonne nouvelle, certains mots ne changent jamais : « na metró », « na taksí ». Ce petit groupe se combine naturellement avec « yédu », je vais en véhicule : « Ya yédu v muzéy na metró », mot à mot je, vais en véhicule, dans, musée, sur, métro. Vous pouvez aussi l'utiliser seul pour répondre à une question : « Na taksí », en taxi. Astuce : imaginez-vous perché sur le toit du train, comme dans un film, et vous n'oublierez plus jamais « na ».","exampleRo":"Záftra my yédem v Maskvú na póyezde.","lit":"demain · nous · allons [en véhicule] · à · Moscou · sur · train"}},{"title":"Acheter un billet de train","phrases":[{"fr":"Je voudrais un billet pour Moscou.","tgt":"Мне билет до Москвы.","ro":"Mne bilét da Maskvý.","lit":"à-moi · billet · jusqu'à · Moscou"},{"fr":"Pour quelle date ?","tgt":"На какое число?","ro":"Na kakóye chisló?","lit":"pour · quelle · date"},{"fr":"Pour vendredi, le train de nuit.","tgt":"На пятницу, на ночной поезд.","ro":"Na pyátnitsu, na nachnóy póyezt.","lit":"pour · vendredi · pour · de-nuit · train"},{"fr":"Il reste des places en compartiment ?","tgt":"Есть места в купе?","ro":"Yest' mestá v kupé?","lit":"[il y a] (yest') · places · dans · compartiment"},{"fr":"Oui, il reste deux places.","tgt":"Да, осталось два места.","ro":"Da, astálas' dva mésta.","lit":"oui · [il] reste · deux · places"},{"fr":"Couchette du haut ou du bas ?","tgt":"Верхняя или нижняя полка?","ro":"Vérkhnyaya íli nízhnyaya pólka?","lit":"du-haut · ou · du-bas · couchette"},{"fr":"Celle du bas, s'il vous plaît.","tgt":"Нижнюю, пожалуйста.","ro":"Nízhnyuyu, pazhálsta.","lit":"du-bas · s'il-vous-plaît"},{"fr":"Le billet coûte quatre mille roubles.","tgt":"Билет стоит четыре тысячи рублей.","ro":"Bilét stóit chetýre týsyachi rubléy.","lit":"billet · coûte · quatre · mille · roubles"},{"fr":"Et le train part à quelle heure exactement ?","tgt":"А во сколько точно отправляется поезд?","ro":"A va skól'ka tóchna atpravlyáyetsa póyezt?","lit":"et · à · combien · exactement · part · train"},{"fr":"À vingt-trois heures dix.","tgt":"В двадцать три десять.","ro":"V dvátsat' tri désyat'.","lit":"à · vingt · trois · dix"}]},{"title":"Les environs de Pétersbourg","phrases":[{"fr":"Peterhof, c'est loin d'ici ?","tgt":"Петергоф далеко отсюда?","ro":"Petergóf dalekó atsyúda?","lit":"Peterhof · loin · d'ici"},{"fr":"Non, c'est assez près, une heure en bateau.","tgt":"Нет, довольно близко, час на катере.","ro":"Net, davól'na blízka, chas na kátere.","lit":"non · assez · près · heure · sur · bateau"},{"fr":"Le palais est près de l'embarcadère ?","tgt":"Дворец близко от пристани?","ro":"Dvaréts blízka at prístani?","lit":"palais · près · de · embarcadère"},{"fr":"Oui, tout près, à cinq minutes.","tgt":"Да, совсем близко, пять минут.","ro":"Da, safsém blízka, pyat' minút.","lit":"oui · tout-à-fait · près · cinq · minutes"},{"fr":"Les fontaines sont tout simplement merveilleuses !","tgt":"Фонтаны просто чудесные!","ro":"Fantány prósta chudésnyye!","lit":"fontaines · simplement · merveilleuses"},{"fr":"Et la ville de Pouchkine, c'est loin ?","tgt":"А город Пушкин далеко?","ro":"A górat Púshkin dalekó?","lit":"et · ville · Pouchkine · loin"},{"fr":"Assez loin, il faut prendre le bus.","tgt":"Довольно далеко, надо ехать на автобусе.","ro":"Davól'na dalekó, náda yékhat' na aftóbuse.","lit":"assez · loin · [il faut] · rouler · sur · bus"},{"fr":"Le métro est près de l'hôtel ?","tgt":"Метро близко от гостиницы?","ro":"Metró blízka at gastínitsy?","lit":"métro · près · de · hôtel"},{"fr":"Oui, la station est juste à côté.","tgt":"Да, станция совсем рядом.","ro":"Da, stántsiya safsém ryádam.","lit":"oui · station · tout-à-fait · à-côté"},{"fr":"Moscou, en revanche, c'est très loin !","tgt":"А вот Москва очень далеко!","ro":"A vot Maskvá óchen' dalekó!","lit":"et · voici · Moscou · très · loin"}],"tip":{"title":"« Dalekó » et « blízka » : loin et près","example":"Peterhof, c'est loin d'ici ? — Петергоф <b>далеко</b> отсюда?","body":"Avant de partir en excursion, on demande toujours si c'est loin. En russe, loin se dit « dalekó » et près se dit « blízka ». Attention à la force : elle tombe à la fin dans da-le-KO, mais au début dans BLIZ-ka, et le o final de « blízka » se prononce a. Pas besoin de verbe être ni de mot interrogatif : « Petergóf dalekó ? », avec une voix qui monte, veut dire Peterhof, c'est loin ? Pour préciser de quoi, ajoutez « at », de : « blízka at gastínitsy », mot à mot près, de, hôtel, c'est-à-dire près de l'hôtel. Pour nuancer, ajoutez « óchen' », très, « safsém », tout à fait, ou « davól'na », assez : « safsém blízka », tout près. Et pour dire juste à côté, on utilise aussi « ryádam ». Astuce : « dalekó » s'étire longuement vers la fin, comme une route qui n'en finit pas, alors que « blízka » est bref et sec, comme un pas.","exampleRo":"Petergóf dalekó atsyúda?","lit":"Peterhof · loin · d'ici"}},{"title":"Le train de nuit pour Moscou","phrases":[{"fr":"Notre train est sur la voie cinq.","tgt":"Наш поезд на пятом пути.","ro":"Nash póyezt na pyátam putí.","lit":"notre · train · sur · cinquième · voie"},{"fr":"Voici notre wagon, le numéro sept.","tgt":"Вот наш вагон, седьмой.","ro":"Vot nash vagón, sed'móy.","lit":"voici · notre · wagon · septième"},{"fr":"L'hôtesse du wagon vérifie les billets.","tgt":"Проводница проверяет билеты.","ro":"Pravadnítsa praveryáyet biléty.","lit":"hôtesse-de-wagon · vérifie · billets"},{"fr":"Le compartiment est petit mais douillet.","tgt":"Купе маленькое, но уютное.","ro":"Kupé málen'kaye, no uyútnaye.","lit":"compartiment · petit · mais · douillet"},{"fr":"Il y a du thé dans le train ?","tgt":"В поезде есть чай?","ro":"V póyezde yest' chay?","lit":"dans · train · [il y a] (yest') · thé"},{"fr":"Oui, le thé est servi dans un joli porte-verre.","tgt":"Да, чай подают в подстаканнике.","ro":"Da, chay padayút v patstakánnike.","lit":"oui · thé · [on] sert · dans · porte-verre"},{"fr":"Les draps sont déjà sur la couchette.","tgt":"Бельё уже на полке.","ro":"Bel'yó uzhé na pólke.","lit":"linge · déjà · sur · couchette"},{"fr":"Bonne nuit à tous, à demain matin !","tgt":"Всем спокойной ночи, до утра!","ro":"Fsem spakóynay nóchi, da utrá!","lit":"à-tous · calme · nuit · jusqu'à · matin"},{"fr":"Le train arrive à Moscou à huit heures du matin.","tgt":"Поезд приходит в Москву в восемь утра.","ro":"Póyezt prikhódit v Maskvú v vósem' utrá.","lit":"train · arrive · à · Moscou · à · huit · matin"},{"fr":"Bonjour Moscou ! Quel voyage merveilleux !","tgt":"Доброе утро, Москва! Какая чудесная поездка!","ro":"Dóbraye útra, Maskvá! Kakáya chudésnaya payéstka!","lit":"bon · matin · Moscou · quel · merveilleux · voyage"}]},{"title":"Fin du module : un bilan de voyage","phrases":[{"fr":"Mon séjour à Saint-Pétersbourg est terminé.","tgt":"Моя поездка в Петербург закончилась.","ro":"Mayá payéstka v Peterbúrk zakónchilas'.","lit":"mon · voyage · à · Pétersbourg · [s'est] terminé"},{"fr":"Maintenant, je pars pour Kazan.","tgt":"Теперь я еду в Казань.","ro":"Tepér' ya yédu v Kazán'.","lit":"maintenant · je · vais [en véhicule] · à · Kazan"},{"fr":"Et ensuite, je vais au lac Baïkal !","tgt":"А потом я еду на Байкал!","ro":"A patóm ya yédu na Baykál!","lit":"et · puis · je · vais [en véhicule] · sur · Baïkal"},{"fr":"Ce soir, je vais au restaurant.","tgt":"Вечером я иду в ресторан.","ro":"Vécheram ya idú v restarán.","lit":"le-soir · je · vais [à pied] · dans · restaurant"},{"fr":"Je sais demander mon chemin en russe.","tgt":"Я умею спрашивать дорогу по-русски.","ro":"Ya uméyu spráshivat' darógu pa-rússki.","lit":"je · sais · demander · chemin · en-russe"},{"fr":"Je peux acheter un billet de train tout seul.","tgt":"Я могу сам купить билет на поезд.","ro":"Ya magú sam kupít' bilét na póyezt.","lit":"je · peux · moi-même · acheter · billet · pour · train"},{"fr":"Et je sais demander : combien ça coûte ?","tgt":"И я умею спросить: сколько стоит?","ro":"I ya uméyu sprasít': skól'ka stóit?","lit":"et · je · sais · demander · combien · coûte"},{"fr":"Le russe n'est pas si difficile que ça !","tgt":"Русский язык не такой уж трудный!","ro":"Rússkiy yazýk ne takóy ush trúdnyy!","lit":"russe · langue · [ne… pas] · si · [vraiment] · difficile"},{"fr":"Mes amis partent à Sotchi, au bord de la mer.","tgt":"Мои друзья едут в Сочи, на море.","ro":"Maí druz'yá yédut v Sóchi, na móre.","lit":"mes · amis · vont [en véhicule] · à · Sotchi · sur · mer"},{"fr":"Au revoir la Russie, à très bientôt !","tgt":"До свидания, Россия, до скорой встречи!","ro":"Da svidániya, Rassíya, da skóray fstréchi!","lit":"jusqu'à · revoir · Russie · jusqu'à · prochaine · rencontre"}],"tip":{"title":"Aller vers un lieu : « ya yédu v Kazán' »","example":"Maintenant, je pars pour Kazan. — Теперь я <b>еду в Казань</b>.","body":"Vous connaissez déjà « v » et « na » pour dire où l'on est. Bonne nouvelle : ce sont les mêmes petits mots pour dire où l'on va. La différence s'entend à la fin du mot. Pour être à Moscou, on dit « v Maskvé », mais pour aller à Moscou, on dit « v Maskvú », avec un ou à la fin. Pour beaucoup de noms, comme « Kazán' » ou « Petergóf », rien ne change du tout : « ya yédu v Kazán' », mot à mot je, vais en véhicule, à, Kazan. Et l'on garde « na » pour les lieux qui le demandent : « na Baykál », au Baïkal, « na móre », à la mer. La question change aussi : « gde ? » demande où l'on est, alors que « kudá ? » demande où l'on va. Ainsi, « Kudá vy yédete ? », où allez-vous ?, appelle la réponse « V Kazán' ». Astuce : « kudá » et le ou de « v Maskvú » vont ensemble, comme une flèche qui pointe vers la destination.","exampleRo":"Tepér' ya yédu v Kazán'.","lit":"maintenant · je · vais [en véhicule] · à · Kazan"}}]},{"id":3,"name":"Conversation sociale","desc":"Faire connaissance, se présenter, échanger avec aisance.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Rencontre à Kazan","phrases":[{"fr":"Salut, je m'appelle Marc.","tgt":"Привет, меня зовут Марк.","ro":"Privét, menyá zavút Mark.","lit":"salut · moi · [ils] appellent · Marc"},{"fr":"Et toi, c'est quoi ton prénom ?","tgt":"А тебя как зовут?","ro":"A tebyá kak zavút?","lit":"et · toi · comment · [ils] appellent"},{"fr":"Moi, c'est Aïgoul.","tgt":"Я Айгуль.","ro":"Ya Aygúl'.","lit":"je · Aïgoul"},{"fr":"Vraiment ravi de faire connaissance.","tgt":"Очень рад познакомиться.","ro":"Óchen' rad paznakómitsa.","lit":"très · content · faire connaissance"},{"fr":"Tu habites à Kazan ?","tgt":"Ты живёшь в Казани?","ro":"Ty zhivyósh' v Kazáni?","lit":"tu · vis · à · Kazan"},{"fr":"Oui, j'habite dans le centre.","tgt":"Да, я живу в центре.","ro":"Da, ya zhivú v tséntre.","lit":"oui · je · vis · dans · centre"},{"fr":"Et toi, tu es originaire d'où ?","tgt":"А ты откуда?","ro":"A ty atkúda?","lit":"et · tu · d'où"},{"fr":"Moi, je suis de Lyon, en France.","tgt":"Я из Лиона, из Франции.","ro":"Ya iz Lióna, iz Frántsii.","lit":"je · de · Lyon · de · France"},{"fr":"Tu parles bien russe !","tgt":"Ты хорошо говоришь по-русски!","ro":"Ty kharashó gavarísh' pa-rússki!","lit":"tu · bien · parles · en russe"},{"fr":"Merci, j'apprends encore.","tgt":"Спасибо, я ещё учусь.","ro":"Spasíba, ya yeshchyó uchús'.","lit":"merci · je · encore · apprends"}]},{"title":"Le nouveau voisin","phrases":[{"fr":"Bonjour ! Je suis le nouveau voisin.","tgt":"Здравствуйте, я ваш новый сосед.","ro":"Zdrávstvuyte, ya vash nóvyy saséd.","lit":"bonjour · je · votre · nouveau · voisin"},{"fr":"Enchanté, moi c'est Ivan Petrovitch.","tgt":"Очень приятно, я Иван Петрович.","ro":"Óchen' priyátna, ya Iván Petróvich.","lit":"très · agréable · je · Ivan · Petrovitch"},{"fr":"Vous habitez ici depuis longtemps ?","tgt":"Вы давно здесь живёте?","ro":"Vy davnó zdes' zhivyóte?","lit":"vous · depuis longtemps · ici · vivez"},{"fr":"Oui, déjà depuis vingt ans.","tgt":"Да, уже двадцать лет.","ro":"Da, uzhé dvádtsat' let.","lit":"oui · déjà · vingt · ans"},{"fr":"On peut se tutoyer ?","tgt":"Можно на «ты»?","ro":"Mózhna na «ty»?","lit":"[on] peut · sur · « tu »"},{"fr":"Bien sûr, appelle-moi Vania.","tgt":"Конечно, зови меня Ваня.","ro":"Kanéshna, zaví menyá Ványa.","lit":"bien sûr · appelle · moi · Vania"},{"fr":"Comment ça va, Vania ?","tgt":"Как ты, Ваня?","ro":"Kak ty, Ványa?","lit":"comment · tu · Vania"},{"fr":"Et vous, comment allez-vous ?","tgt":"А как вы поживаете?","ro":"A kak vy pazhiváyete?","lit":"et · comment · vous · vivez"},{"fr":"Avec les inconnus, on dit « vous ».","tgt":"С незнакомыми людьми говорят на «вы».","ro":"S neznakómymi lyud'mí gavaryát na «vy».","lit":"avec · inconnus · gens · [on] parle · sur · « vous »"},{"fr":"Entre amis, on dit « tu ».","tgt":"Между друзьями говорят на «ты».","ro":"Mézhdu druz'yámi gavaryát na «ty».","lit":"entre · amis · [on] parle · sur · « tu »"}],"tip":{"title":"« Ty » ou « vy » : tutoyer et vouvoyer","example":"Vous habitez ici depuis longtemps ? — <b>Вы</b> давно здесь <b>живёте</b>?","body":"En russe, comme en français, il existe deux façons de s'adresser à quelqu'un : « ty », tu, et « vy », vous. On dit « vy » à un inconnu, à une personne plus âgée, à un voisin qu'on connaît encore peu. On dit « ty » à un ami, à un enfant, à quelqu'un de la famille. Le verbe change avec le pronom : « ty zhivyósh' », tu vis, mais « vy zhivyóte », vous vivez. Retenez que la forme polie se termine presque toujours par un petit son « te », comme dans « zdrávstvuyte », le bonjour poli. Pour proposer de se tutoyer, une petite phrase suffit : « Mózhna na ty ? », mot à mot : on peut sur tu ? Et pour parler de l'habitude, on dit « gavarít' na vy », parler sur vous. Astuce : dans le doute, commencez toujours par « vy », c'est poli et jamais vexant, puis laissez votre interlocuteur russe vous proposer le « ty ».","exampleRo":"Vy davnó zdes' zhivyóte?","lit":"vous · depuis longtemps · ici · vivez"}},{"title":"Un voisin sympathique","phrases":[{"fr":"Mon voisin est vraiment gentil.","tgt":"Мой сосед очень добрый.","ro":"Moy saséd óchen' dóbryy.","lit":"mon · voisin · très · gentil"},{"fr":"Il s'appelle Roustam.","tgt":"Его зовут Рустам.","ro":"Yevó zavút Rustám.","lit":"lui · [ils] appellent · Roustam"},{"fr":"Il a un grand chien.","tgt":"У него большая собака.","ro":"U nevó bal'sháya sabáka.","lit":"[chez lui] (u nevo) · grand · chien"},{"fr":"Le chien s'appelle Bars.","tgt":"Собаку зовут Барс.","ro":"Sabáku zavút Bars.","lit":"chien [cas] · [ils] appellent · Bars"},{"fr":"Le soir, Roustam joue de la guitare.","tgt":"Вечером Рустам играет на гитаре.","ro":"Vécheram Rustám igráyet na gitáre.","lit":"le soir · Roustam · joue · sur · guitare"},{"fr":"Ce n'est pas bruyant ?","tgt":"Это не шумно?","ro":"Éta ne shúmna?","lit":"ce · [ne… pas] · bruyant"},{"fr":"Non, il joue vraiment bien.","tgt":"Нет, он очень хорошо играет.","ro":"Net, on óchen' kharashó igráyet.","lit":"non · il · très · bien · joue"},{"fr":"Sa femme fait de délicieuses tartes.","tgt":"Его жена печёт вкусные пироги.","ro":"Yevó zhená pechyót vkúsnyye piragí.","lit":"sa · femme · cuit · délicieuses · tartes"},{"fr":"Ce sont des voisins formidables.","tgt":"Это очень хорошие соседи.","ro":"Éta óchen' kharóshiye sasédi.","lit":"ce · très · bons · voisins"},{"fr":"Je les invite souvent pour le thé.","tgt":"Я часто зову их на чай.","ro":"Ya chásta zavú ikh na chay.","lit":"je · souvent · appelle · eux · sur · thé"}]},{"title":"Ce qui me plaît à Kazan","phrases":[{"fr":"Kazan me plaît beaucoup.","tgt":"Мне очень нравится Казань.","ro":"Mne óchen' nrávitsa Kazán'.","lit":"à moi · très · plaît · Kazan"},{"fr":"Qu'est-ce qui te plaît ici ?","tgt":"Что тебе здесь нравится?","ro":"Shto tebé zdes' nrávitsa?","lit":"quoi · à toi · ici · plaît"},{"fr":"La vieille ville me plaît.","tgt":"Мне нравится старый город.","ro":"Mne nrávitsa stáryy górad.","lit":"à moi · plaît · vieille · ville"},{"fr":"Les gens me plaisent aussi.","tgt":"Люди мне тоже нравятся.","ro":"Lyúdi mne tózhe nrávyatsa.","lit":"gens · à moi · aussi · plaisent"},{"fr":"Le thé tatar te plaît ?","tgt":"Тебе нравится татарский чай?","ro":"Tebé nrávitsa tatárskiy chay?","lit":"à toi · plaît · tatar · thé"},{"fr":"Oui, il me plaît énormément.","tgt":"Да, очень нравится.","ro":"Da, óchen' nrávitsa.","lit":"oui · très · plaît"},{"fr":"L'hiver d'ici ne me plaît pas.","tgt":"Здешняя зима мне не нравится.","ro":"Zdéshnyaya zimá mne ne nrávitsa.","lit":"d'ici · hiver · à moi · [ne… pas] · plaît"},{"fr":"Pour moi, il fait très froid.","tgt":"Для меня очень холодно.","ro":"Dlya menyá óchen' khóladna.","lit":"pour · moi · très · froid"},{"fr":"Ma nouvelle chambre me plaît.","tgt":"Мне нравится моя новая комната.","ro":"Mne nrávitsa mayá nóvaya kómnata.","lit":"à moi · plaît · ma · nouvelle · chambre"},{"fr":"Et toi, la Russie te plaît ?","tgt":"А тебе нравится Россия?","ro":"A tebé nrávitsa Rassíya?","lit":"et · à toi · plaît · Russie"}],"tip":{"title":"« Mne nrávitsa » : j'aime, ça me plaît","example":"Kazan me plaît beaucoup. — Мне очень <b>нравится</b> Казань.","body":"Pour dire qu'une chose vous plaît, le russe retourne la phrase, exactement comme notre « ça me plaît ». On dit « Mne nrávitsa Kazán' », mot à mot : à moi plaît Kazan. La chose aimée est le sujet, et la personne est un petit mot qui veut dire à moi, à toi : « mne », à moi, « tebé », à toi, « vam », à vous. Si la chose est au pluriel, le verbe devient « nrávyatsa » : « Lyúdi mne nrávyatsa », les gens me plaisent. Pour la négation, glissez « ne » juste devant le verbe : « Mne ne nrávitsa zimá », l'hiver ne me plaît pas. Pour une question, gardez la même phrase et montez simplement la voix : « Tebé nrávitsa chay ? ». Côté prononciation, la fin du verbe se dit tout simplement « tsa », sans aucune difficulté. Astuce : pensez toujours « ça me plaît », jamais « j'aime », et la phrase russe se construit toute seule.","exampleRo":"Mne óchen' nrávitsa Kazán'.","lit":"à moi · très · plaît · Kazan"}},{"title":"Parler de son travail","phrases":[{"fr":"Tu fais quoi comme métier ?","tgt":"Кем ты работаешь?","ro":"Kem ty rabótayesh'?","lit":"qui [cas] · tu · travailles"},{"fr":"Et moi, je suis ingénieur.","tgt":"Я инженер.","ro":"Ya inzhenér.","lit":"je · ingénieur"},{"fr":"Je travaille dans une grande usine.","tgt":"Я работаю на большом заводе.","ro":"Ya rabótayu na bal'shóm zavóde.","lit":"je · travaille · sur · grande · usine"},{"fr":"Et toi, où est-ce que tu travailles ?","tgt":"А ты где работаешь?","ro":"A ty gde rabótayesh'?","lit":"et · tu · où · travailles"},{"fr":"Je suis professeure de musique.","tgt":"Я учительница музыки.","ro":"Ya uchítel'nitsa múzyki.","lit":"je · professeure · musique [cas]"},{"fr":"Il te plaît, ton travail ?","tgt":"Тебе нравится твоя работа?","ro":"Tebé nrávitsa tvayá rabóta?","lit":"à toi · plaît · ton · travail"},{"fr":"Oui, j'aime beaucoup mes élèves.","tgt":"Да, я очень люблю своих учеников.","ro":"Da, ya óchen' lyublyú svaíkh uchenikóv.","lit":"oui · je · très · aime · mes · élèves"},{"fr":"Tu travailles même le samedi ?","tgt":"Ты работаешь и в субботу?","ro":"Ty rabótayesh' i v subbótu?","lit":"tu · travailles · aussi · le · samedi"},{"fr":"Non, le samedi je suis libre.","tgt":"Нет, в субботу я свободен.","ro":"Net, v subbótu ya svabóden.","lit":"non · le · samedi · je · libre"},{"fr":"Mon bureau est à côté de la gare.","tgt":"Мой офис рядом с вокзалом.","ro":"Moy ófis ryádam s vakzálam.","lit":"mon · bureau · à côté · avec · gare [cas]"}]},{"title":"Parler de sa famille","phrases":[{"fr":"Tu as des frères, des sœurs ?","tgt":"У тебя есть братья или сёстры?","ro":"U tebyá yest' brát'ya íli syóstry?","lit":"[chez toi] (u tebya) · il y a · frères · ou · sœurs"},{"fr":"Moi, j'ai un frère et une sœur.","tgt":"У меня есть брат и сестра.","ro":"U menyá yest' brat i sestrá.","lit":"[chez moi] (u menya) · il y a · frère · et · sœur"},{"fr":"Mon frère s'appelle Paul.","tgt":"Моего брата зовут Поль.","ro":"Mayevó bráta zavút Pol'.","lit":"mon [cas] · frère [cas] · [ils] appellent · Paul"},{"fr":"Ma sœur est encore étudiante.","tgt":"Моя сестра ещё студентка.","ro":"Mayá sestrá yeshchyó studéntka.","lit":"ma · sœur · encore · étudiante"},{"fr":"Ma mère est médecin.","tgt":"Моя мама врач.","ro":"Mayá máma vrach.","lit":"ma · maman · médecin"},{"fr":"Et mon père est cuisinier.","tgt":"А мой папа повар.","ro":"A moy pápa póvar.","lit":"et · mon · papa · cuisinier"},{"fr":"Tes parents vivent à Kazan ?","tgt":"Твои родители живут в Казани?","ro":"Tvaí radíteli zhivút v Kazáni?","lit":"tes · parents · vivent · à · Kazan"},{"fr":"Non, mes parents vivent à Samara.","tgt":"Нет, мои родители живут в Самаре.","ro":"Net, maí radíteli zhivút v Samáre.","lit":"non · mes · parents · vivent · à · Samara"},{"fr":"Notre grand-mère habite avec nous.","tgt":"Бабушка живёт с нами.","ro":"Bábushka zhivyót s námi.","lit":"grand-mère · vit · avec · nous"},{"fr":"J'ai une grande famille.","tgt":"У меня большая семья.","ro":"U menyá bal'sháya sem'yá.","lit":"[chez moi] (u menya) · grande · famille"}],"tip":{"title":"La famille : « máma », « pápa », « brat », « sestrá »","example":"Moi, j'ai un frère et une sœur. — У меня есть <b>брат</b> и <b>сестра</b>.","body":"Bonne nouvelle : les mots de la famille sont parmi les plus faciles du russe. « Máma » et « pápa » s'emploient à tout âge, même entre adultes, là où le français dirait plutôt ma mère et mon père. « Brat », le frère, est court et sec, et « sestrá », la sœur, porte l'accent sur la dernière syllabe : ses-TRA. Ajoutez « bábushka », grand-mère, et « dédushka », grand-père, avec l'accent bien sur la première syllabe. Pour dire que vous avez un frère, on reprend la tournure « u menyá yest' » : « U menyá yest' brat i sestrá », mot à mot : chez moi il y a frère et sœur. Le possessif s'accorde au genre : « moy brat », mon frère, mais « mayá sestrá », ma sœur. Au pluriel, on dit « brát'ya », des frères, et « syóstry », des sœurs. Astuce : « pápa » et « dédushka » finissent par un son « a », mais restent bien masculins, on dit donc « moy pápa ».","exampleRo":"U menyá yest' brat i sestrá.","lit":"[chez moi] (u menya) · il y a · frère · et · sœur"}},{"title":"Les photos de famille","phrases":[{"fr":"Regarde, voici ma famille.","tgt":"Смотри, это моя семья.","ro":"Smatrí, éta mayá sem'yá.","lit":"regarde · c'est · ma · famille"},{"fr":"Qui est-ce, là, à gauche ?","tgt":"Кто это слева?","ro":"Kto éta sléva?","lit":"qui · c'est · à gauche"},{"fr":"C'est mon grand-père Ilya.","tgt":"Это мой дедушка Илья.","ro":"Éta moy dédushka Il'yá.","lit":"c'est · mon · grand-père · Ilya"},{"fr":"Il a un visage très doux.","tgt":"У него доброе лицо.","ro":"U nevó dóbraye litsó.","lit":"[chez lui] (u nevo) · gentil · visage"},{"fr":"Et cette jeune fille, qui est-ce ?","tgt":"А эта девушка кто?","ro":"A éta dévushka kto?","lit":"et · cette · jeune fille · qui"},{"fr":"C'est ma cousine Macha.","tgt":"Это моя двоюродная сестра Маша.","ro":"Éta mayá dvayúradnaya sestrá Másha.","lit":"c'est · ma · au deuxième degré · sœur · Macha"},{"fr":"Elle vit à Saint-Pétersbourg.","tgt":"Она живёт в Петербурге.","ro":"Aná zhivyót v Peterbúrge.","lit":"elle · vit · à · Pétersbourg"},{"fr":"Et ces deux garçons ?","tgt":"А эти два мальчика?","ro":"A éti dva mál'chika?","lit":"et · ces · deux · garçons"},{"fr":"Ce sont mes neveux.","tgt":"Это мои племянники.","ro":"Éta maí plemyánniki.","lit":"ce sont · mes · neveux"},{"fr":"Vous vous ressemblez beaucoup !","tgt":"Вы очень похожи!","ro":"Vy óchen' pakhózhi!","lit":"vous · très · semblables"}]},{"title":"Les loisirs","phrases":[{"fr":"Qu'est-ce que tu aimes faire pendant le week-end ?","tgt":"Что ты любишь делать в выходные?","ro":"Shto ty lyúbish' délat' v vykhadnýye?","lit":"quoi · tu · aimes · faire · pendant · jours de repos"},{"fr":"J'aime lire et me promener.","tgt":"Я люблю читать и гулять.","ro":"Ya lyublyú chitát' i gulyát'.","lit":"je · aime · lire · et · se promener"},{"fr":"J'adore faire la cuisine.","tgt":"Я очень люблю готовить.","ro":"Ya óchen' lyublyú gatóvit'.","lit":"je · très · aime · cuisiner"},{"fr":"Et toi, tu aimes danser ?","tgt":"А ты любишь танцевать?","ro":"A ty lyúbish' tantsevát'?","lit":"et · tu · aimes · danser"},{"fr":"Non, mais j'aime chanter.","tgt":"Нет, но я люблю петь.","ro":"Net, no ya lyublyú pet'.","lit":"non · mais · je · aime · chanter"},{"fr":"Ma sœur aime nager dans la Volga.","tgt":"Моя сестра любит плавать в Волге.","ro":"Mayá sestrá lyúbit plávat' v Vólge.","lit":"ma · sœur · aime · nager · dans · Volga"},{"fr":"Mes amis aiment jouer aux échecs.","tgt":"Мои друзья любят играть в шахматы.","ro":"Maí druz'yá lyúbyat igrát' v shákhmaty.","lit":"mes · amis · aiment · jouer · à · échecs"},{"fr":"Moi, j'aime faire du vélo.","tgt":"А я люблю кататься на велосипеде.","ro":"A ya lyublyú katátsa na velasipéde.","lit":"et · je · aime · rouler · sur · vélo"},{"fr":"Nous aimons aller au théâtre.","tgt":"Мы любим ходить в театр.","ro":"My lyúbim khadít' v teátr.","lit":"nous · aimons · aller · à · théâtre"},{"fr":"Moi, je n'aime pas me lever tôt.","tgt":"А я не люблю рано вставать.","ro":"A ya ne lyublyú rána vstavát'.","lit":"et · je · [ne… pas] · aime · tôt · se lever"}],"tip":{"title":"« Lyublyú » + verbe : j'aime faire quelque chose","example":"J'aime lire et me promener. — Я <b>люблю</b> читать и гулять.","body":"Pour dire ce qu'on aime faire, le russe fait exactement comme le français : le verbe aimer, puis un verbe à l'infinitif. « Ya lyublyú chitát' », mot à mot : je aime lire. L'infinitif russe se reconnaît à l'oreille, il finit presque toujours par un petit « t' » mouillé, comme dans « gulyát' », se promener, ou « pet' », chanter. Le verbe aimer change selon la personne : « ya lyublyú », j'aime, « ty lyúbish' », tu aimes, « on lyúbit », il aime, « my lyúbim », nous aimons. Attention à l'accent qui saute : il tombe sur la fin pour « lyublyú », puis sur le début pour toutes les autres formes. Pour dire beaucoup, ajoutez « óchen' » devant : « Ya óchen' lyublyú gatóvit' », j'adore cuisiner. Pour la négation, « ne » se place juste avant : « Ya ne lyublyú rána vstavát' », je n'aime pas me lever tôt. Astuce : « lyublyú » sert aussi à dire je t'aime, « ya tebyá lyublyú », alors c'est un mot qui fait toujours plaisir à entendre.","exampleRo":"Ya lyublyú chitát' i gulyát'.","lit":"je · aime · lire · et · se promener"}},{"title":"Sport et musique","phrases":[{"fr":"Tu fais du sport ?","tgt":"Ты занимаешься спортом?","ro":"Ty zanimáyesh'sya spórtam?","lit":"tu · t'occupes · sport [cas]"},{"fr":"Oui, je joue au hockey.","tgt":"Да, я играю в хоккей.","ro":"Da, ya igráyu v khakkéy.","lit":"oui · je · joue · à · hockey"},{"fr":"Kazan a une très bonne équipe.","tgt":"В Казани очень хорошая команда.","ro":"V Kazáni óchen' kharóshaya kamánda.","lit":"à · Kazan · très · bonne · équipe"},{"fr":"Le matin, je cours au parc.","tgt":"Утром я бегаю в парке.","ro":"Útram ya bégayu v párke.","lit":"le matin · je · cours · dans · parc"},{"fr":"Tu écoutes quelle musique, toi ?","tgt":"Какую музыку ты слушаешь?","ro":"Kakúyu múzyku ty slúshayesh'?","lit":"quelle · musique · tu · écoutes"},{"fr":"J'écoute du jazz et du rock.","tgt":"Я слушаю джаз и рок.","ro":"Ya slúshayu dzhaz i rok.","lit":"je · écoute · jazz · et · rock"},{"fr":"Tu joues d'un instrument de musique ?","tgt":"Ты играешь на чём-нибудь?","ro":"Ty igráyesh' na chyóm-nibud'?","lit":"tu · joues · sur · quelque chose"},{"fr":"Je joue un peu de piano.","tgt":"Я немного играю на пианино.","ro":"Ya nemnóga igráyu na pianína.","lit":"je · un peu · joue · sur · piano"},{"fr":"Samedi, il y a un concert au parc.","tgt":"В субботу в парке концерт.","ro":"V subbótu v párke kantsért.","lit":"le · samedi · dans · parc · concert"},{"fr":"Tu viens avec moi ?","tgt":"Пойдёшь со мной?","ro":"Paydyósh' sa mnoy?","lit":"iras · avec · moi"}]},{"title":"L'été ou l'hiver ?","phrases":[{"fr":"Tu préfères l'été ou l'hiver ?","tgt":"Что тебе больше нравится: лето или зима?","ro":"Shto tebé ból'she nrávitsa: léta íli zimá?","lit":"quoi · à toi · plus · plaît · été · ou · hiver"},{"fr":"C'est l'été qui me plaît le plus.","tgt":"Мне больше нравится лето.","ro":"Mne ból'she nrávitsa léta.","lit":"à moi · plus · plaît · été"},{"fr":"L'été, c'est mieux que l'hiver.","tgt":"Летом лучше, чем зимой.","ro":"Létam lúchshe, chem zimóy.","lit":"en été · mieux · que · en hiver"},{"fr":"Kazan est plus petite que Moscou.","tgt":"Казань меньше, чем Москва.","ro":"Kazán' mén'she, chem Maskvá.","lit":"Kazan · plus petite · que · Moscou"},{"fr":"Mais ici, la vie est plus calme.","tgt":"Но здесь жизнь спокойнее.","ro":"No zdes' zhizn' spakóyneye.","lit":"mais · ici · vie · plus calme"},{"fr":"Le thé, c'est meilleur que le café.","tgt":"Чай лучше, чем кофе.","ro":"Chay lúchshe, chem kófe.","lit":"thé · meilleur · que · café"},{"fr":"Mon grand frère est plus grand que moi.","tgt":"Мой старший брат выше, чем я.","ro":"Moy stárshiy brat výshe, chem ya.","lit":"mon · aîné · frère · plus haut · que · moi"},{"fr":"Tu parles russe mieux que moi.","tgt":"Ты говоришь по-русски лучше, чем я.","ro":"Ty gavarísh' pa-rússki lúchshe, chem ya.","lit":"tu · parles · en russe · mieux · que · moi"},{"fr":"Le dimanche, j'ai plus de temps.","tgt":"В воскресенье у меня больше времени.","ro":"V vaskresén'ye u menyá ból'she vrémeni.","lit":"le · dimanche · [chez moi] (u menya) · plus · temps [cas]"},{"fr":"Le printemps est plus beau que l'automne.","tgt":"Весна красивее, чем осень.","ro":"Vesná krasíveye, chem ósen'.","lit":"printemps · plus beau · que · automne"}],"tip":{"title":"Comparer : « ból'she », « lúchshe », « chem »","example":"L'été, c'est mieux que l'hiver. — Летом <b>лучше</b>, <b>чем</b> зимой.","body":"Pour comparer, le russe a deux petits mots très courants : « ból'she », plus, et « lúchshe », mieux ou meilleur. Le « que » français se dit « chem », précédé d'une petite pause : « Létam lúchshe, chem zimóy », mot à mot : en été mieux, que en hiver. Bonne nouvelle, ces comparatifs ne changent jamais de forme, que l'on parle d'un homme, d'une femme ou d'une chose. « Ból'she » sert aussi pour la quantité : « U menyá ból'she vrémeni », j'ai plus de temps. Son contraire est « mén'she », moins ou plus petit. Pour beaucoup d'autres adjectifs, on ajoute simplement la terminaison « eye » : « spakóynyy », calme, devient « spakóyneye », plus calme, et « krasívyy », beau, devient « krasíveye ». Astuce : dans la conversation, on peut souvent laisser tomber la deuxième partie, comme dans « Mne ból'she nrávitsa léta », c'est l'été qui me plaît le plus, et tout le monde comprend.","exampleRo":"Létam lúchshe, chem zimóy.","lit":"en été · mieux · que · en hiver"}},{"title":"Parler du temps qu'il fait","phrases":[{"fr":"Quel temps magnifique aujourd'hui !","tgt":"Какая сегодня прекрасная погода!","ro":"Kakáya sevódnya prekrásnaya pagóda!","lit":"quel · aujourd'hui · magnifique · temps"},{"fr":"Oui, il fait doux et il y a du soleil.","tgt":"Да, тепло и солнечно.","ro":"Da, tepló i sólnechna.","lit":"oui · chaud · et · ensoleillé"},{"fr":"Hier, il a plu toute la journée.","tgt":"Вчера весь день шёл дождь.","ro":"Vcherá ves' den' shol dozhd'.","lit":"hier · toute · journée · allait · pluie"},{"fr":"En hiver, il y a beaucoup de neige ici.","tgt":"Зимой здесь много снега.","ro":"Zimóy zdes' mnóga snéga.","lit":"en hiver · ici · beaucoup · neige [cas]"},{"fr":"Tu as froid ?","tgt":"Тебе холодно?","ro":"Tebé khóladna?","lit":"à toi · froid"},{"fr":"Un peu, j'ai oublié ma veste.","tgt":"Немного, я забыл куртку.","ro":"Nemnóga, ya zabýl kúrtku.","lit":"un peu · je · ai oublié · veste"},{"fr":"Tiens, prends mon écharpe.","tgt":"Возьми мой шарф.","ro":"Vaz'mí moy sharf.","lit":"prends · mon · écharpe"},{"fr":"Merci, tu es très gentille.","tgt":"Спасибо, ты очень добрая.","ro":"Spasíba, ty óchen' dóbraya.","lit":"merci · tu · très · gentille"},{"fr":"Il fait combien de degrés aujourd'hui ?","tgt":"Сколько сегодня градусов?","ro":"Skól'ka sevódnya grádusav?","lit":"combien · aujourd'hui · degrés"},{"fr":"À peu près vingt degrés.","tgt":"Около двадцати градусов.","ro":"Ókala dvadtsatí grádusav.","lit":"environ · vingt [cas] · degrés"}]},{"title":"Pourquoi le russe ?","phrases":[{"fr":"Pourquoi est-ce que tu apprends le russe ?","tgt":"Почему ты учишь русский?","ro":"Pachemú ty úchish' rússkiy?","lit":"pourquoi · tu · apprends · russe"},{"fr":"Parce que j'aime la Russie.","tgt":"Потому что я люблю Россию.","ro":"Patamú shto ya lyublyú Rassíyu.","lit":"parce que · je · aime · Russie"},{"fr":"Et parce que j'ai des amis ici.","tgt":"И потому что у меня здесь друзья.","ro":"I patamú shto u menyá zdes' druz'yá.","lit":"et · parce que · [chez moi] (u menya) · ici · amis"},{"fr":"Pourquoi tu vis à Kazan ?","tgt":"Почему ты живёшь в Казани?","ro":"Pachemú ty zhivyósh' v Kazáni?","lit":"pourquoi · tu · vis · à · Kazan"},{"fr":"Parce que ma femme est d'ici.","tgt":"Потому что моя жена отсюда.","ro":"Patamú shto mayá zhená atsyúda.","lit":"parce que · ma · femme · d'ici"},{"fr":"Je suis fatigué, parce que je travaille énormément.","tgt":"Я устал, потому что очень много работаю.","ro":"Ya ustál, patamú shto óchen' mnóga rabótayu.","lit":"je · fatigué · parce que · très · beaucoup · travaille"},{"fr":"Dis, pourquoi tu ne viens pas ce soir ?","tgt":"Слушай, почему ты не придёшь сегодня вечером?","ro":"Slúshay, pachemú ty ne pridyósh' sevódnya vécheram?","lit":"écoute · pourquoi · tu · [ne… pas] · viendras · aujourd'hui · le soir"},{"fr":"Parce que je suis malade.","tgt":"Потому что я болею.","ro":"Patamú shto ya baléyu.","lit":"parce que · je · suis malade"},{"fr":"Je reste chez moi parce qu'il pleut.","tgt":"Я сижу дома, потому что идёт дождь.","ro":"Ya sizhú dóma, patamú shto idyót dozhd'.","lit":"je · suis assis · à la maison · parce que · va · pluie"},{"fr":"J'aime l'automne parce que c'est beau.","tgt":"Я люблю осень, потому что это красиво.","ro":"Ya lyublyú ósen', patamú shto éta krasíva.","lit":"je · aime · automne · parce que · c'est · beau"}],"tip":{"title":"« Patamú shto » : parce que","example":"Parce que j'aime la Russie. — <b>Потому что</b> я люблю Россию.","body":"Pour donner une raison, le russe utilise « patamú shto », parce que. Ce sont deux mots, mais à l'oral on les dit d'un seul souffle, en appuyant bien sur « mú ». La question qui va avec est « pachemú ? », pourquoi, et les deux mots se répondent comme un écho : « pachemú » demande, « patamú » répond. Par exemple : « Pachemú ty úchish' rússkiy ? », pourquoi tu apprends le russe ? Réponse : « Patamú shto ya lyublyú Rassíyu », mot à mot : parce que je aime Russie. Comme en français, on peut aussi le placer au milieu de la phrase, après une petite pause : « Ya ustál, patamú shto óchen' mnóga rabótayu », je suis fatigué, parce que je travaille énormément. Dans la vie de tous les jours, on répond même parfois juste « patamú ! », comme un enfant qui dit parce que ! Astuce : retenez la paire « pachemú, patamú », elle sonne comme une petite comptine et ne s'oublie plus.","exampleRo":"Patamú shto ya lyublyú Rassíyu.","lit":"parce que · je · aime · Russie"}},{"title":"Thé et chak-chak","phrases":[{"fr":"Assieds-toi, le thé est prêt.","tgt":"Садись, чай готов.","ro":"Sadís', chay gatóv.","lit":"assieds-toi · thé · prêt"},{"fr":"Tu veux du chak-chak ?","tgt":"Хочешь чак-чак?","ro":"Khóchesh' chak-chák?","lit":"veux · chak-chak"},{"fr":"C'est quoi, le chak-chak ?","tgt":"Что такое чак-чак?","ro":"Shto takóye chak-chák?","lit":"quoi · tel · chak-chak"},{"fr":"C'est un dessert tatar au miel.","tgt":"Это татарский десерт с мёдом.","ro":"Éta tatárskiy desért s myódam.","lit":"c'est · tatar · dessert · avec · miel [cas]"},{"fr":"Mmm, c'est vraiment bon !","tgt":"Ммм, очень вкусно!","ro":"Mmm, óchen' vkúsna!","lit":"mmm · très · délicieux"},{"fr":"C'est ma grand-mère qui l'a préparé.","tgt":"Это бабушка приготовила.","ro":"Éta bábushka prigatóvila.","lit":"c'est · grand-mère · a préparé"},{"fr":"Tu prends ton thé avec du sucre ?","tgt":"Тебе чай с сахаром?","ro":"Tebé chay s sákharam?","lit":"à toi · thé · avec · sucre [cas]"},{"fr":"Non, avec du citron, s'il te plaît.","tgt":"Нет, с лимоном, пожалуйста.","ro":"Net, s limónam, pazhálusta.","lit":"non · avec · citron [cas] · s'il te plaît"},{"fr":"Encore une tasse ?","tgt":"Ещё чашку?","ro":"Yeshchyó cháshku?","lit":"encore · tasse"},{"fr":"Avec plaisir, il est délicieux.","tgt":"С удовольствием, он очень вкусный.","ro":"S udavól'stviyem, on óchen' vkúsnyy.","lit":"avec · plaisir [cas] · il · très · délicieux"}]},{"title":"Les anniversaires","phrases":[{"fr":"Dis-moi, tu as quel âge ?","tgt":"Скажи, сколько тебе лет?","ro":"Skazhí, skól'ka tebé let?","lit":"dis · combien · à toi · ans"},{"fr":"J'ai vingt ans.","tgt":"Мне двадцать лет.","ro":"Mne dvádtsat' let.","lit":"à moi · vingt · ans"},{"fr":"Et ton frère, il a quel âge ?","tgt":"А сколько лет твоему брату?","ro":"A skól'ka let tvayemú brátu?","lit":"et · combien · ans · ton [cas] · frère [cas]"},{"fr":"Il a vingt-cinq ans.","tgt":"Ему двадцать пять лет.","ro":"Yemú dvádtsat' pyat' let.","lit":"à lui · vingt · cinq · ans"},{"fr":"Ma petite sœur a douze ans.","tgt":"Моей младшей сестре двенадцать лет.","ro":"Mayéy mládshey sestré dvenádtsat' let.","lit":"ma [cas] · cadette [cas] · sœur [cas] · douze · ans"},{"fr":"Mon grand-père a quatre-vingts ans.","tgt":"Дедушке восемьдесят лет.","ro":"Dédushke vósem'desyat let.","lit":"à grand-père · quatre-vingts · ans"},{"fr":"Aujourd'hui, c'est mon anniversaire !","tgt":"Сегодня мой день рождения!","ro":"Sevódnya moy den' razhdéniya!","lit":"aujourd'hui · mon · jour · de naissance"},{"fr":"Bon anniversaire, Aïgoul !","tgt":"С днём рождения, Айгуль!","ro":"S dnyom razhdéniya, Aygúl'!","lit":"avec · jour [cas] · de naissance · Aïgoul"},{"fr":"J'ai trente ans aujourd'hui.","tgt":"Мне сегодня тридцать лет.","ro":"Mne sevódnya trítsat' let.","lit":"à moi · aujourd'hui · trente · ans"},{"fr":"Tu as l'air plus jeune !","tgt":"Ты выглядишь моложе!","ro":"Ty výglyadish' malózhe!","lit":"tu · as l'air · plus jeune"}],"tip":{"title":"« Mne dvádtsat' let » : dire son âge","example":"J'ai vingt ans. — <b>Мне</b> двадцать <b>лет</b>.","body":"Pour dire son âge, le russe ne dit pas j'ai vingt ans, mais à moi vingt ans : « Mne dvádtsat' let ». On retrouve le petit « mne », à moi, déjà rencontré avec « mne nrávitsa ». Pour demander, on dit « Skól'ka tebé let ? », mot à mot : combien à toi ans, ou « Skól'ka vam let ? » quand on vouvoie. Pour parler de quelqu'un d'autre, on dit « yemú », à lui, ou « yey », à elle : « Yemú dvádtsat' pyat' let », il a vingt-cinq ans. Le mot ans change un peu selon le nombre : « god » après un, comme dans « dvádtsat' adín god », vingt et un ans, « góda » après deux, trois et quatre, et « let » à partir de cinq. Pas de panique : « let » est de loin le plus fréquent, et on vous comprendra parfaitement même avec une petite erreur. Astuce : apprenez « Mne dvádtsat' let » comme un bloc, puis changez seulement le nombre au milieu.","exampleRo":"Mne dvádtsat' let.","lit":"à moi · vingt · ans"}},{"title":"Au bord de la Volga","phrases":[{"fr":"Tu veux te promener au bord de la Volga ?","tgt":"Хочешь погулять по набережной Волги?","ro":"Khóchesh' pagulyát' pa náberezhnay Vólgi?","lit":"veux · se promener · le long de · quai [cas] · Volga [cas]"},{"fr":"Avec joie, il fait beau.","tgt":"С радостью, погода хорошая.","ro":"S rádast'yu, pagóda kharóshaya.","lit":"avec · joie [cas] · temps · beau"},{"fr":"Ici, la Volga est très large.","tgt":"Здесь Волга очень широкая.","ro":"Zdes' Vólga óchen' shirókaya.","lit":"ici · Volga · très · large"},{"fr":"Regarde tous ces bateaux !","tgt":"Смотри, какие корабли!","ro":"Smatrí, kakíye karablí!","lit":"regarde · quels · bateaux"},{"fr":"On peut s'asseoir sur ce banc.","tgt":"Можно сесть на эту скамейку.","ro":"Mózhna sest' na étu skaméyku.","lit":"[on] peut · s'asseoir · sur · ce · banc"},{"fr":"Le coucher de soleil est magnifique ici.","tgt":"Здесь очень красивый закат.","ro":"Zdes' óchen' krasívyy zakát.","lit":"ici · très · beau · coucher de soleil"},{"fr":"Ici, le soir, il y a beaucoup de monde.","tgt":"Вечером здесь много людей.","ro":"Vécheram zdes' mnóga lyudéy.","lit":"le soir · ici · beaucoup · gens [cas]"},{"fr":"Tu veux une glace ?","tgt":"Хочешь мороженое?","ro":"Khóchesh' marózhenaye?","lit":"veux · glace"},{"fr":"Oui, à la vanille.","tgt":"Да, ванильное.","ro":"Da, vaníl'naye.","lit":"oui · à la vanille"},{"fr":"Quelle soirée merveilleuse !","tgt":"Какой чудесный вечер!","ro":"Kakóy chudésnyy vécher!","lit":"quelle · merveilleuse · soirée"}]},{"title":"Faire des projets ensemble","phrases":[{"fr":"Allez, ce soir on va au cinéma !","tgt":"Давай вечером сходим в кино!","ro":"Daváy vécheram skhódim v kinó!","lit":"allez · le soir · irons · à · cinéma"},{"fr":"Excellente idée, allons-y !","tgt":"Отличная идея, давай!","ro":"Atlíchnaya idéya, daváy!","lit":"excellente · idée · allez"},{"fr":"Et si on se tutoyait ?","tgt":"Давай на «ты»?","ro":"Daváy na «ty»?","lit":"allez · sur · « tu »"},{"fr":"Allez, on prend un taxi.","tgt":"Давай возьмём такси.","ro":"Daváy vaz'myóm taksí.","lit":"allez · prendrons · taxi"},{"fr":"Non, allons-y à pied, ce n'est pas loin.","tgt":"Нет, давай пешком, это недалеко.","ro":"Net, daváy peshkóm, éta nedalekó.","lit":"non · allez · à pied · c'est · pas loin"},{"fr":"Retrouvons-nous à sept heures.","tgt":"Давай встретимся в семь часов.","ro":"Daváy vstrétimsya v sem' chasóv.","lit":"allez · nous retrouverons · à · sept · heures"},{"fr":"Où est-ce qu'on se retrouve ?","tgt":"Где встретимся?","ro":"Gde vstrétimsya?","lit":"où · nous retrouverons"},{"fr":"Devant le théâtre, ça te va ?","tgt":"У театра, хорошо?","ro":"U teátra, kharashó?","lit":"près de · théâtre [cas] · bien"},{"fr":"Allez, à ce soir !","tgt":"Давай, до вечера!","ro":"Daváy, da véchera!","lit":"allez · jusqu'à · soir [cas]"},{"fr":"Prenons une photo ensemble !","tgt":"Давай сфотографируемся вместе!","ro":"Daváy sfatagrafíruyemsya vméste!","lit":"allez · nous photographierons · ensemble"}],"tip":{"title":"« Daváy » : allez, faisons-le ensemble","example":"Retrouvons-nous à sept heures. — <b>Давай</b> встретимся в семь часов.","body":"« Daváy » est l'un des mots les plus utiles du russe parlé. Mot à mot, il veut dire donne, mais on l'emploie comme notre allez ou allons-y, pour proposer de faire quelque chose ensemble. On le place en tête de phrase, suivi du verbe à la forme nous : « Daváy vstrétimsya v sem' chasóv », mot à mot : allez nous nous retrouverons à sept heures, c'est-à-dire retrouvons-nous à sept heures. Quand on vouvoie, ou qu'on parle à plusieurs personnes, il devient « daváyte » : « Daváyte pagulyáyem », promenons-nous. Tout seul, « daváy » veut aussi dire d'accord, je suis partant, et même salut entre amis au moment de se quitter : « Nu, daváy ! », allez, à plus ! Pour l'intonation, on monte un peu la voix sur la dernière syllabe, avec entrain. Astuce : chaque fois que vous diriez on y va en français, essayez « daváy », c'est presque toujours juste.","exampleRo":"Daváy vstrétimsya v sem' chasóv.","lit":"allez · nous retrouverons · à · sept · heures"}},{"title":"Une invitation chez des amis","phrases":[{"fr":"Viens chez nous samedi !","tgt":"Приходи к нам в субботу!","ro":"Prikhadí k nam v subbótu!","lit":"viens · chez · nous · le · samedi"},{"fr":"Merci, avec grand plaisir.","tgt":"Спасибо, с удовольствием.","ro":"Spasíba, s udavól'stviyem.","lit":"merci · avec · plaisir [cas]"},{"fr":"Je dois venir à quelle heure ?","tgt":"Во сколько мне прийти?","ro":"Va skól'ka mne priytí?","lit":"à · combien · à moi · venir"},{"fr":"Vers six heures, le soir.","tgt":"Часов в шесть вечера.","ro":"Chasóv v shest' véchera.","lit":"heures · à · six · soir [cas]"},{"fr":"Qu'est-ce que j'apporte ?","tgt":"Что принести?","ro":"Shto prinestí?","lit":"quoi · apporter"},{"fr":"Rien du tout, nous avons tout.","tgt":"Ничего не надо, у нас всё есть.","ro":"Nichevó ne náda, u nas vsyo yest'.","lit":"rien · [ne… pas] · faut · [chez nous] (u nas) · tout · il y a"},{"fr":"Tu m'envoies ton adresse ?","tgt":"Пришлёшь мне адрес?","ro":"Prishlyósh' mne ádres?","lit":"enverras · à moi · adresse"},{"fr":"Bonsoir, entre donc !","tgt":"Добрый вечер, заходи!","ro":"Dóbryy vécher, zakhadí!","lit":"bon · soir · entre"},{"fr":"Tiens, ces fleurs sont pour toi.","tgt":"Это тебе цветы.","ro":"Éta tebé tsvetý.","lit":"ceci · à toi · fleurs"},{"fr":"Fais comme chez toi.","tgt":"Чувствуй себя как дома.","ro":"Chúvstvuy sebyá kak dóma.","lit":"sens · soi · comme · à la maison"}]},{"title":"À table chez des amis","phrases":[{"fr":"Tout est tellement bon !","tgt":"Всё так вкусно!","ro":"Vsyo tak vkúsna!","lit":"tout · tellement · délicieux"},{"fr":"La soupe est trop chaude.","tgt":"Суп слишком горячий.","ro":"Sup slíshkam garyáchiy.","lit":"soupe · trop · chaude"},{"fr":"Tu cuisines tellement bien !","tgt":"Ты так хорошо готовишь!","ro":"Ty tak kharashó gatóvish'!","lit":"tu · tellement · bien · cuisines"},{"fr":"C'est trop pour moi, merci.","tgt":"Это слишком много для меня, спасибо.","ro":"Éta slíshkam mnóga dlya menyá, spasíba.","lit":"c'est · trop · beaucoup · pour · moi · merci"},{"fr":"Ce gâteau est trop sucré.","tgt":"Этот торт слишком сладкий.","ro":"État tort slíshkam sládkiy.","lit":"ce · gâteau · trop · sucré"},{"fr":"Je suis tellement content de vous voir !","tgt":"Я так рад вас видеть!","ro":"Ya tak rad vas vídet'!","lit":"je · tellement · content · vous · voir"},{"fr":"La musique est trop forte ?","tgt":"Музыка слишком громкая?","ro":"Múzyka slíshkam grómkaya?","lit":"musique · trop · forte"},{"fr":"Non, tout est parfait.","tgt":"Нет, всё отлично.","ro":"Net, vsyo atlíchna.","lit":"non · tout · excellent"},{"fr":"Il est trop tard, je dois y aller.","tgt":"Уже слишком поздно, мне пора.","ro":"Uzhé slíshkam pózna, mne pará.","lit":"déjà · trop · tard · à moi · [il est] temps"},{"fr":"Dommage, la soirée passe tellement vite !","tgt":"Жаль, вечер так быстро проходит!","ro":"Zhal', vécher tak býstra prakhódit!","lit":"dommage · soirée · tellement · vite · passe"}],"tip":{"title":"« Slíshkam » et « tak » : trop et tellement","example":"Ce gâteau est trop sucré. — Этот торт <b>слишком</b> сладкий.","body":"Pour dire trop, le russe utilise « slíshkam », avec l'accent sur la première syllabe : « État tort slíshkam sládkiy », mot à mot : ce gâteau trop sucré. Comme toujours au présent, pas de verbe être. Attention, « slíshkam » est vraiment négatif : il veut dire plus que ce qu'il faut. Pour un compliment, on utilise plutôt « tak », tellement ou si : « Vsyo tak vkúsna ! », tout est tellement bon, ou « Ty tak kharashó gatóvish' ! », tu cuisines tellement bien. « Tak » se place juste devant le mot qu'il renforce, et on appuie un peu la voix dessus pour montrer son émotion. Devant un nom, on dit plutôt « takóy » : « takóy krasívyy vécher », une si belle soirée. Astuce : à table chez des amis russes, dites « tak » pour complimenter, et gardez « slíshkam » pour refuser poliment, par exemple « Éta slíshkam mnóga », c'est trop pour moi.","exampleRo":"État tort slíshkam sládkiy.","lit":"ce · gâteau · trop · sucré"}},{"title":"Se dire au revoir","phrases":[{"fr":"Merci pour cette merveilleuse soirée.","tgt":"Спасибо за чудесный вечер.","ro":"Spasíba za chudésnyy vécher.","lit":"merci · pour · merveilleuse · soirée"},{"fr":"C'était vraiment agréable.","tgt":"Было очень приятно.","ro":"Býla óchen' priyátna.","lit":"était · très · agréable"},{"fr":"Reviens nous voir !","tgt":"Приходи к нам ещё!","ro":"Prikhadí k nam yeshchyó!","lit":"viens · chez · nous · encore"},{"fr":"Promis, la prochaine fois chez moi.","tgt":"Обязательно, в следующий раз у меня.","ro":"Abyazátel'na, v sléduyushchiy raz u menyá.","lit":"sans faute · à · prochaine · fois · chez · moi"},{"fr":"Je t'appelle un taxi ?","tgt":"Тебе вызвать такси?","ro":"Tebé výzvat' taksí?","lit":"à toi · appeler · taxi"},{"fr":"Non merci, j'habite tout près.","tgt":"Нет, спасибо, я живу рядом.","ro":"Net, spasíba, ya zhivú ryádam.","lit":"non · merci · je · vis · à côté"},{"fr":"Embrasse tes parents pour moi.","tgt":"Передавай привет родителям.","ro":"Peredaváy privét radítelyam.","lit":"transmets · salut · parents [cas]"},{"fr":"Bonne nuit à tout le monde !","tgt":"Всем спокойной ночи!","ro":"Vsem spakóynay nóchi!","lit":"à tous · calme · nuit [cas]"},{"fr":"Écris-moi quand tu seras à la maison.","tgt":"Напиши, когда будешь дома.","ro":"Napishí, kagdá búdesh' dóma.","lit":"écris · quand · seras · à la maison"},{"fr":"Salut, à très bientôt !","tgt":"Пока, до скорого!","ro":"Paká, da skórava!","lit":"salut · jusqu'à · prochain [cas]"}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Alors, tu parles russe maintenant ?","tgt":"Ну что, ты теперь говоришь по-русски?","ro":"Nu shto, ty tepér' gavarísh' pa-rússki?","lit":"eh bien · quoi · tu · maintenant · parles · en russe"},{"fr":"Eh bien, un petit peu.","tgt":"Ну, немножко.","ro":"Nu, nemnózhka.","lit":"eh bien · un petit peu"},{"fr":"Je sais me présenter en russe.","tgt":"Я умею представиться по-русски.","ro":"Ya uméyu predstávitsa pa-rússki.","lit":"je · sais · me présenter · en russe"},{"fr":"Je sais parler de ma famille.","tgt":"Я могу рассказать о своей семье.","ro":"Ya magú rasskazát' a svayéy sem'yé.","lit":"je · peux · raconter · sur · ma · famille [cas]"},{"fr":"Allons donc, tu parles très bien !","tgt":"Да ладно, ты отлично говоришь!","ro":"Da ládna, ty atlíchna gavarísh'!","lit":"allons donc · tu · excellemment · parles"},{"fr":"Mais c'est simple, voyons !","tgt":"Это же просто!","ro":"Éta zhe prósta!","lit":"c'est · [insistance] (zhe) · simple"},{"fr":"Maintenant, je comprends mieux les Russes.","tgt":"Теперь я лучше понимаю русских.","ro":"Tepér' ya lúchshe panimáyu rússkikh.","lit":"maintenant · je · mieux · comprends · Russes [cas]"},{"fr":"J'aime le russe parce que c'est une belle langue.","tgt":"Я люблю русский язык, потому что он красивый.","ro":"Ya lyublyú rússkiy yazýk, patamú shto on krasívyy.","lit":"je · aime · russe · langue · parce que · il · beau"},{"fr":"Bon, on continue ensemble ?","tgt":"Ну, продолжаем вместе?","ro":"Nu, pradalzháyem vméste?","lit":"eh bien · continuons · ensemble"},{"fr":"Bien sûr, en avant !","tgt":"Конечно, вперёд!","ro":"Kanéshna, vperyód!","lit":"bien sûr · en avant"}],"tip":{"title":"Les petits mots de la conversation : « nu », « zhe », « da ládna »","example":"Mais c'est simple, voyons ! — Это <b>же</b> просто!","body":"Les Russes parsèment leurs phrases de petits mots qui ne se traduisent pas toujours, mais qui rendent la conversation vivante. « Nu » ressemble à notre bon ou eh bien : on le dit pour commencer une phrase ou pour gagner un peu de temps, comme dans « Nu, nemnózhka », eh bien, un petit peu. « Zhe » se place juste après un mot pour insister, comme notre voyons ou quand même : « Éta zhe prósta ! », mot à mot : c'est donc simple, autrement dit mais c'est simple, voyons ! « Da ládna » est une petite merveille : selon le ton, il veut dire allons donc, pas possible, ou bon d'accord, laisse tomber. Dit en souriant après un compliment, il signifie arrête, tu exagères. « Nu » et « zhe » sont très courts et sans accent, ils se collent au mot voisin. Astuce : écoutez les Russes autour de vous et comptez les « nu » : vous en entendrez des dizaines par jour, et les glisser dans vos phrases vous fera tout de suite sonner plus naturel.","exampleRo":"Éta zhe prósta!","lit":"c'est · [insistance] (zhe) · simple"}}]}]},{"id":2,"name":"Niveau 2","freeLessonsPerModule":{"1":3,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"La vie de tous les jours, avec un vocabulaire plus riche.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Une nouvelle vie à Nijni Novgorod","phrases":[{"fr":"Je vis à Nijni Novgorod depuis un mois déjà.","tgt":"Я живу в Нижнем Новгороде уже месяц.","ro":"Ya zhivú v Nízhnem Nóvgarade uzhé mésyats."},{"fr":"Avant, j'habitais à Moscou.","tgt":"Раньше я жил в Москве.","ro":"Rán'she ya zhil v Maskvé."},{"fr":"Ici, la vie est plus calme.","tgt":"Здесь жизнь спокойнее.","ro":"Zdes' zhizn' spakóyneye."},{"fr":"Mes fenêtres donnent sur la Volga.","tgt":"Мои окна выходят на Волгу.","ro":"Mayí ókna vykhódyat na Vólgu."},{"fr":"Le matin, je vais au travail en tramway.","tgt":"Утром я езжу на работу на трамвае.","ro":"Útram ya yézzhu na rabótu na tramváye."},{"fr":"La ville se trouve là où deux rivières se rejoignent.","tgt":"Город стоит там, где сливаются две реки.","ro":"Górad staít tam, gde sliváyutsa dve rekí."},{"fr":"Le soir, je me promène sur la Pokrovka.","tgt":"Вечером я гуляю по Покровке.","ro":"Vécheram ya gulyáyu pa Pakróvke."},{"fr":"J'ai déjà trouvé une bonne boulangerie près de chez moi.","tgt":"Я уже нашёл хорошую пекарню рядом с домом.","ro":"Ya uzhé nashól kharóshuyu pekárnyu ryádam s dómam."},{"fr":"Les gens d'ici sont très accueillants.","tgt":"Люди здесь очень приветливые.","ro":"Lyúdi zdes' óchen' privétlivyye."},{"fr":"Je crois que je vais me plaire ici.","tgt":"Думаю, мне здесь понравится.","ro":"Dúmayu, mne zdes' panrávitsa."}]},{"title":"Une journée au bureau","phrases":[{"fr":"Hier, j'ai travaillé jusqu'à huit heures du soir.","tgt":"Вчера я работал до восьми вечера.","ro":"Vcherá ya rabótal da vas'mí véchera."},{"fr":"Ma collègue Olga a travaillé à la maison.","tgt":"Моя коллега Ольга работала дома.","ro":"Mayá kalléga Ól'ga rabótala dóma."},{"fr":"Qu'avez-vous fait toute la journée ?","tgt":"Что вы делали весь день?","ro":"Shto vy délali ves' den'?"},{"fr":"J'ai écrit des messages et j'ai appelé des clients.","tgt":"Я писал письма и звонил клиентам.","ro":"Ya pisál pís'ma i zvaníl kliyéntam."},{"fr":"Le directeur était de bonne humeur.","tgt":"Директор был в хорошем настроении.","ro":"Diréktar byl v kharóshem nastrayénii."},{"fr":"La réunion a duré deux heures.","tgt":"Совещание длилось два часа.","ro":"Saveshchániye dlílas' dva chasá."},{"fr":"Ma femme m'a appelé à l'heure du déjeuner.","tgt":"Жена позвонила мне в обед.","ro":"Zhená pazvaníla mne v abéd."},{"fr":"Nous avons déjeuné ensemble à la cantine.","tgt":"Мы вместе обедали в столовой.","ro":"My vméste abédali v stalóvay."},{"fr":"J'étais très fatigué, et ma collègue aussi.","tgt":"Я очень устал, и коллега тоже.","ro":"Ya óchen' ustál, i kalléga tózhe."},{"fr":"Je suis rentré à la maison en taxi.","tgt":"Домой я вернулся на такси.","ro":"Damóy ya vernúlsya na taksí."}],"tip":{"title":"Le passé : « rabótal », « rabótala », il s'accorde au genre","example":"Ma collègue Olga a travaillé à la maison. — Моя коллега Ольга <b>работала</b> дома.","body":"Bonne nouvelle : le russe n'a qu'un seul temps du passé, là où le français hésite entre passé composé et imparfait. On part de l'infinitif « rabótat' », travailler, on enlève le « t' » final et on ajoute « l » : « rabótal ». Ce passé ne change pas selon la personne mais selon le genre : un homme dit « ya rabótal », une femme dit « ya rabótala », et pour plusieurs personnes ou pour le vouvoiement on dit « rabótali ». Décomposons : « Mayá kalléga Ól'ga rabótala dóma », mot à mot ma collègue Olga a-travaillé-elle à la maison. Même logique avec « byl », il était, « bylá », elle était, ou « zvaníl », il a appelé, « zvaníla », elle a appelé. Pour retenir, voyez le « a » final comme la signature des femmes au passé.","exampleRo":"Mayá kalléga Ól'ga rabótala dóma.","lit":"ma · collègue · Olga · a travaillé (elle) · à la maison"}},{"title":"Les courses au supermarché","phrases":[{"fr":"Il faut acheter du lait et du pain.","tgt":"Надо купить молоко и хлеб.","ro":"Náda kupít' malakó i khleb."},{"fr":"Vous avez pris un panier ou un chariot ?","tgt":"Вы взяли корзину или тележку?","ro":"Vy vzyáli karzínu íli telézhku?"},{"fr":"Les fruits sont tout au fond du magasin.","tgt":"Фрукты в самом конце магазина.","ro":"Frúkty v sámam kantsé magazína."},{"fr":"Combien coûte ce fromage blanc ?","tgt":"Сколько стоит этот творог?","ro":"Skól'ka stóit état tvaróg?"},{"fr":"Trois cents roubles le kilo.","tgt":"Триста рублей за килограмм.","ro":"Trísta rubléy za kilagrám."},{"fr":"J'ai oublié ma liste de courses à la maison.","tgt":"Я забыл список покупок дома.","ro":"Ya zabýl spísak pakúpak dóma."},{"fr":"Aujourd'hui, il y a une réduction sur les pommes.","tgt":"Сегодня скидка на яблоки.","ro":"Sevódnya skídka na yáblaki."},{"fr":"La queue à la caisse est très longue.","tgt":"На кассе очень длинная очередь.","ro":"Na kásse óchen' dlínnaya óchered'."},{"fr":"Vous payez par carte ou en espèces ?","tgt":"Вы платите картой или наличными?","ro":"Vy plátite kártay íli nalíchnymi?"},{"fr":"Il me faut un sac, s'il vous plaît.","tgt":"Мне нужен пакет, пожалуйста.","ro":"Mne núzhen pakét, pazhálusta."}]},{"title":"Chez le médecin","phrases":[{"fr":"J'ai mal à la gorge depuis trois jours.","tgt":"У меня три дня болит горло.","ro":"U menyá tri dnya balít górla."},{"fr":"Vous avez pris votre température ?","tgt":"Вы мерили температуру?","ro":"Vy mérili temperatúru?"},{"fr":"Hier soir, j'avais trente-huit.","tgt":"Вчера вечером было тридцать восемь.","ro":"Vcherá vécheram býla trídtsat' vósem'."},{"fr":"Ouvrez la bouche et dites « a ».","tgt":"Откройте рот и скажите «а».","ro":"Atkróyte rot i skazhíte «a»."},{"fr":"La gorge est un peu rouge.","tgt":"Горло немного красное.","ro":"Górla nemnóga krásnaye."},{"fr":"Ce n'est qu'un rhume, rien de grave.","tgt":"Это просто простуда, ничего серьёзного.","ro":"Éta prósta prastúda, nichevó ser'yóznava."},{"fr":"Buvez beaucoup de thé chaud avec du miel.","tgt":"Пейте побольше горячего чая с мёдом.","ro":"Péyte paból'she garyácheva cháya s myódam."},{"fr":"J'aurai besoin d'un arrêt de travail ?","tgt":"Мне нужен больничный?","ro":"Mne núzhen bal'níchnyy?"},{"fr":"Oui, je vous le fais pour cinq jours.","tgt":"Да, я выпишу вам его на пять дней.","ro":"Da, ya výpishu vam yevó na pyat' dney."},{"fr":"Revenez si ça ne va pas mieux.","tgt":"Приходите, если не станет лучше.","ro":"Prikhadíte, yésli ne stánet lúchshe."}]},{"title":"Les syrniki du dimanche","phrases":[{"fr":"Ce matin, j'ai fait des syrniki.","tgt":"Сегодня утром я сделал сырники.","ro":"Sevódnya útram ya sdélal sýrniki."},{"fr":"Pendant que je faisais les syrniki, ma fille dormait.","tgt":"Пока я делал сырники, дочка спала.","ro":"Paká ya délal sýrniki, dóchka spalá."},{"fr":"Ma grand-mère en faisait chaque dimanche.","tgt":"Бабушка делала их каждое воскресенье.","ro":"Bábushka délala ikh kázhdaye vaskresén'ye."},{"fr":"J'ai mélangé le fromage blanc avec un œuf.","tgt":"Я смешал творог с яйцом.","ro":"Ya smeshál tvaróg s yaytsóm."},{"fr":"Ensuite, j'ai ajouté un peu de farine.","tgt":"Потом добавил немного муки.","ro":"Patóm dabávil nemnóga mukí."},{"fr":"Qu'est-ce que vous faisiez hier soir ?","tgt":"Что вы делали вчера вечером?","ro":"Shto vy délali vcherá vécheram?"},{"fr":"Hier soir, je faisais mes devoirs de russe.","tgt":"Вчера вечером я делал домашнее задание по русскому.","ro":"Vcherá vécheram ya délal damáshneye zadániye pa rússkamu."},{"fr":"Et vous avez tout fait ?","tgt":"И вы всё сделали?","ro":"I vy vsyo sdélali?"},{"fr":"Oui, j'ai tout fait avant minuit.","tgt":"Да, я всё сделал до полуночи.","ro":"Da, ya vsyo sdélal da palúnachi."},{"fr":"Les syrniki sont meilleurs avec de la crème fraîche.","tgt":"Сырники вкуснее со сметаной.","ro":"Sýrniki vkusnéye sa smetánay."}],"tip":{"title":"Imperfectif et perfectif : « délal » ou « sdélal »","example":"Pendant que je faisais les syrniki, ma fille dormait. — Пока я <b>делал</b> сырники, дочка спала.","body":"En russe, la plupart des verbes vont par deux : une forme pour l'action en cours ou habituelle, et une forme pour l'action terminée, avec un résultat. « Délal » ressemble à notre imparfait, je faisais, j'étais en train de faire ; « sdélal », avec un petit « s » devant, veut dire j'ai fait, c'est fini. Comparez « Paká ya délal sýrniki », pendant que je faisais les syrniki, et « Ya sdélal sýrniki », j'ai fait les syrniki, ils sont prêts. Même chose avec « zvaníl », j'appelais, et « pazvaníl », j'ai appelé, ou « pisál », j'écrivais, et « napisál », j'ai écrit. Pour choisir, demandez-vous simplement : est-ce que je raconte le déroulement ou le résultat ?","exampleRo":"Paká ya délal sýrniki, dóchka spalá.","lit":"pendant que · je · faisais · syrniki · fillette · dormait"}},{"title":"Le week-end prochain à la datcha","phrases":[{"fr":"Ce week-end, nous serons à la datcha.","tgt":"В эти выходные мы будем на даче.","ro":"V éti vykhadnýye my búdem na dáche."},{"fr":"Je vais travailler au potager.","tgt":"Я буду работать в огороде.","ro":"Ya búdu rabótat' v agaróde."},{"fr":"Ma femme va planter des tomates.","tgt":"Жена будет сажать помидоры.","ro":"Zhená búdet sazhát' pamidóry."},{"fr":"Le soir, nous ferons griller des chachliks.","tgt":"Вечером будем жарить шашлыки.","ro":"Vécheram búdem zhárit' shashlykí."},{"fr":"Vous allez dormir là-bas ?","tgt":"Вы будете там ночевать?","ro":"Vy búdete tam nachevát'?"},{"fr":"Oui, nous y serons jusqu'à dimanche.","tgt":"Да, будем там до воскресенья.","ro":"Da, búdem tam da vaskresén'ya."},{"fr":"Il n'y aura pas d'internet, et c'est parfait.","tgt":"Там не будет интернета, и это прекрасно.","ro":"Tam ne búdet internéta, i éta prekrásna."},{"fr":"Les enfants vont se baigner dans la rivière.","tgt":"Дети будут купаться в речке.","ro":"Déti búdut kupát'sa v réchke."},{"fr":"Qu'est-ce que vous allez faire samedi ?","tgt":"Что вы будете делать в субботу?","ro":"Shto vy búdete délat' v subbótu?"},{"fr":"Je vais lire au soleil, tout simplement.","tgt":"Я буду читать на солнце, вот и всё.","ro":"Ya búdu chitát' na sóntse, vot i vsyo."}],"tip":{"title":"Le futur avec « búdu » : je vais faire, je ferai","example":"Je vais travailler au potager. — Я <b>буду</b> работать в огороде.","body":"Pour parler d'une activité à venir, sans insister sur le résultat, le russe utilise une recette très simple : le verbe être au futur, puis l'infinitif. « Ya búdu rabótat' », mot à mot je serai travailler, veut dire je vais travailler, je travaillerai. Seul « búdu » change selon la personne : « ya búdu », « vy búdete », « my búdem », « on búdet », « aní búdut ». Écoutez : « Vy búdete tam nachevát' ? », vous allez dormir là-bas ? « Búdem zhárit' shashlykí », nous ferons griller des chachliks. Et sans infinitif, « búdu » signifie tout simplement je serai : « My búdem na dáche », nous serons à la datcha. Astuce : apprenez « búdu » comme un mot magique qui projette n'importe quel verbe dans le futur.","exampleRo":"Ya búdu rabótat' v agaróde.","lit":"je · serai · travailler · dans · potager"}},{"title":"Les tâches ménagères","phrases":[{"fr":"Aujourd'hui, c'est le jour du grand ménage.","tgt":"Сегодня у нас генеральная уборка.","ro":"Sevódnya u nas generál'naya ubórka."},{"fr":"Qui passe l'aspirateur aujourd'hui ?","tgt":"Кто сегодня пылесосит?","ro":"Kto sevódnya pylesósit?"},{"fr":"Moi, je fais la vaisselle.","tgt":"Я мою посуду.","ro":"Ya móyu pasúdu."},{"fr":"Ma fille range sa chambre.","tgt":"Дочка убирает свою комнату.","ro":"Dóchka ubiráyet svayú kómnatu."},{"fr":"Il faut sortir les poubelles ce soir.","tgt":"Вечером надо вынести мусор.","ro":"Vécheram náda výnesti músar."},{"fr":"La machine à laver ne marche plus.","tgt":"Стиральная машина больше не работает.","ro":"Stirál'naya mashína ból'she ne rabótayet."},{"fr":"J'ai lavé le sol de la cuisine.","tgt":"Я помыл пол на кухне.","ro":"Ya pamýl pol na kúkhne."},{"fr":"Après l'hiver, les fenêtres sont sales.","tgt":"После зимы окна грязные.","ro":"Pósle zimý ókna gryáznyye."},{"fr":"Chez nous, on se partage toujours les tâches.","tgt":"Мы всегда делим обязанности.","ro":"My vsegdá délim abyázannasti."},{"fr":"Après le ménage, nous avons bien mérité un thé.","tgt":"После уборки мы заслужили хороший чай.","ro":"Pósle ubórki my zasluzhíli kharóshiy chay."}]},{"title":"Les voisins de l'immeuble","phrases":[{"fr":"Nos nouveaux voisins sont arrivés hier.","tgt":"Наши новые соседи приехали вчера.","ro":"Náshi nóvyye sasédi priyékhali vcherá."},{"fr":"Ils ont sonné à la porte pour faire connaissance.","tgt":"Они позвонили в дверь, чтобы познакомиться.","ro":"Aní pazvaníli v dver', shtóby paznakómit'sa."},{"fr":"La voisine nous a apporté des pirojki.","tgt":"Соседка принесла нам пирожки.","ro":"Sasédka prineslá nam pirazhkí."},{"fr":"Ils ont un petit chien très calme.","tgt":"У них маленькая собака, очень спокойная.","ro":"U nikh málen'kaya sabáka, óchen' spakóynaya."},{"fr":"Le voisin du dessus fait des travaux.","tgt":"Сосед сверху делает ремонт.","ro":"Saséd svérkhu délayet remónt."},{"fr":"Le bruit commence à huit heures du matin.","tgt":"Шум начинается в восемь утра.","ro":"Shum nachináyetsa v vósem' utrá."},{"fr":"Je vais lui en parler poliment.","tgt":"Я поговорю с ним вежливо.","ro":"Ya pagavaryú s nim vézhliva."},{"fr":"Il a promis de finir avant samedi.","tgt":"Он обещал закончить до субботы.","ro":"On abeshchál zakónchit' da subbóty."},{"fr":"Les voisins arrosent nos fleurs quand nous sommes en vacances.","tgt":"Соседи поливают наши цветы, когда мы в отпуске.","ro":"Sasédi paliváyut náshi tsvetý, kagdá my v ótpuske."},{"fr":"C'est agréable d'avoir des voisins sympathiques.","tgt":"Хорошо, когда соседи хорошие.","ro":"Kharashó, kagdá sasédi kharóshiye."}]},{"title":"La kacha du matin","phrases":[{"fr":"Le matin, je mange toujours de la kacha.","tgt":"Утром я всегда ем кашу.","ro":"Útram ya vsegdá yem káshu."},{"fr":"Aujourd'hui, c'est de la kacha au sarrasin.","tgt":"Сегодня гречневая каша.","ro":"Sevódnya gréchnevaya kásha."},{"fr":"Les enfants préfèrent la kacha de semoule.","tgt":"Дети больше любят манную кашу.","ro":"Déti ból'she lyúbyat mánnuyu káshu."},{"fr":"Je la fais cuire dans du lait.","tgt":"Я варю её на молоке.","ro":"Ya varyú yeyó na malaké."},{"fr":"Il faut ajouter une pincée de sel.","tgt":"Нужно добавить щепотку соли.","ro":"Núzhna dabávit' shchepótku sóli."},{"fr":"Avec un morceau de beurre, c'est délicieux.","tgt":"С кусочком масла очень вкусно.","ro":"S kusóchkam másla óchen' vkúsna."},{"fr":"Ma mère y ajoute aussi des baies.","tgt":"Мама ещё кладёт туда ягоды.","ro":"Máma yeshchó kladyót tudá yágady."},{"fr":"La kacha donne de l'énergie pour toute la matinée.","tgt":"Каша даёт энергию на всё утро.","ro":"Kásha dayót enérgiyu na vsyo útra."},{"fr":"Vous reprendrez bien un peu de thé ?","tgt":"Хотите ещё чаю?","ro":"Khatíte yeshchó cháyu?"},{"fr":"Non merci, il est l'heure d'aller au travail.","tgt":"Нет, спасибо, мне пора на работу.","ro":"Net, spasíba, mne pará na rabótu."}]},{"title":"Une promenade au bord de la Volga","phrases":[{"fr":"Le dimanche, nous nous promenons sur les quais.","tgt":"По воскресеньям мы гуляем по набережной.","ro":"Pa vaskresén'yam my gulyáyem pa náberezhnay."},{"fr":"D'ici, on voit l'Oka se jeter dans la Volga.","tgt":"Отсюда видно, как Ока впадает в Волгу.","ro":"Atsyúda vídna, kak Aká vpadáyet v Vólgu."},{"fr":"Prenons le téléphérique au-dessus de la Volga.","tgt":"Давайте прокатимся на канатной дороге через Волгу.","ro":"Daváyte prakátimsya na kanátnay daróge chérez Vólgu."},{"fr":"D'en haut, la vue est tout simplement magnifique.","tgt":"Сверху вид просто потрясающий.","ro":"Svérkhu vid prósta patryasáyushchiy."},{"fr":"Il y a beaucoup de monde aujourd'hui.","tgt":"Сегодня много народу.","ro":"Sevódnya mnóga naródu."},{"fr":"Asseyons-nous sur ce banc.","tgt":"Давайте сядем на эту скамейку.","ro":"Daváyte syádem na étu skaméyku."},{"fr":"Près de l'eau, le vent est frais.","tgt":"У воды прохладный ветер.","ro":"U vadý prakhládnyy véter."},{"fr":"On s'achète une glace ?","tgt":"Купим мороженое?","ro":"Kúpim marózhenaye?"},{"fr":"Pour moi, une glace à la vanille.","tgt":"Мне ванильное мороженое.","ro":"Mne vaníl'naye marózhenaye."},{"fr":"Le coucher de soleil sur la Volga est inoubliable.","tgt":"Закат над Волгой незабываемый.","ro":"Zakát nad Vólgay nezabyváyemyy."}]},{"title":"Au bania le samedi","phrases":[{"fr":"Le samedi, je vais au bania avec mon frère.","tgt":"По субботам я хожу в баню с братом.","ro":"Pa subbótam ya khazhú v bányu s brátam."},{"fr":"Dans l'étuve, il fait très chaud.","tgt":"В парилке очень жарко.","ro":"V parílke óchen' zhárka."},{"fr":"On se fouette avec des branches de bouleau.","tgt":"Мы паримся берёзовыми вениками.","ro":"My párimsya beryózavymi vénikami."},{"fr":"Après, on saute dans l'eau froide.","tgt":"Потом прыгаем в холодную воду.","ro":"Patóm prýgayem v khalódnuyu vódu."},{"fr":"N'oubliez pas votre bonnet de feutre.","tgt":"Не забудьте войлочную шапку.","ro":"Ne zabúd'te vóylachnuyu shápku."},{"fr":"Entre deux passages, on boit une tisane.","tgt":"Между заходами пьём травяной чай.","ro":"Mézhdu zakhódami p'yom travyanóy chay."},{"fr":"Le bania, c'est excellent pour la santé.","tgt":"Баня полезна для здоровья.","ro":"Bánya palézna dlya zdaróv'ya."},{"fr":"Je me sens comme neuf.","tgt":"Я чувствую себя как новый.","ro":"Ya chúvstvuyu sebyá kak nóvyy."},{"fr":"On y retourne la semaine prochaine ?","tgt":"Пойдём туда на следующей неделе?","ro":"Paydyóm tudá na sléduyushchey nedéle?"},{"fr":"Bien sûr, c'est notre petite tradition.","tgt":"Конечно, это наша традиция.","ro":"Kanéshna, éta násha tradítsiya."}]},{"title":"Les projets de demain","phrases":[{"fr":"Demain, je ferai tout ce que j'ai prévu.","tgt":"Завтра я сделаю всё, что запланировал.","ro":"Závtra ya sdélayu vsyo, shto zaplaníraval."},{"fr":"D'abord, j'appellerai le plombier.","tgt":"Сначала я позвоню сантехнику.","ro":"Snachála ya pazvanyú santékhniku."},{"fr":"Ensuite, je passerai à la poste.","tgt":"Потом схожу на почту.","ro":"Patóm skhazhú na póchtu."},{"fr":"Je vous écrirai dès que j'arriverai.","tgt":"Я вам напишу, как только приеду.","ro":"Ya vam napishú, kak tól'ka priyédu."},{"fr":"Vous m'appellerez ce soir ?","tgt":"Вы мне позвоните вечером?","ro":"Vy mne pazvaníte vécheram?"},{"fr":"Oui, je vous appellerai vers sept heures.","tgt":"Да, позвоню около семи.","ro":"Da, pazvanyú ókala semí."},{"fr":"Je finirai ce rapport avant le déjeuner.","tgt":"Я закончу этот отчёт до обеда.","ro":"Ya zakónchu état atchyót da abéda."},{"fr":"Ma femme achètera les billets de train.","tgt":"Жена купит билеты на поезд.","ro":"Zhená kúpit biléty na póyezd."},{"fr":"Si vous voulez, je vous aiderai.","tgt":"Если хотите, я вам помогу.","ro":"Yésli khatíte, ya vam pamagú."},{"fr":"Ne vous inquiétez pas, je n'oublierai rien.","tgt":"Не волнуйтесь, я ничего не забуду.","ro":"Ne valnúytes', ya nichevó ne zabúdu."}],"tip":{"title":"Le futur perfectif : « sdélayu », « pazvanyú »","example":"D'abord, j'appellerai le plombier. — Сначала я <b>позвоню</b> сантехнику.","body":"Voici une astuce surprenante : pour annoncer une action précise qu'on va mener jusqu'au bout, le russe prend le verbe perfectif et le conjugue simplement comme un présent. « Sdélat' », faire jusqu'au bout, donne « ya sdélayu », je ferai ; « pazvanít' », passer un coup de fil, donne « ya pazvanyú », j'appellerai. Pas de « búdu » ici : il est réservé aux verbes imperfectifs. Décomposons : « Snachála ya pazvanyú santékhniku », mot à mot d'abord je appellerai au plombier. Autres exemples : « ya napishú », j'écrirai, « ya pamagú », j'aiderai, « ya ne zabúdu », je n'oublierai pas. Pour retenir : forme de présent plus verbe perfectif égale promesse pour plus tard.","exampleRo":"Snachála ya pazvanyú santékhniku.","lit":"d'abord · je · appellerai · [à] plombier"}},{"title":"Une fuite dans la cuisine","phrases":[{"fr":"Il y a une fuite sous l'évier.","tgt":"Под раковиной течёт вода.","ro":"Pad rákavinay techyót vadá."},{"fr":"Le robinet goutte toute la nuit.","tgt":"Кран капает всю ночь.","ro":"Kran kápayet vsyu noch'."},{"fr":"J'ai appelé la société de gestion de l'immeuble.","tgt":"Я позвонил в управляющую компанию.","ro":"Ya pazvaníl v upravlyáyushchuyu kampániyu."},{"fr":"Le plombier est venu au bout d'une heure.","tgt":"Сантехник пришёл через час.","ro":"Santékhnik prishól chérez chas."},{"fr":"Il faut changer ce vieux tuyau.","tgt":"Нужно заменить эту старую трубу.","ro":"Núzhna zamenít' étu stáruyu trubú."},{"fr":"Combien je vous dois pour la réparation ?","tgt":"Сколько я вам должен за ремонт?","ro":"Skól'ka ya vam dólzhen za remónt?"},{"fr":"Mille deux cents roubles, pièces comprises.","tgt":"Тысяча двести рублей вместе с деталями.","ro":"Týsyacha dvésti rubléy vméste s detályami."},{"fr":"Il a tout réparé en vingt minutes.","tgt":"Он всё починил за двадцать минут.","ro":"On vsyo pachiníl za dvátsat' minút."},{"fr":"Maintenant, tout fonctionne parfaitement.","tgt":"Теперь всё работает отлично.","ro":"Tepér' vsyo rabótayet atlíchna."},{"fr":"Je garde son numéro, au cas où.","tgt":"Сохраню его номер на всякий случай.","ro":"Sakhranyú yevó nómer na vsyákiy slúchay."}]},{"title":"À la pharmacie","phrases":[{"fr":"Y a-t-il une pharmacie ouverte jour et nuit près d'ici ?","tgt":"Здесь рядом есть круглосуточная аптека?","ro":"Zdes' ryádam yest' kruglasútachnaya aptéka?"},{"fr":"Je voudrais quelque chose contre la toux, s'il vous plaît.","tgt":"Мне что-нибудь от кашля, пожалуйста.","ro":"Mne shtó-nibud' at káshlya, pazhálusta."},{"fr":"Ce sirop est pour les adultes ou pour les enfants ?","tgt":"Этот сироп для взрослых или для детей?","ro":"État siróp dlya vzróslykh íli dlya detéy?"},{"fr":"C'est pour mon fils, il a six ans.","tgt":"Для сына, ему шесть лет.","ro":"Dlya sýna, yemú shest' let."},{"fr":"Prenez une cuillère trois fois par jour.","tgt":"Принимайте по ложке три раза в день.","ro":"Prinimáyte pa lózhke tri ráza v den'."},{"fr":"Il faut une ordonnance pour ce médicament ?","tgt":"На это лекарство нужен рецепт?","ro":"Na éta lekárstva núzhen retsépt?"},{"fr":"Non, il est en vente libre.","tgt":"Нет, оно продаётся без рецепта.","ro":"Net, anó pradayótsa bez retsépta."},{"fr":"Donnez-moi aussi un pansement.","tgt":"Дайте ещё пластырь.","ro":"Dáyte yeshchó plástyr'."},{"fr":"Ça vous fera quatre cent cinquante roubles.","tgt":"С вас четыреста пятьдесят рублей.","ro":"S vas chetýresta pyat'desyát rubléy."},{"fr":"Que votre fils guérisse vite !","tgt":"Пусть сын скорее поправляется!","ro":"Pust' syn skaréye papravlyáyetsa!"}]},{"title":"Au marché Mytny","phrases":[{"fr":"Le samedi matin, je vais au marché Mytny.","tgt":"В субботу утром я иду на Мытный рынок.","ro":"V subbótu útram ya idú na Mýtnyy rýnak."},{"fr":"Les légumes y sont plus frais qu'au supermarché.","tgt":"Там овощи свежее, чем в супермаркете.","ro":"Tam óvashchi svezhéye, chem v supermárkete."},{"fr":"Je vais prendre un kilo de pommes de terre.","tgt":"Мне килограмм картошки.","ro":"Mne kilagrám kartóshki."},{"fr":"Ces concombres sont d'ici.","tgt":"Эти огурцы местные.","ro":"Éti agurtsý méstnyye."},{"fr":"Goûtez ce miel, il vient de notre rucher.","tgt":"Попробуйте мёд, он с нашей пасеки.","ro":"Papróbuyte myod, on s náshey páseki."},{"fr":"Vous pouvez me faire une petite réduction ?","tgt":"Уступите немного?","ro":"Ustupíte nemnóga?"},{"fr":"Pour vous, ce sera cinq cents roubles.","tgt":"Для вас пятьсот рублей.","ro":"Dlya vas pyat'sót rubléy."},{"fr":"Je reviendrai chez vous samedi prochain.","tgt":"Я ещё приду к вам в следующую субботу.","ro":"Ya yeshchó pridú k vam v sléduyushchuyu subbótu."},{"fr":"La vendeuse m'a offert des herbes fraîches.","tgt":"Продавщица дала мне зелень в подарок.","ro":"Pradavshchítsa dalá mne zélen' v padárak."},{"fr":"Mon sac est lourd, mais je suis content.","tgt":"Сумка тяжёлая, но я доволен.","ro":"Súmka tyazhólaya, no ya davólen."}]},{"title":"L'anniversaire de Svetlana","phrases":[{"fr":"Samedi, c'est l'anniversaire de Svetlana.","tgt":"В субботу у Светланы день рождения.","ro":"V subbótu u Svetlány den' razhdéniya."},{"fr":"Elle a invité toute l'équipe chez elle.","tgt":"Она пригласила всю команду к себе.","ro":"Aná priglasíla vsyu kamándu k sebé."},{"fr":"Qu'est-ce qu'on lui offre ?","tgt":"Что ей подарим?","ro":"Shto yey padárim?"},{"fr":"Elle adore les livres et les fleurs.","tgt":"Она обожает книги и цветы.","ro":"Aná abazháyet knígi i tsvetý."},{"fr":"On peut se cotiser pour un beau cadeau.","tgt":"Можно скинуться на хороший подарок.","ro":"Mózhna skínut'sa na kharóshiy padárak."},{"fr":"Je m'occupe du bouquet.","tgt":"Я беру на себя букет.","ro":"Ya berú na sebyá bukét."},{"fr":"N'oubliez pas : il faut un nombre impair de fleurs.","tgt":"Не забудьте: цветов должно быть нечётное число.","ro":"Ne zabúd'te: tsvetóv dalzhnó byt' nechyótnaye chisló."},{"fr":"Joyeux anniversaire, Svetlana !","tgt":"С днём рождения, Светлана!","ro":"S dnyom razhdéniya, Svetlána!"},{"fr":"Je vous souhaite du bonheur et une bonne santé.","tgt":"Желаю вам счастья и здоровья.","ro":"Zheláyu vam shchást'ya i zdaróv'ya."},{"fr":"Le gâteau au miel était un délice.","tgt":"Медовик был очень вкусный.","ro":"Medavík byl óchen' vkúsnyy."}]},{"title":"Un nouvel appartement","phrases":[{"fr":"Nous avons trouvé un appartement plus grand.","tgt":"Мы нашли квартиру побольше.","ro":"My nashlí kvartíru paból'she."},{"fr":"Il est dans la partie haute de la ville.","tgt":"Она в верхней части города.","ro":"Aná v vérkhney chásti górada."},{"fr":"Il y a trois pièces et un balcon.","tgt":"Там три комнаты и балкон.","ro":"Tam tri kómnaty i balkón."},{"fr":"Le loyer est de trente mille roubles par mois.","tgt":"Аренда стоит тридцать тысяч рублей в месяц.","ro":"Arénda stóit trídtsat' týsyach rubléy v mésyats."},{"fr":"Le déménagement est prévu pour vendredi.","tgt":"Переезд назначен на пятницу.","ro":"Pereyézd naznáchen na pyátnitsu."},{"fr":"Mes amis vont m'aider à porter les meubles.","tgt":"Друзья помогут мне перенести мебель.","ro":"Druz'yá pamógut mne perenestí mébel'."},{"fr":"Il faut emballer la vaisselle avec soin.","tgt":"Посуду надо аккуратно упаковать.","ro":"Pasúdu náda akkurátna upakavát'."},{"fr":"Il y a déjà des cartons partout.","tgt":"Везде уже коробки.","ro":"Vezdé uzhé karóbki."},{"fr":"Le chat ne comprend rien à ce qui se passe.","tgt":"Кот ничего не понимает.","ro":"Kot nichevó ne panimáyet."},{"fr":"Nous fêterons la crémaillère le mois prochain.","tgt":"Новоселье отметим в следующем месяце.","ro":"Navasél'ye atmétim v sléduyushchem mésyatse."}]},{"title":"Une soirée tranquille","phrases":[{"fr":"Ce soir, je reste à la maison.","tgt":"Сегодня вечером я дома.","ro":"Sevódnya vécheram ya dóma."},{"fr":"J'ai préparé une soupe au chou.","tgt":"Я сварил щи.","ro":"Ya svaríl shchi."},{"fr":"On regarde un vieux film ?","tgt":"Посмотрим старый фильм?","ro":"Pasmótrim stáryy fil'm?"},{"fr":"Je préfère lire un roman sur le canapé.","tgt":"Я лучше почитаю роман на диване.","ro":"Ya lúchshe pachitáyu ramán na diváne."},{"fr":"Ma femme tricote une écharpe pour l'hiver.","tgt":"Жена вяжет шарф на зиму.","ro":"Zhená vyázhet sharf na zímu."},{"fr":"Dehors, il neige doucement.","tgt":"На улице тихо идёт снег.","ro":"Na úlitse tíkha idyót sneg."},{"fr":"Une tasse de thé avec de la confiture ?","tgt":"Чашку чая с вареньем?","ro":"Cháshku cháya s varén'yem?"},{"fr":"Avec plaisir, à la framboise si possible.","tgt":"С удовольствием, малиновым, если можно.","ro":"S udavól'stviyem, malínavym, yésli mózhna."},{"fr":"Ces soirées calmes me font du bien.","tgt":"Такие тихие вечера мне на пользу.","ro":"Takíye tíkhiye vecherá mne na pól'zu."},{"fr":"Je vais me coucher tôt, demain je travaille.","tgt":"Лягу пораньше, завтра на работу.","ro":"Lyágu parán'she, závtra na rabótu."}]},{"title":"Les conseils de la grand-mère","phrases":[{"fr":"Ma grand-mère a un conseil pour tout.","tgt":"У бабушки на всё есть совет.","ro":"U bábushki na vsyo yest' savét."},{"fr":"On ne doit pas siffler à la maison.","tgt":"Дома нельзя свистеть.","ro":"Dóma nel'zyá svistét'."},{"fr":"Il ne faut pas s'asseoir sur une pierre froide.","tgt":"Не надо сидеть на холодном камне.","ro":"Ne náda sidét' na khalódnam kámne."},{"fr":"On ne doit pas sortir avec les cheveux mouillés.","tgt":"Нельзя выходить на улицу с мокрой головой.","ro":"Nel'zyá vykhadít' na úlitsu s mókray galavóy."},{"fr":"Il ne faut pas marcher pieds nus sur le carrelage.","tgt":"Не надо ходить босиком по плитке.","ro":"Ne náda khadít' basikóm pa plítke."},{"fr":"On ne se dit pas bonjour par-dessus le seuil.","tgt":"Через порог нельзя здороваться.","ro":"Chérez paróg nel'zyá zdaróvat'sa."},{"fr":"Ne t'inquiète pas, mamie, on fera attention.","tgt":"Не волнуйся, бабушка, мы будем осторожны.","ro":"Ne valnúysya, bábushka, my búdem astarózhny."},{"fr":"Et surtout, on ne part pas le ventre vide !","tgt":"И главное, нельзя уходить голодным!","ro":"I glávnaye, nel'zyá ukhadít' galódnym!"},{"fr":"Ce n'est pas la peine de m'apporter des fleurs.","tgt":"Не надо приносить мне цветы.","ro":"Ne náda prinasít' mne tsvetý."},{"fr":"On en rit, mais on suit toujours ses conseils.","tgt":"Мы смеёмся, но всегда её слушаемся.","ro":"My smeyómsya, no vsegdá yeyó slúshayemsya."}],"tip":{"title":"L'interdiction : « ne náda » et « nel'zyá »","example":"On ne doit pas siffler à la maison. — Дома <b>нельзя</b> свистеть.","body":"Pour dire qu'une chose ne se fait pas, le russe a deux petits mots très pratiques, suivis d'un simple infinitif, sans aucun sujet. « Nel'zyá » est ferme : c'est interdit, on ne peut pas. « Dóma nel'zyá svistét' », mot à mot à la maison interdit siffler, veut dire on ne doit pas siffler à la maison. « Ne náda » est plus doux : ce n'est pas la peine, il vaut mieux éviter. « Ne náda prinasít' mne tsvetý », ce n'est pas la peine de m'apporter des fleurs. Vous entendrez aussi « Ne náda ! » tout seul, pour dire non merci, inutile. Pour retenir : « nel'zyá » ferme la porte, « ne náda » la laisse entrouverte.","exampleRo":"Dóma nel'zyá svistét'.","lit":"à la maison · [il est interdit] · siffler"}},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module nous a fait découvrir la vie à Nijni Novgorod.","tgt":"Этот модуль познакомил нас с жизнью в Нижнем Новгороде.","ro":"État módul' paznakómil nas s zhízn'yu v Nízhnem Nóvgarade."},{"fr":"Maintenant, vous savez parler du passé en russe.","tgt":"Теперь вы умеете говорить о прошлом по-русски.","ro":"Tepér' vy uméyete gavarít' a próshlam pa-rússki."},{"fr":"Vous savez aussi dire ce que vous ferez demain.","tgt":"Вы также можете сказать, что сделаете завтра.","ro":"Vy tákzhe mózhete skazát', shto sdélayete závtra."},{"fr":"Les aspects des verbes ne vous font plus peur.","tgt":"Виды глаголов вас больше не пугают.","ro":"Vídy glagólav vas ból'she ne pugáyut."},{"fr":"Vous savez dire ce qui est interdit.","tgt":"Вы знаете, как сказать, что нельзя.","ro":"Vy znáyete, kak skazát', shto nel'zyá."},{"fr":"Le plus important : parler à voix haute chaque jour.","tgt":"Самое главное: говорить вслух каждый день.","ro":"Sámaye glávnaye: gavarít' vslukh kázhdyy den'."},{"fr":"Le prochain module nous emmènera en voyage à travers la Russie.","tgt":"Следующий модуль отправит нас в путешествие по России.","ro":"Sléduyushchiy módul' atprávit nas v puteshéstviye pa Rassíi."},{"fr":"Nous prendrons le Transsibérien jusqu'au lac Baïkal.","tgt":"Мы поедем по Транссибу до Байкала.","ro":"My payédem pa Transsíbu da Baykála."},{"fr":"Bravo, vous avez fait un excellent travail !","tgt":"Молодцы, отличная работа!","ro":"Maladtsý, atlíchnaya rabóta!"},{"fr":"À très bientôt dans le prochain module !","tgt":"До скорой встречи в следующем модуле!","ro":"Da skóray vstréchi v sléduyushchem módule!"}]}]},{"id":2,"name":"En voyage","desc":"Des situations de voyage plus variées et plus complexes.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"À la gare de Iaroslavl","phrases":[{"fr":"Notre train part de la gare de Iaroslavl.","tgt":"Наш поезд отправляется с Ярославского вокзала.","ro":"Nash póyezd atpravlyáyetsa s Yaraslávskava vakzála."},{"fr":"Je voudrais un billet jusqu'à Irkoutsk, s'il vous plaît.","tgt":"Я хотел бы билет до Иркутска, пожалуйста.","ro":"Ya khatél by bilét da Irkútska, pazhálsta."},{"fr":"Combien de jours faut-il pour aller jusqu'à Irkoutsk ?","tgt":"Сколько дней ехать до Иркутска?","ro":"Skól'ka dney yékhat' da Irkútska?"},{"fr":"Presque quatre jours, avec un arrêt à Novossibirsk.","tgt":"Почти четыре дня, с остановкой в Новосибирске.","ro":"Pachtí chetýre dnya, s astanóvkay v Navasibírske."},{"fr":"Je préfère un compartiment à quatre places.","tgt":"Я предпочитаю купе на четыре места.","ro":"Ya predpachitáyu kupé na chetýre mésta."},{"fr":"Le billet coûte quinze mille roubles.","tgt":"Билет стоит пятнадцать тысяч рублей.","ro":"Bilét stóit pyatnátsat' týsyach rubléy."},{"fr":"Vous voulez partir quel jour ?","tgt":"В какой день вы хотите ехать?","ro":"V kakóy den' vy khatíte yékhat'?"},{"fr":"Demain soir, si c'est possible.","tgt":"Завтра вечером, если можно.","ro":"Závtra vécheram, yésli mózhna."},{"fr":"Voici votre billet et votre numéro de place.","tgt":"Вот ваш билет и номер места.","ro":"Vot vash bilét i nómer mésta."},{"fr":"J'ai du mal à croire que je pars vraiment !","tgt":"Не верится, что я правда еду!","ro":"Ne véritsa, shto ya právda yédu!"}]},{"title":"Le départ de Moscou","phrases":[{"fr":"Le train part à minuit moins dix.","tgt":"Поезд отходит без десяти двенадцать.","ro":"Póyezd atkhódit bez desyatí dvenátsat'."},{"fr":"Nous montons dans le wagon numéro sept.","tgt":"Мы садимся в седьмой вагон.","ro":"My sadímsya v sed'móy vagón."},{"fr":"La contrôleuse vérifie les billets et les passeports.","tgt":"Проводница проверяет билеты и паспорта.","ro":"Pravadnítsa praveryáyet biléty i paspartá."},{"fr":"Notre compartiment est au milieu du wagon.","tgt":"Наше купе в середине вагона.","ro":"Náshe kupé v seredíne vagóna."},{"fr":"Je mets ma valise sous la couchette.","tgt":"Я кладу чемодан под полку.","ro":"Ya kladú chemadán pad pólku."},{"fr":"Les draps sont déjà posés sur la couchette.","tgt":"Постельное бельё уже лежит на полке.","ro":"Pastél'naye bel'yó uzhé lezhít na pólke."},{"fr":"Le train démarre lentement.","tgt":"Поезд медленно трогается.","ro":"Póyezd médlenna trógayetsa."},{"fr":"Au revoir, Moscou ! On se revoit dans trois semaines.","tgt":"До свидания, Москва! Увидимся через три недели.","ro":"Da svidániya, Maskvá! Uvídimsya chérez tri nedéli."},{"fr":"Les lumières de la ville disparaissent peu à peu.","tgt":"Огни города постепенно исчезают.","ro":"Agní górada pastepénna ischezáyut."},{"fr":"Le grand voyage commence enfin.","tgt":"Наконец-то начинается путешествие.","ro":"Nakanéts-ta nachináyetsa puteshéstviye."}]},{"title":"La vie dans le wagon","phrases":[{"fr":"Je vais au wagon-restaurant.","tgt":"Я иду в вагон-ресторан.","ro":"Ya idú v vagón-restarán."},{"fr":"Les enfants marchent dans le couloir toute la journée.","tgt":"Дети весь день ходят по коридору.","ro":"Déti ves' den' khódyat pa karidóru."},{"fr":"Où est-ce que vous allez ?","tgt":"Куда вы идёте?","ro":"Kudá vy idyóte?"},{"fr":"Je vais chercher de l'eau bouillante.","tgt":"Я иду за кипятком.","ro":"Ya idú za kipyatkóm."},{"fr":"Je vais souvent voir la contrôleuse pour avoir du thé.","tgt":"Я часто хожу к проводнице за чаем.","ro":"Ya chásta khazhú k pravadnítse za cháyem."},{"fr":"Dans le train, les gens marchent peu.","tgt":"В поезде люди мало ходят.","ro":"V póyezde lyúdi mála khódyat."},{"fr":"Le matin, je vais toujours me laver le premier.","tgt":"Утром я всегда хожу умываться первым.","ro":"Útram ya vsegdá khazhú umyvátsa pérvym."},{"fr":"Regardez, un homme avec un chien marche sur le quai.","tgt":"Смотрите, по перрону идёт человек с собакой.","ro":"Smatríte, pa perrónu idyót chelavék s sabákay."},{"fr":"J'avance lentement : le wagon tangue.","tgt":"Я иду медленно: вагон качается.","ro":"Ya idú médlenna: vagón kacháyetsa."},{"fr":"Dans le train, le temps passe autrement.","tgt":"В поезде время идёт по-другому.","ro":"V póyezde vrémya idyót pa-drugómu."}],"tip":{"title":"Les verbes de mouvement : « idtí » et « khadít' »","example":"Je vais chercher de l'eau bouillante. — Я <b>иду</b> за кипятком.","body":"En français, on dit simplement « aller », mais le russe distingue deux verbes. « Idtí » désigne un trajet précis, dans une seule direction, en ce moment : « Ya idú za kipyatkóm », littéralement je vais pour l'eau bouillante, c'est-à-dire j'y vais maintenant. « Khadít' » désigne les allers-retours, les habitudes ou le fait de marcher en général : « Ya chásta khazhú k pravadnítse », je vais souvent voir la contrôleuse. Pour demander à quelqu'un où il va maintenant, on dit « Kudá vy idyóte ? », et pour une habitude, « Vy chásta khódite ? », vous y allez souvent ? Astuce pour retenir : « idtí », c'est une flèche tendue vers un but, « khadít' », c'est une boucle qui revient sur elle-même.","exampleRo":"Ya idú za kipyatkóm.","lit":"je · vais (à pied, maintenant) · pour · eau bouillante"}},{"title":"Le samovar du train","phrases":[{"fr":"Au bout du wagon, il y a un grand samovar.","tgt":"В конце вагона стоит большой самовар.","ro":"V kantsé vagóna stoít bal'shóy samavár."},{"fr":"L'eau bouillante est gratuite jour et nuit.","tgt":"Кипяток бесплатный днём и ночью.","ro":"Kipyatók besplátnyy dnyom i nóch'yu."},{"fr":"La contrôleuse nous apporte du thé dans des porte-verres.","tgt":"Проводница приносит нам чай в подстаканниках.","ro":"Pravadnítsa prinósit nam chay v padstakánnikakh."},{"fr":"Ces porte-verres en métal sont très jolis.","tgt":"Эти металлические подстаканники очень красивые.","ro":"Éti metallícheskiye padstakánniki óchen' krasívyye."},{"fr":"Je bois mon thé avec du citron et du sucre.","tgt":"Я пью чай с лимоном и сахаром.","ro":"Ya p'yu chay s limónam i sákharam."},{"fr":"Vous voulez aussi un verre de thé ?","tgt":"Вы тоже хотите стакан чаю?","ro":"Vy tózhe khatíte stakán cháyu?"},{"fr":"Avec plaisir, et moi, j'ai apporté des biscuits.","tgt":"С удовольствием, а я принёс печенье.","ro":"S udavól'stviyem, a ya prinyós pechén'ye."},{"fr":"Tout le monde boit du thé du matin au soir.","tgt":"Все пьют чай с утра до вечера.","ro":"Vse p'yut chay s utrá da véchera."},{"fr":"Dans le train, le thé a meilleur goût, c'est sûr.","tgt":"В поезде чай вкуснее, это точно.","ro":"V póyezde chay vkusnéye, éta tóchna."},{"fr":"Je vais acheter un porte-verre en souvenir.","tgt":"Я куплю подстаканник на память.","ro":"Ya kuplyú padstakánnik na pámyat'."}]},{"title":"Au wagon-restaurant","phrases":[{"fr":"Est-ce qu'il faut réserver une table ?","tgt":"Надо заказывать столик?","ro":"Náda zakázyvat' stólik?"},{"fr":"Non, vous pouvez vous asseoir où vous voulez.","tgt":"Нет, можно сесть куда хотите.","ro":"Net, mózhna sest' kudá khatíte."},{"fr":"J'ai besoin du menu, s'il vous plaît.","tgt":"Мне нужно меню, пожалуйста.","ro":"Mne núzhna menyú, pazhálsta."},{"fr":"Il faut absolument goûter la solianka.","tgt":"Обязательно надо попробовать солянку.","ro":"Abyazátel'na náda papróbavat' salyánku."},{"fr":"On doit payer en espèces ou par carte ?","tgt":"Платить нужно наличными или картой?","ro":"Platít' núzhna nalíchnymi íli kártay?"},{"fr":"Il me faudrait encore une fourchette.","tgt":"Мне нужна ещё одна вилка.","ro":"Mne nuzhná yeshchyó adná vílka."},{"fr":"On n'a pas besoin de dessert.","tgt":"Десерт нам не нужен.","ro":"Desért nam ne núzhen."},{"fr":"Faut-il laisser un pourboire ici ?","tgt":"Здесь надо оставлять чаевые?","ro":"Zdes' náda astavlyát' chayevýye?"},{"fr":"Je dois retourner dans mon compartiment.","tgt":"Мне надо вернуться в купе.","ro":"Mne náda vernútsa v kupé."},{"fr":"Le dîner était très bon, merci beaucoup.","tgt":"Ужин был очень вкусный, большое спасибо.","ro":"Úzhin byl óchen' vkúsnyy, bal'shóye spasíba."}],"tip":{"title":"« Náda » et « núzhna » : il faut, j'ai besoin","example":"J'ai besoin du menu, s'il vous plaît. — Мне <b>нужно</b> меню, пожалуйста.","body":"Pour dire « il faut », le russe utilise un petit mot qui ne change pas, « náda » ou « núzhna », suivi d'un verbe à l'infinitif : « Náda papróbavat' salyánku », il faut goûter la solianka. Pour dire qui doit le faire, on ajoute la personne sous la forme « à moi », « à nous » : « mne náda », « nam náda », littéralement à moi il faut. Quand on a besoin d'une chose, « núzhna » s'accorde avec cette chose : « mne núzhen bilét » pour un billet, « mne nuzhná vílka » pour une fourchette, « mne núzhna menyú » pour le menu. Décomposons « Mne núzhna menyú » : à moi, nécessaire, le menu. Astuce : pensez à la tournure française « il me faut », où, comme en russe, la chose dont on a besoin vient vers vous.","exampleRo":"Mne núzhna menyú, pazhálsta.","lit":"à moi · nécessaire · menu · s'il vous plaît"}},{"title":"Les voisins de compartiment","phrases":[{"fr":"Bonjour, je suis votre voisin de compartiment.","tgt":"Здравствуйте, я ваш сосед по купе.","ro":"Zdrávstvuyte, ya vash saséd pa kupé."},{"fr":"Je m'appelle Pierre, je viens de Lyon.","tgt":"Меня зовут Пьер, я из Лиона.","ro":"Menyá zavút P'yer, ya iz Lióna."},{"fr":"Notre voisine va voir sa fille à Krasnoïarsk.","tgt":"Наша соседка едет в Красноярск к дочери.","ro":"Násha sasédka yédet v Krasnayársk k dócheri."},{"fr":"Elle a emporté un énorme sac de provisions.","tgt":"Она взяла с собой огромную сумку с едой.","ro":"Aná vzyalá s sabóy agrómnuyu súmku s yedóy."},{"fr":"Servez-vous en pirojki, ils sont faits maison.","tgt":"Берите пирожки, они домашние.","ro":"Beríte pirazhkí, aní damáshniye."},{"fr":"Le monsieur d'en face joue aux échecs avec moi.","tgt":"Мужчина напротив играет со мной в шахматы.","ro":"Muzhchína naprótiv igráyet sa mnoy v shákhmaty."},{"fr":"Il a déjà fait ce trajet dix fois.","tgt":"Он уже десять раз ездил по этому маршруту.","ro":"On uzhé désyat' raz yézdil pa étamu marshrútu."},{"fr":"On bavarde de tout pendant des heures.","tgt":"Мы часами болтаем обо всём.","ro":"My chasámi baltáyem aba vsyom."},{"fr":"Dans le train, les inconnus deviennent vite des amis.","tgt":"В поезде незнакомые люди быстро становятся друзьями.","ro":"V póyezde neznakómyye lyúdi býstra stanóvyatsa druz'yámi."},{"fr":"Voici mon adresse, écrivez-moi.","tgt":"Вот мой адрес, пишите мне.","ro":"Vot moy ádres, pishíte mne."}]},{"title":"Un arrêt sur le quai","phrases":[{"fr":"Le train s'arrête vingt minutes à Kirov.","tgt":"Поезд стоит в Кирове двадцать минут.","ro":"Póyezd stoít v Kírave dvátsat' minút."},{"fr":"On peut descendre se dégourdir les jambes.","tgt":"Можно выйти размять ноги.","ro":"Mózhna výyti razmyát' nógi."},{"fr":"Sur le quai, des grands-mères vendent des pommes de terre chaudes.","tgt":"На перроне бабушки продают горячую картошку.","ro":"Na perróne bábushki pradayút garyáchuyu kartóshku."},{"fr":"Combien coûtent ces pirojki au chou ?","tgt":"Сколько стоят эти пирожки с капустой?","ro":"Skól'ka stóyat éti pirazhkí s kapústay?"},{"fr":"Cinquante roubles pièce, ils sont encore chauds.","tgt":"Пятьдесят рублей за штуку, они ещё горячие.","ro":"Pyat'desyát rubléy za shtúku, aní yeshchyó garyáchiye."},{"fr":"Il fait froid, mettez votre bonnet.","tgt":"Холодно, наденьте шапку.","ro":"Khóladna, nadén'te shápku."},{"fr":"Ne vous éloignez pas trop du wagon !","tgt":"Не отходите далеко от вагона!","ro":"Ne atkhadíte dalekó at vagóna!"},{"fr":"La contrôleuse rappelle tout le monde dans le wagon.","tgt":"Проводница зовёт всех обратно в вагон.","ro":"Pravadnítsa zavyót vsekh abrátna v vagón."},{"fr":"Vite, le train repart dans deux minutes !","tgt":"Скорее, поезд отправляется через две минуты!","ro":"Skaréye, póyezd atpravlyáyetsa chérez dve minúty!"},{"fr":"J'ai acheté un sachet de pignons de cèdre.","tgt":"Я купил пакетик кедровых орешков.","ro":"Ya kupíl pakétik kedróvykh aréshkav."}]},{"title":"Une escale à Novossibirsk","phrases":[{"fr":"Si le train n'a pas de retard, on arrivera à Novossibirsk le matin.","tgt":"Если поезд не опоздает, мы приедем в Новосибирск утром.","ro":"Yésli póyezd ne apazdáyet, my priyédem v Navasibírsk útram."},{"fr":"Si vous avez le temps, allez voir le théâtre d'opéra.","tgt":"Если у вас будет время, сходите в оперный театр.","ro":"Yésli u vas búdet vrémya, skhadíte v ópernyy teátr."},{"fr":"S'il pleut, on ira au musée.","tgt":"Если пойдёт дождь, мы пойдём в музей.","ro":"Yésli paydyót dozhd', my paydyóm v muzéy."},{"fr":"Si vous voulez, je peux vous montrer la ville.","tgt":"Если хотите, я могу показать вам город.","ro":"Yésli khatíte, ya magú pakazát' vam górad."},{"fr":"Novossibirsk est très grande et très jeune.","tgt":"Новосибирск очень большой и молодой.","ro":"Navasibírsk óchen' bal'shóy i maladóy."},{"fr":"Si on a faim, on mangera des pelmenis près de la gare.","tgt":"Если проголодаемся, поедим пельменей у вокзала.","ro":"Yésli pragaladáyemsya, payedím pel'ményey u vakzála."},{"fr":"Si je rate mon train, je prendrai le suivant.","tgt":"Если я опоздаю на поезд, я сяду на следующий.","ro":"Yésli ya apazdáyu na póyezd, ya syádu na sléduyushchiy."},{"fr":"Ne vous inquiétez pas : si vous vous perdez, appelez-moi.","tgt":"Не волнуйтесь: если потеряетесь, звоните мне.","ro":"Ne valnúytes': yésli pateryáyetes', zvaníte mne."},{"fr":"La gare de Novossibirsk est immense et toute verte.","tgt":"Вокзал в Новосибирске огромный и весь зелёный.","ro":"Vakzál v Navasibírske agrómnyy i ves' zelyónyy."},{"fr":"Si tout va bien, nous repartirons ce soir.","tgt":"Если всё будет хорошо, мы уедем сегодня вечером.","ro":"Yésli vsyo búdet kharashó, my uyédem sevódnya vécheram."}],"tip":{"title":"« Yésli » : si, la condition","example":"Si tout va bien, nous repartirons ce soir. — <b>Если</b> всё будет хорошо, мы уедем сегодня вечером.","body":"« Yésli » veut dire « si » et se place en tête de la phrase, exactement comme en français : « Yésli khatíte, ya magú pakazát' vam górad », si vous voulez, je peux vous montrer la ville. La vraie différence concerne le futur : là où le français dit « si tout va bien », le russe dit « si tout sera bien », « yésli vsyo búdet kharashó ». Décomposons : « yésli » si, « vsyo » tout, « búdet » sera, « kharashó » bien. De même, « Yésli paydyót dozhd' » signifie mot à mot s'il pleuvra, et « Yésli u vas búdet vrémya », si vous aurez du temps. Astuce : quand la condition parle de plus tard, mettez le futur des deux côtés de la phrase, le russe est plus logique que le français sur ce point.","exampleRo":"Yésli vsyo búdet kharashó, my uyédem sevódnya vécheram.","lit":"si · tout · sera · bien · nous · partirons · aujourd'hui · le soir"}},{"title":"Une journée à Novossibirsk","phrases":[{"fr":"Le théâtre d'opéra a une immense coupole.","tgt":"У оперного театра огромный купол.","ro":"U ópernava teátra agrómnyy kúpal."},{"fr":"On se promène sur les quais de l'Ob.","tgt":"Мы гуляем по набережной Оби.","ro":"My gulyáyem pa náberezhnay Óbi."},{"fr":"Le pont sur le fleuve est très long.","tgt":"Мост через реку очень длинный.","ro":"Most chérez réku óchen' dlínnyy."},{"fr":"L'après-midi, on prend le bus pour Akademgorodok.","tgt":"После обеда мы едем на автобусе в Академгородок.","ro":"Pósle abéda my yédem na avtóbuse v Akademgaradók."},{"fr":"C'est une petite ville de scientifiques au milieu de la forêt.","tgt":"Это городок учёных среди леса.","ro":"Éta garadók uchyónykh sredí lésa."},{"fr":"Les écureuils mangent directement dans la main.","tgt":"Белки едят прямо с руки.","ro":"Bélki yedyát pryáma s rukí."},{"fr":"J'ai acheté des noix pour eux.","tgt":"Я купил для них орехи.","ro":"Ya kupíl dlya nikh arékhi."},{"fr":"Le soir, nous avons dîné dans un petit café.","tgt":"Вечером мы поужинали в маленьком кафе.","ro":"Vécheram my paúzhinali v málen'kam kafé."},{"fr":"Il faisait déjà froid, mais la ville était belle.","tgt":"Было уже холодно, но город был красивый.","ro":"Býla uzhé khóladna, no górad byl krasívyy."},{"fr":"Cette escale m'a vraiment plu.","tgt":"Эта остановка мне очень понравилась.","ro":"Éta astanóvka mne óchen' panrávilas'."}]},{"title":"Une nuit dans le train","phrases":[{"fr":"La contrôleuse éteint la lumière à dix heures.","tgt":"Проводница выключает свет в десять часов.","ro":"Pravadnítsa vyklyucháyet svet v désyat' chasóv."},{"fr":"Je grimpe sur la couchette du haut.","tgt":"Я забираюсь на верхнюю полку.","ro":"Ya zabiráyus' na vérkhnyuyu pólku."},{"fr":"Le bruit des roues m'endort tout de suite.","tgt":"Стук колёс сразу меня усыпляет.","ro":"Stuk kalyós srázu menyá usyplyáyet."},{"fr":"Mon voisin ronfle un peu, mais ce n'est pas grave.","tgt":"Мой сосед немного храпит, но это не страшно.","ro":"Moy saséd nemnóga khrapít, no éta ne stráshna."},{"fr":"Vers trois heures, le train s'arrête dans une petite gare.","tgt":"Около трёх часов поезд останавливается на маленькой станции.","ro":"Ókala tryokh chasóv póyezd astanávlivayetsa na málen'kay stántsii."},{"fr":"Je regarde par la fenêtre : tout est sous la neige.","tgt":"Я смотрю в окно: всё в снегу.","ro":"Ya smatryú v aknó: vsyo v snegú."},{"fr":"Il n'y a personne sur le quai.","tgt":"На платформе никого нет.","ro":"Na platfórme nikavó net."},{"fr":"Je me réveille à l'aube, en pleine taïga.","tgt":"Я просыпаюсь на рассвете, посреди тайги.","ro":"Ya prasypáyus' na rassvéte, pasredí taygí."},{"fr":"Le soleil se lève au-dessus des bouleaux.","tgt":"Над берёзами встаёт солнце.","ro":"Nad beryózami vstayót sóntse."},{"fr":"Bonjour ! Comment avez-vous dormi ?","tgt":"Доброе утро! Как вы спали?","ro":"Dóbraye útra! Kak vy spáli?"}]},{"title":"La taïga par la fenêtre","phrases":[{"fr":"Ça fait trois jours qu'on ne voit presque que des forêts.","tgt":"Уже третий день мы видим почти одни леса.","ro":"Uzhé trétiy den' my vídim pachtí adní lesá."},{"fr":"La taïga semble sans fin.","tgt":"Тайга кажется бесконечной.","ro":"Taygá kázhetsa beskanéchnay."},{"fr":"De temps en temps, on passe devant un petit village.","tgt":"Иногда мы проезжаем мимо маленькой деревни.","ro":"Inagdá my prayezzháyem míma málen'kay derévni."},{"fr":"Les maisons ont des fenêtres bleues sculptées.","tgt":"У домов резные синие окна.","ro":"U damóv reznýye síniye ókna."},{"fr":"Nous traversons un grand fleuve, c'est l'Ienisseï.","tgt":"Мы переезжаем большую реку, это Енисей.","ro":"My pereyezzháyem bal'shúyu réku, éta Yeniséy."},{"fr":"Il faut encore avancer nos montres.","tgt":"Нужно опять переводить часы.","ro":"Núzhna apyát' perevadít' chasý."},{"fr":"Ici, il est déjà quatre heures de plus qu'à Moscou.","tgt":"Здесь уже на четыре часа больше, чем в Москве.","ro":"Zdes' uzhé na chetýre chasá ból'she, chem v Maskvé."},{"fr":"Je lis un livre et je rêvasse.","tgt":"Я читаю книгу и мечтаю.","ro":"Ya chitáyu knígu i mechtáyu."},{"fr":"Je n'ai jamais vu autant d'espace.","tgt":"Я никогда не видел столько простора.","ro":"Ya nikagdá ne vídel stól'ka prastóra."},{"fr":"Ce pays est vraiment immense.","tgt":"Эта страна действительно огромная.","ro":"Éta straná deystvítel'na agrómnaya."}]},{"title":"Arrivée à Irkoutsk","phrases":[{"fr":"Nous sommes arrivés à Irkoutsk à l'heure.","tgt":"Мы приехали в Иркутск вовремя.","ro":"My priyékhali v Irkútsk vóvremya."},{"fr":"Quand est-ce que vous êtes arrivé ?","tgt":"Когда вы приехали?","ro":"Kagdá vy priyékhali?"},{"fr":"Mon ami est venu me chercher à la gare.","tgt":"Мой друг приехал за мной на вокзал.","ro":"Moy drug priyékhal za mnoy na vakzál."},{"fr":"Le train est déjà reparti plus loin, vers Vladivostok.","tgt":"Поезд уже уехал дальше, во Владивосток.","ro":"Póyezd uzhé uyékhal dál'she, va Vladivastók."},{"fr":"Demain matin, je pars au Baïkal.","tgt":"Завтра утром я уезжаю на Байкал.","ro":"Závtra útram ya uyezzháyu na Baykál."},{"fr":"Dans une semaine, je reviendrai à Irkoutsk.","tgt":"Через неделю я снова приеду в Иркутск.","ro":"Chérez nedélyu ya snóva priyédu v Irkútsk."},{"fr":"Et vous, vous partez quand ?","tgt":"А вы когда уезжаете?","ro":"A vy kagdá uyezzháyete?"},{"fr":"Mes amis arriveront de Moscou samedi.","tgt":"Мои друзья приедут из Москвы в субботу.","ro":"Maí druz'yá priyédut iz Maskvý v subbótu."},{"fr":"Irkoutsk m'a plu tout de suite.","tgt":"Иркутск мне сразу понравился.","ro":"Irkútsk mne srázu panrávilsya."},{"fr":"Je n'ai pas envie de partir d'ici trop vite.","tgt":"Мне не хочется уезжать отсюда слишком быстро.","ro":"Mne ne khóchetsa uyezzhát' atsyúda slíshkam býstra."}],"tip":{"title":"Les préfixes de mouvement : « priyékhat' », « uyékhat' »","example":"Mon ami est venu me chercher à la gare. — Мой друг <b>приехал</b> за мной на вокзал.","body":"Le russe construit ses verbes comme un jeu de construction : on part de « yékhat' », aller en véhicule, et on colle un petit préfixe devant. « Pri » marque l'arrivée, « priyékhat' », arriver, et « u » marque le départ, « uyékhat' », partir, s'en aller. Ainsi « Moy drug priyékhal za mnoy na vakzál » se décompose en mon ami, est arrivé, pour moi, à la gare. Pour un projet proche, on dit « Závtra ya uyezzháyu », demain je pars, et pour une promesse, « Ya priyédu », je viendrai. Les mêmes préfixes marchent pour la marche à pied : « prishól », il est arrivé, « ushól », il est parti. Astuce : « pri », c'est quelqu'un qui pousse la porte pour entrer, et « u », c'est le dernier signe de la main avant de disparaître.","exampleRo":"Moy drug priyékhal za mnoy na vakzál.","lit":"mon · ami · est arrivé · pour · moi · à · gare"}},{"title":"Les maisons en bois d'Irkoutsk","phrases":[{"fr":"Le centre est plein de vieilles maisons en bois.","tgt":"В центре много старых деревянных домов.","ro":"V tséntre mnóga stárykh derevyánnykh damóv."},{"fr":"Certaines penchent un peu sur le côté.","tgt":"Некоторые немного наклонились набок.","ro":"Nékataryye nemnóga naklanílis' nábok."},{"fr":"Les fenêtres sont décorées de dentelle de bois.","tgt":"Окна украшены деревянным кружевом.","ro":"Ókna ukrásheny derevyánnym krúzhevam."},{"fr":"C'est un vrai musée à ciel ouvert.","tgt":"Это настоящий музей под открытым небом.","ro":"Éta nastayáshchiy muzéy pad atkrýtym nébam."},{"fr":"Une partie du quartier a été restaurée récemment.","tgt":"Часть квартала недавно отреставрировали.","ro":"Chast' kvartála nedávna atrestavríravali."},{"fr":"Dans les cafés, on sert des poze, des raviolis bouriates.","tgt":"В кафе подают позы, бурятские пельмени.","ro":"V kafé padayút pózy, buryátskiye pel'méni."},{"fr":"On les mange avec les mains pour ne pas perdre le bouillon.","tgt":"Их едят руками, чтобы не потерять бульон.","ro":"Ikh yedyát rukámi, shtóby ne pateryát' bul'yón."},{"fr":"Le long de l'Angara, il y a une belle promenade.","tgt":"Вдоль Ангары идёт красивая набережная.","ro":"Vdol' Angarý idyót krasívaya náberezhnaya."},{"fr":"L'eau de l'Angara est glacée même en été.","tgt":"Вода в Ангаре ледяная даже летом.","ro":"Vadá v Angaré ledyanáya dázhe létam."},{"fr":"Demain, on part pour le Baïkal !","tgt":"Завтра едем на Байкал!","ro":"Závtra yédem na Baykál!"}]},{"title":"La route du Baïkal","phrases":[{"fr":"Le minibus pour Listvianka part de la gare routière.","tgt":"Маршрутка до Листвянки отходит от автовокзала.","ro":"Marshrútka da Listvyánki atkhódit at avtavakzála."},{"fr":"Le trajet prend environ une heure.","tgt":"Дорога занимает около часа.","ro":"Daróga zanimáyet ókala chása."},{"fr":"La route passe à travers une forêt de pins.","tgt":"Дорога идёт через сосновый лес.","ro":"Daróga idyót chérez sasnóvyy les."},{"fr":"Soudain, le lac apparaît entre les arbres.","tgt":"Вдруг между деревьями появляется озеро.","ro":"Vdrug mézhdu derév'yami payavlyáyetsa ózera."},{"fr":"Le Baïkal ressemble à une mer.","tgt":"Байкал похож на море.","ro":"Baykál pakhózh na móre."},{"fr":"C'est le lac le plus profond du monde.","tgt":"Это самое глубокое озеро в мире.","ro":"Éta sámaye glubókaye ózera v míre."},{"fr":"L'eau est si transparente qu'on voit le fond.","tgt":"Вода такая прозрачная, что видно дно.","ro":"Vadá takáya prazráchnaya, shto vídna dno."},{"fr":"On dit qu'on peut la boire directement dans le lac.","tgt":"Говорят, её можно пить прямо из озера.","ro":"Gavaryát, yeyó mózhna pit' pryáma iz ózera."},{"fr":"Le chauffeur nous dépose près de l'embarcadère.","tgt":"Водитель высаживает нас у пристани.","ro":"Vadítel' vysázhivayet nas u prístani."},{"fr":"Ce paysage me coupe le souffle.","tgt":"У меня дух захватывает от этого вида.","ro":"U menyá dukh zakhvátyvayet at étava vída."}]},{"title":"L'omoul fumé","phrases":[{"fr":"Au marché de Listvianka, ça sent le poisson fumé.","tgt":"На рынке в Листвянке пахнет копчёной рыбой.","ro":"Na rýnke v Listvyánke pákhnet kapchyónay rýbay."},{"fr":"L'omoul ne vit que dans le Baïkal.","tgt":"Омуль водится только в Байкале.","ro":"Ómul' vóditsa tól'ka v Baykále."},{"fr":"Vous voulez de l'omoul fumé à chaud ou à froid ?","tgt":"Вам омуля горячего или холодного копчения?","ro":"Vam ómulya garyácheva íli khalódnava kapchéniya?"},{"fr":"Je vais goûter les deux, bien sûr.","tgt":"Я попробую оба, конечно.","ro":"Ya papróbuyu óba, kanéshna."},{"fr":"Celui-là est encore tiède.","tgt":"Этот ещё тёплый.","ro":"État yeshchyó tyóplyy."},{"fr":"C'est combien, le kilo d'omoul ?","tgt":"Сколько стоит килограмм омуля?","ro":"Skól'ka stóit kilagrámm ómulya?"},{"fr":"Prenez-en deux, ils sont bien gros.","tgt":"Берите две рыбки, они крупные.","ro":"Beríte dve rýbki, aní krúpnyye."},{"fr":"On mange le poisson sur la rive, avec du pain noir.","tgt":"Мы едим рыбу на берегу с чёрным хлебом.","ro":"My yedím rýbu na beregú s chyórnym khlébam."},{"fr":"C'est le meilleur poisson que j'aie jamais goûté.","tgt":"Это самая вкусная рыба, которую я пробовал.","ro":"Éta sámaya vkúsnaya rýba, katóruyu ya próbaval."},{"fr":"Je dois absolument en rapporter à la maison.","tgt":"Надо обязательно привезти омуля домой.","ro":"Náda abyazátel'na priveztí ómulya damóy."}]},{"title":"Une auberge en bois","phrases":[{"fr":"Bonsoir, nous avons réservé une chambre pour trois nuits.","tgt":"Добрый вечер, мы забронировали комнату на три ночи.","ro":"Dóbryy vécher, my zabraníravali kómnatu na tri nóchi."},{"fr":"Montrez vos passeports, s'il vous plaît.","tgt":"Покажите, пожалуйста, ваши паспорта.","ro":"Pakazhíte, pazhálsta, váshi paspartá."},{"fr":"Dites-moi, le petit-déjeuner est à quelle heure ?","tgt":"Скажите, во сколько завтрак?","ro":"Skazhíte, va skól'ka závtrak?"},{"fr":"Toute la maison est construite en rondins.","tgt":"Весь дом построен из брёвен.","ro":"Ves' dom pastróyen iz bryóven."},{"fr":"Ça sent le bois et le poêle.","tgt":"Пахнет деревом и печкой.","ro":"Pákhnet dérevam i péchkay."},{"fr":"Donnez-moi une couverture de plus, s'il vous plaît.","tgt":"Дайте, пожалуйста, ещё одно одеяло.","ro":"Dáyte, pazhálsta, yeshchyó adnó adeyála."},{"fr":"Montrez-nous le chemin du lac, s'il vous plaît.","tgt":"Покажите нам, пожалуйста, дорогу к озеру.","ro":"Pakazhíte nam, pazhálsta, darógu k ózeru."},{"fr":"Dites, on peut chauffer le bania ce soir ?","tgt":"Скажите, а можно сегодня вечером затопить баню?","ro":"Skazhíte, a mózhna sevódnya vécheram zatapít' bányu?"},{"fr":"Entrez, installez-vous, faites comme chez vous.","tgt":"Проходите, располагайтесь, будьте как дома.","ro":"Prakhadíte, raspalagáytes', búd'te kak dóma."},{"fr":"Réveillez-nous à sept heures, s'il vous plaît.","tgt":"Разбудите нас, пожалуйста, в семь часов.","ro":"Razbudíte nas, pazhálsta, v sem' chasóv."}],"tip":{"title":"L'impératif poli : « skazhíte », « pakazhíte »","example":"Dites-moi, le petit-déjeuner est à quelle heure ? — <b>Скажите</b>, во сколько завтрак?","body":"Pour demander poliment quelque chose à quelqu'un qu'on vouvoie, le russe utilise un impératif qui se termine presque toujours par « íte » : « skazhíte », dites, « pakazhíte », montrez, « razbudíte », réveillez. C'est l'équivalent exact de notre terminaison en « ez », et on l'adoucit avec « pazhálsta », s'il vous plaît, placé juste après le verbe. « Skazhíte » sert aussi à ouvrir n'importe quelle question, comme notre « dites-moi » : « Skazhíte, va skól'ka závtrak ? », mot à mot dites, à combien, petit-déjeuner. Retenez aussi « dáyte », donnez, très utile à l'hôtel ou au marché : « Dáyte, pazhálsta, adeyála », donnez-moi une couverture. Astuce : dès que vous entendez « íte » à la fin d'un verbe, c'est qu'on vous demande poliment de faire quelque chose.","exampleRo":"Skazhíte, va skól'ka závtrak?","lit":"dites · à · combien · petit-déjeuner"}},{"title":"Le bania au bord du lac","phrases":[{"fr":"Le bania se trouve juste au bord de l'eau.","tgt":"Баня стоит прямо у воды.","ro":"Bánya stoít pryáma u vadý."},{"fr":"Le propriétaire l'a chauffé pendant trois heures.","tgt":"Хозяин топил её три часа.","ro":"Khazyáin tapíl yeyó tri chasá."},{"fr":"À l'intérieur, il fait plus de quatre-vingts degrés.","tgt":"Внутри больше восьмидесяти градусов.","ro":"Vnutrí ból'she vas'midesyatí grádusav."},{"fr":"On se fouette avec un balai de bouleau.","tgt":"Мы паримся берёзовым веником.","ro":"My párimsya beryózavym vénikam."},{"fr":"Ensuite, on court sauter dans le lac glacé.","tgt":"Потом бежим прыгать в ледяное озеро.","ro":"Patóm bezhím prýgat' v ledyanóye ózera."},{"fr":"L'eau fait à peine dix degrés.","tgt":"В воде всего десять градусов.","ro":"V vadé vsevó désyat' grádusav."},{"fr":"J'ai crié, mais je me sens incroyablement bien.","tgt":"Я закричал, но чувствую себя потрясающе.","ro":"Ya zakrichál, no chústvuyu sebyá patryasáyushche."},{"fr":"Après le bania, on boit une tisane.","tgt":"После бани пьём травяной чай.","ro":"Pósle báni p'yom travyanóy chay."},{"fr":"Avec du miel et de la confiture de baies.","tgt":"С мёдом и ягодным вареньем.","ro":"S myódam i yágadnym varén'yem."},{"fr":"Comme on dit ici après le bania : « Bonne vapeur ! »","tgt":"Как здесь говорят после бани: «С лёгким паром!»","ro":"Kak zdes' gavaryát pósle báni: «S lyókhkim páram!»"}]},{"title":"Une randonnée sur la rive","phrases":[{"fr":"Nous partons à pied le long du rivage.","tgt":"Мы идём пешком вдоль берега.","ro":"My idyóm peshkóm vdol' bérega."},{"fr":"Le sentier monte et descend sans arrêt.","tgt":"Тропа всё время то поднимается, то спускается.","ro":"Trapá vsyo vrémya to padnimáyetsa, to spuskáyetsa."},{"fr":"Prenez assez d'eau : il n'y a pas de magasin ici.","tgt":"Возьмите побольше воды: магазинов здесь нет.","ro":"Vaz'míte paból'she vadý: magazínav zdes' net."},{"fr":"Attention, le chemin est glissant après la pluie.","tgt":"Осторожно, после дождя тропа скользкая.","ro":"Astarózhna, pósle dazhdyá trapá skól'zkaya."},{"fr":"On fait un pique-nique sur un rocher.","tgt":"Мы устраиваем пикник на скале.","ro":"My ustráivayem pikník na skalé."},{"fr":"D'en haut, la vue sur le lac est incroyable.","tgt":"Сверху вид на озеро просто невероятный.","ro":"Svérkhu vid na ózera prósta neverayátnyy."},{"fr":"Regardez, un phoque se repose sur les pierres !","tgt":"Смотрите, на камнях отдыхает нерпа!","ro":"Smatríte, na kamnyákh atdykháyet nérpa!"},{"fr":"Ce sont les seuls phoques d'eau douce au monde.","tgt":"Это единственные пресноводные тюлени в мире.","ro":"Éta yedínstvennyye presnavódnyye tyuléni v míre."},{"fr":"Le soir, on fait un feu sur la plage.","tgt":"Вечером мы разводим костёр на берегу.","ro":"Vécheram my razvódim kastyór na beregú."},{"fr":"Je suis fatigué, mais tellement heureux.","tgt":"Я устал, но я так счастлив.","ro":"Ya ustál, no ya tak shchástliv."}]},{"title":"Les derniers jours au Baïkal","phrases":[{"fr":"C'est déjà notre dernière journée au bord du lac.","tgt":"Это уже наш последний день на Байкале.","ro":"Éta uzhé nash paslédniy den' na Baykále."},{"fr":"J'ai acheté des souvenirs pour ma famille.","tgt":"Я купил сувениры для семьи.","ro":"Ya kupíl suveníry dlya sem'í."},{"fr":"Un petit phoque en peluche pour ma nièce.","tgt":"Плюшевую нерпу для племянницы.","ro":"Plyúshevuyu nérpu dlya plemyánnitsy."},{"fr":"Et un pot de miel de la taïga pour mes parents.","tgt":"И банку таёжного мёда для родителей.","ro":"I bánku tayózhnava myóda dlya radíteley."},{"fr":"Je ramasse un caillou sur la plage en souvenir.","tgt":"Я беру на память камешек с берега.","ro":"Ya berú na pámyat' kámeshek s bérega."},{"fr":"Le patron de l'auberge nous fait ses adieux.","tgt":"Хозяин гостиницы прощается с нами.","ro":"Khazyáin gastínitsy prashcháyetsa s námi."},{"fr":"Revenez en été, c'est encore plus beau !","tgt":"Приезжайте летом, будет ещё красивее!","ro":"Priyezzháyte létam, búdet yeshchyó krasíveye!"},{"fr":"Nous promettons de revenir un jour.","tgt":"Мы обещаем когда-нибудь вернуться.","ro":"My abeshcháyem kagdá-nibud' vernútsa."},{"fr":"Le minibus pour Irkoutsk part à midi.","tgt":"Маршрутка в Иркутск уходит в полдень.","ro":"Marshrútka v Irkútsk ukhódit v pólden'."},{"fr":"Je laisse ici un petit morceau de mon cœur.","tgt":"Я оставляю здесь частичку своего сердца.","ro":"Ya astavlyáyu zdes' chastíchku svayevó sértsa."}]},{"title":"Fin du module : un bilan de voyage","phrases":[{"fr":"Ce voyage nous a menés de Moscou jusqu'au Baïkal.","tgt":"Это путешествие привело нас из Москвы на Байкал.","ro":"Éta puteshéstviye priveló nas iz Maskvý na Baykál."},{"fr":"Maintenant, je sais demander mon chemin en russe.","tgt":"Теперь я умею спрашивать дорогу по-русски.","ro":"Tepér' ya uméyu spráshivat' darógu pa-rússki."},{"fr":"Les verbes de mouvement ne me font plus peur.","tgt":"Глаголы движения меня уже не пугают.","ro":"Glagóly dvizhéniya menyá uzhé ne pugáyut."},{"fr":"Je sais dire ce dont j'ai besoin.","tgt":"Я могу сказать, что мне нужно.","ro":"Ya magú skazát', shto mne núzhna."},{"fr":"Et poser poliment des questions.","tgt":"И вежливо задавать вопросы.","ro":"I vézhliva zadavát' vaprósy."},{"fr":"Chaque étape m'a appris de nouveaux mots.","tgt":"Каждая остановка научила меня новым словам.","ro":"Kázhdaya astanóvka nauchíla menyá nóvym slavám."},{"fr":"Je parle russe plus librement qu'avant.","tgt":"Я говорю по-русски свободнее, чем раньше.","ro":"Ya gavaryú pa-rússki svabódneye, chem rán'she."},{"fr":"Bravo, vous avez fait un long chemin !","tgt":"Молодцы, вы прошли большой путь!","ro":"Maladtsý, vy prashlí bal'shóy put'!"},{"fr":"Reposez-vous bien avant le prochain module.","tgt":"Хорошо отдохните перед следующим модулем.","ro":"Kharashó atdakhníte péred sléduyushchim módulem."},{"fr":"À bientôt pour de nouvelles conversations !","tgt":"До скорой встречи и новых разговоров!","ro":"Da skóray vstréchi i nóvykh razgavórav!"}]}]},{"id":3,"name":"Conversation sociale","desc":"Des échanges sociaux plus nuancés et plus naturels.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Des retrouvailles à Sotchi","phrases":[{"fr":"Salut, ça me fait tellement plaisir de te revoir !","tgt":"Привет, как я рад тебя видеть!","ro":"Privét, kak ya rad tebyá vídet'!"},{"fr":"Tu es arrivé quand à Sotchi ?","tgt":"Когда ты приехал в Сочи?","ro":"Kagdá ty priyékhal v Sóchi?"},{"fr":"Je suis arrivé hier soir, par le train de nuit.","tgt":"Я приехал вчера вечером на ночном поезде.","ro":"Ya priyékhal vcherá vécheram na nachnóm póyezde."},{"fr":"Tu as fait bon voyage ?","tgt":"Ты хорошо доехал?","ro":"Ty kharashó dayékhal?"},{"fr":"Oui, mais le trajet a été long.","tgt":"Да, но дорога была долгой.","ro":"Da, no daróga bylá dólgay."},{"fr":"Tu loges où, cette fois-ci ?","tgt":"Где ты живёшь на этот раз?","ro":"Gde ty zhivyósh na état raz?"},{"fr":"Chez Macha, à deux pas de la mer.","tgt":"У Маши, в двух шагах от моря.","ro":"U Máshi, v dvukh shagákh at mórya."},{"fr":"Génial, on va se baigner tous les jours !","tgt":"Здорово, будем купаться каждый день!","ro":"Zdórava, búdem kupát'sya kázhdyy den'!"},{"fr":"Et les autres, ils arrivent quand ?","tgt":"А когда приезжают остальные?","ro":"A kagdá priyezzháyut astal'nýye?"},{"fr":"Ils arrivent en avion demain matin.","tgt":"Они прилетят завтра утром.","ro":"Aní priletyát závtra útram."}]},{"title":"Les surnoms entre amis","phrases":[{"fr":"Mon vrai prénom est Alexandre, mais tout le monde m'appelle Sacha.","tgt":"Моё настоящее имя Александр, но все зовут меня Саша.","ro":"Mayó nastayáshcheye ímya Aleksándr, no vse zavút menyá Sásha."},{"fr":"Ma sœur s'appelle Maria, mais pour nous, c'est Macha.","tgt":"Мою сестру зовут Мария, но для нас она Маша.","ro":"Mayú sestrú zavút Maríya, no dlya nas aná Másha."},{"fr":"Dmitri, Dima pour les amis, va bientôt arriver.","tgt":"Дмитрий, а для друзей Дима, скоро придёт.","ro":"Dmítriy, a dlya druzéy Díma, skóra pridyót."},{"fr":"Salut, Katia, comment ça va ?","tgt":"Привет, Катя, как дела?","ro":"Privét, Kátya, kak delá?"},{"fr":"Ne m'appelle pas Alexandre, ça fait trop sérieux !","tgt":"Не зови меня Александром, это слишком серьёзно!","ro":"Ne zaví menyá Aleksándram, éta slíshkam ser'yózna!"},{"fr":"Entre amis, on utilise toujours les diminutifs.","tgt":"Между друзьями мы всегда называем друг друга уменьшительными именами.","ro":"Mézhdu druz'yámi my vsegdá nazyváyem drug drúga umen'shítel'nymi imenámi."},{"fr":"Ma grand-mère m'appelle encore Sachenka.","tgt":"Бабушка до сих пор называет меня Сашенькой.","ro":"Bábushka da sikh por nazyváyet menyá Sáshen'kay."},{"fr":"Lena, tu viens avec nous à la plage ?","tgt":"Лена, ты пойдёшь с нами на пляж?","ro":"Léna, ty paydyósh s námi na plyazh?"},{"fr":"Sérioja, passe-moi le sel, s'il te plaît.","tgt":"Серёжа, передай мне соль, пожалуйста.","ro":"Seryózha, peredáy mne sol', pazhálsta."},{"fr":"Pour toi, je suis simplement Dima.","tgt":"Для тебя я просто Дима.","ro":"Dlya tebyá ya prósta Díma."}],"tip":{"title":"Le registre familier : les diminutifs « Sásha », « Másha »","example":"Ma sœur s'appelle Maria, mais pour nous, c'est Macha. — Мою сестру зовут Мария, но для нас она <b>Маша</b>.","body":"En russe, presque chaque prénom possède une forme courte et familière, qu'on emploie entre amis et en famille : Alexandre devient « Sásha », Maria devient « Másha », Dmitri devient « Díma » et Ekaterina devient « Kátya ». Dans « Mayú sestrú zavút Maríya, no dlya nas aná Másha », mot à mot « ma sœur, on l'appelle Maria, mais pour nous elle Macha », on passe en douceur du prénom officiel au diminutif. Avec un inconnu ou un collègue, on garde le prénom complet et le « vy » ; avec un ami, on passe au diminutif et au « ty ». Pour plus de tendresse, on ajoute encore « -en'ka » : « Sáshen'ka », « Máshen'ka », comme le ferait une grand-mère. Astuce : ces diminutifs se terminent presque tous par « a » ou « ya », même pour les garçons, alors ne soyez pas surpris qu'un grand gaillard s'appelle « Sásha ».","exampleRo":"Mayú sestrú zavút Maríya, no dlya nas aná Másha.","lit":"ma · sœur · [on] appelle · Maria · mais · pour · nous · elle · Macha"}},{"title":"Une journée à la plage","phrases":[{"fr":"Il fait chaud aujourd'hui, allons à la plage !","tgt":"Сегодня жарко, пошли на пляж!","ro":"Sevódnya zhárka, pashlí na plyazh!"},{"fr":"Pense à prendre de la crème solaire.","tgt":"Не забудь крем от солнца.","ro":"Ne zabúd' krem at sóntsa."},{"fr":"Le matin, l'eau est encore un peu froide.","tgt":"Утром вода ещё немного холодная.","ro":"Útram vadá yeshchó nemnóga khalódnaya."},{"fr":"Je préfère me baigner l'après-midi.","tgt":"Я больше люблю купаться днём.","ro":"Ya ból'she lyublyú kupát'sya dnyom."},{"fr":"Tu as pris le parasol ?","tgt":"Ты взял пляжный зонтик?","ro":"Ty vzyal plyázhnyy zóntik?"},{"fr":"Les galets sont brûlants, mets tes sandales.","tgt":"Галька горячая, надень сандалии.","ro":"Gál'ka garyáchaya, nadén' sandálii."},{"fr":"Je nage jusqu'aux bouées et je reviens.","tgt":"Я сплаваю до буйков.","ro":"Ya splávayu da buykóv."},{"fr":"Fais attention, il y a de grosses vagues aujourd'hui.","tgt":"Осторожно, сегодня сильные волны.","ro":"Astarózhna, sevódnya síl'nyye vólny."},{"fr":"On s'achète du maïs chaud ?","tgt":"Купим варёную кукурузу?","ro":"Kúpim varyónuyu kukurúzu?"},{"fr":"Après la baignade, j'ai toujours une faim de loup.","tgt":"После купания я всегда голоден как волк.","ro":"Pósle kupániya ya vsegdá góladen kak volk."}]},{"title":"La promenade du bord de mer","phrases":[{"fr":"Le soir, toute la ville se promène sur le front de mer.","tgt":"Вечером весь город гуляет по набережной.","ro":"Vécheram ves' górad gulyáyet pa náberezhnay."},{"fr":"Si on marchait jusqu'au port ?","tgt":"Давай прогуляемся до морского порта.","ro":"Daváy pragulyáyemsya da marskóva pórta."},{"fr":"Regarde comme le coucher de soleil est beau !","tgt":"Посмотри, какой красивый закат!","ro":"Pasmatrí, kakóy krasívyy zakát!"},{"fr":"On s'assoit un moment sur ce banc ?","tgt":"Сядем на эту скамейку ненадолго?","ro":"Syádem na étu skaméyku nenadólga?"},{"fr":"Ici, le soir, il y a toujours de la musique.","tgt":"Здесь вечером всегда играет музыка.","ro":"Zdes' vécheram vsegdá igráyet múzyka."},{"fr":"Je t'achète une glace ?","tgt":"Тебе купить мороженое?","ro":"Tebé kupít' marózhenaye?"},{"fr":"Oui, à la pistache, s'il te plaît.","tgt":"Да, фисташковое, пожалуйста.","ro":"Da, fistáshkavaye, pazhálsta."},{"fr":"Avant, on venait marcher ici tous les soirs.","tgt":"Раньше мы гуляли здесь каждый вечер.","ro":"Rán'she my gulyáli zdes' kázhdyy vécher."},{"fr":"Il y a beaucoup plus de monde qu'avant.","tgt":"Народу стало гораздо больше, чем раньше.","ro":"Naródu stála garázda ból'she, chem rán'she."},{"fr":"Rentrons, il commence à faire frais.","tgt":"Пойдём домой, становится прохладно.","ro":"Paydyóm damóy, stanóvitsya prakhládna."}]},{"title":"Les projets du week-end","phrases":[{"fr":"Qu'est-ce qu'on fait ce week-end ?","tgt":"Что будем делать в выходные?","ro":"Shto búdem délat' v vykhadnýye?"},{"fr":"On ira peut-être à la montagne.","tgt":"Может быть, поедем в горы.","ro":"Mózhet byt', payédem v góry."},{"fr":"Dima viendra peut-être aussi.","tgt":"Может быть, Дима тоже поедет.","ro":"Mózhet byt', Díma tózhe payédet."},{"fr":"S'il pleut, on restera peut-être à la maison.","tgt":"Если пойдёт дождь, может быть, останемся дома.","ro":"Yésli paydyót dozhd', mózhet byt', astánemsya dóma."},{"fr":"Ou alors, on ira peut-être au musée.","tgt":"Или, может быть, сходим в музей.","ro":"Íli, mózhet byt', skhódim v muzéy."},{"fr":"Samedi, tu es libre ?","tgt":"Ты свободен в субботу?","ro":"Ty svabóden v subbótu?"},{"fr":"Je ne sais pas encore, peut-être.","tgt":"Ещё не знаю, может быть.","ro":"Yeshchó ne znáyu, mózhet byt'."},{"fr":"Peut-être bien que tu as raison.","tgt":"Может быть, ты прав.","ro":"Mózhet byt', ty prav."},{"fr":"Et si on faisait un chachlik ?","tgt":"Может, сделаем шашлык?","ro":"Mózhet, sdélayem shashlýk?"},{"fr":"Excellente idée, j'appelle tout le monde.","tgt":"Отличная идея, я позвоню всем.","ro":"Atlíchnaya idéya, ya pazvanyú vsem."}],"tip":{"title":"« Mózhet byt' » : peut-être","example":"On ira peut-être à la montagne. — <b>Может быть</b>, поедем в горы.","body":"Pour dire « peut-être », le russe emploie « mózhet byt' », mot à mot « il peut être », exactement comme en français mais en deux mots bien séparés. On le place en tête de phrase, on marque une petite pause, puis on enchaîne : « Mózhet byt', payédem v góry », peut-être qu'on ira à la montagne. Attention, aucun « que » derrière : la suite de la phrase vient directement. Entre amis, on raccourcit très souvent en « mózhet » tout seul : « Mózhet, sdélayem shashlýk ? », et si on faisait un chachlik ? L'accent tombe sur « mó », et le « zh » se prononce comme le « j » de « jour ». Astuce : pensez à « il se peut », qui contient la même idée de pouvoir, et « mózhet » viendra tout seul.","exampleRo":"Mózhet byt', payédem v góry.","lit":"peut · être · [nous] irons · dans · montagnes"}},{"title":"Une journée à Krasnaïa Poliana","phrases":[{"fr":"Demain, on monte à Krasnaïa Poliana.","tgt":"Завтра мы едем в Красную Поляну.","ro":"Závtra my yédem v Krásnuyu Palyánu."},{"fr":"C'est à une heure de route de la mer.","tgt":"Это в часе езды от моря.","ro":"Éta v chasé yezdý at mórya."},{"fr":"On y va en train ou en bus ?","tgt":"Поедем на электричке или на автобусе?","ro":"Payédem na elektríchke íli na avtóbuse?"},{"fr":"Du sommet, la vue sur les montagnes est incroyable.","tgt":"С вершины открывается потрясающий вид на горы.","ro":"S vershíny atkryváyetsya patryasáyushchiy vid na góry."},{"fr":"Même en été, il reste de la neige sur les sommets.","tgt":"Даже летом на вершинах лежит снег.","ro":"Dázhe létam na vershínakh lezhít sneg."},{"fr":"Prends un pull, il fait plus frais là-haut.","tgt":"Возьми свитер, наверху холоднее.","ro":"Vaz'mí svíter, naverkhú khaladnéye."},{"fr":"Nous sommes montés tout en haut en téléphérique.","tgt":"Мы поднялись на канатной дороге на самый верх.","ro":"My padnyalís' na kanátnay daróge na sámyy verkh."},{"fr":"J'avais un peu peur, mais ça valait le coup.","tgt":"Мне было немного страшно, но оно того стоило.","ro":"Mne býla nemnóga stráshna, no anó tavó stóila."},{"fr":"Ensuite, nous avons mangé dans un petit café de montagne.","tgt":"Потом мы поели в маленьком горном кафе.","ro":"Patóm my payéli v málen'kam górnam kafé."},{"fr":"On reviendra cet hiver pour skier.","tgt":"Мы вернёмся сюда зимой кататься на лыжах.","ro":"My vernyómsya syudá zimóy katát'sya na lýzhakh."}]},{"title":"Un chachlik entre amis","phrases":[{"fr":"Samedi, on fait un chachlik à la datcha de Dima.","tgt":"В субботу делаем шашлык у Димы на даче.","ro":"V subbótu délayem shashlýk u Dímy na dáche."},{"fr":"Qui se charge de la viande ?","tgt":"Кто займётся мясом?","ro":"Kto zaymyótsya myásam?"},{"fr":"Moi, je la fais mariner dès ce soir.","tgt":"Я замариную его уже сегодня вечером.","ro":"Ya zamarinúyu yevó uzhé sevódnya vécheram."},{"fr":"N'oublie pas d'acheter du charbon.","tgt":"Не забудь купить уголь.","ro":"Ne zabúd' kupít' úgal'."},{"fr":"Macha apportera les légumes et le pain.","tgt":"Маша принесёт овощи и хлеб.","ro":"Másha prinesyót óvashchi i khleb."},{"fr":"Allume le feu, et moi, j'embroche la viande.","tgt":"Разжигай огонь, а я нанижу мясо на шампуры.","ro":"Razzhigáy agón', a ya nanizhú myása na shampurý."},{"fr":"Qu'est-ce que ça sent bon !","tgt":"Как вкусно пахнет!","ro":"Kak vkúsna pákhnet!"},{"fr":"Attends, la viande n'est pas encore cuite.","tgt":"Подожди, мясо ещё не готово.","ro":"Padazhdí, myása yeshchó ne gatóva."},{"fr":"Qui reprend du chachlik ?","tgt":"Кто хочет ещё шашлыка?","ro":"Kto khóchet yeshchó shashlyká?"},{"fr":"C'était le meilleur chachlik de tout l'été !","tgt":"Это был лучший шашлык за всё лето!","ro":"Éta byl lúchshiy shashlýk za vsyo léta!"}]},{"title":"Des souvenirs autour du feu","phrases":[{"fr":"Tu te souviens de notre premier été ensemble ?","tgt":"Помнишь наше первое лето вместе?","ro":"Pómnish náshe pérvaye léta vméste?"},{"fr":"À l'époque, on avait dix-huit ans.","tgt":"Нам тогда было восемнадцать лет.","ro":"Nam tagdá býla vasemnádtsat' let."},{"fr":"On dormait sous la tente sur la plage.","tgt":"Мы спали в палатке на пляже.","ro":"My spáli v palátke na plyázhe."},{"fr":"Une nuit, la pluie a tout inondé !","tgt":"Однажды ночью дождь всё залил!","ro":"Adnázhdy nóch'yu dozhd' vsyo zalíl!"},{"fr":"Sacha racontait des blagues jusqu'au matin.","tgt":"Саша рассказывал анекдоты до утра.","ro":"Sásha rasskázyval anekdóty da utrá."},{"fr":"C'est à ce moment-là que j'ai rencontré Katia.","tgt":"Тогда я и познакомился с Катей.","ro":"Tagdá ya i paznakómilsya s Kátey."},{"fr":"Raconte encore l'histoire du chien !","tgt":"Расскажи ещё раз ту историю с собакой!","ro":"Rasskazhí yeshchó raz tu istóriyu s sabákay!"},{"fr":"On riait tellement qu'on n'arrivait plus à s'arrêter.","tgt":"Мы так смеялись, что не могли остановиться.","ro":"My tak smeyális', shto ne maglí astanavít'sya."},{"fr":"Ce sont mes plus beaux souvenirs de jeunesse.","tgt":"Это мои самые лучшие воспоминания о молодости.","ro":"Éta maí sámyye lúchshiye vaspaminániya a móladasti."},{"fr":"On devrait se réunir ici chaque année.","tgt":"Нам надо собираться здесь каждый год.","ro":"Nam náda sabirát'sya zdes' kázhdyy god."}]},{"title":"Parler de son travail entre amis","phrases":[{"fr":"Alors, ça se passe comment au travail ?","tgt":"Ну, как дела на работе?","ro":"Nu, kak delá na rabóte?"},{"fr":"J'ai changé de travail au printemps.","tgt":"Весной я сменил работу.","ro":"Vesnóy ya smeníl rabótu."},{"fr":"Maintenant, je travaille dans un hôtel à Sotchi.","tgt":"Теперь я работаю в гостинице в Сочи.","ro":"Tepér' ya rabótayu v gastínitse v Sóchi."},{"fr":"L'été, nous avons énormément de clients.","tgt":"Летом у нас очень много клиентов.","ro":"Létam u nas óchen' mnóga kliyéntav."},{"fr":"Tu es content de ton nouveau poste ?","tgt":"Ты доволен новой работой?","ro":"Ty davólen nóvay rabótay?"},{"fr":"Oui, même si les horaires sont fatigants.","tgt":"Да, хотя график утомительный.","ro":"Da, khatyá gráfik utamítel'nyy."},{"fr":"Et toi, tu enseignes toujours le français ?","tgt":"А ты всё ещё преподаёшь французский?","ro":"A ty vsyo yeshchó prepadayósh frantsúzskiy?"},{"fr":"Oui, et cette année, j'ai des élèves adultes.","tgt":"Да, и в этом году у меня взрослые студенты.","ro":"Da, i v étam gadú u menyá vzróslyye studénty."},{"fr":"Ils sont très motivés, c'est un vrai plaisir de travailler avec eux.","tgt":"Они очень увлечённые, работать с ними одно удовольствие.","ro":"Aní óchen' uvlechónnyye, rabótat' s ními adnó udavól'stviye."},{"fr":"Bon, assez parlé du travail !","tgt":"Ладно, хватит о работе!","ro":"Ládna, khvátit a rabóte!"}]},{"title":"Préparer un anniversaire surprise","phrases":[{"fr":"Samedi prochain, c'est l'anniversaire de Lena.","tgt":"В следующую субботу у Лены день рождения.","ro":"V sléduyushchuyu subbótu u Lény den' razhdéniya."},{"fr":"Et si on lui préparait une surprise ?","tgt":"Может, устроим ей сюрприз?","ro":"Mózhet, ustróim yey syurpríz?"},{"fr":"Super idée, mais elle ne doit rien savoir !","tgt":"Отличная мысль, но она ничего не должна знать!","ro":"Atlíchnaya mysl', no aná nichevó ne dalzhná znat'!"},{"fr":"Le gâteau, je m'en occupe.","tgt":"Я беру на себя торт.","ro":"Ya berú na sebyá tort."},{"fr":"Qui l'emmène ailleurs pendant qu'on prépare tout ?","tgt":"Кто уведёт её, пока мы всё готовим?","ro":"Kto uvedyót yeyó, paká my vsyo gatóvim?"},{"fr":"Macha peut l'inviter à la plage.","tgt":"Маша может позвать её на пляж.","ro":"Másha mózhet pazvát' yeyó na plyazh."},{"fr":"On lui offre quoi ?","tgt":"Что подарим?","ro":"Shto padárim?"},{"fr":"Elle rêve d'un nouvel appareil photo.","tgt":"Она мечтает о новом фотоаппарате.","ro":"Aná mechtáyet a nóvam fataapparáte."},{"fr":"On met mille roubles chacun, d'accord ?","tgt":"Скинемся по тысяче рублей, хорошо?","ro":"Skínemsya pa týsyache rubléy, kharashó?"},{"fr":"Surtout, pas un mot à personne !","tgt":"Главное, никому ни слова!","ro":"Glávnaye, nikamú ni slóva!"}]},{"title":"La fête d'anniversaire","phrases":[{"fr":"Surprise ! Joyeux anniversaire, Lena !","tgt":"Сюрприз! С днём рождения, Лена!","ro":"Syurpríz! S dnyom razhdéniya, Léna!"},{"fr":"Je n'arrive pas à y croire, vous avez tout préparé !","tgt":"Не могу поверить, вы всё приготовили!","ro":"Ne magú pavérit', vy vsyo prigatóvili!"},{"fr":"Ouvre vite ton cadeau !","tgt":"Открывай скорее подарок!","ro":"Atkryváy skaréye padárak!"},{"fr":"Oh, c'est exactement ce que je voulais !","tgt":"Ой, это именно то, что я хотела!","ro":"Oy, éta ímenna to, shto ya khatéla!"},{"fr":"Je voudrais porter un toast.","tgt":"Я хочу поднять тост.","ro":"Ya khachú padnyát' tost."},{"fr":"À notre chère Lena, qu'elle reste toujours aussi joyeuse !","tgt":"За нашу дорогую Лену, пусть она всегда будет такой же весёлой!","ro":"Za náshu daragúyu Lénu, pust' aná vsegdá búdet takóy zhe vesyólay!"},{"fr":"Je te souhaite beaucoup de bonheur et une bonne santé.","tgt":"Желаю тебе счастья и здоровья.","ro":"Zheláyu tebé shchást'ya i zdaróv'ya."},{"fr":"Fais un vœu et souffle les bougies !","tgt":"Загадай желание и задувай свечи!","ro":"Zagadáy zhelániye i zaduváy svéchi!"},{"fr":"Il y a combien de bougies sur le gâteau ?","tgt":"Сколько свечей на торте?","ro":"Skól'ka svechéy na tórte?"},{"fr":"C'est le plus bel anniversaire de ma vie, merci !","tgt":"Это лучший день рождения в моей жизни, спасибо!","ro":"Éta lúchshiy den' razhdéniya v mayéy zhízni, spasíba!"}]},{"title":"Les nouvelles des amis","phrases":[{"fr":"On dit que Sacha va se marier.","tgt":"Говорят, что Саша женится.","ro":"Gavaryát, shto Sásha zhénitsya."},{"fr":"On dit que la mer sera très chaude cet été.","tgt":"Говорят, что летом море будет очень тёплым.","ro":"Gavaryát, shto létam móre búdet óchen' tyóplym."},{"fr":"C'est vrai ? Qui t'a dit ça ?","tgt":"Правда? Кто тебе это сказал?","ro":"Právda? Kto tebé éta skazál?"},{"fr":"C'est Katia qui me l'a dit hier au téléphone.","tgt":"Мне вчера Катя сказала по телефону.","ro":"Mne vcherá Kátya skazála pa telefónu."},{"fr":"On dit qu'il a acheté un appartement près de la mer.","tgt":"Говорят, что он купил квартиру у моря.","ro":"Gavaryát, shto on kupíl kvartíru u mórya."},{"fr":"Il paraît que le nouveau restaurant du port est excellent.","tgt":"Говорят, что новый ресторан в порту отличный.","ro":"Gavaryát, shto nóvyy restarán v partú atlíchnyy."},{"fr":"Ne crois pas tout ce qu'on raconte.","tgt":"Не верь всему, что говорят.","ro":"Ne ver' vsemú, shto gavaryát."},{"fr":"On dit que Dima est parti vivre à Kazan.","tgt":"Говорят, что Дима переехал в Казань.","ro":"Gavaryát, shto Díma pereyékhal v Kazán'."},{"fr":"À mon avis, ce ne sont que des rumeurs.","tgt":"По-моему, это просто слухи.","ro":"Pa-móyemu, éta prósta slúkhi."},{"fr":"Samedi, on saura tout !","tgt":"В субботу всё узнаем!","ro":"V subbótu vsyo uznáyem!"}],"tip":{"title":"« Gavaryát, shto » : on dit que","example":"On dit que Sacha va se marier. — <b>Говорят</b>, <b>что</b> Саша женится.","body":"Pour rapporter une nouvelle ou une rumeur, le russe dit « Gavaryát, shto », mot à mot « disent, que ». Il n'y a pas de pronom « ils » : le verbe seul, à la forme du pluriel, suffit à exprimer notre « on dit ». Dans « Gavaryát, shto Sásha zhénitsya », on entend « disent que Sacha se marie » : une petite pause après « gavaryát », puis la nouvelle elle-même. Le petit mot « shto », qui se prononce « chto », joue le rôle de notre « que » pour relier deux phrases, et vous pouvez l'utiliser avec d'autres verbes : « Ya dúmayu, shto », je pense que, ou « Ya znáyu, shto », je sais que. L'accent de « gavaryát » tombe sur la dernière syllabe, bien appuyée. Astuce : imaginez tout le quartier qui bavarde, « gavaryát », et la rumeur qui suit derrière « shto ».","exampleRo":"Gavaryát, shto Sásha zhénitsya.","lit":"[ils] disent · que · Sacha · se marie"}},{"title":"Parler de la famille","phrases":[{"fr":"Comment vont tes parents ?","tgt":"Как поживают твои родители?","ro":"Kak pazhiváyut tvaí radíteli?"},{"fr":"Bien, merci, ils sont à la retraite maintenant.","tgt":"Спасибо, хорошо, они теперь на пенсии.","ro":"Spasíba, kharashó, aní tepér' na pénsii."},{"fr":"Ils passent tout l'été à la datcha.","tgt":"Они всё лето проводят на даче.","ro":"Aní vsyo léta pravódyat na dáche."},{"fr":"Mon petit frère vient d'avoir un fils.","tgt":"У моего младшего брата недавно родился сын.","ro":"U mayevó mládsheva bráta nedávna radílsya syn."},{"fr":"Félicitations ! Comment s'appelle le bébé ?","tgt":"Поздравляю! Как зовут малыша?","ro":"Pazdravlyáyu! Kak zavút malyshá?"},{"fr":"Ils l'ont appelé Micha, en l'honneur de notre grand-père.","tgt":"Его назвали Мишей, в честь дедушки.","ro":"Yevó nazváli Míshey, v chest' dédushki."},{"fr":"Ta sœur habite toujours à Saint-Pétersbourg ?","tgt":"Твоя сестра всё ещё живёт в Петербурге?","ro":"Tvayá sestrá vsyo yeshchó zhivyót v Peterbúrge?"},{"fr":"Non, elle est revenue à Sotchi l'année dernière.","tgt":"Нет, в прошлом году она вернулась в Сочи.","ro":"Net, v próshlam gadú aná vernúlas' v Sóchi."},{"fr":"Pour le Nouvel An, toute la famille se réunit.","tgt":"На Новый год вся семья собирается вместе.","ro":"Na Nóvyy god vsya sem'yá sabiráyetsya vméste."},{"fr":"Chez nous, c'est toujours bruyant et joyeux.","tgt":"У нас всегда шумно и весело.","ro":"U nas vsegdá shúmna i vésela."}]},{"title":"Se retrouver et apprendre","phrases":[{"fr":"On se donne rendez-vous à quelle heure ?","tgt":"Во сколько встречаемся?","ro":"Va skól'ka vstrecháyemsya?"},{"fr":"Retrouvons-nous à sept heures devant la gare.","tgt":"Давай встретимся в семь у вокзала.","ro":"Daváy vstrétimsya v sem' u vakzála."},{"fr":"On se voit rarement depuis que j'ai déménagé.","tgt":"Мы редко видимся с тех пор, как я переехал.","ro":"My rédka vídimsya s tekh por, kak ya pereyékhal."},{"fr":"Macha fait ses études à l'université de Sotchi.","tgt":"Маша учится в университете в Сочи.","ro":"Másha úchitsya v universitéte v Sóchi."},{"fr":"Elle apprend aussi à jouer de la guitare.","tgt":"Она также учится играть на гитаре.","ro":"Aná tákzhe úchitsya igrát' na gitáre."},{"fr":"Moi, j'ai fait mes études à Moscou, puis je suis venu ici.","tgt":"Я учился в Москве, а потом переехал сюда.","ro":"Ya uchílsya v Maskvé, a patóm pereyékhal syudá."},{"fr":"Où est-ce que vous vous êtes rencontrés, Katia et toi ?","tgt":"Где вы с Катей познакомились?","ro":"Gde vy s Kátey paznakómilis'?"},{"fr":"On s'est rencontrés sur le front de mer, il y a trois ans.","tgt":"Мы встретились на набережной три года назад.","ro":"My vstrétilis' na náberezhnay tri góda nazád."},{"fr":"Ça me plaît énormément ici.","tgt":"Мне здесь очень нравится.","ro":"Mne zdes' óchen' nrávitsya."},{"fr":"Ne t'inquiète pas, tout va bien se passer.","tgt":"Не беспокойся, всё получится.","ro":"Ne bespakóysya, vsyo palúchitsya."}],"tip":{"title":"Les verbes en « -sya » : « vstrechát'sya », « uchít'sya »","example":"Retrouvons-nous à sept heures devant la gare. — Давай <b>встретимся</b> в семь у вокзала.","body":"Beaucoup de verbes russes se terminent par « -sya », un petit morceau qui correspond à notre « se » : « vstrechát' », rencontrer, devient « vstrechát'sya », se rencontrer, se retrouver. Mais au lieu de se placer devant le verbe comme en français, ce « se » se colle à la fin : « Daváy vstrétimsya v sem' », mot à mot « allons, retrouvons-nous à sept ». Après une voyelle, il se réduit à « -s' » : « My vstrétilis' », nous nous sommes rencontrés. Certains verbes ne s'emploient qu'avec cette fin, comme « uchít'sya », faire ses études, apprendre : « Másha úchitsya v universitéte », Macha étudie à l'université. À l'oral, les fins « -t'sya » et « -tsya » sonnent pareil, comme un « tsa » rapide et léger. Astuce : dès que vous entendez ce petit « sya » final, pensez au « se » français qui aurait glissé en bout de verbe.","exampleRo":"Daváy vstrétimsya v sem' u vakzála.","lit":"allons · [nous nous] retrouverons · à · sept · près de · gare"}},{"title":"Randonnée vers les cascades","phrases":[{"fr":"Ce matin, on part en randonnée jusqu'aux cascades.","tgt":"Сегодня утром идём в поход к водопадам.","ro":"Sevódnya útram idyóm v pakhód k vadapádam."},{"fr":"Le sentier monte à travers la forêt.","tgt":"Тропа идёт вверх через лес.","ro":"Trapá idyót vverkh chérez les."},{"fr":"Marche moins vite, je n'en peux plus !","tgt":"Иди помедленнее, я уже не могу!","ro":"Idí pamédlenneye, ya uzhé ne magú!"},{"fr":"Faisons une pause au bord de la rivière.","tgt":"Давай отдохнём у реки.","ro":"Daváy atdakhnyóm u rekí."},{"fr":"Bois un peu d'eau, il fait très chaud.","tgt":"Попей воды, очень жарко.","ro":"Papéy vadý, óchen' zhárka."},{"fr":"Il nous reste encore combien de kilomètres ?","tgt":"Сколько нам ещё осталось километров?","ro":"Skól'ka nam yeshchó astálas' kilamétrav?"},{"fr":"Plus que deux, tiens bon !","tgt":"Всего два, держись!","ro":"Vsevó dva, derzhís'!"},{"fr":"Regarde, la voilà, la cascade !","tgt":"Смотри, вот он, водопад!","ro":"Smatrí, vot on, vadapád!"},{"fr":"L'eau est glacée, mais je vais quand même me baigner.","tgt":"Вода ледяная, но я всё равно искупаюсь.","ro":"Vadá ledyanáya, no ya vsyo ravnó iskupáyus'."},{"fr":"Je suis épuisé, mais tellement heureux.","tgt":"Я устал, но такой счастливый.","ro":"Ya ustál, no takóy shchastlívyy."}]},{"title":"Conseiller un ami","phrases":[{"fr":"Tu as l'air triste, qu'est-ce qui se passe ?","tgt":"Ты какой-то грустный, что случилось?","ro":"Ty kakóy-ta grústnyy, shto sluchílas'?"},{"fr":"Je me suis disputé avec ma copine.","tgt":"Я поссорился со своей девушкой.","ro":"Ya passórilsya sa svayéy dévushkay."},{"fr":"Elle trouve que je travaille trop.","tgt":"Она считает, что я слишком много работаю.","ro":"Aná shchitáyet, shto ya slíshkam mnóga rabótayu."},{"fr":"Elle a peut-être un peu raison.","tgt":"Может, она в чём-то права.","ro":"Mózhet, aná v chom-ta pravá."},{"fr":"Appelle-la et propose-lui une promenade.","tgt":"Позвони ей и предложи погулять.","ro":"Pazvaní yey i predlazhí pagulyát'."},{"fr":"À ta place, je prendrais quelques jours de congé.","tgt":"На твоём месте я бы взял несколько выходных.","ro":"Na tvayóm méste ya by vzyal néskal'ka vykhadnýkh."},{"fr":"Emmène-la à Krasnaïa Poliana pour le week-end.","tgt":"Свози её в Красную Поляну на выходные.","ro":"Svazí yeyó v Krásnuyu Palyánu na vykhadnýye."},{"fr":"Tu as raison, je vais tenter le coup.","tgt":"Ты прав, попробую.","ro":"Ty prav, papróbuyu."},{"fr":"Merci d'avoir pris le temps de m'écouter.","tgt":"Спасибо, что выслушал.","ro":"Spasíba, shto výslushal."},{"fr":"Sinon, à quoi servent les amis ?","tgt":"А для чего ещё нужны друзья?","ro":"A dlya chevó yeshchó nuzhný druz'yá?"}]},{"title":"Les projets de vacances","phrases":[{"fr":"Tu pars où en vacances cette année ?","tgt":"Куда ты поедешь в отпуск в этом году?","ro":"Kudá ty payédesh v ótpusk v étam gadú?"},{"fr":"Je rêve de voir le lac Baïkal.","tgt":"Я мечтаю увидеть Байкал.","ro":"Ya mechtáyu uvídet' Baykál."},{"fr":"On pourrait y aller ensemble en août.","tgt":"Мы могли бы поехать туда вместе в августе.","ro":"My maglí by payékhat' tudá vméste v ávguste."},{"fr":"Si on traverse toute la Sibérie en train, ce sera une vraie aventure.","tgt":"Если поедем на поезде через всю Сибирь, будет настоящее приключение.","ro":"Yésli payédem na póyezde chérez vsyu Sibír', búdet nastayáshcheye priklyuchéniye."},{"fr":"Combien de jours met le train ?","tgt":"Сколько дней идёт поезд?","ro":"Skól'ka dney idyót póyezd?"},{"fr":"Environ trois jours jusqu'à Irkoutsk.","tgt":"Примерно трое суток до Иркутска.","ro":"Primérna tróye sútak da Irkútska."},{"fr":"Il faudra acheter les billets à l'avance.","tgt":"Билеты надо будет купить заранее.","ro":"Biléty náda búdet kupít' zaráneye."},{"fr":"Je vais en parler à Sacha et Macha.","tgt":"Я поговорю об этом с Сашей и Машей.","ro":"Ya pagavaryú ab étam s Sáshey i Máshey."},{"fr":"S'ils sont libres, ils viendront avec nous.","tgt":"Если они будут свободны, поедут с нами.","ro":"Yésli aní búdut svabódny, payédut s námi."},{"fr":"Vivement le mois d'août !","tgt":"Скорей бы август!","ro":"Skaréy by ávgust!"}]},{"title":"Des souvenirs de voyage","phrases":[{"fr":"Voici la photo que j'ai prise au bord du Baïkal.","tgt":"Вот фотография, которую я сделал на Байкале.","ro":"Vot fatagráfiya, katóruyu ya sdélal na Baykále."},{"fr":"Le garçon qui est debout à gauche, c'est mon cousin.","tgt":"Парень, который стоит слева, мой двоюродный брат.","ro":"Páren', katóryy staít sléva, moy dvayúradnyy brat."},{"fr":"On logeait dans une petite maison qui se trouvait au bord du lac.","tgt":"Мы жили в домике, который стоял на берегу озера.","ro":"My zhíli v dómike, katóryy stayál na beregú ózera."},{"fr":"L'eau était si transparente qu'on voyait le fond.","tgt":"Вода была такая прозрачная, что было видно дно.","ro":"Vadá bylá takáya prazráchnaya, shto býla vídna dno."},{"fr":"La dame qui nous accueillait faisait de délicieux pirojki.","tgt":"Хозяйка, которая нас принимала, пекла вкусные пирожки.","ro":"Khazyáyka, katóraya nas prinimála, peklá vkúsnyye pirazhkí."},{"fr":"C'est la ville dont je t'ai parlé.","tgt":"Это город, о котором я тебе рассказывал.","ro":"Éta górad, a katóram ya tebé rasskázyval."},{"fr":"Tu te souviens du guide qui parlait français ?","tgt":"Помнишь гида, который говорил по-французски?","ro":"Pómnish gída, katóryy gavaríl pa-frantsúzski?"},{"fr":"Les gens que nous avons rencontrés là-bas étaient très accueillants.","tgt":"Люди, которых мы там встретили, были очень гостеприимными.","ro":"Lyúdi, katórykh my tam vstrétili, býli óchen' gastepriímnymi."},{"fr":"Le prochain voyage dont je rêve, c'est le Kamtchatka.","tgt":"Следующее путешествие, о котором я мечтаю, это Камчатка.","ro":"Sléduyushcheye puteshéstviye, a katóram ya mechtáyu, éta Kamchátka."},{"fr":"Montre-moi encore les photos que tu as prises !","tgt":"Покажи ещё фотографии, которые ты сделал!","ro":"Pakazhí yeshchó fatagráfii, katóryye ty sdélal!"}],"tip":{"title":"« Katóryy » : qui, que, la phrase relative","example":"Le garçon qui est debout à gauche, c'est mon cousin. — Парень, <b>который</b> стоит слева, мой двоюродный брат.","body":"Pour dire « qui » ou « que » au milieu d'une phrase, le russe utilise « katóryy », qui ressemble beaucoup à notre « lequel ». Il s'accorde avec le mot qu'il reprend : « katóryy » pour un garçon, « katóraya » pour une femme, « katóroye » pour un mot neutre et « katóryye » au pluriel. Dans « Páren', katóryy staít sléva, moy dvayúradnyy brat », mot à mot « garçon, lequel se tient à gauche, mon cousin », il reprend simplement « páren' », le garçon. Quand il est complément, sa fin change, comme notre « que » : « fatagráfiya, katóruyu ya sdélal », la photo que j'ai prise. À l'oral, on marque une petite pause avant et après la relative, comme des virgules qu'on entend. Astuce : remplacez mentalement « qui » par « lequel » ou « laquelle », et la bonne forme viendra plus facilement.","exampleRo":"Páren', katóryy staít sléva, moy dvayúradnyy brat.","lit":"garçon · lequel · se tient · à gauche · mon · cousin"}},{"title":"Le dernier soir à Sotchi","phrases":[{"fr":"J'ai du mal à croire que les vacances sont déjà finies.","tgt":"Не верится, что отпуск уже закончился.","ro":"Ne véritsya, shto ótpusk uzhé zakónchilsya."},{"fr":"Le temps est passé tellement vite !","tgt":"Время пролетело так быстро!","ro":"Vrémya praletéla tak býstra!"},{"fr":"Allons voir la mer une dernière fois.","tgt":"Пойдём посмотрим на море в последний раз.","ro":"Paydyóm pasmótrim na móre v paslédniy raz."},{"fr":"Merci pour votre accueil, tout était formidable.","tgt":"Спасибо вам за гостеприимство, всё было замечательно.","ro":"Spasíba vam za gastepriímstva, vsyo býla zamechátel'na."},{"fr":"Tu reviens quand ?","tgt":"Когда ты снова приедешь?","ro":"Kagdá ty snóva priyédesh?"},{"fr":"Je reviendrai sans doute l'hiver prochain.","tgt":"Наверное, приеду следующей зимой.","ro":"Navérnaye, priyédu sléduyushchey zimóy."},{"fr":"Écris-moi quand tu seras rentré.","tgt":"Напиши, когда доберёшься до дома.","ro":"Napishí, kagdá daberyóshsya da dóma."},{"fr":"Je vous enverrai toutes les photos.","tgt":"Я пришлю вам все фотографии.","ro":"Ya prishlyú vam vse fatagráfii."},{"fr":"Tu vas énormément nous manquer.","tgt":"Нам будет тебя очень не хватать.","ro":"Nam búdet tebyá óchen' ne khvatát'."},{"fr":"Ce n'est pas un adieu, c'est un au revoir !","tgt":"Не прощай, а до свидания!","ro":"Ne prashcháy, a da svidániya!"}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module nous a appris à discuter entre amis.","tgt":"В этом модуле мы научились общаться с друзьями.","ro":"V étam módule my nauchílis' abshchát'sya s druz'yámi."},{"fr":"Nous savons maintenant raconter le passé et faire des projets.","tgt":"Теперь мы умеем рассказывать о прошлом и строить планы.","ro":"Tepér' my uméyem rasskázyvat' a próshlam i stróit' plány."},{"fr":"Les diminutifs comme Sacha et Macha n'ont plus de secret pour nous.","tgt":"Уменьшительные имена, как Саша и Маша, для нас больше не секрет.","ro":"Umen'shítel'nyye imená, kak Sásha i Másha, dlya nas ból'she ne sekrét."},{"fr":"Les verbes pronominaux nous sont devenus familiers.","tgt":"Возвратные глаголы стали для нас привычными.","ro":"Vazvrátnyye glagóly stáli dlya nas privýchnymi."},{"fr":"Nous savons aussi partager les nouvelles et les rumeurs.","tgt":"Мы также умеем делиться новостями и слухами.","ro":"My tákzhe uméyem delít'sya navastyámi i slúkhami."},{"fr":"Notre russe devient de plus en plus fluide.","tgt":"Наш русский становится всё более свободным.","ro":"Nash rússkiy stanóvitsya vsyo bóleye svabódnym."},{"fr":"Et voilà, le deuxième niveau est terminé !","tgt":"Второй уровень пройден.","ro":"Vtaróy úraven' próyden."},{"fr":"Bravo, tu as bien travaillé !","tgt":"Молодец, ты хорошо поработал!","ro":"Maladéts, ty kharashó parabótal!"},{"fr":"Repose-toi un peu avant la suite.","tgt":"Отдохни немного перед следующим этапом.","ro":"Atdakhní nemnóga péred sléduyushchim etápam."},{"fr":"Rendez-vous au niveau trois !","tgt":"До встречи на третьем уровне!","ro":"Da vstréchi na trét'yem úravne!"}]}]}]},{"id":3,"name":"Niveau 3","freeLessonsPerModule":{"1":3,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"Une vie quotidienne installée en Russie, avec ses subtilités.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Une journée chargée au bureau","phrases":[{"fr":"Je voudrais finir ce rapport avant le déjeuner.","tgt":"Я бы хотел закончить этот отчёт до обеда.","ro":"Ya by khatél zakónchit' état atchót da abéda."},{"fr":"Pourriez-vous m'envoyer les documents aujourd'hui ?","tgt":"Не могли бы вы прислать мне документы сегодня?","ro":"Ne maglí by vy prislát' mne dakuménty sevódnya?"},{"fr":"À votre place, je demanderais un peu plus de temps.","tgt":"На вашем месте я бы попросил ещё немного времени.","ro":"Na váshem méste ya by paprasíl yeshchó nemnóga vrémeni."},{"fr":"Ce serait plus simple de tout discuter demain.","tgt":"Было бы проще всё обсудить завтра.","ro":"Býla by próshche fsyo absudít' záftra."},{"fr":"Si j'avais le temps, je prendrais bien un café.","tgt":"Если бы у меня было время, я бы выпил кофе.","ro":"Yésli by u menyá býla vrémya, ya by výpil kófe."},{"fr":"Je resterais volontiers plus longtemps, mais j'ai un rendez-vous.","tgt":"Я бы с удовольствием остался подольше, но у меня встреча.","ro":"Ya by s udavól'stviyem astálsya padól'she, no u menyá fstrécha."},{"fr":"Le téléphone sonne sans arrêt depuis ce matin.","tgt":"Телефон звонит с самого утра без остановки.","ro":"Telefón zvanít s samóva utrá bez astanófki."},{"fr":"Mon chef aimerait voir la présentation d'ici vendredi.","tgt":"Мой начальник хотел бы увидеть презентацию к пятнице.","ro":"Moy nachál'nik khatél by uvídet' prezentátsiyu k pyátnitse."},{"fr":"Sans ce café, je ne tiendrais pas jusqu'au soir.","tgt":"Без этого кофе я бы не продержался до вечера.","ro":"Bez étava kófe ya by ne praderzhálsya da véchera."},{"fr":"Enfin, la journée de travail est terminée, je rentre à la maison.","tgt":"Наконец рабочий день закончен, я иду домой.","ro":"Nakanéts rabóchiy den' zakónchen, ya idú damóy."}],"tip":{"title":"Le conditionnel avec « by » : « ya by khatél »","example":"Je voudrais finir ce rapport avant le déjeuner. — Я <b>бы</b> <b>хотел</b> закончить этот отчёт до обеда.","body":"Pour adoucir une demande ou imaginer une situation, le russe ajoute le petit mot « by » à un verbe conjugué au passé. « Ya khachú » veut dire je veux, mais « ya by khatél » devient je voudrais : mot à mot, je by voulu. Ce même petit mot sert pour toutes les personnes, sans aucune nouvelle conjugaison à apprendre. Pour demander poliment, dites « Ne maglí by vy », pourriez-vous, et pour imaginer, « Yésli by u menyá býla vrémya », si j'avais le temps. Une femme dira « ya by khatéla », car le passé s'accorde au féminin. Retenez la recette : un passé plus « by », et votre russe devient aussitôt plus poli.","exampleRo":"Ya by khatél zakónchit' état atchót da abéda.","lit":"je · [conditionnel] (by) · voulu · finir · ce · rapport · avant · déjeuner"}},{"title":"La réunion du lundi matin","phrases":[{"fr":"Chaque lundi, toute l'équipe se réunit à neuf heures.","tgt":"Каждый понедельник вся команда собирается в девять часов.","ro":"Kázhdyy panedél'nik fsya kamánda sabiráyetsa v dévyat' chasóf."},{"fr":"D'abord, le directeur présente les résultats de la semaine.","tgt":"Сначала директор рассказывает о результатах недели.","ro":"Snachála diréktar raskázyvayet a rezul'tátakh nedéli."},{"fr":"Ensuite, chacun parle de ses projets en cours.","tgt":"Потом каждый говорит о своих текущих проектах.","ro":"Patóm kázhdyy gavarít a svaíkh tekúshchikh praéktakh."},{"fr":"Je prends des notes sur mon ordinateur portable.","tgt":"Я делаю заметки в ноутбуке.","ro":"Ya délayu zamétki v nautbúke."},{"fr":"Notre réunion dure souvent plus d'une heure.","tgt":"Наше совещание часто длится больше часа.","ro":"Náshe saveshchániye chásta dlítsa ból'she chása."},{"fr":"Aujourd'hui, nous discutons du budget de l'année prochaine.","tgt":"Сегодня мы обсуждаем бюджет на следующий год.","ro":"Sevódnya my absuzhdáyem byudzhét na sléduyushchiy got."},{"fr":"Ma collègue Olga a proposé une idée intéressante.","tgt":"Моя коллега Ольга предложила интересную идею.","ro":"Mayá kalléga Ól'ga predlazhíla interésnuyu idéyu."},{"fr":"À la fin, personne n'a posé de question.","tgt":"В конце никто не задал вопросов.","ro":"F kantsé niktó ne zádal vaprósaf."},{"fr":"Le compte rendu sera envoyé à tout le monde par courriel.","tgt":"Протокол разошлют всем по электронной почте.","ro":"Pratakól razashlyút fsem pa elektrónnay póchte."},{"fr":"Après la réunion, nous prenons un thé ensemble.","tgt":"После совещания мы вместе пьём чай.","ro":"Pósle saveshchániya my vméste pyom chay."}]},{"title":"Ouvrir un compte à la banque","phrases":[{"fr":"Je suis venu pour ouvrir un compte.","tgt":"Я пришёл, чтобы открыть счёт.","ro":"Ya prishól, shtóby atkrýt' shchot."},{"fr":"Il faut un passeport pour que nous puissions vérifier votre identité.","tgt":"Нужен паспорт, чтобы мы могли проверить вашу личность.","ro":"Núzhen páspart, shtóby my maglí pravérit' váshu líchnast'."},{"fr":"J'ai besoin d'une carte pour payer en ligne.","tgt":"Мне нужна карта, чтобы платить в интернете.","ro":"Mne nuzhná kárta, shtóby platít' v internéte."},{"fr":"Remplissez ce formulaire, s'il vous plaît.","tgt":"Заполните, пожалуйста, эту анкету.","ro":"Zapólnite, pazhálsta, étu ankétu."},{"fr":"Signez ici pour confirmer votre demande.","tgt":"Подпишите здесь, чтобы подтвердить заявку.","ro":"Padpishíte zdes', shtóby pattverdít' zayáfku."},{"fr":"Je veux que mon salaire arrive directement sur ce compte.","tgt":"Я хочу, чтобы зарплата приходила прямо на этот счёт.","ro":"Ya khachú, shtóby zarpláta prikhadíla pryáma na état shchot."},{"fr":"Le conseiller m'explique les frais de tenue de compte.","tgt":"Консультант объясняет мне стоимость обслуживания.","ro":"Kansul'tánt ab'yasnyáyet mne stóimast' abslúzhivaniya."},{"fr":"Pour éviter les frais, je choisis l'offre de base.","tgt":"Чтобы избежать комиссий, я выбираю базовый тариф.","ro":"Shtóby izbezhát' kamíssiy, ya vybiráyu bázavyy taríf."},{"fr":"Téléchargez l'application pour suivre vos dépenses.","tgt":"Скачайте приложение, чтобы следить за расходами.","ro":"Skacháyte prilazhéniye, shtóby sledít' za raskhódami."},{"fr":"Votre carte sera prête dans une semaine.","tgt":"Ваша карта будет готова через неделю.","ro":"Vásha kárta búdet gatóva chéres nedélyu."}],"tip":{"title":"« Shtóby » : pour que, afin de","example":"Je suis venu pour ouvrir un compte. — Я пришёл, <b>чтобы</b> открыть счёт.","body":"« Shtóby » se traduit par pour, afin de ou pour que, et il sert à dire dans quel but on agit. Si le sujet ne change pas, on le fait suivre d'un infinitif : « Ya prishól, shtóby atkrýt' shchot », mot à mot je suis venu pour ouvrir compte. Si le sujet change, on met le verbe au passé : « Ya khachú, shtóby zarpláta prikhadíla », je veux que le salaire arrive, littéralement que le salaire arrivait. Ce passé s'explique facilement : on entend le petit « by » du conditionnel caché à la fin de « shtóby ». À l'oral, marquez une courte pause juste avant « shtóby », comme une virgule. Retenez la formule : « shtóby » plus un infinitif pour soi-même, « shtóby » plus un passé pour les autres.","exampleRo":"Ya prishól, shtóby atkrýt' shchot.","lit":"je · suis venu · [pour] (shtóby) · ouvrir · compte"}},{"title":"Chercher un appartement à louer","phrases":[{"fr":"Je cherche un deux-pièces pas loin du centre.","tgt":"Я ищу двухкомнатную квартиру недалеко от центра.","ro":"Ya ishchú dvukhkómnatnuyu kvartíru nedalekó at tséntra."},{"fr":"Les loyers à Iekaterinbourg ont beaucoup augmenté.","tgt":"Аренда в Екатеринбурге сильно подорожала.","ro":"Arénda v Yekaterinbúrge síl'na padarazhála."},{"fr":"J'ai trouvé plusieurs annonces sur un site spécialisé.","tgt":"Я нашёл несколько объявлений на специальном сайте.","ro":"Ya nashól néskal'ka ab'yavléniy na spetsiál'nam sáyte."},{"fr":"Cet appartement est meublé, et les fenêtres donnent sur un parc.","tgt":"Эта квартира с мебелью, а окна выходят на парк.","ro":"Éta kvartíra s mébel'yu, a ókna vykhódyat na park."},{"fr":"Le loyer, c'est trente mille roubles par mois.","tgt":"Аренда стоит тридцать тысяч рублей в месяц.","ro":"Arénda stóit trítsat' týsyach rubléy v mésyats."},{"fr":"Les charges sont-elles comprises dans le prix ?","tgt":"Коммунальные услуги входят в стоимость?","ro":"Kamunál'nyye uslúgi fkhódyat f stóimast'?"},{"fr":"Le propriétaire demande une caution d'un mois.","tgt":"Хозяин просит залог за один месяц.","ro":"Khazyáin prósit zalók za adín mésyats."},{"fr":"Je préférerais un immeuble tout près du métro.","tgt":"Я бы предпочёл дом рядом с метро.","ro":"Ya by pretpachól dom ryádam s metró."},{"fr":"Je vais appeler l'agence pour organiser une visite.","tgt":"Я позвоню в агентство и договорюсь о просмотре.","ro":"Ya pazvanyú v agénstva i dagavaryús' a prasmótre."},{"fr":"Il faut se décider vite : les bons appartements partent en un jour.","tgt":"Надо решать быстро: хорошие квартиры сдают за один день.","ro":"Náda reshát' býstra: kharóshiye kvartíry zdayút za adín den'."}]},{"title":"Le trajet du matin","phrases":[{"fr":"En attendant le tramway, je lis les nouvelles.","tgt":"Ожидая трамвай, я читаю новости.","ro":"Azhidáya tramváy, ya chitáyu nóvasti."},{"fr":"Je traverse le parc en écoutant de la musique.","tgt":"Я иду через парк, слушая музыку.","ro":"Ya idú chéres park, slúshaya múzyku."},{"fr":"En me promenant le long de l'Iset, je me réveille doucement.","tgt":"Гуляя вдоль Исети, я потихоньку просыпаюсь.","ro":"Gulyáya vdol' Iséti, ya patikhón'ku prasypáyus'."},{"fr":"Le matin, il y a beaucoup de monde dans le métro.","tgt":"Утром в метро много народу.","ro":"Útram v metró mnóga naródu."},{"fr":"En lisant un livre, je ne vois pas le temps passer.","tgt":"Читая книгу, я не замечаю, как идёт время.","ro":"Chitáya knígu, ya ne zamecháyu, kak idyót vrémya."},{"fr":"Certains travaillent déjà en sirotant leur café.","tgt":"Некоторые уже работают, попивая кофе.","ro":"Nékataryye uzhé rabótayut, papiváya kófe."},{"fr":"Je descends à la station Dinamo.","tgt":"Я выхожу на станции «Динамо».","ro":"Ya vykhazhú na stántsii «Dinámo»."},{"fr":"En sortant du métro, j'achète toujours un café à emporter.","tgt":"Выходя из метро, я всегда покупаю кофе с собой.","ro":"Vykhadyá iz metró, ya fsegdá pakupáyu kófe s sabóy."},{"fr":"Je téléphone en marchant vers le bureau.","tgt":"Я разговариваю по телефону, шагая к офису.","ro":"Ya razgavárivayu pa telefónu, shagáya k ófisu."},{"fr":"J'arrive au travail de bonne humeur.","tgt":"Я прихожу на работу в хорошем настроении.","ro":"Ya prikhazhú na rabótu f kharóshem nastrayénii."}],"tip":{"title":"Le gérondif présent : « chitáya », « gulyáya »","example":"En me promenant le long de l'Iset, je me réveille doucement. — <b>Гуляя</b> вдоль Исети, я потихоньку просыпаюсь.","body":"Le gérondif présent correspond à notre en faisant : il décrit une action qui se déroule en même temps que l'action principale. On le forme à partir du présent, en remplaçant la terminaison par « ya » ou « a » : « chitáyu », je lis, donne « chitáya », en lisant, et « gulyáyu », je me promène, donne « gulyáya ». Dans « Gulyáya vdol' Iséti, ya patikhón'ku prasypáyus' », on entend mot à mot en se promenant le long de l'Iset, je doucement me réveille. Ce mot ne change jamais, quel que soit le sujet, ce qui le rend très pratique. Autres exemples : « slúshaya múzyku », en écoutant de la musique, et « shagáya k ófisu », en marchant vers le bureau. Astuce : ce « ya » final sonne comme un écho du présent, facile à reconnaître à l'oreille.","exampleRo":"Gulyáya vdol' Iséti, ya patikhón'ku prasypáyus'.","lit":"en se promenant · le long de · Iset · je · doucement · me réveille"}},{"title":"La visite de l'appartement","phrases":[{"fr":"L'agent immobilier nous attend devant l'entrée de l'immeuble.","tgt":"Риелтор ждёт нас у подъезда.","ro":"Riyéltar zhdyot nas u pad'yézda."},{"fr":"L'appartement est au cinquième étage, et il n'y a pas d'ascenseur.","tgt":"Квартира находится на пятом этаже, лифта нет.","ro":"Kvartíra nakhóditsa na pyátam etazhé, lífta net."},{"fr":"La cuisine est petite, mais très lumineuse.","tgt":"Кухня маленькая, но очень светлая.","ro":"Kúkhnya málen'kaya, no óchen' svétlaya."},{"fr":"Le chauffage fonctionne-t-il bien en hiver ?","tgt":"Отопление зимой хорошо работает?","ro":"Atapléniye zimóy kharashó rabótayet?"},{"fr":"Les fenêtres ont été changées l'année dernière.","tgt":"Окна поменяли в прошлом году.","ro":"Ókna pamenyáli f próshlam gadú."},{"fr":"La salle de bains aurait besoin d'un petit rafraîchissement.","tgt":"В ванной не помешал бы небольшой ремонт.","ro":"V vánnay ne pameshál by nebal'shóy remónt."},{"fr":"Peut-on garer une voiture dans la cour ?","tgt":"Можно ставить машину во дворе?","ro":"Mózhna stávit' mashínu va dvaré?"},{"fr":"D'après le propriétaire, les voisins du dessus sont calmes.","tgt":"По словам хозяина, соседи сверху спокойные.","ro":"Pa slavám khazyáina, sasédi svérkhu spakóynyye."},{"fr":"Le quartier est animé, mais pas trop bruyant.","tgt":"Район оживлённый, но не слишком шумный.","ro":"Rayón azhivlyónnyy, no ne slíshkam shúmnyy."},{"fr":"Cet appartement me plaît, je vais réfléchir jusqu'à demain.","tgt":"Мне нравится эта квартира, я подумаю до завтра.","ro":"Mne nrávitsa éta kvartíra, ya padúmayu da záftra."}]},{"title":"Le bail et la caution","phrases":[{"fr":"Aujourd'hui, nous signons le contrat de location.","tgt":"Сегодня мы подписываем договор аренды.","ro":"Sevódnya my padpísyvayem dagavór aréndy."},{"fr":"Le contrat est conclu pour onze mois.","tgt":"Договор заключается на одиннадцать месяцев.","ro":"Dagavór zaklyucháyetsa na adínatsat' mésyatsef."},{"fr":"Je verse la caution et le premier loyer.","tgt":"Я вношу залог и первую оплату.","ro":"Ya vnashú zalók i pérvuyu aplátu."},{"fr":"Le propriétaire nous remet deux jeux de clés.","tgt":"Хозяин отдаёт нам два комплекта ключей.","ro":"Khazyáin addayót nam dva kamplékta klyuchéy."},{"fr":"Nous vérifions ensemble l'état de chaque pièce.","tgt":"Мы вместе проверяем состояние каждой комнаты.","ro":"My vméste praveryáyem sastayániye kázhday kómnaty."},{"fr":"Toutes les rayures sont notées dans un document à part.","tgt":"Все царапины записывают в отдельный акт.","ro":"Fse tsarápiny zapísyvayut v addél'nyy akt."},{"fr":"Il faut payer avant le dix de chaque mois.","tgt":"Платить нужно до десятого числа каждого месяца.","ro":"Platít' núzhna da desyátava chislá kázhdava mésyatsa."},{"fr":"A-t-on le droit d'avoir des animaux dans l'appartement ?","tgt":"В квартире можно держать животных?","ro":"F kvartíre mózhna derzhát' zhivótnykh?"},{"fr":"Si quelque chose tombe en panne, il faut prévenir le propriétaire.","tgt":"Если что-то сломается, нужно сообщить хозяину.","ro":"Yésli shtó-ta slamáyetsa, núzhna saabshchít' khazyáinu."},{"fr":"Voilà, nous pouvons emménager dès samedi.","tgt":"Ну всё, мы можем переезжать уже в субботу.","ro":"Nu fsyo, my mózhem pereyezhát' uzhé f subbótu."}]},{"title":"Les démarches administratives","phrases":[{"fr":"Même pour un petit certificat, il faut faire la queue.","tgt":"Даже за маленькой справкой надо стоять в очереди.","ro":"Dázhe za málen'kay správkay náda stayát' v óchiredi."},{"fr":"Je me suis inscrit en ligne, c'est possible même le samedi.","tgt":"Я записался онлайн, можно даже в субботу.","ro":"Ya zapisálsya anláyn, mózhna dázhe f subbótu."},{"fr":"Le centre des services publics ouvre même le dimanche.","tgt":"Центр госуслуг работает даже по воскресеньям.","ro":"Tsentr gasuslúk rabótayet dázhe pa vaskresén'yam."},{"fr":"Il faut faire enregistrer sa nouvelle adresse.","tgt":"Нужно оформить регистрацию по новому адресу.","ro":"Núzhna afórmit' registrátsiyu pa nóvamu ádresu."},{"fr":"L'employé n'a même pas regardé mes papiers.","tgt":"Сотрудник даже не посмотрел мои документы.","ro":"Satrúdnik dázhe ne pasmatrél mai dakuménty."},{"fr":"Même mes collègues russes ne comprennent pas ce formulaire.","tgt":"Даже мои русские коллеги не понимают эту анкету.","ro":"Dázhe mai rússkiye kallégi ne panimáyut étu ankétu."},{"fr":"Apportez aussi une photocopie de votre passeport.","tgt":"Принесите также копию паспорта.","ro":"Prinesíte tákzhe kópiyu pásparta."},{"fr":"Le dossier sera prêt dans dix jours ouvrables.","tgt":"Документы будут готовы через десять рабочих дней.","ro":"Dakuménty búdut gatóvy chéres désyat' rabóchikh dney."},{"fr":"Cette fois, tout s'est passé encore plus vite que prévu.","tgt":"На этот раз всё прошло даже быстрее, чем я ожидал.","ro":"Na état ras fsyo prashló dázhe bystréye, chem ya azhidál."},{"fr":"Je n'ai même pas eu besoin de revenir.","tgt":"Мне даже не пришлось приходить второй раз.","ro":"Mne dázhe ne prishlós' prikhadít' ftaróy ras."}],"tip":{"title":"« Dázhe » : même","example":"L'employé n'a même pas regardé mes papiers. — Сотрудник <b>даже</b> не посмотрел мои документы.","body":"« Dázhe » veut dire même, au sens de jusqu'à, et il se place juste devant le mot qu'il met en valeur. Dans « Satrúdnik dázhe ne pasmatrél mai dakuménty », mot à mot employé même ne pas a regardé mes documents, il vient avant la négation, exactement comme notre n'a même pas. Déplacez-le, et l'insistance change : « mózhna dázhe f subbótu », c'est possible même le samedi, souligne le jour. Avec une comparaison, il se traduit plutôt par encore : « dázhe bystréye », encore plus vite. À l'oral, on appuie un peu sur le mot qui suit « dázhe », pour faire entendre la surprise. Ne le confondez pas avec « tózhe », aussi, qui ajoute sans étonner. Retenez que « dázhe » se colle toujours au mot qui surprend.","exampleRo":"Satrúdnik dázhe ne pasmatrél mai dakuménty.","lit":"employé · même · [ne… pas] (ne) · a regardé · mes · documents"}},{"title":"Les pirojki de la pause déjeuner","phrases":[{"fr":"À une heure, tout le bureau part déjeuner.","tgt":"В час весь офис идёт обедать.","ro":"F chas ves' ófis idyót abédat'."},{"fr":"Il y a une petite boulangerie au coin de la rue.","tgt":"На углу есть маленькая пекарня.","ro":"Na uglú yest' málen'kaya pekárnya."},{"fr":"Leurs pirojki au chou sont tout simplement délicieux.","tgt":"Пирожки с капустой у них просто чудесные.","ro":"Pirazhkí s kapústay u nikh prósta chudésnyye."},{"fr":"J'en prends deux : un à la viande, l'autre aux pommes.","tgt":"Я беру два: один с мясом, другой с яблоками.","ro":"Ya berú dva: adín s myásam, drugóy s yáblakami."},{"fr":"Ma collègue apporte toujours sa soupe de la maison.","tgt":"Моя коллега всегда приносит суп из дома.","ro":"Mayá kalléga fsegdá prinósit sup iz dóma."},{"fr":"Quand il fait beau, nous mangeons sur un banc.","tgt":"Когда хорошая погода, мы едим на скамейке.","ro":"Kagdá kharóshaya pagóda, my yedím na skaméyke."},{"fr":"En hiver, nous restons généralement à la cantine.","tgt":"Зимой мы обычно остаёмся в столовой.","ro":"Zimóy my abýchna astayómsya f stalóvay."},{"fr":"Le menu du jour coûte trois cents roubles.","tgt":"Комплексный обед стоит триста рублей.","ro":"Kómpleksnyy abéd stóit trísta rubléy."},{"fr":"Nous parlons de tout, sauf du travail.","tgt":"Мы говорим обо всём, кроме работы.","ro":"My gavarím aba fsyom, króme rabóty."},{"fr":"Cette heure de pause me fait vraiment du bien.","tgt":"Этот час отдыха идёт мне на пользу.","ro":"État chas ótdykha idyót mne na pól'zu."}]},{"title":"Un nouveau collègue","phrases":[{"fr":"Un nouveau collègue est arrivé dans notre service.","tgt":"В наш отдел пришёл новый сотрудник.","ro":"V nash addél prishól nóvyy satrúdnik."},{"fr":"Il s'appelle Dmitri, et il vient de Perm.","tgt":"Его зовут Дмитрий, он из Перми.","ro":"Yevó zavút Dmítriy, on is Permí."},{"fr":"Je lui montre où se trouve la salle de réunion.","tgt":"Я показываю ему, где переговорная.","ro":"Ya pakázyvayu yemú, gde peregavórnaya."},{"fr":"Avant, il travaillait dans une grande entreprise.","tgt":"Раньше он работал в крупной компании.","ro":"Rán'she on rabótal f krúpnay kampánii."},{"fr":"Je lui présente toute l'équipe.","tgt":"Я знакомлю его со всей командой.","ro":"Ya znakómlyu yevó sa fsey kamánday."},{"fr":"Il pose beaucoup de questions, c'est bon signe.","tgt":"Он задаёт много вопросов, это хороший знак.","ro":"On zadayót mnóga vaprósaf, éta kharóshiy znak."},{"fr":"On se tutoie déjà ?","tgt":"Мы уже на «ты»?","ro":"My uzhé na «ty»?"},{"fr":"Je lui explique comment marche l'imprimante.","tgt":"Я объясняю ему, как работает принтер.","ro":"Ya ab'yasnyáyu yemú, kak rabótayet prínter."},{"fr":"À la pause déjeuner, nous l'emmenons avec nous.","tgt":"В обед мы зовём его с собой.","ro":"V abéd my zavyóm yevó s sabóy."},{"fr":"On dirait qu'il a déjà trouvé ses marques.","tgt":"Кажется, он уже хорошо освоился.","ro":"Kázhetsa, on uzhé kharashó asvóilsya."}]},{"title":"Un souci avec la carte bancaire","phrases":[{"fr":"Ce matin, ma carte a été bloquée.","tgt":"Сегодня утром мою карту заблокировали.","ro":"Sevódnya útram mayú kártu zablakíravali."},{"fr":"J'ai essayé de payer trois fois au supermarché.","tgt":"Я три раза пытался заплатить в супермаркете.","ro":"Ya tri ráza pytálsya zaplatít' f supermárkete."},{"fr":"J'appelle tout de suite le service client de la banque.","tgt":"Я сразу звоню в службу поддержки банка.","ro":"Ya srázu zvanyú f slúzhbu paddérzhki bánka."},{"fr":"L'opératrice me demande mon nom et ma date de naissance.","tgt":"Оператор спрашивает моё имя и дату рождения.","ro":"Aperátar spráshivayet mayó ímya i dátu razhdéniya."},{"fr":"Apparemment, ils ont repéré un paiement suspect.","tgt":"Оказывается, заметили подозрительный платёж.","ro":"Akázyvayetsa, zamétili padazrítel'nyy platyózh."},{"fr":"Ce n'était pas moi, je n'ai rien acheté hier soir.","tgt":"Это был не я, я ничего не покупал вчера вечером.","ro":"Éta byl ne ya, ya nichevó ne pakupál fcherá vécheram."},{"fr":"La banque va me rendre l'argent.","tgt":"Банк вернёт мне деньги.","ro":"Bank vernyót mne dén'gi."},{"fr":"On m'enverra une nouvelle carte d'ici cinq jours.","tgt":"Новую карту пришлют в течение пяти дней.","ro":"Nóvuyu kártu prishlyút f techéniye pyatí dney."},{"fr":"En attendant, je paie avec mon téléphone.","tgt":"А пока я расплачиваюсь телефоном.","ro":"A paká ya raspláchivayus' telefónam."},{"fr":"Désormais, je vérifierai mon compte plus souvent.","tgt":"Теперь я буду чаще проверять свой счёт.","ro":"Tepér' ya búdu cháshche praveryát' svoy shchot."}]},{"title":"Un courriel au directeur","phrases":[{"fr":"Cher Ivan Petrovitch, je vous écris au sujet de notre contrat.","tgt":"Уважаемый Иван Петрович, пишу вам по поводу нашего договора.","ro":"Uvazháyemyy Iván Petróvich, pishú vam pa póvadu násheva dagavóra."},{"fr":"Je vous prie de confirmer la date de la réunion.","tgt":"Прошу вас подтвердить дату встречи.","ro":"Prashú vas pattverdít' dátu fstréchi."},{"fr":"Veuillez trouver ci-joint le rapport demandé.","tgt":"Во вложении направляю запрошенный отчёт.","ro":"Va vlazhénii napravlyáyu zapróshennyy atchót."},{"fr":"Je vous serais reconnaissant de répondre avant vendredi.","tgt":"Буду признателен за ответ до пятницы.","ro":"Búdu priznátelen za atvét da pyátnitsy."},{"fr":"Chers collègues, la réunion est reportée à jeudi.","tgt":"Уважаемые коллеги, совещание переносится на четверг.","ro":"Uvazháyemyye kallégi, saveshchániye perenósitsa na chetvérk."},{"fr":"Permettez-moi de vous présenter notre nouveau projet.","tgt":"Позвольте представить вам наш новый проект.","ro":"Pazvól'te pretstávit' vam nash nóvyy praékt."},{"fr":"Nous restons à votre disposition pour toute question.","tgt":"Мы готовы ответить на любые ваши вопросы.","ro":"My gatóvy atvétit' na lyubýye váshi vaprósy."},{"fr":"Je vous remercie de votre compréhension.","tgt":"Благодарю вас за понимание.","ro":"Blagadaryú vas za panimániye."},{"fr":"Cordialement, Alexeï Smirnov.","tgt":"С уважением, Алексей Смирнов.","ro":"S uvazhéniyem, Aleksyéy Smirnóf."},{"fr":"À la machine à café, bien sûr, on se parle plus simplement.","tgt":"У кофемашины мы, конечно, говорим проще.","ro":"U kafemashíny my, kanéshna, gavarím próshche."}],"tip":{"title":"Le registre du bureau : « uvazháyemyy » et les formules soutenues","example":"Chers collègues, la réunion est reportée à jeudi. — <b>Уважаемые</b> коллеги, совещание переносится на четверг.","body":"Au bureau, le russe change de ton dès qu'on écrit un message officiel ou qu'on parle devant un groupe. On commence par « uvazháyemyy », mot à mot estimé, suivi du prénom et du patronyme : « Uvazháyemyy Iván Petróvich ». Pour plusieurs personnes, on dit « Uvazháyemyye kallégi », littéralement estimés collègues, là où le français dit chers collègues. Viennent ensuite des formules toutes faites comme « Prashú vas », je vous prie, « Búdu priznátelen », je vous serais reconnaissant, et « Blagadaryú vas », je vous remercie. Pour terminer, on écrit « S uvazhéniyem », avec respect, l'équivalent de notre cordialement. Astuce : apprenez ces formules comme des blocs entiers, elles ne changent presque jamais.","exampleRo":"Uvazháyemyye kallégi, saveshchániye perenósitsa na chetvérk.","lit":"estimés · collègues · réunion · se reporte · à · jeudi"}},{"title":"Les heures supplémentaires","phrases":[{"fr":"Ce mois-ci, nous avons un projet très urgent.","tgt":"В этом месяце у нас очень срочный проект.","ro":"V étam mésyatse u nas óchen' sróchnyy praékt."},{"fr":"Je reste au bureau jusqu'à huit heures du soir.","tgt":"Я сижу в офисе до восьми вечера.","ro":"Ya sizhú v ófise da vas'mí véchera."},{"fr":"Les heures supplémentaires sont payées double.","tgt":"Сверхурочные оплачиваются в двойном размере.","ro":"Sverkhuróchnyye apláchivayutsa v dvaynóm razmére."},{"fr":"Ma femme n'est pas ravie que je rentre si tard.","tgt":"Жена не очень рада, что я прихожу так поздно.","ro":"Zhená ne óchen' ráda, shto ya prikhazhú tak pózdna."},{"fr":"Je suis fatigué, mais l'équipe compte sur moi.","tgt":"Я устал, но команда на меня рассчитывает.","ro":"Ya ustál, no kamánda na menyá rashchítyvayet."},{"fr":"Nous commandons des pizzas pour tenir le coup.","tgt":"Мы заказываем пиццу, чтобы продержаться.","ro":"My zakázyvayem píttsu, shtóby praderzhátsa."},{"fr":"Le chef a promis deux jours de repos une fois le projet rendu.","tgt":"Начальник обещал два выходных после сдачи проекта.","ro":"Nachál'nik abeshchál dva vykhadnýkh pósle zdáchi praékta."},{"fr":"Je ne veux pas que cela devienne une habitude.","tgt":"Не хочу, чтобы это стало привычкой.","ro":"Ne khachú, shtóby éta stála privýchkay."},{"fr":"De temps en temps, il faut savoir dire non.","tgt":"Иногда нужно уметь говорить «нет».","ro":"Inagdá núzhna umét' gavarít' «net»."},{"fr":"Vendredi, le projet est enfin rendu !","tgt":"В пятницу проект наконец сдан!","ro":"F pyátnitsu praékt nakanéts zdan!"}]},{"title":"Le télétravail","phrases":[{"fr":"Deux jours par semaine, je travaille de chez moi.","tgt":"Два дня в неделю я работаю из дома.","ro":"Dva dnya v nedélyu ya rabótayu iz dóma."},{"fr":"J'économise une heure de trajet chaque jour.","tgt":"Я экономлю час на дорогу каждый день.","ro":"Ya ekanómlyu chas na darógu kázhdyy den'."},{"fr":"J'ai installé un petit bureau près de la fenêtre.","tgt":"Я поставил маленький стол у окна.","ro":"Ya pastávil málen'kiy stol u akná."},{"fr":"Les visioconférences commencent à neuf heures pile.","tgt":"Видеозвонки начинаются ровно в девять.","ro":"Videazvankí nachináyutsa róvna v dévyat'."},{"fr":"Parfois, le chat passe devant la caméra pendant la réunion.","tgt":"Иногда кот проходит перед камерой во время совещания.","ro":"Inagdá kot prakhódit péred kámeray va vrémya saveshchániya."},{"fr":"À la maison, il est difficile de ne pas se laisser distraire.","tgt":"Дома трудно не отвлекаться.","ro":"Dóma trúdna ne atvlekátsa."},{"fr":"En travaillant seul, je me sens parfois isolé.","tgt":"Работая один, я иногда чувствую себя одиноко.","ro":"Rabótaya adín, ya inagdá chústvuyu sebyá adinóka."},{"fr":"Pour faire une pause, je fais un tour dans le quartier.","tgt":"Чтобы отдохнуть, я гуляю по району.","ro":"Shtóby addakhnút', ya gulyáyu pa rayónu."},{"fr":"Le soir, je ferme l'ordinateur à six heures précises.","tgt":"Вечером я закрываю ноутбук ровно в шесть.","ro":"Vécheram ya zakryváyu nautbúk róvna f shest'."},{"fr":"Deux jours de télétravail par semaine, ça me convient parfaitement.","tgt":"Мне идеально подходят два дня удалёнки в неделю.","ro":"Mne ideál'na patkhódyat dva dnya udalyónki v nedélyu."}]},{"title":"Les factures et les charges","phrases":[{"fr":"Les factures arrivent au début de chaque mois.","tgt":"Квитанции приходят в начале каждого месяца.","ro":"Kvitántsii prikhódyat v nachále kázhdava mésyatsa."},{"fr":"En hiver, le chauffage revient assez cher.","tgt":"Зимой отопление обходится довольно дорого.","ro":"Zimóy atapléniye abkhóditsa davól'na dóraga."},{"fr":"Je paie l'électricité directement dans l'application de la banque.","tgt":"Я оплачиваю электричество прямо в приложении банка.","ro":"Ya apláchivayu elektríchestva pryáma f prilazhénii bánka."},{"fr":"Il faut transmettre les relevés des compteurs d'eau.","tgt":"Нужно передавать показания счётчиков воды.","ro":"Núzhna peredavát' pakazániya shchyótchikaf vadý."},{"fr":"C'est le propriétaire qui paie Internet, c'est écrit dans le contrat.","tgt":"Интернет оплачивает хозяин, так написано в договоре.","ro":"Internét apláchivayet khazyáin, tak napísana v dagavóre."},{"fr":"Ce mois-ci, la facture d'eau me semble trop élevée.","tgt":"В этом месяце счёт за воду кажется мне слишком большим.","ro":"V étam mésyatse shchot za vódu kázhetsa mne slíshkam bal'shím."},{"fr":"Peut-être qu'un robinet fuit dans la salle de bains.","tgt":"Может быть, в ванной течёт кран.","ro":"Mózhet byt', v vánnay techyót kran."},{"fr":"J'appelle la société de gestion de l'immeuble pour vérifier.","tgt":"Я звоню в управляющую компанию, чтобы проверить.","ro":"Ya zvanyú v upravlyáyushchuyu kampániyu, shtóby pravérit'."},{"fr":"Un plombier passera demain matin.","tgt":"Сантехник придёт завтра утром.","ro":"Santékhnik pridyót záftra útram."},{"fr":"Je range toutes les factures dans un classeur.","tgt":"Я храню все квитанции в папке.","ro":"Ya khranyú fse kvitántsii f pápke."}]},{"title":"Un week-end pour souffler","phrases":[{"fr":"Le vendredi soir, je quitte la ville avec plaisir.","tgt":"В пятницу вечером я с удовольствием уезжаю из города.","ro":"F pyátnitsu vécheram ya s udavól'stviyem uyezháyu iz górada."},{"fr":"Mes parents ont une datcha non loin de la ville.","tgt":"У моих родителей дача недалеко от города.","ro":"U maíkh radíteley dácha nedalekó at górada."},{"fr":"Là-bas, je ne lis pas mes courriels professionnels.","tgt":"Там я не читаю рабочую почту.","ro":"Tam ya ne chitáyu rabóchuyu póchtu."},{"fr":"Le samedi, nous chauffons le bania.","tgt":"В субботу мы топим баню.","ro":"F subbótu my tópim bányu."},{"fr":"Après le bania, nous buvons du thé avec de la confiture.","tgt":"После бани мы пьём чай с вареньем.","ro":"Pósle báni my pyom chay s varén'yem."},{"fr":"Le dimanche, je ramasse des champignons dans la forêt.","tgt":"В воскресенье я собираю грибы в лесу.","ro":"V vaskresén'ye ya sabiráyu gribý v lesú."},{"fr":"Sans téléphone, le temps passe autrement.","tgt":"Без телефона время идёт по-другому.","ro":"Bes telefóna vrémya idyót pa-drugómu."},{"fr":"Lundi, je reviens avec des forces nouvelles.","tgt":"В понедельник я возвращаюсь с новыми силами.","ro":"F panedél'nik ya vazvrashcháyus' s nóvymi sílami."},{"fr":"Ces week-ends me sont tout simplement indispensables.","tgt":"Такие выходные мне просто необходимы.","ro":"Takíye vykhadnýye mne prósta neabkhadímy."},{"fr":"Je conseille à tout le monde de couper complètement le week-end.","tgt":"Всем советую на выходных полностью отключаться.","ro":"Fsem savétuyu na vykhadnýkh pólnast'yu atklyuchátsa."}]},{"title":"Un arrêt maladie","phrases":[{"fr":"Ce matin, je me suis réveillé avec de la fièvre.","tgt":"Сегодня утром я проснулся с температурой.","ro":"Sevódnya útram ya prasnúlsya s temperatúray."},{"fr":"J'ai écrit à mon chef que je ne viendrais pas.","tgt":"Я написал начальнику, что не приду.","ro":"Ya napisál nachál'niku, shto ne pridú."},{"fr":"J'ai fait venir un médecin à domicile.","tgt":"Я вызвал врача на дом.","ro":"Ya výzval vrachá na dom."},{"fr":"Le médecin m'a prescrit une semaine de repos.","tgt":"Врач назначил мне неделю отдыха.","ro":"Vrach naznáchil mne nedélyu ótdykha."},{"fr":"Il m'a fait un arrêt maladie électronique.","tgt":"Он открыл мне электронный больничный.","ro":"On atkrýl mne elektrónnyy bal'níchnyy."},{"fr":"Je dois boire beaucoup de thé chaud au citron.","tgt":"Мне нужно пить много горячего чая с лимоном.","ro":"Mne núzhna pit' mnóga garyácheva cháya s limónam."},{"fr":"Mes collègues m'ont souhaité un prompt rétablissement.","tgt":"Коллеги пожелали мне скорейшего выздоровления.","ro":"Kallégi pazheláli mne skaréyshava vyzdaravléniya."},{"fr":"Tant que je suis malade, je ne réponds pas aux courriels.","tgt":"Пока я болею, я не отвечаю на письма.","ro":"Paká ya baléyu, ya ne atvecháyu na pís'ma."},{"fr":"Je vais déjà mieux, la fièvre est tombée.","tgt":"Мне уже лучше, температура спала.","ro":"Mne uzhé lúchshe, temperatúra spála."},{"fr":"Je reprends le travail lundi prochain.","tgt":"Я выхожу на работу в следующий понедельник.","ro":"Ya vykhazhú na rabótu f sléduyushchiy panedél'nik."}]},{"title":"Les voisins de l'immeuble","phrases":[{"fr":"Nous vivons dans un grand immeuble de seize étages.","tgt":"Мы живём в большом шестнадцатиэтажном доме.","ro":"My zhivyóm v bal'shóm shesnatsatietázhnam dóme."},{"fr":"La voisine du dessous nous a apporté des blinis.","tgt":"Соседка снизу принесла нам блины.","ro":"Sasétka snízu prineslá nam bliný."},{"fr":"La gardienne connaît tous les habitants par leur prénom.","tgt":"Консьержка знает всех жильцов по имени.","ro":"Kans'érzhka znáyet fsekh zhil'tsóf pa ímeni."},{"fr":"Nous nous croisons souvent dans l'ascenseur.","tgt":"Мы часто встречаемся в лифте.","ro":"My chásta fstrecháyemsya v lífte."},{"fr":"Le voisin d'en face fait des travaux depuis un mois.","tgt":"Сосед напротив уже месяц делает ремонт.","ro":"Saséd naprótiv uzhé mésyats délayet remónt."},{"fr":"La perceuse commence à faire du bruit dès huit heures.","tgt":"Дрель начинает шуметь с восьми утра.","ro":"Drel' nachináyet shumét' s vas'mí utrá."},{"fr":"Je suis allé lui parler poliment.","tgt":"Я пошёл и вежливо с ним поговорил.","ro":"Ya pashól i vézhliva s nim pagavaríl."},{"fr":"Il a promis de finir avant la fin de la semaine.","tgt":"Он обещал закончить до конца недели.","ro":"On abeshchál zakónchit' da kantsá nedéli."},{"fr":"En été, les voisins organisent une fête dans la cour.","tgt":"Летом соседи устраивают праздник во дворе.","ro":"Létam sasédi ustráivayut práznik va dvaré."},{"fr":"Avec de bons voisins, la vie est bien plus facile.","tgt":"С хорошими соседями жить гораздо легче.","ro":"S kharóshimi sasédyami zhit' garázda lékhche."}]},{"title":"L'équilibre entre travail et vie privée","phrases":[{"fr":"Avant, je travaillais même le week-end.","tgt":"Раньше я работал даже по выходным.","ro":"Rán'she ya rabótal dázhe pa vykhadným."},{"fr":"Un jour, j'ai compris que j'étais vraiment épuisé.","tgt":"Однажды я понял, что очень устал.","ro":"Adnázhdy ya pónyal, shto óchen' ustál."},{"fr":"Maintenant, le soir, j'éteins mon téléphone professionnel.","tgt":"Теперь вечером я выключаю рабочий телефон.","ro":"Tepér' vécheram ya vyklyucháyu rabóchiy telefón."},{"fr":"Je vais à la piscine deux fois par semaine.","tgt":"Я хожу в бассейн два раза в неделю.","ro":"Ya khazhú v basséyn dva ráza v nedélyu."},{"fr":"Je passe plus de temps avec ma famille.","tgt":"Я провожу больше времени с семьёй.","ro":"Ya pravazhú ból'she vrémeni s sem'yóy."},{"fr":"Le dimanche soir, nous dînons tous ensemble.","tgt":"В воскресенье вечером мы все вместе ужинаем.","ro":"V vaskresén'ye vécheram my fse vméste úzhinayem."},{"fr":"Mon travail n'en souffre pas, bien au contraire.","tgt":"Работа от этого не страдает, наоборот.","ro":"Rabóta at étava ne stradáyet, naabarót."},{"fr":"Je suis devenu plus concentré et plus efficace.","tgt":"Я стал более сосредоточенным и эффективным.","ro":"Ya stal bóleye sasredatóchennym i effektívnym."},{"fr":"Si j'avais su, j'aurais tout changé plus tôt.","tgt":"Если бы я знал, я бы всё поменял раньше.","ro":"Yésli by ya znal, ya by fsyo pamenyál rán'she."},{"fr":"Le travail compte, mais la vie compte encore plus.","tgt":"Работа важна, но жизнь ещё важнее.","ro":"Rabóta vazhná, no zhizn' yeshchó vazhnéye."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module m'a appris à parler de mon quotidien en russe.","tgt":"Этот модуль научил меня говорить по-русски о повседневной жизни.","ro":"État módul' nauchíl menyá gavarít' pa-rússki a pafsednévnay zhízni."},{"fr":"Je sais maintenant faire une demande polie avec « by ».","tgt":"Теперь я умею вежливо просить с помощью «бы».","ro":"Tepér' ya uméyu vézhliva prasít' s pómashch'yu «by»."},{"fr":"Avec « shtoby », j'explique facilement mes intentions.","tgt":"Со словом «чтобы» я легко объясняю свои цели.","ro":"Sa slóvam «shtóby» ya lekhkó ab'yasnyáyu svaí tséli."},{"fr":"Les formules officielles ne me font plus peur.","tgt":"Официальные выражения меня больше не пугают.","ro":"Afitsiál'nyye vyrazhéniya menyá ból'she ne pugáyut."},{"fr":"Je pourrais même écrire un courriel à un directeur.","tgt":"Я бы даже мог написать письмо директору.","ro":"Ya by dázhe mok napisát' pis'mó diréktaru."},{"fr":"Le gérondif rend mes phrases plus fluides.","tgt":"Деепричастия делают мои фразы более плавными.","ro":"Deyeprichástiya délayut mai frázy bóleye plávnymi."},{"fr":"Je comprends mieux mes collègues russes au bureau.","tgt":"Я лучше понимаю русских коллег в офисе.","ro":"Ya lúchshe panimáyu rússkikh kallék v ófise."},{"fr":"La prononciation me donne parfois encore du mal.","tgt":"Произношение иногда всё ещё даётся мне трудно.","ro":"Praiznashéniye inagdá fsyo yeshchó dayótsa mne trúdna."},{"fr":"Chaque matin, je répète les phrases à voix haute.","tgt":"Каждое утро я повторяю фразы вслух.","ro":"Kázhdaye útra ya paftaryáyu frázy fslukh."},{"fr":"Je suis prêt pour le module suivant !","tgt":"Я готов к следующему модулю!","ro":"Ya gatóf k sléduyushchemu módulyu!"}]}]},{"id":2,"name":"En voyage","desc":"Des aventures de voyage plus poussées et plus authentiques.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Embarquer à Moscou pour la Volga","phrases":[{"fr":"Notre croisière sur la Volga commence au port fluvial de Moscou.","tgt":"Наш круиз по Волге начинается в московском речном порту.","ro":"Nash kruíz pa Vólge nachináyetsa v maskóvskam rechnóm partú."},{"fr":"On nous a remis les clés de la cabine dès l'embarquement.","tgt":"Ключи от каюты нам выдали сразу при посадке.","ro":"Klyuchí at kayúty nam výdali srázu pri pasádke."},{"fr":"La fenêtre de notre cabine donne directement sur le fleuve.","tgt":"Окно нашей каюты выходит прямо на реку.","ro":"Aknó náshey kayúty vykhódit pryáma na réku."},{"fr":"Le bateau compte trois ponts et un restaurant panoramique.","tgt":"На теплоходе три палубы и панорамный ресторан.","ro":"Na teplakhóde tri páluby i panarámnyy restarán."},{"fr":"Le départ est prévu à six heures du soir précises.","tgt":"Отплытие назначено ровно на шесть вечера.","ro":"Atplýtiye naznáchena róvna na shest' véchera."},{"fr":"Avant le départ, l'équipage présente les règles de sécurité.","tgt":"Перед отплытием экипаж рассказывает о правилах безопасности.","ro":"Péred atplýtiyem ekipázh rasskázyvayet a právilakh bezapásnasti."},{"fr":"Les enfants regardent les quais de Moscou s'éloigner.","tgt":"Дети смотрят, как удаляется московская набережная.","ro":"Déti smótryat, kak udalyáyetsa maskóvskaya náberezhnaya."},{"fr":"Le soir, on passe déjà la première écluse.","tgt":"Вечером мы уже проходим первый шлюз.","ro":"Vécheram my uzhé prakhódim pérvyy shlyuz."},{"fr":"Je n'avais jamais voyagé aussi lentement de ma vie.","tgt":"Я никогда в жизни не путешествовал так медленно.","ro":"Ya nikagdá v zhízni ne puteshéstvaval tak médlenna."},{"fr":"Douze jours sur l'eau nous attendent jusqu'à Astrakhan.","tgt":"До Астрахани нас ждут двенадцать дней на воде.","ro":"Da Ástrakhani nas zhdut dvenádtsat' dney na vadé."}]},{"title":"Ceux qui vivent à bord","phrases":[{"fr":"Le capitaine, qui travaille sur la Volga depuis trente ans, connaît chaque rive.","tgt":"Капитан, работающий на Волге тридцать лет, знает каждый берег.","ro":"Kapitán, rabótayushchiy na Vólge trídtsat' let, znáyet kázhdyy béreg."},{"fr":"La femme qui vit à Iaroslavl nous a conseillé un café.","tgt":"Женщина, живущая в Ярославле, посоветовала нам кафе.","ro":"Zhénshchina, zhivúshchaya v Yaraslávle, pasavétavala nam kafé."},{"fr":"Les passagers qui parlent français se sont assis ensemble.","tgt":"Пассажиры, говорящие по-французски, сели вместе.","ro":"Passazhíry, gavaryáshchiye pa-frantsúzski, séli vméste."},{"fr":"Le guide qui accompagne notre groupe s'appelle Igor.","tgt":"Гида, сопровождающего нашу группу, зовут Игорь.","ro":"Gída, sapravazhdáyushchevo náshu grúppu, zavút Ígar'."},{"fr":"Le cuisinier qui prépare l'oukha chaque vendredi est originaire d'Astrakhan.","tgt":"Повар, готовящий уху каждую пятницу, родом из Астрахани.","ro":"Póvar, gatóvyashchiy ukhú kázhduyu pyátnitsu, ródam iz Ástrakhani."},{"fr":"Un musicien qui joue de l'accordéon anime les soirées sur le pont.","tgt":"Вечера на палубе оживляет музыкант, играющий на баяне.","ro":"Vecherá na pálube azhivlyáyet muzykánt, igráyushchiy na bayáne."},{"fr":"Les touristes ayant réservé la croisière tôt ont obtenu les meilleures cabines.","tgt":"Туристы, забронировавшие круиз заранее, получили лучшие каюты.","ro":"Turísty, zabranírovavshiye kruíz zaráneye, paluchíli lúchshiye kayúty."},{"fr":"Le marin qui m'a aidé avec mes bagages vient de Kostroma.","tgt":"Матрос, помогавший мне с багажом, родом из Костромы.","ro":"Matrós, pamagávshiy mne s bagazhóm, ródam iz Kastramý."},{"fr":"J'aime regarder les mouettes qui volent derrière le bateau.","tgt":"Я люблю смотреть на чаек, летящих за теплоходом.","ro":"Ya lyublyú smatrét' na cháyek, letyáshchikh za teplakhódam."},{"fr":"Nous entendons des gens qui chantent sur le pont supérieur.","tgt":"Мы слышим людей, поющих на верхней палубе.","ro":"My slýshim lyudéy, payúshchikh na vérkhney pálube."}],"tip":{"title":"Les participes actifs : « rabótayushchiy », « zhivúshchiy »","example":"La femme qui vit à Iaroslavl nous a conseillé un café. — Женщина, <b>живущая</b> в Ярославле, посоветовала нам кафе.","body":"Pour dire « qui fait quelque chose », le russe peut remplacer « katóryy », qui, par un seul mot : le participe actif, un peu comme notre « vivant » ou « travaillant ». On le fabrique à partir du verbe au présent : « rabótayut », ils travaillent, donne « rabótayushchiy », travaillant, et « zhivút », ils vivent, donne « zhivúshchiy », vivant. À l'oreille, c'est ce petit son « shch » au milieu qui signale le participe. Il s'accorde comme un adjectif : « zhivúshchiy » pour un homme, « zhivúshchaya » pour une femme, « zhivúshchiye » au pluriel, comme dans « Zhénshchina, zhivúshchaya v Yaraslávle », mot à mot la femme vivant à Iaroslavl. Pour le passé, on entend plutôt « -vshiy » : « pamagávshiy », qui aidait. Dans la conversation de tous les jours, « katóryy rabótayet » reste très courant ; le participe donne simplement un ton plus soigné, idéal pour raconter un voyage.","exampleRo":"Zhénshchina, zhivúshchaya v Yaraslávle, pasavétavala nam kafé.","lit":"femme · vivant · à · Iaroslavl · a conseillé · à nous · café"}},{"title":"Première escale à Iaroslavl","phrases":[{"fr":"Iaroslavl passe pour l'une des plus anciennes villes de la Volga.","tgt":"Ярославль считается одним из старейших городов на Волге.","ro":"Yaraslávl' schitáyetsa adním iz staréyshikh garadóv na Vólge."},{"fr":"Nous sommes descendus à terre juste à côté des quais fleuris.","tgt":"Мы сошли на берег прямо у цветущей набережной.","ro":"My sashlí na béreg pryáma u tsvetúshchey náberezhnay."},{"fr":"La ville se dresse au confluent de la Volga et de la Kotorosl.","tgt":"Город стоит у слияния Волги и Которосли.","ro":"Górad staít u sliyániya Vólgi i Kótarasli."},{"fr":"Le centre historique est inscrit au patrimoine mondial de l'UNESCO.","tgt":"Исторический центр внесён в список всемирного наследия ЮНЕСКО.","ro":"Istarícheskiy tsentr vnesyón v spísak vsemírnava naslédiya Yunéska."},{"fr":"On a mangé des pelmenis dans un petit restaurant de la rue piétonne.","tgt":"Мы поели пельменей в маленьком ресторанчике на пешеходной улице.","ro":"My payéli pel'méney v málen'kam restaránchike na peshekhódnay úlitse."},{"fr":"On dit que Iaroslavl a eu le premier théâtre public de Russie.","tgt":"Говорят, что театр в Ярославле стал первым публичным театром в России.","ro":"Gavaryát, shto teátr v Yaraslávle stal pérvym publíchnym teátram v Rassíi."},{"fr":"Le musée « Musique et temps » nous a beaucoup étonnés.","tgt":"Музей «Музыка и время» нас очень удивил.","ro":"Muzéy «Múzyka i vrémya» nas óchen' udivíl."},{"fr":"Il faut être de retour à bord avant quatre heures.","tgt":"Вернуться на борт надо до четырёх часов.","ro":"Vernútsa na bort náda da chetyryókh chasóv."},{"fr":"J'ai acheté des pains d'épices pour mes collègues.","tgt":"Я купил коллегам пряники.","ro":"Ya kupíl kalégam pryániki."},{"fr":"Après cette première escale, j'ai eu envie de revenir ici.","tgt":"После этой первой стоянки мне захотелось вернуться сюда.","ro":"Pósle étay pérvay stayánki mne zakhatélas' vernútsa syudá."}]},{"title":"Une fois arrivés à Kostroma","phrases":[{"fr":"Arrivés à Kostroma, nous sommes tout de suite allés au marché.","tgt":"Приехав в Кострому, мы сразу пошли на рынок.","ro":"Priyékhav v Kastramú, my srázu pashlí na rýnak."},{"fr":"En apercevant les vieilles galeries marchandes, j'ai pensé à un décor de cinéma.","tgt":"Увидев торговые ряды, я подумал о декорациях к фильму.","ro":"Uvídev targóvyye ryadý, ya padúmal a dekarátsiyakh k fíl'mu."},{"fr":"Après avoir goûté le fromage local, j'en ai acheté un gros morceau.","tgt":"Попробовав местный сыр, я купил большой кусок.","ro":"Papróbavav mésnyy syr, ya kupíl bal'shóy kusók."},{"fr":"Ayant appris qu'il y avait une ferme d'élans tout près, on a pris un taxi.","tgt":"Узнав, что рядом есть лосиная ферма, мы взяли такси.","ro":"Uznáv, shto ryádam yest' lasínaya férma, my vzyáli taksí."},{"fr":"Après avoir nourri les élans, les enfants ne voulaient plus partir.","tgt":"Покормив лосей, дети не хотели уезжать.","ro":"Pakarmív laséy, déti ne khatéli uyezzhát'."},{"fr":"Remarquant notre intérêt, le guide nous a raconté la légende de la Snégourotchka.","tgt":"Заметив наш интерес, экскурсовод рассказал нам легенду о Снегурочке.","ro":"Zamétiv nash interés, ekskursavód rasskazál nam legéndu a Snegúrachke."},{"fr":"Après avoir fait le tour de la place, on s'est assis en terrasse.","tgt":"Обойдя всю площадь, мы сели за столик на улице.","ro":"Abaydyá vsyu plóshchad', my séli za stólik na úlitse."},{"fr":"De retour au bateau, nous nous sentions fatigués mais heureux.","tgt":"Вернувшись на теплоход, мы чувствовали себя усталыми, но счастливыми.","ro":"Vernúvshis' na teplakhód, my chústvavali sebyá ustálymi, no shchaslívymi."},{"fr":"Ayant oublié mon chapeau au café, j'ai été obligé d'y retourner.","tgt":"Забыв шляпу в кафе, я был вынужден вернуться.","ro":"Zabýv shlyápu v kafé, ya byl výnuzhden vernútsa."},{"fr":"Après avoir vu Kostroma, je comprends mieux la vieille Russie.","tgt":"Увидев Кострому, я лучше понимаю старую Россию.","ro":"Uvídev Kastramú, ya lúchshe panimáyu stáruyu Rassíyu."}],"tip":{"title":"Le gérondif passé : « priyékhav », « uvídev »","example":"Arrivés à Kostroma, nous sommes tout de suite allés au marché. — <b>Приехав</b> в Кострому, мы сразу пошли на рынок.","body":"Pour dire « une fois arrivé » ou « après avoir vu », le russe a une forme très économique : le gérondif passé. On part du verbe au passé perfectif, on enlève le « l » final et on met un « v » : « priyékhal », il est arrivé, devient « priyékhav », une fois arrivé, et « uvídel », il a vu, devient « uvídev », après avoir vu. Avec un verbe en « -sya », on dit « -vshis' » : « vernúlsya » donne « vernúvshis' », une fois rentré. Décomposons « Priyékhav v Kastramú, my srázu pashlí na rýnak » : étant arrivés à Kostroma, nous sommes aussitôt allés au marché. Attention, les deux actions doivent avoir le même sujet, comme en français. Astuce : ce petit « v » final sonne comme un « voilà, c'est fait », et on enchaîne sur la suite.","exampleRo":"Priyékhav v Kastramú, my srázu pashlí na rýnak.","lit":"étant arrivé · à · Kostroma · nous · aussitôt · sommes allés · au · marché"}},{"title":"Plyos, la petite ville des peintres","phrases":[{"fr":"La minuscule ville de Plyos est perchée sur une colline au-dessus de la Volga.","tgt":"Крошечный городок Плёс стоит на холме над Волгой.","ro":"Króshechnyy garadók Plyos staít na khalmé nad Vólgay."},{"fr":"Le peintre Lévitan y a passé plusieurs étés de suite.","tgt":"Здесь несколько лет подряд проводил лето художник Левитан.","ro":"Zdes' néskal'ka let padryád pravadíl léta khudózhnik Levitán."},{"fr":"On comprend tout de suite pourquoi les artistes aiment cet endroit.","tgt":"Сразу понятно, почему художники любят это место.","ro":"Srázu panyátna, pachemú khudózhniki lyúbyat éta mésta."},{"fr":"Les maisons en bois ont des encadrements de fenêtres sculptés.","tgt":"У деревянных домов резные наличники.","ro":"U derevyánnykh damóv reznýye nalíchniki."},{"fr":"Nous sommes montés au belvédère par un vieil escalier.","tgt":"Мы поднялись на смотровую площадку по старой лестнице.","ro":"My padnyalís' na smatravúyu plashchádku pa stáray lésnitse."},{"fr":"D'en haut, la vue sur le fleuve est à couper le souffle.","tgt":"Сверху вид на реку просто захватывает дух.","ro":"Svérkhu vid na réku prósta zakhvátyvayet dukh."},{"fr":"Ici, il n'y a ni embouteillages ni grands magasins.","tgt":"Здесь нет ни пробок, ни больших магазинов.","ro":"Zdes' net ni própak, ni bal'shíkh magazínav."},{"fr":"Les habitants vendent des baies et des champignons au bord de la route.","tgt":"Местные жители продают ягоды и грибы у дороги.","ro":"Mésnyye zhíteli pradayút yágady i gribý u darógi."},{"fr":"On dirait que le temps s'est arrêté dans cette petite ville.","tgt":"Кажется, что время в этом городке остановилось.","ro":"Kázhetsa, shto vrémya v étam garadké astanavílas'."},{"fr":"Un jour, j'aimerais passer une semaine entière ici.","tgt":"Когда-нибудь я хотел бы провести здесь целую неделю.","ro":"Kagdá-nibud' ya khatél by pravestí zdes' tséluyu nedélyu."}]},{"title":"Une soirée sur le pont","phrases":[{"fr":"Le soleil se couche lentement derrière la rive boisée.","tgt":"Солнце медленно садится за лесистый берег.","ro":"Sóntse médlenna sadítsa za lesístyy béreg."},{"fr":"Quelqu'un a apporté une guitare et un plaid.","tgt":"Кто-то принёс гитару и плед.","ro":"Któ-ta prinyós gitáru i pled."},{"fr":"On boit du thé chaud en regardant les rives défiler.","tgt":"Мы пьём горячий чай и смотрим, как мимо проплывают берега.","ro":"My p'yom garyáchiy chay i smótrim, kak míma praplyváyut beregá."},{"fr":"Dans la lumière du soir, l'eau paraît presque dorée.","tgt":"В вечернем свете вода кажется почти золотой.","ro":"V vechérnem svéte vadá kázhetsa pachtí zalatóy."},{"fr":"Au loin, on aperçoit les lumières d'un petit village.","tgt":"Вдалеке видны огоньки небольшой деревни.","ro":"Vdaleké vidný agan'kí nebal'shóy derévni."},{"fr":"Il commence à faire frais, prenez une veste.","tgt":"Становится прохладно, возьмите куртку.","ro":"Stanóvitsa prakhládna, vaz'míte kúrtku."},{"fr":"Une passagère âgée m'a appris une vieille chanson de la Volga.","tgt":"Пожилая пассажирка научила меня старой волжской песне.","ro":"Pazhiláya passazhírka nauchíla menyá stáray vólzhskay pésne."},{"fr":"Je n'avais jamais vu autant d'étoiles dans le ciel.","tgt":"Я никогда не видел столько звёзд на небе.","ro":"Ya nikagdá ne vídel stól'ka zvyozd na nébe."},{"fr":"Nous avons bavardé sur le pont jusqu'à minuit.","tgt":"Мы проговорили на палубе до полуночи.","ro":"My pragavaríli na pálube da palúnachi."},{"fr":"De telles soirées tranquilles valent tous les voyages.","tgt":"Такие тихие вечера стоят любых путешествий.","ro":"Takíye tíkhiye vecherá stóyat lyubýkh puteshéstviy."}]},{"title":"Les rencontres sur le bateau","phrases":[{"fr":"Chacun à table a raconté son histoire.","tgt":"Каждый за столом рассказал свою историю.","ro":"Kázhdyy za stalóm rasskazál svayú istóriyu."},{"fr":"Mon voisin de cabine voyage avec sa femme et ses petits-enfants.","tgt":"Мой сосед по каюте путешествует со своей женой и внуками.","ro":"Moy saséd pa kayúte puteshéstvuyet sa svayéy zhenóy i vnúkami."},{"fr":"Elle m'a montré des photos de sa maison à Samara.","tgt":"Она показала мне фотографии своего дома в Самаре.","ro":"Aná pakazála mne fatagráfii svayevó dóma v Samáre."},{"fr":"J'ai oublié mon appareil photo dans ma cabine.","tgt":"Я забыл фотоаппарат в своей каюте.","ro":"Ya zabýl fataapparát v svayéy kayúte."},{"fr":"Le professeur de Kazan parle de son métier avec passion.","tgt":"Преподаватель из Казани с увлечением рассказывает о своей работе.","ro":"Prepadavátel' iz Kazáni s uvlechéniyem rasskázyvayet a svayéy rabóte."},{"fr":"Ils fêtent leur anniversaire de mariage sur le bateau.","tgt":"Они отмечают свою годовщину свадьбы на теплоходе.","ro":"Aní atmecháyut svayú gadavshchínu svád'by na teplakhóde."},{"fr":"Chaque passager a sa propre place au restaurant.","tgt":"У каждого пассажира своё место в ресторане.","ro":"U kázhdava passazhíra svayó mésta v restaráne."},{"fr":"Il nous a invités à sa table pour le dîner.","tgt":"Он пригласил нас за свой столик на ужин.","ro":"On priglasíl nas za svoy stólik na úzhin."},{"fr":"Une jeune femme de Tver dessine des vues de la Volga dans son carnet.","tgt":"Девушка из Твери рисует в своём блокноте виды Волги.","ro":"Dévushka iz Tverí risúyet v svayóm blaknóte vídy Vólgi."},{"fr":"Chacun a son caractère, mais on s'entend tous très bien.","tgt":"У каждого свой характер, но мы все прекрасно ладим.","ro":"U kázhdava svoy kharákter, no my vse prekrásna ládim."}],"tip":{"title":"« Svóy » : son propre, le possessif réfléchi","example":"Chacun à table a raconté son histoire. — Каждый за столом рассказал <b>свою</b> историю.","body":"Le français dit « son histoire » sans préciser à qui elle est ; le russe, lui, fait la différence. Quand ce qu'on possède appartient au sujet de la phrase, on dit « svoy », son propre : « On rasskazál svayú istóriyu », il a raconté sa propre histoire. Si l'on dit « On rasskazál yevó istóriyu », on comprend qu'il raconte l'histoire d'un autre homme. « Svoy » s'accorde comme « moy » : « svoy » au masculin, « svayá » au féminin, « svayó » au neutre, « svaí » au pluriel, et « sa svayéy zhenóy », avec sa femme. On l'entend aussi dans des expressions toutes faites : « U kázhdava svoy kharákter », chacun a son caractère. Astuce : dès que le possesseur est celui qui agit, pensez « svoy ».","exampleRo":"Kázhdyy za stalóm rasskazál svayú istóriyu.","lit":"chacun · à · table · a raconté · sa propre · histoire"}},{"title":"Nijni Novgorod, là où l'Oka rejoint la Volga","phrases":[{"fr":"À Nijni Novgorod, l'Oka se jette dans la Volga.","tgt":"В Нижнем Новгороде Ока впадает в Волгу.","ro":"V Nízhnem Nóvgarade Aká vpadáyet v Vólgu."},{"fr":"Depuis la rive haute, on voit bien les deux fleuves se rejoindre.","tgt":"С высокого берега хорошо видно, как сливаются две реки.","ro":"S vysókava bérega kharashó vídna, kak sliváyutsa dve rekí."},{"fr":"Le grand escalier qui descend vers la Volga compte plus de cinq cents marches.","tgt":"У большой лестницы, ведущей к Волге, больше пятисот ступеней.","ro":"U bal'shóy lésnitsy, vedúshchey k Vólge, ból'she pyatisót stupéney."},{"fr":"Nous l'avons descendu, mais nous n'avons pas osé le remonter.","tgt":"Мы спустились по ней, но подниматься обратно не решились.","ro":"My spustílis' pa ney, no padnimátsa abrátna ne reshílis'."},{"fr":"Le téléphérique passe juste au-dessus de la Volga.","tgt":"Канатная дорога проходит прямо над Волгой.","ro":"Kanátnaya daróga prakhódit pryáma nad Vólgay."},{"fr":"Depuis la cabine, on voit toute la ville d'un seul coup.","tgt":"Из кабинки виден весь город сразу.","ro":"Iz kabínki víden ves' górad srázu."},{"fr":"Dans la rue piétonne, il y a beaucoup de musiciens de rue.","tgt":"На пешеходной улице много уличных музыкантов.","ro":"Na peshekhódnay úlitse mnóga úlichnykh muzykántav."},{"fr":"On a mangé des glaces en se promenant sur les quais.","tgt":"Гуляя по набережной, мы ели мороженое.","ro":"Gulyáya pa náberezhnay, my yéli marózhenaye."},{"fr":"Cette ville s'est révélée plus vivante que je ne le pensais.","tgt":"Этот город оказался живее, чем я думал.","ro":"État górad akazálsa zhivéye, chem ya dúmal."},{"fr":"Ce soir, le bateau repart vers Kazan.","tgt":"Вечером теплоход отправляется дальше, в Казань.","ro":"Vécheram teplakhód atpravlyáyetsa dál'she, v Kazán'."}]},{"title":"Une journée de pluie à bord","phrases":[{"fr":"Il pleut depuis ce matin, impossible de sortir sur le pont.","tgt":"С утра идёт дождь, на палубу не выйти.","ro":"S utrá idyót dozhd', na pálubu ne výyti."},{"fr":"Un tournoi d'échecs a été organisé dans le salon.","tgt":"В салоне устроили шахматный турнир.","ro":"V salóne ustróili shákhmatnyy turnír."},{"fr":"J'ai perdu dès le premier tour contre un garçon de dix ans.","tgt":"Я проиграл в первом же туре десятилетнему мальчику.","ro":"Ya praigrál v pérvam zhe túre desyatilétnemu mál'chiku."},{"fr":"D'autres préfèrent lire au bar avec un chocolat chaud.","tgt":"Другие предпочитают читать в баре с горячим шоколадом.","ro":"Drugíye predpachitáyut chitát' v báre s garyáchim shakaládam."},{"fr":"L'après-midi, on donne un cours de russe aux étrangers.","tgt":"Днём для иностранцев проводят урок русского языка.","ro":"Dnyom dlya inastrántsev pravódyat urók rússkava yazyká."},{"fr":"J'ai profité de la pluie pour écrire des cartes postales.","tgt":"Я воспользовался дождём, чтобы написать открытки.","ro":"Ya vaspól'zavalsa dazhdyóm, shtóby napisát' atkrýtki."},{"fr":"Sous la pluie, la Volga a un charme un peu mélancolique.","tgt":"У Волги в дождь какое-то грустное очарование.","ro":"U Vólgi v dozhd' kakóye-ta grúsnaye acharavániye."},{"fr":"Vers le soir, la pluie a enfin cessé.","tgt":"К вечеру дождь наконец прекратился.","ro":"K vécheru dozhd' nakanéts prekratílsa."},{"fr":"Un immense arc-en-ciel est apparu au-dessus du fleuve.","tgt":"Над рекой появилась огромная радуга.","ro":"Nad rekóy payavílas' agrómnaya ráduga."},{"fr":"Tout le monde s'est précipité sur le pont pour le photographier.","tgt":"Все выбежали на палубу её фотографировать.","ro":"Vse výbezhali na pálubu yeyó fatagrafíravat'."}]},{"title":"Escale gourmande à Kazan","phrases":[{"fr":"Kazan est la capitale du Tatarstan.","tgt":"Казань является столицей Татарстана.","ro":"Kazán' yavlyáyetsa stalítsey Tatarstána."},{"fr":"Ici, on parle à la fois russe et tatar.","tgt":"Здесь говорят и по-русски, и по-татарски.","ro":"Zdes' gavaryát i pa-rússki, i pa-tatárski."},{"fr":"Les noms des rues sont écrits en deux langues.","tgt":"Названия улиц написаны на двух языках.","ro":"Nazvániya úlits napísany na dvukh yazykákh."},{"fr":"Goûtez absolument le tchak-tchak, une douceur au miel.","tgt":"Обязательно попробуйте чак-чак, сладость с мёдом.","ro":"Abyazátel'na papróbuyte chak-chák, sládast' s myódam."},{"fr":"Les échpotchmaks ressemblent à de petits chaussons triangulaires à la viande.","tgt":"Эчпочмаки похожи на маленькие треугольные пирожки с мясом.","ro":"Echpachmáki pakhózhi na málen'kiye treugól'nyye pirazhkí s myásam."},{"fr":"Nous avons flâné dans le vieux quartier tatar.","tgt":"Мы погуляли по Старо-Татарской слободе.","ro":"My pagulyáli pa Stara-Tatárskay slabadé."},{"fr":"Là-bas, les maisons sont peintes de couleurs vives.","tgt":"Дома там выкрашены в яркие цвета.","ro":"Damá tam výkrasheny v yárkiye tsvetá."},{"fr":"Un habitant nous a appris à dire merci en tatar.","tgt":"Один местный житель научил нас говорить «спасибо» по-татарски.","ro":"Adín mésnyy zhítel' nauchíl nas gavarít' «spasíba» pa-tatárski."},{"fr":"Kazan nous a paru à la fois moderne et chaleureuse.","tgt":"Казань показалась нам одновременно современной и уютной.","ro":"Kazán' pakazálas' nam adnavreménna savreménnay i uyútnay."},{"fr":"Peut-être qu'un jour nous reviendrons ici pour plus longtemps.","tgt":"Может быть, когда-нибудь мы вернёмся сюда надолго.","ro":"Mózhet byt', kagdá-nibud' my vernyómsa syudá nadólga."}]},{"title":"Un atelier oukha avec le chef","phrases":[{"fr":"Aujourd'hui, le chef nous apprend à préparer l'oukha.","tgt":"Сегодня шеф-повар учит нас варить уху.","ro":"Sevódnya shef-póvar úchit nas varít' ukhú."},{"fr":"La vraie oukha se prépare avec plusieurs sortes de poissons.","tgt":"Настоящую уху варят из нескольких видов рыбы.","ro":"Nastayáshchuyu ukhú váryat iz néskal'kikh vídav rýby."},{"fr":"D'abord, on fait cuire les petits poissons pour le bouillon.","tgt":"Сначала для бульона варят мелкую рыбу.","ro":"Snachála dlya bul'yóna váryat mélkuyu rýbu."},{"fr":"Ensuite, on ajoute des morceaux de sandre et de sterlet.","tgt":"Потом добавляют куски судака и стерляди.","ro":"Patóm dabavlyáyut kuskí sudaká i stérlyadi."},{"fr":"Le chef dit qu'il ne faut pas remuer l'oukha trop souvent.","tgt":"Шеф говорит, что уху нельзя часто помешивать.","ro":"Shef gavarít, shto ukhú nel'zyá chásta paméshivat'."},{"fr":"Pour l'arôme, on met du poivre, du laurier et de l'aneth.","tgt":"Для аромата кладут перец, лавровый лист и укроп.","ro":"Dlya aramáta kladút pérets, lavróvyy list i ukróp."},{"fr":"Autrefois, les pêcheurs versaient un petit verre de vodka dans l'oukha.","tgt":"Раньше рыбаки добавляли в уху рюмку водки.","ro":"Rán'she rybakí dabavlyáli v ukhú ryúmku vódki."},{"fr":"Ça sent tellement bon que tout le monde a faim.","tgt":"Пахнет так вкусно, что все проголодались.","ro":"Pákhnet tak vkúsna, shto vse pragaladális'."},{"fr":"On sert l'oukha avec du pain noir et de l'oignon vert.","tgt":"Уху подают с чёрным хлебом и зелёным луком.","ro":"Ukhú padayút s chyórnym khlébam i zelyónym lúkam."},{"fr":"Je vais essayer de la refaire à la maison.","tgt":"Попробую приготовить её дома.","ro":"Papróbuyu prigatóvit' yeyó dóma."}]},{"title":"Les consignes avant Samara","phrases":[{"fr":"Nous devons être sur le quai à neuf heures.","tgt":"Мы должны быть на пристани в девять часов.","ro":"My dalzhný byt' na prístani v dévyat' chasóv."},{"fr":"Le bateau devrait arriver à Samara vers huit heures.","tgt":"Теплоход должен прийти в Самару около восьми.","ro":"Teplakhód dólzhen priytí v Samáru ókala vas'mí."},{"fr":"Vous devez absolument voir les quais de Samara.","tgt":"Вы обязательно должны увидеть набережную в Самаре.","ro":"Vy abyazátel'na dalzhný uvídet' náberezhnuyu v Samáre."},{"fr":"Ma femme doit appeler sa mère avant le déjeuner.","tgt":"Жена должна позвонить маме до обеда.","ro":"Zhená dalzhná pazvanít' máme da abéda."},{"fr":"Le musée devrait être ouvert lundi.","tgt":"Музей должен быть открыт в понедельник.","ro":"Muzéy dólzhen byt' atkrýt v panedél'nik."},{"fr":"Nous ne devons pas oublier nos cartes d'embarquement.","tgt":"Мы не должны забыть посадочные талоны.","ro":"My ne dalzhný zabýt' pasádachnyye talóny."},{"fr":"Il devait venir avec nous, mais il est tombé malade.","tgt":"Он должен был пойти с нами, но заболел.","ro":"On dólzhen byl paytí s námi, no zabalél."},{"fr":"Par cette chaleur, on devrait être bien à la plage.","tgt":"В такую жару на пляже должно быть хорошо.","ro":"V takúyu zharú na plyázhe dalzhnó byt' kharashó."},{"fr":"Combien je vous dois pour le taxi ?","tgt":"Сколько я вам должен за такси?","ro":"Skól'ka ya vam dólzhen za taksí?"},{"fr":"Elle devait nous attendre près de la gare fluviale.","tgt":"Она должна была ждать нас у речного вокзала.","ro":"Aná dalzhná bylá zhdat' nas u rechnóva vakzála."}],"tip":{"title":"« Dólzhen » : je dois, ça devrait","example":"Le bateau devrait arriver à Samara vers huit heures. — Теплоход <b>должен</b> прийти в Самару около восьми.","body":"Pour dire « je dois », le russe n'utilise pas un verbe mais un mot qui s'accorde comme un adjectif : « dólzhen ». Un homme dit « Ya dólzhen », une femme « Ya dalzhná », et au pluriel ou avec « vy » on dit « dalzhný » ; écoutez bien, l'accent saute à la fin dès qu'on quitte le masculin. Ensuite vient simplement l'infinitif : « My dalzhný byt' na prístani », mot à mot nous devons être au quai. Comme en français, il exprime aussi une probabilité : « Teplakhód dólzhen priytí v vósem' », le bateau devrait arriver à huit heures. Pour le passé, on ajoute « byl », « bylá » ou « bylí » : « On dólzhen byl paytí », il devait venir. Et au guichet, « Skól'ka ya vam dólzhen ? » veut dire combien je vous dois.","exampleRo":"Teplakhód dólzhen priytí v Samáru ókala vas'mí.","lit":"bateau · doit · arriver · à · Samara · vers · huit"}},{"title":"Samara, ses quais et ses plages","phrases":[{"fr":"Les quais de Samara s'étendent sur plusieurs kilomètres.","tgt":"Набережная Самары тянется на несколько километров.","ro":"Náberezhnaya Samáry tyánetsa na néskal'ka kilamétrav."},{"fr":"Les gens se baignent directement dans la Volga.","tgt":"Люди купаются прямо в Волге.","ro":"Lyúdi kupáyutsa pryáma v Vólge."},{"fr":"La bière d'ici est connue dans tout le pays.","tgt":"Здешнее пиво знаменито на всю страну.","ro":"Zdéshneye píva znameníta na vsyu stranú."},{"fr":"On a traversé vers l'autre rive en vedette.","tgt":"Мы переправились на другой берег на катере.","ro":"My perepravílis' na drugóy béreg na kátere."},{"fr":"Là-bas, il y a de longues plages de sable presque désertes.","tgt":"Там длинные песчаные пляжи, почти пустые.","ro":"Tam dlínnyye peshchányye plyázhi, pachtí pustýye."},{"fr":"La ville a conservé de belles maisons de marchands.","tgt":"В городе сохранились красивые купеческие дома.","ro":"V górade sakhranílis' krasívyye kupécheskiye damá."},{"fr":"Le soir, toute la ville se promène au bord de l'eau.","tgt":"Вечером весь город гуляет у воды.","ro":"Vécheram ves' górad gulyáyet u vadý."},{"fr":"Il faisait trente-cinq degrés à l'ombre.","tgt":"В тени было тридцать пять градусов.","ro":"V tení býla trídtsat' pyat' grádusav."},{"fr":"On s'est réfugiés dans un café climatisé pour fuir la chaleur.","tgt":"Мы спрятались от жары в кафе с кондиционером.","ro":"My spryátalis' at zharý v kafé s kanditsianéram."},{"fr":"Samara m'a semblé plus détendue que Moscou.","tgt":"Самара показалась мне спокойнее Москвы.","ro":"Samára pakazálas' mne spakóyneye Maskvý."}]},{"title":"Randonnée dans les monts Jigouli","phrases":[{"fr":"Après Samara, le fleuve dessine une grande boucle.","tgt":"После Самары река делает большую петлю.","ro":"Pósle Samáry reká délayet bal'shúyu petlyú."},{"fr":"Cette boucle s'appelle la Samarskaïa Louka.","tgt":"Эта излучина называется Самарская Лука.","ro":"Éta izlúchina nazyváyetsa Samárskaya Luká."},{"fr":"Les monts Jigouli sont couverts de forêts.","tgt":"Жигулёвские горы покрыты лесом.","ro":"Zhigulyóvskiye góry pakrýty lésam."},{"fr":"Nous sommes montés à pied jusqu'à l'un des sommets.","tgt":"Мы поднялись пешком на одну из вершин.","ro":"My padnyalís' peshkóm na adnú iz vershín."},{"fr":"Le sentier était raide, mais bien balisé.","tgt":"Тропа была крутая, но хорошо размеченная.","ro":"Trapá bylá krutáya, no kharashó razméchennaya."},{"fr":"D'en haut, on voit la Volga contourner les montagnes.","tgt":"Сверху видно, как Волга огибает горы.","ro":"Svérkhu vídna, kak Vólga agibáyet góry."},{"fr":"Des plantes très rares poussent dans ce parc national.","tgt":"В национальном парке растут очень редкие растения.","ro":"V natsianál'nam párke rastút óchen' rédkiye rasténiya."},{"fr":"Le guide nous a raconté des légendes sur les brigands de la Volga.","tgt":"Гид рассказал нам легенды о волжских разбойниках.","ro":"Gid rasskazál nam legéndy a vólzhskikh razbóynikakh."},{"fr":"On dit qu'ils cachaient leurs trésors dans ces grottes.","tgt":"Говорят, что в этих пещерах они прятали сокровища.","ro":"Gavaryát, shto v étikh peshchérakh aní pryátali sakróvishcha."},{"fr":"Descendre a été plus dur pour les jambes que monter.","tgt":"Спускаться было тяжелее для ног, чем подниматься.","ro":"Spuskátsa býla tyazheléye dlya nog, chem padnimátsa."}]},{"title":"Un petit souci de santé à bord","phrases":[{"fr":"Je me suis réveillé avec un gros mal de gorge.","tgt":"Я проснулся с сильной болью в горле.","ro":"Ya prasnúlsa s síl'nay ból'yu v górle."},{"fr":"À l'accueil, on m'a conseillé d'aller voir le médecin du bord.","tgt":"Администратор посоветовал мне сходить к судовому врачу.","ro":"Administrátar pasavétaval mne skhadít' k sudavómu vrachú."},{"fr":"L'infirmerie se trouve sur le pont inférieur.","tgt":"Медпункт находится на нижней палубе.","ro":"Medpúnkt nakhóditsa na nízhney pálube."},{"fr":"Le médecin m'a demandé si j'avais de la fièvre.","tgt":"Врач спросил, есть ли у меня температура.","ro":"Vrach sprasíl, yest' li u menyá temperatúra."},{"fr":"Il m'a prescrit des pastilles pour la gorge et du thé au miel.","tgt":"Он прописал мне леденцы от горла и чай с мёдом.","ro":"On prapisál mne ledentsý at górla i chay s myódam."},{"fr":"On m'a conseillé de rester au chaud un jour ou deux.","tgt":"Мне посоветовали денёк-другой посидеть в тепле.","ro":"Mne pasavétavali denyók-drugóy pasidét' v teplé."},{"fr":"Une voisine m'a apporté de la confiture de framboises.","tgt":"Соседка принесла мне малиновое варенье.","ro":"Sasédka prineslá mne malínavaye varén'ye."},{"fr":"Paraît-il que c'est le meilleur remède contre le rhume.","tgt":"Говорят, это лучшее средство от простуды.","ro":"Gavaryát, éta lúchsheye srétstva at prastúdy."},{"fr":"Dès le lendemain, je me sentais beaucoup mieux.","tgt":"Уже на следующий день мне стало гораздо лучше.","ro":"Uzhé na sléduyushchiy den' mne stála garázda lúchshe."},{"fr":"Heureusement, je n'ai manqué aucune escale.","tgt":"К счастью, я не пропустил ни одной стоянки.","ro":"K shchást'yu, ya ne prapustíl ni adnóy stayánki."}]},{"title":"Astrakhan, la porte du delta","phrases":[{"fr":"Au bout de douze jours, nous voici enfin à Astrakhan.","tgt":"Спустя двенадцать дней мы наконец прибыли в Астрахань.","ro":"Spustyá dvenádtsat' dney my nakanéts príbyli v Ástrakhan'."},{"fr":"Il fait bien plus chaud ici que dans le nord.","tgt":"Здесь гораздо жарче, чем на севере.","ro":"Zdes' garázda zhárche, chem na sévere."},{"fr":"La ville est bâtie sur plusieurs îles.","tgt":"Город стоит на нескольких островах.","ro":"Górad staít na néskal'kikh astravákh."},{"fr":"Le marché central sent le poisson fumé et le melon.","tgt":"На центральном рынке пахнет копчёной рыбой и дынями.","ro":"Na tsentrál'nam rýnke pákhnet kapchyónay rýbay i dýnyami."},{"fr":"Les pastèques d'Astrakhan sont célèbres dans toute la Russie.","tgt":"Астраханские арбузы знамениты на всю Россию.","ro":"Astrakhánskiye arbúzy znameníty na vsyu Rassíyu."},{"fr":"Un vendeur nous a fait goûter du caviar sur un morceau de pain.","tgt":"Продавец дал нам попробовать икру на кусочке хлеба.","ro":"Pradavéts dal nam papróbavat' ikrú na kusóchke khléba."},{"fr":"Nous avons acheté de la vobla séchée pour la soirée.","tgt":"Мы купили сушёную воблу к вечеру.","ro":"My kupíli sushyónuyu vóblu k vécheru."},{"fr":"Le soir, les fontaines du centre s'illuminent.","tgt":"Вечером в центре подсвечивают фонтаны.","ro":"Vécheram v tséntre padsvéchivayut fantány."},{"fr":"Cette nuit, nous dormons dans un petit hôtel près du fleuve.","tgt":"Сегодня мы ночуем в маленькой гостинице у реки.","ro":"Sevódnya my nachúyem v málen'kay gastínitse u rekí."},{"fr":"Demain, une vedette nous emmènera dans le delta.","tgt":"Завтра катер повезёт нас в дельту.","ro":"Závtra káter pavezyót nas v dél'tu."}]},{"title":"Au cœur du delta de la Volga","phrases":[{"fr":"Le delta de la Volga compte des centaines de bras et de chenaux.","tgt":"В дельте Волги сотни рукавов и проток.","ro":"V dél'te Vólgi sótni rukavóv i pratók."},{"fr":"Notre barque glisse lentement entre les roseaux.","tgt":"Наша лодка медленно скользит среди камышей.","ro":"Násha lódka médlenna skal'zít sredí kamyshéy."},{"fr":"En été, des champs entiers de lotus fleurissent sur l'eau.","tgt":"Летом на воде цветут целые поля лотосов.","ro":"Létam na vadé tsvetút tsélyye palyá lótasav."},{"fr":"Nous avons vu des hérons, des pélicans et des cormorans.","tgt":"Мы видели цапель, пеликанов и бакланов.","ro":"My vídeli tsápel', pelikánav i baklánav."},{"fr":"Le guide a attrapé un poisson en quelques minutes.","tgt":"Гид за несколько минут поймал рыбу.","ro":"Gid za néskal'ka minút paymál rýbu."},{"fr":"Il nous a préparé une oukha directement sur la rive.","tgt":"Он сварил нам уху прямо на берегу.","ro":"On svaríl nam ukhú pryáma na beregú."},{"fr":"Les moustiques sont nombreux, n'oubliez pas votre répulsif.","tgt":"Комаров много, не забудьте средство от комаров.","ro":"Kamaróv mnóga, ne zabúd'te srétstva at kamaróv."},{"fr":"C'est ici que la Volga se jette enfin dans la mer Caspienne.","tgt":"Здесь Волга наконец впадает в Каспийское море.","ro":"Zdes' Vólga nakanéts vpadáyet v Kaspíyskaye móre."},{"fr":"Seuls les oiseaux troublent le silence.","tgt":"Тишину нарушают только птицы.","ro":"Tishinú narusháyut tól'ka ptítsy."},{"fr":"C'est sans doute le plus bel endroit de tout le voyage.","tgt":"Это, наверное, самое красивое место за всё путешествие.","ro":"Éta, navérnaye, sámaye krasívaye mésta za vsyo puteshéstviye."}]},{"title":"En descendant vers le sud","phrases":[{"fr":"Il fait de plus en plus chaud de jour en jour.","tgt":"С каждым днём становится всё жарче и жарче.","ro":"S kázhdym dnyom stanóvitsa vsyo zhárche i zhárche."},{"fr":"Le fleuve devient de plus en plus large.","tgt":"Река становится всё шире и шире.","ro":"Reká stanóvitsa vsyo shíre i shíre."},{"fr":"Il y a de plus en plus de pastèques sur les étals.","tgt":"На прилавках всё больше и больше арбузов.","ro":"Na prilávkakh vsyo ból'she i ból'she arbúzav."},{"fr":"Je comprends de mieux en mieux les conversations à table.","tgt":"Я всё лучше понимаю разговоры за столом.","ro":"Ya vsyo lúchshe panimáyu razgavóry za stalóm."},{"fr":"Les villages se font de plus en plus rares.","tgt":"Деревни попадаются всё реже.","ro":"Derévni papadáyutsa vsyo rézhe."},{"fr":"Le ciel devient de plus en plus bleu.","tgt":"Небо становится всё синее.","ro":"Néba stanóvitsa vsyo sinéye."},{"fr":"Entre nous, on parle de moins en moins français.","tgt":"Мы всё меньше говорим между собой по-французски.","ro":"My vsyo mén'she gavarím mézhdu sabóy pa-frantsúzski."},{"fr":"Ce voyage me plaît de plus en plus.","tgt":"Это путешествие нравится мне всё больше и больше.","ro":"Éta puteshéstviye nrávitsa mne vsyo ból'she i ból'she."},{"fr":"Les passagers se sentent de plus en plus proches les uns des autres.","tgt":"Пассажиры становятся всё ближе друг к другу.","ro":"Passazhíry stanóvyatsa vsyo blízhe drug k drúgu."},{"fr":"Plus on approche de la mer, plus le fleuve coule lentement.","tgt":"Чем ближе к морю, тем медленнее течёт река.","ro":"Chem blízhe k móryu, tem médlenneye techyót reká."}],"tip":{"title":"« Vsyo ból'she i ból'she » : de plus en plus","example":"Il y a de plus en plus de pastèques sur les étals. — На прилавках <b>всё больше и больше</b> арбузов.","body":"Pour dire « de plus en plus », le russe prend le petit mot « vsyo », qui veut dire tout, et le place devant un comparatif. « Vsyo ból'she i ból'she » se dit littéralement tout plus et plus, et « vsyo mén'she », de moins en moins. Avec un adjectif, on met simplement sa forme comparative : « vsyo zhárche », de plus en plus chaud, « vsyo shíre », de plus en plus large, « vsyo lúchshe », de mieux en mieux. Répéter le comparatif, « zhárche i zhárche », ajoute de l'insistance, mais on peut très bien le dire une seule fois. Pour « plus... plus... », on utilise « chem... tem... » : « Chem blízhe k móryu, tem médlenneye techyót reká ». Astuce : pensez à une vague qui monte, « vsyo », toujours un peu plus.","exampleRo":"Na prilávkakh vsyo ból'she i ból'she arbúzav.","lit":"sur · étals · tout · plus · et · plus · pastèques"}},{"title":"L'heure des adieux","phrases":[{"fr":"Demain matin, chacun rentrera chez soi par son propre chemin.","tgt":"Завтра утром каждый поедет домой своим путём.","ro":"Závtra útram kázhdyy payédet damóy svaím putyóm."},{"fr":"Nous avons échangé nos numéros de téléphone et nos adresses.","tgt":"Мы обменялись телефонами и адресами.","ro":"My abmenyális' telefónami i adresámi."},{"fr":"Le capitaine a organisé un dîner d'adieu.","tgt":"Капитан устроил прощальный ужин.","ro":"Kapitán ustróil prashchál'nyy úzhin."},{"fr":"L'équipage a chanté une chanson pour nous.","tgt":"Команда спела для нас песню.","ro":"Kamánda spéla dlya nas pésnyu."},{"fr":"Mes voisins de table m'ont invité chez eux à Saratov.","tgt":"Соседи по столу пригласили меня к себе в Саратов.","ro":"Sasédi pa stalú priglasíli menyá k sebé v Sarátav."},{"fr":"Je leur ai promis de venir l'été prochain.","tgt":"Я обещал приехать к ним следующим летом.","ro":"Ya abeshchál priyékhat' k nim sléduyushchim létam."},{"fr":"C'est triste de quitter des gens qu'on connaît depuis si peu.","tgt":"Грустно расставаться с людьми, которых знаешь так недолго.","ro":"Grúsna rasstavátsa s lyud'mí, katórykh znáyesh' tak nedólga."},{"fr":"On a l'impression d'être partis il y a un mois.","tgt":"Кажется, будто мы уехали месяц назад.","ro":"Kázhetsa, búdta my uyékhali mésyats nazád."},{"fr":"Une dame m'a offert un petit pot de miel de sa datcha.","tgt":"Одна женщина подарила мне баночку мёда со своей дачи.","ro":"Adná zhénshchina padaríla mne bánachku myóda sa svayéy dáchi."},{"fr":"Ces rencontres resteront le plus beau souvenir de la croisière.","tgt":"Эти встречи останутся лучшим воспоминанием о круизе.","ro":"Éti vstréchi astánutsa lúchshim vaspaminániyem a kruíze."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Dans ce module, nous avons descendu la Volga de Moscou jusqu'à la mer.","tgt":"В этом модуле мы спустились по Волге от Москвы до моря.","ro":"V étam módule my spustílis' pa Vólge at Maskvý da mórya."},{"fr":"Nous avons découvert des villes anciennes et des paysages immenses.","tgt":"Мы открыли для себя старинные города и бескрайние просторы.","ro":"My atkrýli dlya sebyá starínnyye garadá i beskráyniye prastóry."},{"fr":"Les participes rendent désormais nos phrases plus élégantes.","tgt":"Причастия делают наши фразы изящнее.","ro":"Prichástiya délayut náshi frázy izyáshchneye."},{"fr":"Nous disons « priyékhav » sans même y réfléchir.","tgt":"Мы говорим «приехав», даже не задумываясь.","ro":"My gavarím «priyékhav», dázhe ne zadúmyvayas'."},{"fr":"Nous disons déjà facilement « ya dólzhen » et « my dalzhný ».","tgt":"Мы уже легко говорим «я должен» и «мы должны».","ro":"My uzhé lekhkó gavarím «ya dólzhen» i «my dalzhný»."},{"fr":"Le russe nous paraît de plus en plus naturel.","tgt":"Русский язык становится для нас всё естественнее.","ro":"Rússkiy yazýk stanóvitsa dlya nas vsyo yestéstvenneye."},{"fr":"Chacun a progressé à son propre rythme.","tgt":"Каждый продвигался в своём темпе.","ro":"Kázhdyy pradvigálsa v svayóm témpe."},{"fr":"Bravo, nous avons parcouru un long chemin sur le fleuve !","tgt":"Молодцы, мы проплыли по реке долгий путь!","ro":"Maladtsý, my praplýli pa reké dólgiy put'!"},{"fr":"Reposez-vous un peu avant le module suivant.","tgt":"Отдохните немного перед следующим модулем.","ro":"Atdakhníte nemnóga péred sléduyushchim módulem."},{"fr":"À bientôt pour de nouvelles conversations intéressantes !","tgt":"До скорой встречи и новых интересных разговоров!","ro":"Da skóray vstréchi i nóvykh interésnykh razgavórav!"}]}]},{"id":3,"name":"Conversation sociale","desc":"Des conversations profondes : opinions, débats, émotions.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Une nuit blanche à Saint-Pétersbourg","phrases":[{"fr":"Cette nuit, tous les ponts sont levés jusqu'à l'aube.","tgt":"Сегодня ночью все мосты разведены до рассвета.","ro":"Sevódnya nóch'yu vse mastý razvedený da rassvéta."},{"fr":"Le métro est déjà fermé, on rentrera à pied.","tgt":"Метро уже закрыто, домой пойдём пешком.","ro":"Metró uzhé zakrýta, damóy paydyóm peshkóm."},{"fr":"La table est mise, tout est prêt pour la soirée.","tgt":"Стол накрыт, всё готово к вечеру.","ro":"Stol nakrýt, vsyo gatóva k vécheru."},{"fr":"Le gâteau a été préparé par ma sœur.","tgt":"Торт сделан моей сестрой.","ro":"Tort sdélan mayéy sestróy."},{"fr":"Cette ville a été construite sur des marais, tu le savais ?","tgt":"Этот город построен на болотах, ты знал?","ro":"État górad pastróyen na balótakh, ty znal?"},{"fr":"Le travail est fini, enfin on peut se détendre.","tgt":"Работа сделана, наконец можно расслабиться.","ro":"Rabóta sdélana, nakanéts mózhna rasslábitsa."},{"fr":"Toutes les fenêtres sont ouvertes, il fait clair comme en plein jour.","tgt":"Все окна открыты, светло как днём.","ro":"Vse ókna atkrýty, svetló kak dnyom."},{"fr":"Toutes les tables du café sur le quai sont déjà prises.","tgt":"Все столики в кафе на набережной уже заняты.","ro":"Vse stóliki v kafé na náberezhnay uzhé zányaty."},{"fr":"Ce livre a été écrit ici même, dans cette maison.","tgt":"Эта книга была написана именно здесь, в этом доме.","ro":"Éta kníga bylá napísana iménna zdes', v étam dóme."},{"fr":"Tout est décidé : demain, on dort jusqu'à midi.","tgt":"Всё решено: завтра спим до обеда.","ro":"Vsyo reshenó: záftra spim da abéda."}],"tip":{"title":"Les participes passifs : « zakrýt », « sdélana »","example":"Le métro est déjà fermé, on rentrera à pied. — Метро уже <b>закрыто</b>, домой пойдём пешком.","body":"Pour dire qu'une chose est dans un certain état, le russe utilise un participe passif court, comme nos mots « fermé » ou « fait ». Il s'accorde avec le nom : « zakrýt » au masculin, « zakrýta » au féminin et au neutre, « zakrýty » au pluriel. À l'oral, féminin et neutre se confondent, car le « o » final non accentué se prononce « a ». Au présent, pas de verbe être : « Metró uzhé zakrýta », mot à mot métro déjà fermé. Au passé, on ajoute « byl », « bylá » ou « býla », et pour dire par qui, on met simplement la personne à l'instrumental, sans préposition : « Tort sdélan mayéy sestróy », le gâteau est fait par ma sœur. Astuce : retenez les deux mots qu'on entend partout devant les portes, « atkrýta », ouvert, et « zakrýta », fermé.","exampleRo":"Metró uzhé zakrýta, damóy paydyóm peshkóm.","lit":"métro · déjà · fermé · à la maison · [nous] irons · à pied"}},{"title":"Au bania entre amis","phrases":[{"fr":"Samedi, on va tous ensemble au bania.","tgt":"В субботу мы все вместе идём в баню.","ro":"V subbótu my vse vméste idyóm v bányu."},{"fr":"Il faut d'abord bien se réchauffer dans l'étuve.","tgt":"Сначала надо хорошо прогреться в парилке.","ro":"Snachála náda kharashó pragrétsa v parílke."},{"fr":"Tu veux que je te fouette avec le balai de bouleau ?","tgt":"Хочешь, я тебя попарю веником?","ro":"Khóchesh', ya tebyá papáryu vénikam?"},{"fr":"Après la chaleur, on plonge dans l'eau froide.","tgt":"После жары ныряем в холодную воду.","ro":"Pósle zharý nyryáyem v khalódnuyu vódu."},{"fr":"En hiver, certains se roulent même dans la neige.","tgt":"Зимой некоторые даже валяются в снегу.","ro":"Zimóy nékatoryye dázhe valyáyutsa v snegú."},{"fr":"Ensuite, on boit du thé au miel et on parle de tout.","tgt":"Потом пьём чай с мёдом и болтаем обо всём.","ro":"Patóm p'yom chay s myódam i baltáyem aba vsyom."},{"fr":"Le bania, c'est bien plus qu'un endroit pour se laver.","tgt":"Баня значит гораздо больше, чем просто место, где моются.","ro":"Bánya znáchit garázda ból'she, chem prósta mésta, gde móyutsa."},{"fr":"Mon grand-père disait que le bania guérit de tout.","tgt":"Мой дедушка говорил, что баня лечит от всего.","ro":"Moy dédushka gavaríl, shto bánya léchit at vsevó."},{"fr":"Ne reste pas trop longtemps, tu es tout rouge.","tgt":"Не сиди слишком долго, ты весь красный.","ro":"Ne sidí slíshkam dólga, ty ves' krásnyy."},{"fr":"Après le bania, on se sent une autre personne.","tgt":"После бани чувствуешь себя другим человеком.","ro":"Pósle báni chústvuyesh' sebyá drugím chelavékam."}]},{"title":"Encourager et relativiser","phrases":[{"fr":"Tu passes ton examen demain ? Bonne chance !","tgt":"Завтра у тебя экзамен? Ни пуха ни пера!","ro":"Záftra u tebyá ekzámen? Ni pukhá ni perá!"},{"fr":"Et l'autre répond toujours : « Au diable ! »","tgt":"А в ответ всегда говорят: «К чёрту!»","ro":"A v atvét vsegdá gavaryát: «K chórtu!»"},{"fr":"Ce matin, j'ai raté mon train, mais bon, ça arrive.","tgt":"Утром я опоздал на поезд, но всё бывает.","ro":"Útram ya apazdál na póyezd, no vsyo bývayet."},{"fr":"Ne t'inquiète pas, ça arrive à tout le monde.","tgt":"Не переживай, со всеми бывает.","ro":"Ne perezhiváy, sa vsémi bývayet."},{"fr":"Ce n'est pas grave, je t'assure.","tgt":"Ничего страшного, правда.","ro":"Nichevó stráshnava, právda."},{"fr":"Eh bien ça alors : il pleut encore !","tgt":"Вот тебе и на: опять дождь!","ro":"Vot tebé i na: apyát' dozhd'!"},{"fr":"Pas de souci, on trouvera bien une idée.","tgt":"Без проблем, что-нибудь придумаем.","ro":"Bez prablém, shto-nibúd' pridúmayem."},{"fr":"C'est la vie, il faut aller de l'avant.","tgt":"Такова жизнь, надо двигаться дальше.","ro":"Takavá zhizn', náda dvígatsa dál'she."},{"fr":"Allez, tiens bon, tout se passera bien !","tgt":"Ну, держись, всё будет хорошо!","ro":"Nu, derzhís', vsyo búdet kharashó!"},{"fr":"Dans la vie, tout peut arriver, pas vrai ?","tgt":"В жизни всё бывает, правда?","ro":"V zhízni vsyo bývayet, právda?"}],"tip":{"title":"Les expressions du quotidien : « ni pukhá ni perá », « vsyo bývayet »","example":"Tu passes ton examen demain ? Bonne chance ! — Завтра у тебя экзамен? <b>Ни пуха ни пера</b>!","body":"« Ni pukhá ni perá » se dit pour souhaiter bonne chance avant un examen ou une épreuve, mot à mot ni duvet ni plume. C'est une vieille formule de chasseurs : souhaiter directement le succès portait malheur, alors on faisait mine de souhaiter une chasse vide. La réponse rituelle est « k chórtu », au diable, et on la lance avec le sourire. L'autre expression, « vsyo bývayet », signifie tout arrive : on la glisse pour dédramatiser, exactement comme notre « c'est la vie ». Appuyez bien sur la première syllabe de « bývayet », et essayez la variante « sa vsémi bývayet », ça arrive à tout le monde. Astuce : imaginez un chasseur qui revient sans une plume, et vous n'oublierez plus la formule.","exampleRo":"Záftra u tebyá ekzámen? Ni pukhá ni perá!","lit":"demain · [chez] toi · examen ? · ni · duvet · ni · plume !"}},{"title":"Un week-end à la datcha","phrases":[{"fr":"Cet été, on passe tous les week-ends à la datcha.","tgt":"Этим летом мы проводим все выходные на даче.","ro":"Étim létam my pravódim vse vykhadnýye na dáche."},{"fr":"La datcha de mes amis est à deux heures de la ville.","tgt":"Дача моих друзей находится в двух часах от города.","ro":"Dácha maíkh druzéy nakhóditsa v dvukh chasákh at górada."},{"fr":"Le matin, on cueille des framboises directement dans le jardin.","tgt":"Утром мы собираем малину прямо в саду.","ro":"Útram my sabiráyem malínu pryáma v sadú."},{"fr":"La grand-mère fait de la confiture pour tout l'hiver.","tgt":"Бабушка варит варенье на всю зиму.","ro":"Bábushka várit varén'ye na vsyu zímu."},{"fr":"Le soir, on fait griller des chachliks au feu de bois.","tgt":"Вечером жарим шашлыки на костре.","ro":"Vécheram zhárim shashlykí na kastré."},{"fr":"Il n'y a pas de réseau ici, et c'est tant mieux.","tgt":"Здесь нет связи, и это к лучшему.","ro":"Zdes' net svyázi, i éta k lúchshemu."},{"fr":"On a passé toute la journée à arroser les concombres.","tgt":"Мы весь день поливали огурцы.","ro":"My ves' den' paliváli agurtsý."},{"fr":"Les moustiques nous ont piqués toute la nuit.","tgt":"Комары кусали нас всю ночь.","ro":"Kamarý kusáli nas vsyu noch'."},{"fr":"Rien ne vaut le silence de la campagne russe.","tgt":"Ничто не сравнится с тишиной русской деревни.","ro":"Nishtó ne sravnítsa s tishinóy rússkay derévni."},{"fr":"Dimanche soir, personne n'a envie de rentrer en ville.","tgt":"В воскресенье вечером никому не хочется возвращаться в город.","ro":"V vaskresén'ye vécheram nikamú ne khóchetsa vazvrashchátsa v górad."}]},{"title":"Parler d'un film","phrases":[{"fr":"Hier soir, on a vu un vieux film russe au cinéma.","tgt":"Вчера вечером мы смотрели старый русский фильм в кино.","ro":"Vcherá vécheram my smatréli stáryy rússkiy fil'm v kinó."},{"fr":"C'était comme si le temps s'était arrêté.","tgt":"Было так, как будто время остановилось.","ro":"Býla tak, kak búdta vrémya astanavílas'."},{"fr":"L'acteur parle comme s'il avait vraiment vécu tout ça.","tgt":"Актёр говорит так, как будто сам всё это пережил.","ro":"Aktyór gavarít tak, kak búdta sam vsyo éta perezhíl."},{"fr":"On dirait que tu as déjà vu ce film.","tgt":"Ты как будто уже видел этот фильм.","ro":"Ty kak búdta uzhé vídel état fil'm."},{"fr":"On regarde chaque plan comme un tableau de musée.","tgt":"Смотришь каждый кадр, как будто картину в музее.","ro":"Smótrish' kázhdyy kadr, kak búdta kartínu v muzéye."},{"fr":"Tu as l'air de ne pas avoir dormi de la nuit.","tgt":"Ты выглядишь так, как будто не спал всю ночь.","ro":"Ty výglyadish' tak, kak búdta ne spal vsyu noch'."},{"fr":"La fin m'a beaucoup surpris, je ne m'y attendais pas.","tgt":"Конец меня очень удивил, я этого не ожидал.","ro":"Kanéts menyá óchen' udivíl, ya étava ne azhidál."},{"fr":"Le réalisateur filme Saint-Pétersbourg comme un véritable personnage.","tgt":"Режиссёр снимает Петербург как отдельного героя.","ro":"Rezhissyór snimáyet Peterbúrg kak atdél'nava geróya."},{"fr":"On en a discuté jusqu'à deux heures du matin.","tgt":"Мы обсуждали его до двух часов ночи.","ro":"My absuzhdáli yevó da dvukh chasóv nóchi."},{"fr":"Parfois, il me semble que je vis dans un film.","tgt":"Иногда мне кажется, что я живу в кино.","ro":"Inagdá mne kázhetsa, shto ya zhivú v kinó."}],"tip":{"title":"« Kak búdta » : comme si, on dirait que","example":"On dirait que tu as déjà vu ce film. — Ты <b>как будто</b> уже видел этот фильм.","body":"« Kak búdta » veut dire comme si, ou on dirait que. Bonne nouvelle : contrairement au français, le verbe qui suit ne change pas de temps, on dit simplement ce qu'on croit voir. Ainsi « Ty kak búdta uzhé vídel état fil'm », mot à mot tu comme si déjà vu ce film, signifie on dirait que tu as déjà vu ce film. Pour une comparaison plus appuyée, on l'annonce par « tak », ainsi : « Ty výglyadish' tak, kak búdta ne spal », tu as l'air de ne pas avoir dormi. À l'oral, le « d » de « búdta » s'entend presque comme un « t », et l'accent tombe sur « bú ». Astuce : utilisez « kak búdta » comme un « genre » à la française, glissé juste devant ce qui semble vrai.","exampleRo":"Ty kak búdta uzhé vídel état fil'm.","lit":"tu · comme si · déjà · [as] vu · ce · film"}},{"title":"Discuter d'un roman russe","phrases":[{"fr":"En ce moment, je relis un roman de Dostoïevski.","tgt":"Сейчас я перечитываю роман Достоевского.","ro":"Seychás ya perechítyvayu ramán Dastayévskava."},{"fr":"Ses personnages discutent sans fin du sens de la vie.","tgt":"Его герои бесконечно спорят о смысле жизни.","ro":"Yevó gerói beskanéchna spóryat a smýsle zhízni."},{"fr":"Ce livre, je l'ai lu pour la première fois à vingt ans.","tgt":"Эту книгу я впервые прочитал в двадцать лет.","ro":"Étu knígu ya vpervýye prachitál v dvádtsat' let."},{"fr":"À l'époque, j'étais loin de tout comprendre.","tgt":"Тогда я понял далеко не всё.","ro":"Tagdá ya pónyal dalekó ne vsyo."},{"fr":"Tu préfères Tolstoï ou Tchekhov ?","tgt":"Тебе больше нравится Толстой или Чехов?","ro":"Tebé ból'she nrávitsa Talstóy íli Chékhav?"},{"fr":"Les nouvelles de Tchekhov sont courtes mais profondes.","tgt":"Рассказы Чехова короткие, но глубокие.","ro":"Rasskázy Chékhava karótkiye, no glubókiye."},{"fr":"Les poèmes de Pouchkine, ici, tout le monde les connaît par cœur.","tgt":"Стихи Пушкина здесь все знают наизусть.","ro":"Stikhí Púshkina zdes' vse znáyut naizúst'."},{"fr":"Lire en russe, c'est un tout autre plaisir.","tgt":"Читать по-русски совсем другое удовольствие.","ro":"Chitát' pa-rússki savsém drugóye udavól'stviye."},{"fr":"Prête-moi ce livre quand tu l'auras fini.","tgt":"Дай мне эту книгу, когда дочитаешь.","ro":"Day mne étu knígu, kagdá dachitáyesh'."},{"fr":"Les grands romans russes parlent de nous tous.","tgt":"Великие русские романы говорят обо всех нас.","ro":"Velíkiye rússkiye ramány gavaryát aba vsekh nas."}]},{"title":"Souvenirs du Transsibérien","phrases":[{"fr":"Il y a trois ans, j'ai traversé toute la Russie en Transsibérien.","tgt":"Три года назад я проехал через всю Россию по Транссибирской магистрали.","ro":"Tri góda nazád ya prayékhal chérez vsyu Rassíyu pa Transsibírskay magistráli."},{"fr":"Le trajet de Moscou à Vladivostok dure presque une semaine.","tgt":"Дорога из Москвы во Владивосток занимает почти неделю.","ro":"Daróga iz Maskvý va Vladivastók zanimáyet pachtí nedélyu."},{"fr":"Dans le compartiment, on partageait tout avec nos voisins.","tgt":"В купе мы делились всем с соседями.","ro":"V kupé my delílis' vsem s sasédyami."},{"fr":"Une vieille dame m'a offert des pirojkis faits maison.","tgt":"Одна бабушка угостила меня домашними пирожками.","ro":"Adná bábushka ugastíla menyá damáshnimi pirazhkámi."},{"fr":"Je regardais la taïga défiler pendant des heures.","tgt":"Я часами смотрел, как мимо проносится тайга.","ro":"Ya chasámi smatrél, kak míma pranósitsa taygá."},{"fr":"À chaque gare, les gens descendaient acheter de quoi manger.","tgt":"На каждой станции люди выходили купить что-нибудь поесть.","ro":"Na kázhday stántsii lyúdi vykhadíli kupít' shto-nibúd' payést'."},{"fr":"Le thé servi dans des porte-verres, c'est mon souvenir préféré.","tgt":"Чай в подстаканниках, вот моё любимое воспоминание.","ro":"Chay v padstakánnikakh, vot mayó lyubímaye vaspaminániye."},{"fr":"On a fait connaissance avec un étudiant de Novossibirsk.","tgt":"Мы познакомились со студентом из Новосибирска.","ro":"My paznakómilis' sa studéntam iz Navasibírska."},{"fr":"Le lever du soleil sur le Baïkal m'a coupé le souffle.","tgt":"От рассвета над Байкалом у меня перехватило дыхание.","ro":"At rassvéta nad Baykálam u menyá perekhvatíla dykhániye."},{"fr":"Ce voyage m'a appris à ne pas me presser.","tgt":"Это путешествие научило меня не торопиться.","ro":"Éta puteshéstviye nauchíla menyá ne tarapítsa."}]},{"title":"Quand on n'a pas le choix","phrases":[{"fr":"Désolé, ce soir je dois travailler tard.","tgt":"Извини, сегодня вечером мне приходится работать допоздна.","ro":"Izviní, sevódnya vécheram mne prikhóditsa rabótat' dapazná."},{"fr":"On a dû annuler notre sortie à la datcha.","tgt":"Нам пришлось отменить поездку на дачу.","ro":"Nam prishlós' atmenít' payézdku na dáchu."},{"fr":"Le matin, je suis obligé de me lever à six heures.","tgt":"По утрам мне приходится вставать в шесть.","ro":"Pa utrám mne prikhóditsa vstavát' v shest'."},{"fr":"Il a fallu attendre le dernier bus pendant une heure entière.","tgt":"Пришлось целый час ждать последний автобус.","ro":"Prishlós' tsélyy chas zhdat' paslédniy avtóbus."},{"fr":"Parfois, on est obligé de dire non à ses amis.","tgt":"Иногда приходится отказывать друзьям.","ro":"Inagdá prikhóditsa atkázyvat' druz'yám."},{"fr":"Avec deux enfants, il faut tout organiser à l'avance.","tgt":"С двумя детьми приходится всё планировать заранее.","ro":"S dvumyá det'mí prikhóditsa vsyo planíravat' zaráneye."},{"fr":"Tu as dû beaucoup voyager pour ton travail ?","tgt":"Тебе приходилось много ездить по работе?","ro":"Tebé prikhadílas' mnóga yézdit' pa rabóte?"},{"fr":"J'ai dû tout réexpliquer depuis le début.","tgt":"Мне пришлось объяснять всё с самого начала.","ro":"Mne prishlós' ab'yasnyát' vsyo s sámava nachála."},{"fr":"Ce n'est pas que je ne veux pas, je n'ai simplement pas le choix.","tgt":"Дело не в том, что я не хочу, просто приходится.","ro":"Déla ne v tom, shto ya ne khachú, prósta prikhóditsa."},{"fr":"La prochaine fois, je viendrai, c'est promis.","tgt":"В следующий раз я обязательно приду, обещаю.","ro":"V sléduyushchiy raz ya abyazátel'na pridú, abeshcháyu."}],"tip":{"title":"« Prikhóditsa » : être obligé de","example":"Le matin, je suis obligé de me lever à six heures. — По утрам мне <b>приходится</b> вставать в шесть.","body":"« Prikhóditsa » exprime une obligation imposée par les circonstances, un peu comme notre « je suis bien obligé de ». La construction est impersonnelle : la personne se met au datif, « mne », « tebé », « nam », puis viennent « prikhóditsa » et un verbe à l'infinitif. Ainsi « Pa utrám mne prikhóditsa vstavát' v shest' », mot à mot les matins à moi il arrive se lever à six, veut dire je dois me lever à six heures. Pour une contrainte ponctuelle au passé, on dit « prishlós' » : « Nam prishlós' atmenít' », nous avons dû annuler. La différence avec « náda », il faut, c'est une petite nuance de regret : on le fait parce qu'on n'a pas le choix. Prononcez la fin « tsa » bien nette, sans aucun son mouillé.","exampleRo":"Pa utrám mne prikhóditsa vstavát' v shest'.","lit":"les matins · à moi · [il] arrive · se lever · à six"}},{"title":"Une soirée au ballet","phrases":[{"fr":"Mes amis m'ont invité au ballet ce soir.","tgt":"Друзья пригласили меня сегодня на балет.","ro":"Druz'yá priglasíli menyá sevódnya na balét."},{"fr":"On avait acheté les billets deux mois à l'avance.","tgt":"Билеты мы купили ещё два месяца назад.","ro":"Biléty my kupíli yeshchyó dva mésyatsa nazád."},{"fr":"Dans la salle, tout le monde était élégamment habillé.","tgt":"В зале все были нарядно одеты.","ro":"V zále vse býli naryádna adéty."},{"fr":"À l'entracte, on a bu une coupe de champagne au buffet.","tgt":"В антракте мы выпили по бокалу шампанского в буфете.","ro":"V antrákte my výpili pa bakálu shampánskava v buféte."},{"fr":"Les danseurs avaient l'air de voler au-dessus de la scène.","tgt":"Танцоры как будто летали над сценой.","ro":"Tantsóry kak búdta letáli nad stsénay."},{"fr":"Je n'ai jamais rien vu d'aussi beau.","tgt":"Я никогда не видел ничего красивее.","ro":"Ya nikagdá ne vídel nichevó krasíveye."},{"fr":"La musique de Tchaïkovski me donne toujours des frissons.","tgt":"От музыки Чайковского у меня всегда мурашки.","ro":"At múzyki Chaykóvskava u menyá vsegdá muráshki."},{"fr":"Le public a applaudi pendant dix minutes.","tgt":"Публика аплодировала десять минут.","ro":"Públika apladíravala désyat' minút."},{"fr":"Après le spectacle, on a marché le long du canal.","tgt":"После спектакля мы гуляли вдоль канала.","ro":"Pósle spektáklya my gulyáli vdol' kanála."},{"fr":"Cette soirée restera longtemps dans ma mémoire.","tgt":"Этот вечер надолго останется в моей памяти.","ro":"État vécher nadólga astánetsa v mayéy pámyati."}]},{"title":"La ville ou la campagne ?","phrases":[{"fr":"Toi, tu pourrais vivre à la campagne toute l'année ?","tgt":"А ты смог бы жить в деревне круглый год?","ro":"A ty smog by zhit' v derévne krúglyy god?"},{"fr":"Moi, sans la ville, je m'ennuierais vite.","tgt":"Я бы без города быстро заскучал.","ro":"Ya by bez górada býstra zaskuchál."},{"fr":"En ville, on a tout sous la main.","tgt":"В городе всё под рукой.","ro":"V górade vsyo pad rukóy."},{"fr":"En revanche, à la campagne, l'air est pur et les gens sont plus calmes.","tgt":"Зато в деревне чистый воздух и люди спокойнее.","ro":"Zató v derévne chístyy vózdukh i lyúdi spakóyneye."},{"fr":"Moscou est trop bruyante pour moi.","tgt":"Москва для меня слишком шумная.","ro":"Maskvá dlya menyá slíshkam shúmnaya."},{"fr":"Mais c'est là qu'on trouve les expositions les plus intéressantes.","tgt":"Но именно там самые интересные выставки.","ro":"No iménna tam sámyye interésnyye výstavki."},{"fr":"L'idéal, ce serait de travailler en ville et de vivre à la datcha.","tgt":"Идеально было бы работать в городе, а жить на даче.","ro":"Ideál'na býla by rabótat' v górade, a zhit' na dáche."},{"fr":"Beaucoup de Moscovites font exactement ça en été.","tgt":"Многие москвичи летом так и делают.","ro":"Mnógiye maskvichí létam tak i délayut."},{"fr":"Chacun a ses raisons, on ne va pas se disputer pour ça.","tgt":"У каждого свои причины, не будем из-за этого ссориться.","ro":"U kázhdava svaí prichíny, ne búdem iz-za étava ssóritsa."},{"fr":"Au final, chacun est resté sur ses positions.","tgt":"В итоге каждый остался при своём мнении.","ro":"V itóge kázhdyy astálsya pri svayóm mnénii."}]},{"title":"Mon premier séjour en Russie","phrases":[{"fr":"Je me souviens très bien de mon premier jour à Moscou.","tgt":"Я очень хорошо помню свой первый день в Москве.","ro":"Ya óchen' kharashó pómnyu svoy pérvyy den' v Maskvé."},{"fr":"Je ne connaissais que trois mots de russe.","tgt":"Я знал по-русски всего три слова.","ro":"Ya znal pa-rússki vsevó tri slóva."},{"fr":"Dans le métro, je me suis perdu au bout de dix minutes.","tgt":"В метро я заблудился через десять минут.","ro":"V metró ya zabludílsya chérez désyat' minút."},{"fr":"Un inconnu m'a accompagné jusqu'à ma station.","tgt":"Незнакомый человек проводил меня до моей станции.","ro":"Neznakómyy chelavék pravadíl menyá da mayéy stántsii."},{"fr":"J'ai été frappé par la gentillesse des gens.","tgt":"Меня поразила доброта людей.","ro":"Menyá parazíla dabratá lyudéy."},{"fr":"Tout me semblait immense, les avenues comme les gares.","tgt":"Всё казалось огромным: и проспекты, и вокзалы.","ro":"Vsyo kazálas' agrómnym: i praspékty, i vakzály."},{"fr":"Le premier hiver a été un vrai choc pour moi.","tgt":"Первая зима стала для меня настоящим шоком.","ro":"Pérvaya zimá stála dlya menyá nastayáshchim shókam."},{"fr":"J'avais l'impression que tout le monde parlait trop vite.","tgt":"Мне казалось, что все говорят слишком быстро.","ro":"Mne kazálas', shto vse gavaryát slíshkam býstra."},{"fr":"Aujourd'hui, je ris en repensant à ces premiers jours.","tgt":"Сейчас я смеюсь, вспоминая те первые дни.","ro":"Seychás ya smeyús', vspamináya te pérvyye dni."},{"fr":"Sans ce voyage, je n'aurais jamais commencé le russe.","tgt":"Без этой поездки я бы никогда не начал учить русский.","ro":"Bez étay payézdki ya by nikagdá ne náchal uchít' rússkiy."}]},{"title":"La sagesse des proverbes","phrases":[{"fr":"Comme disent les Russes, mieux vaut tard que jamais.","tgt":"Как говорят русские, лучше поздно, чем никогда.","ro":"Kak gavaryát rússkiye, lúchshe pózdna, chem nikagdá."},{"fr":"Mon ami m'a répondu qu'on n'a rien sans peine.","tgt":"Друг мне ответил: «Без труда не выловишь и рыбку из пруда».","ro":"Drug mne atvétil: «Bez trudá ne výlavish' i rýbku iz prudá»."},{"fr":"Ne remets pas à demain ce que tu peux faire aujourd'hui.","tgt":"Не откладывай на завтра то, что можно сделать сегодня.","ro":"Ne atkládyvay na záftra to, shto mózhna sdélat' sevódnya."},{"fr":"Qui va doucement va loin, dit souvent ma voisine.","tgt":"Тише едешь, дальше будешь, говорит моя соседка.","ro":"Tíshe yédesh', dál'she búdesh', gavarít mayá sasédka."},{"fr":"Ce proverbe veut dire qu'il ne faut pas se précipiter.","tgt":"Эта пословица значит, что не надо спешить.","ro":"Éta paslóvitsa znáchit, shto ne náda speshít'."},{"fr":"N'aie pas cent roubles, aie plutôt cent amis.","tgt":"Не имей сто рублей, а имей сто друзей.","ro":"Ne iméy sto rubléy, a iméy sto druzéy."},{"fr":"Celui-là, je le répète souvent à mes amis en France.","tgt":"Эту пословицу я часто повторяю своим друзьям во Франции.","ro":"Étu paslóvitsu ya chásta pavtaryáyu svaím druz'yám va Frántsii."},{"fr":"Les proverbes en disent long sur la façon de penser d'un peuple.","tgt":"Пословицы многое говорят о том, как думает народ.","ro":"Paslóvitsy mnógaye gavaryát a tom, kak dúmayet naród."},{"fr":"Chaque chose en son temps, comme dit le proverbe.","tgt":"Всему своё время, как говорится.","ro":"Vsemú svayó vrémya, kak gavarítsa."},{"fr":"La parole est d'argent, mais le silence est d'or.","tgt":"Слово серебро, а молчание золото.","ro":"Slóva serebró, a malchániye zólata."}],"tip":{"title":"Les proverbes russes","example":"N'aie pas cent roubles, aie plutôt cent amis. — <b>Не имей сто рублей, а имей сто друзей</b>.","body":"Les Russes adorent glisser un proverbe dans la conversation, souvent introduit par « kak gavarítsa », comme on dit. Beaucoup riment, ce qui les rend faciles à retenir et agréables à dire : « Ne iméy sto rubléy, a iméy sto druzéy », mot à mot n'aie pas cent roubles, mais aie cent amis, joue sur la rime entre « rubléy » et « druzéy ». De même, « Tíshe yédesh', dál'she búdesh' », mot à mot plus doucement tu roules, plus loin tu seras, correspond à notre qui va doucement va loin. Et « Lúchshe pózdna, chem nikagdá » se comprend presque tout seul : mieux vaut tard que jamais, avec un « d » muet dans « pózdna ». Astuce : apprenez-les en les scandant comme une comptine, le rythme fait la moitié du travail.","exampleRo":"Ne iméy sto rubléy, a iméy sto druzéy.","lit":"[ne] aie pas · cent · roubles · mais · aie · cent · amis"}},{"title":"Un anniversaire et ses toasts","phrases":[{"fr":"Ce soir, on fête les trente ans de Macha.","tgt":"Сегодня мы отмечаем тридцатилетие Маши.","ro":"Sevódnya my atmecháyem tridtsatilétiye Máshi."},{"fr":"En Russie, chaque toast devient un petit discours.","tgt":"В России каждый тост превращается в маленькую речь.","ro":"V Rassíi kázhdyy tost prevrashcháyetsa v málen'kuyu rech'."},{"fr":"Je voudrais lever mon verre à la maîtresse de maison.","tgt":"Я хотел бы поднять бокал за хозяйку дома.","ro":"Ya khatél by padnyát' bakál za khazyáyku dóma."},{"fr":"Je te souhaite la santé, le bonheur et beaucoup de voyages.","tgt":"Желаю тебе здоровья, счастья и много путешествий.","ro":"Zheláyu tebé zdaróv'ya, shchást'ya i mnóga puteshéstviy."},{"fr":"Qu'on se retrouve plus souvent autour de cette table !","tgt":"Пусть мы почаще собираемся за этим столом!","ro":"Pust' my pacháshche sabiráyemsya za étim stalóm!"},{"fr":"On ne trinque jamais avec un verre vide.","tgt":"Пустым бокалом не чокаются.","ro":"Pustým bakálam ne chókayutsa."},{"fr":"Quand on trinque, il faut se regarder dans les yeux.","tgt":"Когда чокаешься, надо смотреть в глаза.","ro":"Kagdá chókayesh'sya, náda smatrét' v glazá."},{"fr":"Son oncle a raconté une histoire si drôle que tout le monde a pleuré de rire.","tgt":"Её дядя рассказал такую смешную историю, что все плакали от смеха.","ro":"Yeyó dyádya rasskazál takúyu smeshnúyu istóriyu, shto vse plákali at smékha."},{"fr":"Le gâteau au miel était tout simplement délicieux.","tgt":"Медовик был просто восхитительный.","ro":"Medavík byl prósta vaskhitítel'nyy."},{"fr":"On a chanté des chansons jusqu'au petit matin.","tgt":"Мы пели песни до самого утра.","ro":"My péli pésni da sámava utrá."}]},{"title":"Si l'on pouvait rêver","phrases":[{"fr":"Si j'avais plus de temps, j'apprendrais à jouer de la guitare.","tgt":"Если бы у меня было больше времени, я бы научился играть на гитаре.","ro":"Yésli by u menyá býla ból'she vrémeni, ya by nauchílsya igrát' na gitáre."},{"fr":"Où est-ce que tu aimerais vivre, si tu pouvais choisir ?","tgt":"Где бы ты хотел жить, если бы мог выбирать?","ro":"Gde by ty khatél zhit', yésli by mog vybirát'?"},{"fr":"Moi, je m'installerais au bord de la mer, à Sotchi.","tgt":"Я бы поселился у моря, в Сочи.","ro":"Ya by paselílsya u mórya, v Sóchi."},{"fr":"J'aimerais tant revoir le Baïkal en hiver.","tgt":"Мне бы так хотелось снова увидеть Байкал зимой.","ro":"Mne by tak khatélas' snóva uvídet' Baykál zimóy."},{"fr":"Si je pouvais tout recommencer, je choisirais un autre métier.","tgt":"Если бы можно было всё начать сначала, я бы выбрал другую профессию.","ro":"Yésli by mózhna býla vsyo nachát' snachála, ya by výbral drugúyu praféssiyu."},{"fr":"Mon rêve, c'est d'ouvrir un petit café à Kazan.","tgt":"Я мечтаю открыть маленькое кафе в Казани.","ro":"Ya mechtáyu atkrýt' málen'kaye kafé v Kazáni."},{"fr":"Ce serait formidable de partir tous ensemble cet été.","tgt":"Было бы здорово поехать всем вместе этим летом.","ro":"Býla by zdórava payékhat' vsem vméste étim létam."},{"fr":"Je n'aurais jamais cru que je parlerais russe un jour.","tgt":"Никогда бы не подумал, что когда-нибудь заговорю по-русски.","ro":"Nikagdá by ne padúmal, shto kagdá-nibúd' zagavaryú pa-rússki."},{"fr":"Tout grand projet commence par un petit pas.","tgt":"Любой большой план начинается с маленького шага.","ro":"Lyubóy bal'shóy plan nachináyetsa s málen'kava shága."},{"fr":"Et toi, que ferais-tu d'une année de liberté ?","tgt":"А что бы ты сделал с годом свободы?","ro":"A shto by ty sdélal s gódam svabódy?"}]},{"title":"Un malentendu entre amis","phrases":[{"fr":"Je crois qu'il y a eu un malentendu entre nous.","tgt":"Кажется, между нами произошло недоразумение.","ro":"Kázhetsa, mézhdu námi praizashló nedarazuméniye."},{"fr":"Je ne voulais absolument pas te vexer.","tgt":"Я совсем не хотел тебя обидеть.","ro":"Ya savsém ne khatél tebyá abídet'."},{"fr":"Tu as mal compris ce que je voulais dire.","tgt":"Ты неправильно понял, что я хотел сказать.","ro":"Ty neprávil'na pónyal, shto ya khatél skazát'."},{"fr":"J'aurais dû t'appeler au lieu d'écrire un message.","tgt":"Мне надо было позвонить, а не писать сообщение.","ro":"Mne náda býla pazvanít', a ne pisát' saabshchéniye."},{"fr":"Par écrit, on comprend souvent les choses de travers.","tgt":"В переписке многое понимаешь не так.","ro":"V perepíske mnógaye panimáyesh' ne tak."},{"fr":"Excuse-moi, j'ai réagi trop vivement.","tgt":"Прости, я слишком резко отреагировал.","ro":"Prastí, ya slíshkam rézka atreagíraval."},{"fr":"On en parle calmement autour d'un thé ?","tgt":"Давай спокойно обсудим это за чаем?","ro":"Daváy spakóyna absúdim éta za cháyem?"},{"fr":"Notre amitié compte plus que cette histoire.","tgt":"Наша дружба важнее этой истории.","ro":"Násha drúzhba vazhnéye étay istórii."},{"fr":"Ne t'en fais pas, je ne t'en veux pas du tout.","tgt":"Не переживай, я на тебя совсем не обижаюсь.","ro":"Ne perezhiváy, ya na tebyá savsém ne abizháyus'."},{"fr":"Après cette discussion, on est encore plus proches.","tgt":"После этого разговора мы стали ещё ближе.","ro":"Pósle étava razgavóra my stáli yeshchyó blízhe."}]},{"title":"Souvenirs du lac Baïkal","phrases":[{"fr":"Le Baïkal passe pour le lac le plus profond du monde.","tgt":"Байкал считается самым глубоким озером в мире.","ro":"Baykál shchitáyetsa sámym glubókim ózeram v míre."},{"fr":"En hiver, on peut marcher des kilomètres sur la glace.","tgt":"Зимой по льду можно пройти много километров.","ro":"Zimóy pa l'dú mózhna praytí mnóga kilamétrav."},{"fr":"La glace y est si transparente qu'on voit le fond.","tgt":"Лёд там такой прозрачный, что видно дно.","ro":"Lyod tam takóy prazráchnyy, shto vídna dno."},{"fr":"Nous avons dormi chez l'habitant sur l'île d'Olkhon.","tgt":"Мы ночевали у местных на острове Ольхон.","ro":"My nacheváli u mésnykh na óstrave Al'khón."},{"fr":"Notre hôte pêchait l'omoul chaque matin.","tgt":"Наш хозяин каждое утро ловил омуля.","ro":"Nash khazyáin kázhdaye útra lavíl amulyá."},{"fr":"Je n'avais jamais goûté un poisson aussi frais.","tgt":"Я никогда не пробовал такой свежей рыбы.","ro":"Ya nikagdá ne próbaval takóy svézhey rýby."},{"fr":"L'eau du lac est si pure qu'on peut la boire.","tgt":"Вода в озере такая чистая, что её можно пить.","ro":"Vadá v ózere takáya chístaya, shto yeyó mózhna pit'."},{"fr":"Le soir, on chantait autour du feu avec d'autres voyageurs.","tgt":"Вечерами мы пели у костра с другими путешественниками.","ro":"Vecherámi my péli u kastrá s drugími puteshéstvennikami."},{"fr":"Les gens du coin appellent le Baïkal « la mer ».","tgt":"Местные называют Байкал морем.","ro":"Mésnyye nazyváyut Baykál mórem."},{"fr":"Un jour, j'y retournerai en été.","tgt":"Когда-нибудь я вернусь туда летом.","ro":"Kagdá-nibúd' ya vernús' tudá létam."}]},{"title":"Promenade au bord de la Neva","phrases":[{"fr":"Il est minuit, mais il fait encore jour.","tgt":"Уже полночь, а на улице ещё светло.","ro":"Uzhé pólnach', a na úlitse yeshchyó svetló."},{"fr":"Tout Saint-Pétersbourg se promène sur les quais.","tgt":"Весь Петербург гуляет по набережным.","ro":"Ves' Peterbúrg gulyáyet pa náberezhnym."},{"fr":"Regarde, le pont du Palais commence à se lever.","tgt":"Смотри, Дворцовый мост начинает разводиться.","ro":"Smatrí, Dvartsóvyy most nachináyet razvadítsa."},{"fr":"Des musiciens jouent juste à côté de nous.","tgt":"Совсем рядом с нами играют музыканты.","ro":"Savsém ryádam s námi igráyut muzykánty."},{"fr":"Les Pétersbourgeois disent qu'en juin, ils ne dorment pas.","tgt":"Петербуржцы говорят, что в июне не спят.","ro":"Peterbúrzhtsy gavaryát, shto v iyúne ne spyat."},{"fr":"Et si on faisait un tour en bateau sur les canaux ?","tgt":"Может, покатаемся на кораблике по каналам?","ro":"Mózhet, pakatáyemsya na karáblike pa kanálam?"},{"fr":"Dans cette lumière, la ville paraît encore plus belle.","tgt":"В этом свете город кажется ещё красивее.","ro":"V étam svéte górad kázhetsa yeshchyó krasíveye."},{"fr":"Je pourrais marcher comme ça jusqu'au matin.","tgt":"Я мог бы так гулять до утра.","ro":"Ya mog by tak gulyát' da utrá."},{"fr":"On s'est assis sur les marches pour regarder l'eau.","tgt":"Мы сели на ступеньки и смотрели на воду.","ro":"My séli na stupén'ki i smatréli na vódu."},{"fr":"Ces nuits blanches, je ne les oublierai jamais.","tgt":"Эти белые ночи я никогда не забуду.","ro":"Éti bélyye nóchi ya nikagdá ne zabúdu."}]},{"title":"Le moment des adieux","phrases":[{"fr":"Demain, je rentre en France, le temps a filé trop vite.","tgt":"Завтра я уезжаю во Францию, время пролетело слишком быстро.","ro":"Záftra ya uyezzháyu va Frántsiyu, vrémya praletéla slíshkam býstra."},{"fr":"Merci pour votre accueil, je me suis senti comme chez moi.","tgt":"Спасибо за гостеприимство, я чувствовал себя как дома.","ro":"Spasíba za gastepriímstva, ya chústvaval sebyá kak dóma."},{"fr":"On s'assoit un instant avant le départ, c'est la tradition.","tgt":"Присядем на дорожку, такая традиция.","ro":"Prisyádem na darózhku, takáya tradítsiya."},{"fr":"Promets-moi de venir me voir à Paris.","tgt":"Обещай, что приедешь ко мне в Париж.","ro":"Abeshcháy, shto priyédesh' ka mne v Parízh."},{"fr":"Je t'écrirai dès que je serai arrivé.","tgt":"Я напишу тебе, как только приеду.","ro":"Ya napishú tebé, kak tól'ka priyédu."},{"fr":"Vous allez tous terriblement me manquer.","tgt":"Я буду очень по вам всем скучать.","ro":"Ya búdu óchen' pa vam vsem skuchát'."},{"fr":"Ne pleure pas, on se reverra bientôt.","tgt":"Не плачь, мы скоро увидимся.","ro":"Ne plach, my skóra uvídimsya."},{"fr":"Garde ce petit cadeau en souvenir.","tgt":"Возьми этот маленький подарок на память.","ro":"Vaz'mí état málen'kiy padárak na pámyat'."},{"fr":"Bon voyage, et appelle-nous en arrivant !","tgt":"Счастливого пути, позвони, когда доедешь!","ro":"Shchaslívava putí, pazvaní, kagdá dayédesh'!"},{"fr":"En partant, on laisse toujours un peu de soi derrière.","tgt":"Уезжая, всегда оставляешь здесь частичку себя.","ro":"Uyezzháya, vsegdá astavlyáyesh' zdes' chastíchku sebyá."}]},{"title":"Regard en arrière sur mon parcours en russe","phrases":[{"fr":"Au début, je n'arrivais même pas à dire bonjour.","tgt":"Сначала я даже не мог сказать «здравствуйте».","ro":"Snachála ya dázhe ne mog skazát' «zdrávstvuyte»."},{"fr":"L'accent tonique m'a donné bien du fil à retordre.","tgt":"Ударение доставило мне много хлопот.","ro":"Udaréniye dastávila mne mnóga khlapót."},{"fr":"Puis, petit à petit, les phrases sont venues toutes seules.","tgt":"Потом постепенно фразы стали приходить сами.","ro":"Patóm pastepénna frázy stáli prikhadít' sámi."},{"fr":"Les verbes de mouvement me semblaient un vrai casse-tête.","tgt":"Глаголы движения казались мне настоящей головоломкой.","ro":"Glagóly dvizhéniya kazális' mne nastayáshchey galavalómkay."},{"fr":"Aujourd'hui, je peux discuter de livres et de films en russe.","tgt":"Теперь я могу обсуждать книги и фильмы по-русски.","ro":"Tepér' ya magú absuzhdát' knígi i fíl'my pa-rússki."},{"fr":"Je comprends même les blagues de mes amis, enfin presque.","tgt":"Я даже понимаю шутки друзей, ну почти.","ro":"Ya dázhe panimáyu shútki druzéy, nu pachtí."},{"fr":"Chaque trajet m'a rapproché un peu plus de cette langue.","tgt":"Каждая поездка немного приближала меня к этому языку.","ro":"Kázhdaya payézdka nemnóga priblizhála menyá k étamu yazykú."},{"fr":"Je ne suis plus celui que j'étais le premier jour.","tgt":"Я уже не тот, кем был в первый день.","ro":"Ya uzhé ne tot, kem byl v pérvyy den'."},{"fr":"Le russe m'a ouvert les portes d'un monde entier.","tgt":"Русский язык открыл мне двери в целый мир.","ro":"Rússkiy yazýk atkrýl mne dvéri v tsélyy mir."},{"fr":"Je suis sincèrement fier du chemin parcouru.","tgt":"Я по-настоящему горжусь пройденным путём.","ro":"Ya pa-nastayáshchemu garzhús' próydennym putyóm."}]},{"title":"Fin du parcours : un dernier bilan","phrases":[{"fr":"Ce module était consacré aux conversations entre amis.","tgt":"Этот модуль был посвящён разговорам с друзьями.","ro":"État módul' byl pasvyashchyón razgavóram s druz'yámi."},{"fr":"Nous avons parlé de bania, de datcha et de nuits blanches.","tgt":"Мы говорили о бане, о даче и о белых ночах.","ro":"My gavaríli a báne, a dáche i a bélykh nachákh."},{"fr":"Les participes et les proverbes ne nous font plus peur.","tgt":"Причастия и пословицы нас больше не пугают.","ro":"Prichástiya i paslóvitsy nas ból'she ne pugáyut."},{"fr":"Le russe n'est plus une langue étrangère pour nous.","tgt":"Русский язык для нас больше не чужой.","ro":"Rússkiy yazýk dlya nas ból'she ne chuzhóy."},{"fr":"Trois niveaux, neuf modules et des centaines de phrases dites à voix haute.","tgt":"Три уровня, девять модулей и сотни фраз, сказанных вслух.","ro":"Tri úrovnya, dévyat' móduley i sótni fraz, skázannykh vslukh."},{"fr":"Le plus important, c'était de ne pas avoir peur de parler.","tgt":"Самое главное было не бояться говорить.","ro":"Sámaye glávnaye býla ne bayátsa gavarít'."},{"fr":"Maintenant, il ne reste plus qu'à partir en Russie.","tgt":"Теперь осталось только поехать в Россию.","ro":"Tepér' astálas' tól'ka payékhat' v Rassíyu."},{"fr":"Chaque conversation avec des Russes sera une nouvelle leçon.","tgt":"Каждый разговор с русскими станет новым уроком.","ro":"Kázhdyy razgavór s rússkimi stánet nóvym urókam."},{"fr":"Félicitations pour la fin du parcours, tu peux être fier de toi !","tgt":"Поздравляю с окончанием курса, можешь гордиться собой!","ro":"Pazdravlyáyu s akanchániyem kúrsa, mózhesh' gardítsa sabóy!"},{"fr":"À bientôt, et bonne route en russe !","tgt":"До скорой встречи и удачи с русским!","ro":"Da skóray vstréchi i udáchi s rússkim!"}]}]}]}];
